// ===== APIヘルパー =====
const API = {
  async get(table, params = {}) {
    const qs = new URLSearchParams({ limit: 500, ...params }).toString();
    const res = await fetch(`tables/${table}?${qs}`);
    if (!res.ok) throw new Error(`GET ${table} failed: ${res.status}`);
    return res.json();
  },
  // 全件ページネーション取得（limit上限を超えるテーブル用）
  // ※ APIは実際には100件/ページ上限のため limit=100 で取得する
  // pageSize: 画像等大データを含むテーブルは小さい値を指定（例: 20）
  async getAll(table, params = {}, pageSize = 100) {
    let page = 1, all = [];
    const limit = pageSize;
    while (true) {
      const qs = new URLSearchParams({ ...params, limit, page }).toString();
      const res = await fetch(`tables/${table}?${qs}`, { cache: 'no-store' });
      if (!res.ok) throw new Error(`GET ${table} failed: ${res.status}`);
      const d = await res.json();
      const rows = d.data || [];
      all = all.concat(rows);
      if (all.length >= (d.total || 0) || rows.length === 0) break;
      page++;
    }
    return { data: all, total: all.length };
  },
  async getOne(table, id) {
    const res = await fetch(`tables/${table}/${id}`, { cache: 'no-store' });
    if (!res.ok) throw new Error(`GET ${table}/${id} failed`);
    return res.json();
  },
  async post(table, data) {
    const res = await fetch(`tables/${table}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    });
    if (!res.ok) {
      let msg = `POST ${table} failed: ${res.status}`;
      try { const e = await res.json(); msg += ' ' + JSON.stringify(e); } catch(_){}
      console.error('[API.post]', msg);
      throw new Error(msg);
    }
    const ct = res.headers.get('content-type') || '';
    if (!ct.includes('application/json')) return {};
    return res.json().catch(() => ({}));
  },
  async put(table, id, data) {
    const res = await fetch(`tables/${table}/${id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    });
    if (!res.ok) {
      let msg = `PUT ${table}/${id} failed: ${res.status}`;
      try { const e = await res.json(); msg += ' ' + JSON.stringify(e); } catch(_){}
      console.error('[API.put]', msg);
      throw new Error(msg);
    }
    const ct = res.headers.get('content-type') || '';
    if (!ct.includes('application/json')) return {};
    return res.json().catch(() => ({}));
  },
  async delete(table, id) {
    const res = await fetch(`tables/${table}/${id}`, { method: 'DELETE' });
    if (!res.ok) {
      let msg = `DELETE ${table}/${id} failed: ${res.status}`;
      console.error('[API.delete]', msg);
      throw new Error(msg);
    }
  },
  // PATCH: まず直接PATCHを試みる。405/404なら GET→最小マージ→PUT にフォールバック
  async patch(table, id, data) {
    // 1. 直接 PATCH を試みる
    const patchRes = await fetch(`tables/${table}/${id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    });
    if (patchRes.ok) {
      const ct = patchRes.headers.get('content-type') || '';
      if (!ct.includes('application/json')) return data;
      return patchRes.json().catch(() => data);
    }
    if (patchRes.status !== 405 && patchRes.status !== 404 && patchRes.status !== 501) {
      let msg = `PATCH ${table}/${id} failed: ${patchRes.status}`;
      try { const e = await patchRes.json(); msg += ' ' + JSON.stringify(e); } catch(_){}
      console.error('[API.patch→PATCH]', msg);
      throw new Error(msg);
    }

    // 2. PATCH未対応なら GET → 安全マージ → PUT
    const getRes = await fetch(`tables/${table}/${id}`, { cache: 'no-store' });
    if (!getRes.ok) {
      const msg = `GET(for patch) ${table}/${id} failed: ${getRes.status}`;
      console.error('[API.patch→GET]', msg);
      throw new Error(msg);
    }
    const existing = await getRes.json();
    // システムフィールド・大容量フィールドを除外
    const { gs_project_id, gs_table_name, created_at, updated_at, deleted,
            avatar_image, ...rest } = existing;
    // undefined のキーは既存値を保持（null は明示的削除）
    const patch = Object.fromEntries(
      Object.entries(data).filter(([, v]) => v !== undefined)
    );
    const merged = { ...rest, ...patch };
    // D1_TYPE_ERROR 対策：PUT body 内の object 型フィールドを JSON 文字列化する
    // （sns_urls など文字列で保存されているフィールドが GET 後に object になっているケースを含む）
    Object.keys(merged).forEach(k => {
      if (merged[k] !== null && merged[k] !== undefined && typeof merged[k] === 'object') {
        console.warn('[API.patch] object型フィールドをJSON文字列化:', k, merged[k]);
        merged[k] = JSON.stringify(merged[k]);
      }
    });
    const res = await fetch(`tables/${table}/${id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(merged)
    });
    if (!res.ok) {
      let msg = `PUT(patch) ${table}/${id} failed: ${res.status}`;
      try { const e = await res.json(); msg += ' ' + JSON.stringify(e); } catch(_){}
      console.error('[API.patch→PUT]', msg);
      throw new Error(msg);
    }
    const ct = res.headers.get('content-type') || '';
    if (!ct.includes('application/json')) return merged;
    return res.json().catch(() => merged);
  }
};

