// ── ジャンル選択ウィジェット生成 ──
function buildGenreWidget(wrapperId, hiddenId, currentVal = '') {
  const wrap = document.getElementById(wrapperId);
  if (!wrap) return;
  const selected = new Set(
    currentVal ? currentVal.split(',').map(s => s.trim()).filter(Boolean) : []
  );

  const updateHidden = () => {
    document.getElementById(hiddenId).value = [...selected].join(', ');
    wrap.querySelectorAll('.gw-tag').forEach(t => {
      t.classList.toggle('gw-tag--on', selected.has(t.dataset.val));
    });
    const allBtn = wrap.querySelector('.gw-all-btn');
    if (allBtn) allBtn.classList.toggle('gw-all-btn--on', selected.size === INF_GENRES.length);
  };

  wrap.innerHTML = `
    <div class="gw-toolbar">
      <button type="button" class="gw-all-btn">すべて選択</button>
      <button type="button" class="gw-clear-btn">クリア</button>
    </div>
    <div class="gw-tags">
      ${INF_GENRES.map(g => `<button type="button" class="gw-tag${selected.has(g) ? ' gw-tag--on' : ''}" data-val="${g}">${g}</button>`).join('')}
    </div>
  `;

  wrap.querySelectorAll('.gw-tag').forEach(btn => {
    btn.addEventListener('click', () => {
      const v = btn.dataset.val;
      selected.has(v) ? selected.delete(v) : selected.add(v);
      updateHidden();
    });
  });
  wrap.querySelector('.gw-all-btn').addEventListener('click', () => {
    if (selected.size === INF_GENRES.length) {
      selected.clear();
    } else {
      INF_GENRES.forEach(g => selected.add(g));
    }
    updateHidden();
  });
  wrap.querySelector('.gw-clear-btn').addEventListener('click', () => {
    selected.clear();
    updateHidden();
  });
}

// ── エリア選択ウィジェット生成 ──
function buildAreaWidget(wrapperId, hiddenId, currentVal = '') {
  const wrap = document.getElementById(wrapperId);
  if (!wrap) return;
  const selected = new Set(
    currentVal ? currentVal.split(',').map(s => s.trim()).filter(Boolean) : []
  );

  const updateHidden = () => {
    document.getElementById(hiddenId).value = [...selected].join(', ');
    wrap.querySelectorAll('.aw-pref-btn').forEach(b => {
      b.classList.toggle('aw-pref-btn--on', selected.has(b.dataset.val));
    });
    wrap.querySelectorAll('.aw-region-hd').forEach(hd => {
      const region = hd.dataset.region;
      const prefs  = INF_AREA_MAP[region] || [];
      const allOn  = prefs.length > 0 && prefs.every(p => selected.has(p));
      hd.querySelector('.aw-region-all').classList.toggle('aw-region-all--on', allOn);
    });
  };

  const regions = Object.keys(INF_AREA_MAP);
  wrap.innerHTML = regions.map(region => {
    const prefs = INF_AREA_MAP[region];
    return `
      <div class="aw-region">
        <div class="aw-region-hd" data-region="${region}">
          <span class="aw-region-name">${region}</span>
          <button type="button" class="aw-region-all" data-region="${region}" title="${region}を一括選択">一括</button>
        </div>
        <div class="aw-prefs">
          ${prefs.map(p => `<button type="button" class="aw-pref-btn${selected.has(p) ? ' aw-pref-btn--on' : ''}" data-val="${p}">${p}</button>`).join('')}
        </div>
      </div>`;
  }).join('');

  wrap.querySelectorAll('.aw-pref-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const v = btn.dataset.val;
      selected.has(v) ? selected.delete(v) : selected.add(v);
      updateHidden();
    });
  });
  wrap.querySelectorAll('.aw-region-all').forEach(btn => {
    btn.addEventListener('click', () => {
      const prefs = INF_AREA_MAP[btn.dataset.region] || [];
      const allOn = prefs.every(p => selected.has(p));
      if (allOn) { prefs.forEach(p => selected.delete(p)); }
      else        { prefs.forEach(p => selected.add(p));    }
      updateHidden();
    });
  });
}
/**
 * avatarHtml(inf, size)
 * インフルエンサーのアイコン HTML を生成する共通ヘルパー。
 */
function avatarHtml(inf, size = 30) {
  const fontSize = Math.round(size * 0.42);
  const base = `width:${size}px;height:${size}px;font-size:${fontSize}px;flex-shrink:0;`;
  if (inf && inf.avatar_image) {
    return `<div class="inf-avatar inf-avatar--img" style="${base}position:relative;overflow:hidden;border-radius:50%;background:#d1d5db;border:1.5px solid #9ca3af;">`
      + `<img src="${escHtml(inf.avatar_image)}" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;border-radius:50%;" alt="${escHtml((inf.name||'').slice(0,1))}">`
      + `</div>`;
  }
  return `<div class="inf-avatar" style="${base}"><i class="fas fa-camera"></i></div>`;
}

function showToast(message, type = 'success') {
  const icons = { success: 'fa-check-circle', error: 'fa-exclamation-circle', info: 'fa-info-circle' };
  const container = document.getElementById('toastContainer');
  const toast = document.createElement('div');
  toast.className = `toast ${type}`;
  toast.innerHTML = `<i class="fas ${icons[type]}"></i><span>${message}</span>`;
  container.appendChild(toast);
  setTimeout(() => {
    toast.style.animation = 'toastIn .3s ease reverse';
    setTimeout(() => toast.remove(), 300);
  }, 3000);
}

// ===== モーダル制御 =====
function openModal(id) {
  document.getElementById(id).classList.add('open');
}
function closeModal(id) {
  document.getElementById(id).classList.remove('open');
}

document.querySelectorAll('[data-modal]').forEach(btn => {
  btn.addEventListener('click', () => closeModal(btn.dataset.modal));
});
document.querySelectorAll('.modal-overlay').forEach(overlay => {
  overlay.addEventListener('click', e => {
    if (e.target === overlay) closeModal(overlay.id);
  });
});

// ===== グローバルキャッシュ =====
const Cache = {
  clients         : null,
  influencers     : null,
  projects        : null,
  projectInfluencers: null,
  client_contacts : null,
  clients_all     : null,
  projectGroups   : null,
  tickets         : null,
  ticket_categories: null,
  ticket_products : null,
  products        : null,
  _ts          : {},
  TTL          : 30000,
  async get(key, fetchFn) {
    const now = Date.now();
    if (this[key] && (now - (this._ts[key] || 0)) < this.TTL) return this[key];
    this[key] = await fetchFn();
    this._ts[key] = now;
    return this[key];
  },
  invalidate(...keys) {
    keys.forEach(k => { this[k] = null; this._ts[k] = 0; });
  },
  invalidateAll() {
    Object.keys(this).forEach(k => {
      if (k !== '_ts' && k !== 'TTL' && typeof this[k] !== 'function') {
        this[k] = null;
        this._ts[k] = 0;
      }
    });
  }
};

// ===== ユーティリティ =====
/**
 * parseSnsUrls(val)
 * sns_urls フィールドを安全にオブジェクトへ変換する。
 * API は文字列または既にパース済みオブジェクトで返す場合があるため両方に対応。
 * @param {string|object|null} val
 * @returns {object}  例: { Instagram: 'https://...' }
 */
function parseSnsUrls(val) {
  if (!val) return {};
  if (typeof val === 'object') return val;          // すでにオブジェクト
  try { return JSON.parse(val); } catch { return {}; } // JSON文字列
}
function formatDate(str) {
  if (!str) return '—';
  return str.replace(/-/g, '/');
}

// ── 日本の祝日判定 ──
function isJapaneseHoliday(date) {
  const y = date.getFullYear();
  const m = date.getMonth() + 1;
  const d = date.getDate();
  const w = date.getDay();

  const fixedHolidays = [
    [1, 1], [2, 11], [2, 23], [4, 29],
    [5, 3], [5, 4],  [5, 5],  [8, 11],
    [11, 3], [11, 23],
  ];
  if (fixedHolidays.some(([fm, fd]) => m === fm && d === fd)) return true;

  const nthMonday = (month, n) => {
    if (m !== month) return false;
    if (w !== 1) return false;
    return Math.ceil(d / 7) === n;
  };
  if (nthMonday(1, 2)) return true;
  if (nthMonday(7, 3)) return true;
  if (nthMonday(9, 3)) return true;
  if (nthMonday(10, 2)) return true;

  if (m === 3) {
    const shunbun = Math.floor(20.8431 + 0.242194 * (y - 1980) - Math.floor((y - 1980) / 4));
    if (d === shunbun) return true;
  }
  if (m === 9) {
    const shubun = Math.floor(23.2488 + 0.242194 * (y - 1980) - Math.floor((y - 1980) / 4));
    if (d === shubun) return true;
  }

  if (w === 1) {
    const prev = new Date(date);
    prev.setDate(prev.getDate() - 1);
    if (isJapaneseHoliday(prev)) return true;
  }

  return false;
}

// 土日祝を避けた前倒し平日
function toPrevWeekday(date) {
  const d = new Date(date);
  while (d.getDay() === 0 || d.getDay() === 6 || isJapaneseHoliday(d)) {
    d.setDate(d.getDate() - 1);
  }
  return d;
}

// end_date(YYYY-MM-DD)を受け取り、翌月末日の「直前平日」を返す（YYYY/MM/DD）
function calcPaymentDeadline(endDateStr) {
  if (!endDateStr) return null;
  const base = new Date(endDateStr + 'T00:00:00');
  if (isNaN(base.getTime())) return null;
  const nextMonthEnd = new Date(base.getFullYear(), base.getMonth() + 2, 0);
  const workday = toPrevWeekday(nextMonthEnd);
  const y = workday.getFullYear();
  const mo = String(workday.getMonth() + 1).padStart(2, '0');
  const da = String(workday.getDate()).padStart(2, '0');
  return `${y}/${mo}/${da}`;
}

// 入金通知書用：投稿日の翌月末日（土日祝は直前平日・YYYY-MM-DD形式）
function calcNoticeDueDate(postDateStr) {
  if (!postDateStr) return '';
  const base = new Date(postDateStr + 'T00:00:00');
  if (isNaN(base.getTime())) return '';
  const nextMonthEnd = new Date(base.getFullYear(), base.getMonth() + 2, 0);
  const workday = toPrevWeekday(nextMonthEnd);
  const y  = workday.getFullYear();
  const mo = String(workday.getMonth() + 1).padStart(2, '0');
  const da = String(workday.getDate()).padStart(2, '0');
  return `${y}-${mo}-${da}`;
}

function formatMoney(val) {
  if (val == null || val === '') return '—';
  return '¥' + Number(val).toLocaleString();
}

function formatFollowers(val) {
  if (!val) return '—';
  const n = Number(val);
  if (n >= 10000) return (n / 10000).toFixed(1) + '万';
  return n.toLocaleString();
}

function escHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/** escHtml + 改行を <br> に変換 */
function escHtmlNl(str) {
  return escHtml(str).replace(/\n/g, '<br>');
}

