/**
 * parseSnsType(snsType)
 * "Instagram*,TikTok,YouTube" → [{ name, isMain }, ...]
 * メインが未設定の場合は先頭をメインとして扱う
 */
function parseSnsType(snsType) {
  if (!snsType) return [];
  const raw = snsType.split(',').map(s => s.trim()).filter(Boolean);
  const items = raw.map(s => ({ name: s.endsWith('*') ? s.slice(0,-1) : s, isMain: s.endsWith('*') }));
  if (items.length > 0 && !items.some(i => i.isMain)) items[0].isMain = true; // 旧形式互換
  return items;
}

/**
 * parseSnsInsights(jsonStr)
 * JSON文字列 → { Instagram: { reach, likes, comments, saves }, ... }
 */
function parseSnsInsights(jsonStr) {
  if (!jsonStr) return {};
  // D1 APIがすでにオブジェクトとして返す場合はそのまま使用（JSON二重パース問題対策）
  if (typeof jsonStr === 'object') return jsonStr;
  try { return JSON.parse(jsonStr); } catch { return {}; }
}

/**
 * snsIconTag(snsName)  アイコン <i> タグを返す
 */
function snsIconTag(name) {
  const icon   = snsIconMap[name] || 'fa-share-alt';
  const prefix = snsFabSet.has(icon) ? 'fab' : 'fas';
  return `<i class="${prefix} ${icon}"></i>`;
}

/**
 * snsBadge(sns, url)
 * 表示ルール:
 *   - メインSNS（* 付き）のみバッジ表示
 *   - サブSNSが1件以上あれば「他N」バッジを追加
 *   - * なし単体 or 旧形式（単一値）は全件そのまま表示
 */
function snsBadge(sns, url, urlsObj) {
  if (!sns) return '';

  const raw = sns.split(',').map(s => s.trim()).filter(Boolean);
  if (raw.length === 0) return '';

  // メイン(*付き)を探す
  const mainItem = raw.find(s => s.endsWith('*'));
  const mainName = mainItem ? mainItem.slice(0, -1) : null;
  const subCount = mainName ? raw.filter(s => !s.endsWith('*')).length : 0;

  // 表示対象：メインがあればメインのみ、なければ全件（旧形式互換）
  const displayList = mainName
    ? [{ name: mainName, isMain: true }]
    : raw.map(s => ({ name: s, isMain: false }));

  // urlsObj: { Instagram: 'https://...', TikTok: 'https://...' } 形式
  const resolvedUrlsObj = urlsObj || {};
  // account_url（旧フィールド）をメインSNSのフォールバックとして登録
  if (url && mainName && !resolvedUrlsObj[mainName]) {
    resolvedUrlsObj[mainName] = url;
  }

  const badges = displayList.map(({ name: s, isMain }, i) => {
    const icon   = snsIconMap[s] || 'fa-share-alt';
    const cls    = snsCssMap[s]  || 'sns-other';
    const prefix = snsFabSet.has(icon) ? 'fab' : 'fas';
    const iconTag = `<i class="${prefix} ${icon}"></i>`;
    // urlsObj から SNS名でURL取得、なければ i===0 で account_url フォールバック
    const snsUrl = resolvedUrlsObj[s] || (i === 0 ? url : '');
    if (snsUrl) {
      return `<a href="${escHtml(snsUrl)}" target="_blank" rel="noopener" draggable="false" class="sns-badge ${cls} sns-link" title="${escHtml(s)}のページを開く">${iconTag}${escHtml(s)}</a>`;
    }
    return `<span class="sns-badge ${cls}">${iconTag}${escHtml(s)}</span>`;
  }).join('');

  // サブSNSがあれば「他N」バッジを追加（クリック展開）
  const otherTag = subCount > 0
    ? `<span class="sns-other-count">他${subCount}</span>`
    : '';

  return badges + otherTag;
}

/**
 * snsBadgeForInf(inf)
 * インフルエンサーオブジェクトから sns_urls と account_url を解決して snsBadge を呼ぶ便利ラッパー
 */
function snsBadgeForInf(inf) {
  if (!inf) return '';
  const urlsObj = parseSnsUrls(inf.sns_urls);
  return snsBadge(inf.sns_type, inf.account_url, urlsObj);
}

/**
 * snsBadgeAll(sns, url)
 * 全SNSを展開して表示（インサイト登録など詳細表示用）
 */
function snsBadgeAll(sns, url) {
  if (!sns) return '';
  const raw = sns.split(',').map(s => s.trim()).filter(Boolean);
  if (raw.length === 0) return '';
  return raw.map((s, i) => {
    const name   = s.endsWith('*') ? s.slice(0, -1) : s;
    const isMain = s.endsWith('*');
    const icon   = snsIconMap[name] || 'fa-share-alt';
    const cls    = snsCssMap[name]  || 'sns-other';
    const prefix = snsFabSet.has(icon) ? 'fab' : 'fas';
    const iconTag = `<i class="${prefix} ${icon}"></i>`;
    const mainTag = isMain ? `<span class="sns-main-tag-sm">メイン</span>` : '';
    if (url && i === 0) {
      return `<a href="${escHtml(url)}" target="_blank" rel="noopener" draggable="false" class="${cls} sns-link" title="${escHtml(name)}ページを開く">${iconTag}${escHtml(name)}${mainTag}</a>`;
    }
    return `<span class="sns-badge ${cls}">${iconTag}${escHtml(name)}${mainTag}</span>`;
  }).join('');
}

// 国籍バッジ（フラグ絵文字＋ラベル）
function nationalityBadge(nationality) {
  if (!nationality) return '';
  const flagMap = { '日本':'🇯🇵', '韓国':'🇰🇷', '中国':'🇨🇳', '台湾':'🇹🇼', 'アメリカ':'🇺🇸', 'その他':'🌏' };
  const flag = flagMap[nationality] || '🌏';
  return `<span class="inf-nationality-badge">${flag} ${escHtml(nationality)}</span>`;
}
