// ===== ダッシュボード =====
let _dashMonthlyChart = null;
let _dashVisitDay = 'today';

// カレンダー表示月の状態（デフォルト: 当月）
const _now0 = new Date();
let _dashCalYear  = _now0.getFullYear();
let _dashCalMonth = _now0.getMonth();   // 0-indexed
// カレンダーから選択された特定日付（YYYY-MM-DD | null）
let _dashCalSelectedDate = null;

// ── 決算期ユーティリティ ──
// fiscalMonth: 1〜12（例: 4月始まりなら4）
// 今日の日付が属する「決算期年度の開始日」を返す
function _fiscalYearStart(today, fiscalMonth) {
  const m = (fiscalMonth || 1) - 1; // 0-indexed
  const y = today.getMonth() >= m ? today.getFullYear() : today.getFullYear() - 1;
  return new Date(y, m, 1);
}
// 案件が属する決算期年度ラベルを返す（例: "2025" = 2025年4月〜2026年3月）
function _projFiscalYear(p, fiscalMonth) {
  const fm = (fiscalMonth || 1) - 1;
  let date;
  if (p.start_date) date = new Date(p.start_date);
  else if (p.created_at) date = new Date(p.created_at);
  else return null;
  const y = date.getFullYear();
  const m = date.getMonth();
  return m >= fm ? y : y - 1;
}
// 決算期ラベル文字列（例: "2025年度"）
function _fiscalLabel(year, fiscalMonth) {
  if ((fiscalMonth || 1) === 1) return `${year}年`;
  return `${year}年度（${fiscalMonth}月〜${(fiscalMonth-1)||12}月）`;
}

// ─────────────────────────────────────────────
//  ダッシュボード タブ状態
// ─────────────────────────────────────────────
let _dashCurrentTab = 'overview';  // 'overview' | 'analysis' | 'sales' | 'inf-analysis'
let _dashDataCache  = null;        // 共通データキャッシュ

async function loadDashboard() {
  // タブバーの初期化（1回だけ）
  _initDashPageTabs();

  try {
    // 共通データを取得（両ページで使う）
    const [projectsRes, clientsRes, influencersRes, assignRes,
           productsRes, ticketsRes, ticketCatsRes, companyInfoData] = await Promise.all([
      Cache.get('projects',           () => API.getAll('projects')),
      Cache.get('clients',            () => API.getAll('clients')),
      Cache.get('influencers',        () => API.getAll('influencers', {}, 20)),
      Cache.get('projectInfluencers', () => API.getAll('project_influencers')),
      Cache.get('products',           () => API.getAll('products')),
      Cache.get('tickets',            () => API.getAll('tickets')),
      Cache.get('ticket_categories',  () => API.getAll('ticket_categories')),
      getCompanyInfo(),
    ]);

    const projects    = projectsRes.data    || [];
    const clients     = clientsRes.data     || [];
    const influencers = influencersRes.data  || [];
    const assigns     = assignRes.data      || [];
    const products    = productsRes.data    || [];
    const tickets     = (ticketsRes.data    || []).filter(t => !t.is_deleted);
    const ticketCats  = (ticketCatsRes.data || []).filter(c => !c.is_deleted);

    // 決算期
    const fiscalMonth = (companyInfoData && companyInfoData.fiscal_month)
      ? Number(companyInfoData.fiscal_month) : 1;

    // 共通マップ
    const clientMap = {};
    clients.forEach(c => { clientMap[c.id] = c; });
    const infMap = {};
    influencers.forEach(i => { infMap[i.id] = i; });
    const projMap = {};
    projects.forEach(p => { projMap[p.id] = p; });
    const catMap = {};
    ticketCats.forEach(c => { catMap[c.id] = c; });

    _dashDataCache = { projects, clients, influencers, assigns, products, tickets,
                       ticketCats, fiscalMonth, clientMap, infMap, projMap, catMap };

    // 現在のタブに応じてレンダリング
    if (_dashCurrentTab === 'overview') {
      _renderDashOverview(_dashDataCache);
    } else if (_dashCurrentTab === 'analysis') {
      _renderDashAnalysis(_dashDataCache);
    } else if (_dashCurrentTab === 'inf-analysis') {
      _renderInfAnalysisTable(_dashDataCache);
    } else {
      _renderDashSales(_dashDataCache);
    }

  } catch(err) {
    console.error('[loadDashboard]', err);
    showToast('ダッシュボードの読み込みに失敗しました', 'error');
  }
}

// ─────────────────────────────────────────────
//  ダッシュボード ページ内タブ初期化
// ─────────────────────────────────────────────
function _initDashPageTabs() {
  const bar = document.querySelector('.dash-page-tab-bar');
  if (!bar || bar.dataset.inited === '1') return;
  bar.dataset.inited = '1';

  bar.querySelectorAll('.dash-page-tab').forEach(btn => {
    btn.addEventListener('click', () => {
      bar.querySelectorAll('.dash-page-tab').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      _dashCurrentTab = btn.dataset.dashtab;

      document.querySelectorAll('.dash-page-panel').forEach(p => p.style.display = 'none');
      const panel = document.getElementById(`dash-panel-${_dashCurrentTab}`);
      if (panel) panel.style.display = '';

      // データがすでにあれば即レンダリング
      if (_dashDataCache) {
        if (_dashCurrentTab === 'overview')          _renderDashOverview(_dashDataCache);
        else if (_dashCurrentTab === 'analysis')     _renderDashAnalysis(_dashDataCache);
        else if (_dashCurrentTab === 'inf-analysis') {
          // inf-analysis タブへ切り替え時はフィルターをリセットしてからレンダリング
          _resetInfAnalysisFilter();
          _renderInfAnalysisTable(_dashDataCache);
        }
        else _renderDashSales(_dashDataCache);
      }
    });
  });
}

// ─────────────────────────────────────────────
//  PAGE 1: スケジュール・進行中
// ─────────────────────────────────────────────
function _renderDashOverview({ projects, clients, influencers, assigns, products, tickets,
                                ticketCats, fiscalMonth, clientMap, infMap, projMap, catMap }) {

  // ── 来店予定 ──
  _renderVisitList(assigns, infMap, projMap, _dashVisitDay, _dashCalSelectedDate);
  if (!document.getElementById('page-dashboard')._visitTabBound) {
    document.getElementById('page-dashboard')._visitTabBound = true;
    document.querySelectorAll('.dash-vtab').forEach(btn => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.dash-vtab').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        _dashVisitDay = btn.dataset.day;
        _dashCalSelectedDate = null;           // 日付選択を解除
        // カレンダーの選択ハイライトも外す
        document.querySelectorAll('.dash-cal-day--selected').forEach(el => el.classList.remove('dash-cal-day--selected'));
        _renderVisitList(assigns, infMap, projMap, _dashVisitDay, null);
      });
    });
  }

  // ── 来店スケジュール カレンダー ──
  _renderMonthlyCalendar(assigns, infMap, projMap);

  // ── インフルエンサー案件（進行中）──
  const INF_ACTIVE_STATUS = ['発注済','進行中','投稿完了'];
  const infActive = projects.filter(p => INF_ACTIVE_STATUS.includes(p.status));
  const infBadge  = document.getElementById('dash-inf-active-count');
  if (infBadge) infBadge.textContent = infActive.length;

  const infTbody = document.getElementById('dash-inf-active-tbody');
  if (infTbody) {
    if (infActive.length === 0) {
      infTbody.innerHTML = `<tr><td colspan="4" class="empty" style="padding:20px;">進行中の案件はありません</td></tr>`;
    } else {
      infTbody.innerHTML = infActive.slice(0, 20).map(p => {
        const storeName = p.product_name || '—';
        const from = p.start_date ? p.start_date.slice(0,10) : '—';
        const to   = p.end_date   ? p.end_date.slice(0,10)   : '—';
        return `<tr>
          <td style="font-weight:600;">
            <a href="#" class="proj-link" data-id="${escHtml(p.id)}"
               style="color:var(--primary);">${escHtml(p.project_name||'—')}</a>
          </td>
          <td style="font-size:12px;">${escHtml(storeName)}</td>
          <td style="font-size:11px;white-space:nowrap;">${from}<br>${to}</td>
          <td>${statusBadge(p.status)}</td>
        </tr>`;
      }).join('');
      infTbody.querySelectorAll('.proj-link').forEach(a => {
        a.addEventListener('click', e => {
          e.preventDefault();
          navigateTo('projects');
          setTimeout(() => openProjectDetail(a.dataset.id), 100);
        });
      });
    }
  }

  // ── サブスク/スポット（契約中）──
  const ssActive  = products.filter(p => !p.is_deleted && p.status === '契約中');
  const ssBadge   = document.getElementById('dash-ss-active-count');
  if (ssBadge) ssBadge.textContent = ssActive.length;

  const ssTbody = document.getElementById('dash-ss-active-tbody');
  if (ssTbody) {
    if (ssActive.length === 0) {
      ssTbody.innerHTML = `<tr><td colspan="4" class="empty" style="padding:20px;">契約中のサービスはありません</td></tr>`;
    } else {
      ssTbody.innerHTML = ssActive.slice(0, 20).map(p => {
        const cl      = clientMap[p.client_id];
        const typeInfo = p.product_type === 'subscription'
          ? { label:'サブスク', cls:'badge-sub' }
          : { label:'スポット',  cls:'badge-spot' };
        const amt = p.total_amount != null ? `¥${Number(p.total_amount).toLocaleString()}` : '—';
        return `<tr>
          <td><span class="product-type-badge ${typeInfo.cls}" style="font-size:11px;">${typeInfo.label}</span></td>
          <td style="font-weight:600;font-size:13px;">${escHtml(p.product_name||'—')}</td>
          <td style="font-size:12px;">${cl ? escHtml(cl.company_name) : '—'}</td>
          <td style="font-weight:700;text-align:right;font-size:13px;">${amt}</td>
        </tr>`;
      }).join('');
    }
  }

  // ── チケット（進行中）──
  const tkActive = tickets.filter(t => t.status === '進行中');
  const tkBadge  = document.getElementById('dash-ticket-active-count');
  if (tkBadge) tkBadge.textContent = tkActive.length;

  const tkTbody = document.getElementById('dash-ticket-active-tbody');
  if (tkTbody) {
    if (tkActive.length === 0) {
      tkTbody.innerHTML = `<tr><td colspan="3" class="empty" style="padding:20px;">進行中のチケットはありません</td></tr>`;
    } else {
      tkTbody.innerHTML = tkActive.slice(0, 20).map(t => {
        const cat    = catMap[t.category_id];
        const catClr = cat?.color || '#e2e8f0';
        const catNm  = escHtml(cat?.name || t.category_name || '—');
        const period = [t.start_date, t.end_date].filter(Boolean).map(d => d.slice(0,10)).join(' 〜 ') || '—';
        return `<tr>
          <td style="font-weight:600;font-size:13px;">${escHtml(t.title||'—')}</td>
          <td>
            ${catNm ? `<span style="background:${catClr}20;color:${catClr};border:1px solid ${catClr}50;border-radius:20px;padding:2px 10px;font-size:11px;font-weight:700;">${catNm}</span>` : '—'}
          </td>
          <td style="font-size:11px;white-space:nowrap;">${period}</td>
        </tr>`;
      }).join('');
    }
  }
}

// ── 2か月カレンダー描画 ──
function _renderMonthlyCalendar(assigns, infMap, projMap) {
  const container = document.getElementById('dash-monthly-calendar');
  if (!container) return;

  const realNow = new Date();
  const todayY  = realNow.getFullYear();
  const todayMo = realNow.getMonth();
  const todayD  = realNow.getDate();

  const WDAYS      = ['日','月','火','水','木','金','土'];
  const monthNames = ['1月','2月','3月','4月','5月','6月','7月','8月','9月','10月','11月','12月'];

  // 2か月分の情報を生成するヘルパー
  function buildMonth(y, m) {
    // m は 0-indexed
    const assigns_m = assigns.filter(a => {
      if (!a.visit_datetime) return false;
      const ds = a.visit_datetime.slice(0, 10);
      const [ay, am] = ds.split('-').map(Number);
      return ay === y && (am - 1) === m;
    });
    const dayMap = {};
    assigns_m.forEach(a => {
      const d = parseInt(a.visit_datetime.slice(8, 10), 10);
      if (!dayMap[d]) dayMap[d] = [];
      dayMap[d].push(a);
    });
    const firstDay    = new Date(y, m, 1).getDay();
    const daysInMonth = new Date(y, m + 1, 0).getDate();

    // 選択日（この月のもの）
    let selD = null;
    if (_dashCalSelectedDate) {
      const [sy, sm, sd] = _dashCalSelectedDate.split('-').map(Number);
      if (sy === y && (sm - 1) === m) selD = sd;
    }

    let grid = `<div class="dash-cal-grid">`;
    grid += WDAYS.map((w, i) =>
      `<div class="dash-cal-wday${i===0?' sun':i===6?' sat':''}">${w}</div>`
    ).join('');

    for (let i = 0; i < firstDay; i++) {
      grid += `<div class="dash-cal-day dash-cal-day--empty"></div>`;
    }
    for (let d = 1; d <= daysInMonth; d++) {
      const dow     = (firstDay + d - 1) % 7;
      const list    = dayMap[d] || [];
      const isToday = (d === todayD && m === todayMo && y === todayY);
      const isSel   = (d === selD);
      let cls = 'dash-cal-day';
      if (isToday) cls += ' dash-cal-day--today';
      if (isSel)   cls += ' dash-cal-day--selected';
      if (dow === 0) cls += ' dash-cal-day--sun';
      if (dow === 6) cls += ' dash-cal-day--sat';
      if (list.length > 0) cls += ' dash-cal-day--has-event';

      grid += `<div class="${cls}" data-cyear="${y}" data-cmonth="${m}" data-cday="${d}">
        <span class="dash-cal-date">${d}</span>
        ${list.length > 0 ? `<span class="dash-cal-dot">${list.length}</span>` : ''}
      </div>`;
    }
    grid += `</div>`;

    return { grid, count: assigns_m.length, y, m };
  }

  // 表示する2か月
  let m1y = _dashCalYear,  m1m = _dashCalMonth;
  let m2m = m1m + 1,       m2y = m1y;
  if (m2m > 11) { m2m = 0; m2y++; }

  const mo1 = buildMonth(m1y, m1m);
  const mo2 = buildMonth(m2y, m2m);
  const totalCount = mo1.count + mo2.count;

  const html = `
    <div class="dash-cal-2months">
      <!-- 月ナビヘッダー（2か月分をまとめて操作） -->
      <div class="dash-cal-nav-bar">
        <button class="dash-cal-nav" id="dash-cal-prev" title="前月へ">
          <i class="fas fa-chevron-left"></i>
        </button>
        <span class="dash-cal-range-label">
          ${mo1.y}年 ${monthNames[mo1.m]} ─ ${mo2.y !== mo1.y ? mo2.y+'年 ' : ''}${monthNames[mo2.m]}
          <span class="dash-cal-count">${totalCount}件</span>
        </span>
        <button class="dash-cal-nav" id="dash-cal-next" title="次月へ">
          <i class="fas fa-chevron-right"></i>
        </button>
      </div>

      <!-- 2か月グリッド横並び -->
      <div class="dash-cal-dual">
        <div class="dash-cal-month-block">
          <div class="dash-cal-month-label">${mo1.y}年 ${monthNames[mo1.m]}
            <span class="dash-cal-month-count">${mo1.count}件</span>
          </div>
          ${mo1.grid}
        </div>
        <div class="dash-cal-month-divider"></div>
        <div class="dash-cal-month-block">
          <div class="dash-cal-month-label">${mo2.y}年 ${monthNames[mo2.m]}
            <span class="dash-cal-month-count">${mo2.count}件</span>
          </div>
          ${mo2.grid}
        </div>
      </div>
    </div>
  `;

  container.innerHTML = html;

  // ── 前月 / 次月ボタン ──
  container.querySelector('#dash-cal-prev').addEventListener('click', () => {
    _dashCalMonth--;
    if (_dashCalMonth < 0) { _dashCalMonth = 11; _dashCalYear--; }
    _renderMonthlyCalendar(assigns, infMap, projMap);
  });
  container.querySelector('#dash-cal-next').addEventListener('click', () => {
    _dashCalMonth++;
    if (_dashCalMonth > 11) { _dashCalMonth = 0; _dashCalYear++; }
    _renderMonthlyCalendar(assigns, infMap, projMap);
  });

  // ── 全日付クリック → 来店予定リストに反映 ──
  container.querySelectorAll('.dash-cal-day:not(.dash-cal-day--empty)').forEach(cell => {
    cell.style.cursor = 'pointer';
    cell.addEventListener('click', () => {
      const cy = parseInt(cell.dataset.cyear, 10);
      const cm = parseInt(cell.dataset.cmonth, 10);
      const cd = parseInt(cell.dataset.cday, 10);
      const ds = `${cy}-${String(cm+1).padStart(2,'0')}-${String(cd).padStart(2,'0')}`;

      // 同じ日を再クリック → 選択解除して「今日」に戻す
      if (_dashCalSelectedDate === ds) {
        _dashCalSelectedDate = null;
        _dashVisitDay = 'today';
        container.querySelectorAll('.dash-cal-day--selected').forEach(el => el.classList.remove('dash-cal-day--selected'));
        document.querySelectorAll('.dash-vtab').forEach(b => {
          b.classList.toggle('active', b.dataset.day === 'today');
        });
        _renderVisitList(assigns, infMap, projMap, 'today', null);
        return;
      }

      // 選択更新
      _dashCalSelectedDate = ds;
      _dashVisitDay = null;
      container.querySelectorAll('.dash-cal-day--selected').forEach(el => el.classList.remove('dash-cal-day--selected'));
      cell.classList.add('dash-cal-day--selected');
      document.querySelectorAll('.dash-vtab').forEach(b => b.classList.remove('active'));
      _renderVisitList(assigns, infMap, projMap, null, ds);
    });
  });
}

// ─────────────────────────────────────────────
//  PAGE 2: 分析
// ─────────────────────────────────────────────
// 月別テーブル ソート状態
let _analysisSortCol = 'month';
let _analysisSortDir = 'asc';
// フィルター状態（YYYY-MM）
let _analysisFilterFrom = '';
let _analysisFilterTo   = '';
// キャッシュ済みデータ（フィルター再描画用）
let _analysisDataRef = null;

function _renderDashAnalysis({ projects, clients, influencers, assigns, products, tickets,
                                fiscalMonth, clientMap, infMap }) {
  _analysisDataRef = { projects, clients, influencers, assigns, products, tickets,
                       fiscalMonth, clientMap, infMap };

  // ── コスト計算ヘルパー ──
  const _assignCost = proj => assigns
    .filter(a => a.project_id === proj.id)
    .reduce((s, a) => {
      const inf = infMap[a.influencer_id];
      let v = a.request_amount;
      if (v === null || v === undefined || v === '') v = inf ? inf.unit_price : null;
      const n = (v === null || v === undefined || v === '') ? 0
        : parseFloat(String(v).replace(/[^0-9.-]/g, ''));
      return s + (isNaN(n) ? 0 : n);
    }, 0);

  const today  = new Date();
  const curFY  = _projFiscalYear({ start_date: today.toISOString().slice(0,10) }, fiscalMonth);
  const prevFY = curFY - 1;
  const fm     = (fiscalMonth||1) - 1;
  const curM   = today.getMonth();
  const curY2  = today.getFullYear();

  // ── カテゴリ別当期合計 ──
  const ytdProjects = projects.filter(p => _projFiscalYear(p, fiscalMonth) === curFY);
  const prevProjects= projects.filter(p => _projFiscalYear(p, fiscalMonth) === prevFY);
  const infSales    = ytdProjects.reduce((s, p) => s + (Number(p.budget)||0), 0);
  const prevInfSales= prevProjects.reduce((s, p) => s + (Number(p.budget)||0), 0);

  // サブスク/スポット（contractYearByDate: start_date が当期内のもの）
  const ssProd = (products||[]).filter(p => {
    if (!p.start_date) return false;
    const fy = _projFiscalYear({ start_date: p.start_date }, fiscalMonth);
    return fy === curFY;
  });
  const prevSsProd = (products||[]).filter(p => {
    if (!p.start_date) return false;
    return _projFiscalYear({ start_date: p.start_date }, fiscalMonth) === prevFY;
  });
  const ssSales     = ssProd.reduce((s, p) => s + (Number(p.total_amount)||0), 0);
  const prevSsSales = prevSsProd.reduce((s, p) => s + (Number(p.total_amount)||0), 0);

  // チケット販売
  const tkItems = (tickets||[]).filter(t => {
    if (!t.start_date) return false;
    return _projFiscalYear({ start_date: t.start_date }, fiscalMonth) === curFY;
  });
  const prevTkItems = (tickets||[]).filter(t => {
    if (!t.start_date) return false;
    return _projFiscalYear({ start_date: t.start_date }, fiscalMonth) === prevFY;
  });
  const tkSales     = tkItems.reduce((s, t) => s + (Number(t.total_amount)||Number(t.budget)||0), 0);
  const prevTkSales = prevTkItems.reduce((s, t) => s + (Number(t.total_amount)||Number(t.budget)||0), 0);

  const ytdSales  = infSales + ssSales + tkSales;
  const prevSales = prevInfSales + prevSsSales + prevTkSales;
  const yoy = prevSales > 0 ? ((ytdSales - prevSales) / prevSales * 100) : null;

  const ytdCost   = ytdProjects.reduce((s, p) => s + _assignCost(p), 0);
  const ytdProfit = ytdSales - ytdCost;

  const ytdMargins = ytdProjects
    .filter(p => Number(p.budget) > 0)
    .map(p => { const b = Number(p.budget); const c = _assignCost(p); return (b - c) / b * 100; });
  const avgMargin = ytdMargins.length > 0
    ? ytdMargins.reduce((s, v) => s + v, 0) / ytdMargins.length : null;

  // ── 前月比計算 ──
  const prevM  = curM === 0 ? 11 : curM - 1;
  const prevMY = curM === 0 ? curY2 - 1 : curY2;
  const sumInfByMonth = (y, m) => projects
    .filter(p => { if (!p.start_date) return false; const d = new Date(p.start_date); return d.getFullYear()===y && d.getMonth()===m; })
    .reduce((s, p) => s + (Number(p.budget)||0), 0);
  const sumSsByMonth = (y, m) => (products||[])
    .filter(p => { if (!p.start_date) return false; const d = new Date(p.start_date); return d.getFullYear()===y && d.getMonth()===m; })
    .reduce((s, p) => s + (Number(p.total_amount)||0), 0);
  const sumTkByMonth = (y, m) => (tickets||[])
    .filter(t => { if (!t.start_date) return false; const d = new Date(t.start_date); return d.getFullYear()===y && d.getMonth()===m; })
    .reduce((s, t) => s + (Number(t.total_amount)||Number(t.budget)||0), 0);

  const thisMoSales = sumInfByMonth(curY2, curM) + sumSsByMonth(curY2, curM) + sumTkByMonth(curY2, curM);
  const lastMoSales = sumInfByMonth(prevMY, prevM) + sumSsByMonth(prevMY, prevM) + sumTkByMonth(prevMY, prevM);
  const mom = lastMoSales > 0 ? ((thisMoSales - lastMoSales) / lastMoSales * 100) : null;

  // ── 売上KPIバー ──
  document.getElementById('dash-sales-ytd').textContent  = formatMoney(ytdSales);
  document.getElementById('dash-sales-profit').innerHTML =
    `<span style="color:${ytdProfit>=0?'#86efac':'#fca5a5'}">${formatMoney(ytdProfit)}</span>`;
  document.getElementById('dash-sales-yoy').innerHTML    = yoy !== null
    ? `<span style="color:${yoy>=0?'#86efac':'#fca5a5'}">${yoy>=0?'▲':'▼'}${Math.abs(yoy).toFixed(1)}%</span>`
    : '<span style="color:rgba(255,255,255,0.5)">—</span>';
  document.getElementById('dash-sales-count').textContent = `${ytdProjects.length}件`;
  document.getElementById('dash-sales-avg').textContent   = ytdProjects.length>0
    ? formatMoney(Math.round(infSales/ytdProjects.length)) : '—';
  document.getElementById('dash-sales-margin').innerHTML  = avgMargin !== null
    ? `<span style="color:${avgMargin>=30?'#86efac':'#fca5a5'}">${avgMargin.toFixed(1)}%</span>`
    : '<span style="color:rgba(255,255,255,0.5)">—</span>';

  // ── 前月比・前年比サマリーカード ──
  const compareEl = document.getElementById('dash-compare-row');
  if (compareEl) {
    const monthNames = ['1月','2月','3月','4月','5月','6月','7月','8月','9月','10月','11月','12月'];
    const card = (icon, label, val, diff, diffLabel) => {
      const isPos = diff === null ? null : diff >= 0;
      const diffHtml = diff === null
        ? `<span class="dash-cmp-diff neutral">データ不足</span>`
        : `<span class="dash-cmp-diff ${isPos?'up':'down'}">
            <i class="fas fa-arrow-${isPos?'up':'down'}"></i>
            ${Math.abs(diff).toFixed(1)}% ${diffLabel}
           </span>`;
      return `<div class="dash-cmp-card">
        <div class="dash-cmp-icon"><i class="${icon}"></i></div>
        <div class="dash-cmp-body">
          <div class="dash-cmp-label">${label}</div>
          <div class="dash-cmp-value">${val}</div>
          ${diffHtml}
        </div>
      </div>`;
    };
    compareEl.innerHTML =
      card('fas fa-calendar-day', `${monthNames[curM]}売上`, formatMoney(thisMoSales), mom, '前月比') +
      card('fas fa-calendar-alt', `当期累計売上`, formatMoney(ytdSales), yoy, '前期比') +
      card('fas fa-coins', `当期利益`, formatMoney(ytdProfit),
           ytdSales>0 ? (ytdProfit/ytdSales*100) : null, '利益率') +
      card('fas fa-percentage', '平均利益率', avgMargin!==null?`${avgMargin.toFixed(1)}%`:'—',
           avgMargin!==null?(avgMargin-30):null, 'vs 30%目標');
  }

  // ── カテゴリ別売上比率 ──
  const ratioEl = document.getElementById('dash-ratio-body');
  if (ratioEl) {
    const cats = [
      { label: 'インフルエンサー案件', val: infSales,  color: '#6366f1', icon: 'fas fa-users' },
      { label: 'サブスク/スポット',    val: ssSales,   color: '#10b981', icon: 'fas fa-tags' },
      { label: 'チケット販売',         val: tkSales,   color: '#f59e0b', icon: 'fas fa-ticket-alt' },
    ];
    const total = ytdSales || 1;
    ratioEl.innerHTML = `
      <div class="dash-ratio-bars">
        <div class="dash-ratio-stacked">
          ${cats.map(c => {
            const pct = (c.val/total*100);
            return pct > 0 ? `<div class="dash-ratio-seg" style="width:${pct.toFixed(2)}%;background:${c.color};" title="${c.label}: ${formatMoney(c.val)} (${pct.toFixed(1)}%)"></div>` : '';
          }).join('')}
        </div>
      </div>
      <div class="dash-ratio-legend">
        ${cats.map(c => {
          const pct = (c.val/total*100).toFixed(1);
          return `<div class="dash-ratio-item">
            <span class="dash-ratio-dot" style="background:${c.color};"></span>
            <span class="dash-ratio-lbl"><i class="${c.icon}"></i> ${c.label}</span>
            <span class="dash-ratio-val">${formatMoney(c.val)}</span>
            <span class="dash-ratio-pct">${pct}%</span>
          </div>`;
        }).join('')}
      </div>`;
  }

  // ── 月別売上テーブル ──
  _renderAnalysisTable({ projects, products, tickets, fiscalMonth, assigns, infMap });

  // フィルター初期値セット（当期の開始月〜当月に常に初期化）
  const fromInput = document.getElementById('dash-filter-from');
  const toInput   = document.getElementById('dash-filter-to');
  if (fromInput && toInput) {
    const fyStart = new Date(curFY, fm, 1);
    const fyEndM  = (fm + 11) % 12;
    const fyEndY  = fm === 0 ? curFY : (fyEndM < fm ? curFY + 1 : curFY);
    const fyEnd   = new Date(fyEndY, fyEndM + 1, 0); // 期末月の末日

    // 当期開始月〜期末月（または当月のどちらか早い方）
    const defFrom = `${fyStart.getFullYear()}-${String(fyStart.getMonth()+1).padStart(2,'0')}`;
    const curYM   = `${curY2}-${String(curM+1).padStart(2,'0')}`;
    const fyEndYM = `${fyEnd.getFullYear()}-${String(fyEnd.getMonth()+1).padStart(2,'0')}`;
    const defTo   = curYM < fyEndYM ? curYM : fyEndYM;

    // まだバインドされていない場合のみイベントを登録
    if (!fromInput._bound) {
      fromInput._bound = true;
      document.getElementById('dash-filter-apply').addEventListener('click', () => {
        _analysisFilterFrom = fromInput.value;
        _analysisFilterTo   = toInput.value;
        if (_analysisDataRef) _renderAnalysisTable(_analysisDataRef);
      });
      document.getElementById('dash-filter-reset').addEventListener('click', () => {
        fromInput.value = fromInput._defFrom || defFrom;
        toInput.value   = toInput._defTo   || defTo;
        _analysisFilterFrom = fromInput.value;
        _analysisFilterTo   = toInput.value;
        if (_analysisDataRef) _renderAnalysisTable(_analysisDataRef);
      });
    }
    // 決算期が変わった場合も含め、常にデフォルト値を更新
    fromInput._defFrom = defFrom;
    toInput._defTo     = defTo;
    fromInput.value    = defFrom;
    toInput.value      = defTo;
    _analysisFilterFrom = defFrom;
    _analysisFilterTo   = defTo;
  }

  // ── AI戦略：毎日00:00に自動更新 ──
  _autoRefreshDailyStrategy('analysis', {
    ytdSales, prevSales, yoy, ytdProfit, avgMargin, mom,
    infSales, ssSales, tkSales,
    ytdProjectCount: ytdProjects.length, prevProjectCount: prevProjects.length,
    clientCount: clients.length, elapsedMonths: (curM - fm + 12) % 12 + 1,
  });
}

// ── インフルエンサー分析テーブル描画 ──
let _infAnalysisSortKey  = 'assign_desc';
let _infAnalysisSearch   = '';
let _infAnalysisDataRef  = null;
let _infAnalysisInited   = false;
// 期間フィルター（YYYY-MM）
let _infAFromYM = '';
let _infAToYM   = '';

// ── フィルター変数をリセットしUIを「全期間」に同期 ──
function _resetInfAnalysisFilter() {
  _infAFromYM = '';
  _infAToYM   = '';
  _infAnalysisSearch = '';
  _infAnalysisSortKey = 'assign_desc';
  // UI 同期
  const fromEl   = document.getElementById('ia-period-from');
  const toEl     = document.getElementById('ia-period-to');
  const searchEl = document.getElementById('inf-analysis-search');
  const sortEl   = document.getElementById('inf-analysis-sort');
  if (fromEl)   fromEl.value   = '';
  if (toEl)     toEl.value     = '';
  if (searchEl) searchEl.value = '';
  if (sortEl)   sortEl.value   = 'assign_desc';
  // プリセットボタン：全期間をactive化
  document.querySelectorAll('.ia-preset-btn').forEach(b => {
    b.classList.toggle('active', b.dataset.iaPreset === 'all');
  });
}

// ── 期間内か判定（assigns の基準日：visit_datetime > post_date > 案件 start_date の優先順）
function _infAInRange(a, projMap) {
  const from = _infAFromYM;
  const to   = _infAToYM;
  if (!from && !to) return true;           // フィルターなし → 全件
  // 基準日の取得
  let dateStr = a.visit_datetime || a.post_date || null;
  if (!dateStr) {
    const proj = projMap ? projMap[a.project_id] : null;
    dateStr = proj ? (proj.start_date || null) : null;
  }
  if (!dateStr) return true;              // 日付不明は含める
  const ym = dateStr.slice(0, 7);         // "YYYY-MM"
  if (from && ym < from) return false;
  if (to   && ym > to  ) return false;
  return true;
}

function _renderInfAnalysisTable({ influencers, assigns, infMap, projMap }) {
  _infAnalysisDataRef = { influencers, assigns, infMap, projMap };
  const tbody = document.getElementById('inf-analysis-tbody');
  if (!tbody) return;

  // ── 期間でアサインを絞り込み ──
  const filteredAssigns = assigns.filter(a => {
    // キャンセル案件は除外
    const proj = projMap ? projMap[a.project_id] : null;
    if (proj && proj.status === 'キャンセル') return false;
    // ★ request_status によるフィルタリングは廃止（候補・確定等ステータスを無視して全件カウント）
    return _infAInRange(a, projMap);
  });

  // ── 各インフルエンサーの集計 ──
  const rows = influencers.map(inf => {
    const myAssigns = filteredAssigns.filter(a =>
      a.influencer_id === inf.id && a.group_name !== EXCLUDED_GROUP
    );
    const assignCount = myAssigns.length;

    // ── 累計支払金額
    // request_amount が入力済みのものだけ使う（フォールバック廃止：unit_priceで補填すると全案件に掛けて過大になる）
    const totalPaid = myAssigns.reduce((s, a) => {
      const v = a.request_amount;
      if (v === null || v === undefined || v === '') return s;
      const n = parseFloat(String(v).replace(/[^0-9.-]/g, ''));
      return s + (isNaN(n) ? 0 : n);
    }, 0);

    // ── 累計リーチ（reach がある投稿のみ）
    const totalReach = myAssigns.reduce((s, a) => {
      const n = Number(a.reach);
      return s + (n > 0 ? n : 0);
    }, 0);

    // ── CPR（Cost per Reach）: 累計支払 ÷ 累計リーチ
    const cpr = (totalPaid > 0 && totalReach > 0) ? totalPaid / totalReach : null;

    // ── フォロワー数
    const followers = Number(inf.followers) || 0;

    // スコアと同一のsns_insights SNS合算 + フォールバックreachで平均ER算出
    const _erSnsList = parseSnsType(inf.sns_type);
    const _getMetrics = a => {
      let reach = 0, likes = 0, comments = 0, saves = 0;
      if (a.sns_insights) {
        try {
          const db = JSON.parse(a.sns_insights);
          _erSnsList.forEach(s => {
            const d = db[s.name] || {};
            reach    += Number(d.reach)    || 0;
            likes    += Number(d.likes)    || 0;
            comments += Number(d.comments) || 0;
            saves    += Number(d.saves)    || 0;
          });
        } catch(e) {}
      }
      if (reach    === 0) reach    = Number(a.reach)    || 0;
      if (likes    === 0) likes    = Number(a.likes)    || 0;
      if (comments === 0) comments = Number(a.comments) || 0;
      if (saves    === 0) saves    = Number(a.saves)    || 0;
      return { reach, likes, comments, saves };
    };
    // リーチ>0の案件のみを対象（インサイト入力済み件数が分母）
    const withReach = myAssigns.filter(a => _getMetrics(a).reach > 0);
    let avgER = null, avgReach = null, avgSaves = null;
    if (withReach.length > 0) {
      let erSum = 0, reachSum = 0, savesSum = 0;
      withReach.forEach(a => {
        const { reach, likes, comments, saves } = _getMetrics(a);
        if (reach > 0) {
          erSum    += (likes + comments + saves) / reach * 100;
          reachSum += reach;
          savesSum += saves;
        }
      });
      avgER    = erSum    / withReach.length;
      avgReach = Math.round(reachSum / withReach.length);
      avgSaves = Math.round(savesSum / withReach.length);
    }

    // ── 得意ジャンル上位（期間内アサインから集計）
    const foodGenreCount = {};
    myAssigns.forEach(a => {
      const proj = projMap ? projMap[a.project_id] : null;
      if (proj && proj.food_genre) {
        foodGenreCount[proj.food_genre] = (foodGenreCount[proj.food_genre] || 0) + 1;
      }
    });
    const topGenres = Object.entries(foodGenreCount)
      .sort((a, b) => b[1] - a[1]).slice(0, 2).map(e => e[0]);

    return { inf, assignCount, totalPaid, totalReach, cpr, avgER, avgReach, avgSaves, followers, topGenres };
  });

  // ── 検索フィルター ──
  const q = _infAnalysisSearch.toLowerCase();
  const filtered = rows.filter(r =>
    !q ||
    (r.inf.name    ||'').toLowerCase().includes(q) ||
    (r.inf.sub_name||'').toLowerCase().includes(q)
  );

  // ── ソート ──
  const sortFns = {
    assign_desc:    (a, b) => b.assignCount - a.assignCount,
    unitprice_desc: (a, b) => (Number(b.inf.unit_price)||0) - (Number(a.inf.unit_price)||0),
    followers_desc: (a, b) => b.followers   - a.followers,
    er_desc:        (a, b) => (b.avgER    ?? -1) - (a.avgER    ?? -1),
    paid_desc:      (a, b) => b.totalPaid  - a.totalPaid,
    saves_desc:     (a, b) => (b.avgSaves ?? -1) - (a.avgSaves ?? -1),
  };
  filtered.sort(sortFns[_infAnalysisSortKey] || sortFns.assign_desc);

  // ── 集計サマリー更新 ──
  const statEl = document.getElementById('ia-period-stat');
  if (statEl) {
    const activeInf = filtered.filter(r => r.assignCount > 0).length;
    const totalPaidAll = filtered.reduce((s, r) => s + r.totalPaid, 0);
    const totalAssigns = filteredAssigns.length;
    let periodLabel = '全期間';
    if (_infAFromYM || _infAToYM) {
      periodLabel = `${_infAFromYM || '—'} 〜 ${_infAToYM || '—'}`;
    }
    statEl.innerHTML = `
      <span class="ia-stat-item"><i class="fas fa-calendar-check"></i> ${periodLabel}</span>
      <span class="ia-stat-item"><i class="fas fa-link"></i> アサイン <strong>${totalAssigns}</strong>件</span>
      <span class="ia-stat-item"><i class="fas fa-users"></i> 稼働 <strong>${activeInf}</strong>名</span>
      <span class="ia-stat-item"><i class="fas fa-yen-sign"></i> 期間支払 <strong>${formatMoney(totalPaidAll)}</strong></span>`;
  }

  // ── 件数バッジ ──
  const badgeEl = document.getElementById('ia-count-badge');
  if (badgeEl) badgeEl.textContent = `${filtered.length} 名`;

  if (filtered.length === 0) {
    tbody.innerHTML = `<tr><td colspan="10" class="empty-state-cell">対象データがありません</td></tr>`;
    return;
  }

  tbody.innerHTML = filtered.map((r, i) => {
    const { inf, assignCount, totalPaid, avgER, avgReach, avgSaves, followers } = r;
    const unitPrice = Number(inf.unit_price) || 0;
    const erStr = avgER !== null
      ? `<span class="ia-er ${avgER >= 4 ? 'ia-er--high' : avgER >= 2 ? 'ia-er--mid' : 'ia-er--low'}">${avgER.toFixed(2)}%</span>`
      : '<span class="ia-none">—</span>';
    const paidStr = totalPaid > 0
      ? `<strong>${formatMoney(totalPaid)}</strong>`
      : '<span class="ia-none">—</span>';
    const reachSavesStr = (avgReach !== null || avgSaves !== null)
      ? `<span class="ia-reach-saves">
          <span class="ia-reach-saves-item"><i class="fas fa-eye"></i> ${avgReach !== null ? avgReach.toLocaleString() : '—'}</span>
          <span class="ia-reach-saves-item"><i class="fas fa-bookmark"></i> ${avgSaves !== null ? avgSaves.toLocaleString() : '—'}</span>
        </span>`
      : '<span class="ia-none">—</span>';
    const avatar = inf.avatar_image
      ? `<img src="${escHtml(inf.avatar_image)}" class="ia-avatar" alt="">`
      : `<span class="ia-avatar ia-avatar--placeholder"><i class="fas fa-user"></i></span>`;

    return `<tr class="ia-row">
      <td class="ia-td-num">${i + 1}</td>
      <td class="ia-td-name">
        <div class="ia-name-cell">
          ${avatar}
          <div>
            <span class="ia-name">${escHtml(inf.name || '—')}</span>
            ${inf.nationality ? `<br><span class="ia-nationality">${escHtml(inf.nationality)}</span>` : ''}
          </div>
        </div>
      </td>
      <td class="ia-td-subname">${escHtml(inf.sub_name || '')}</td>
      <td class="ia-td-num">${followers > 0 ? formatFollowers(followers) : '<span class="ia-none">—</span>'}</td>
      <td class="ia-td-num">${unitPrice > 0 ? formatMoney(unitPrice) : '<span class="ia-none">—</span>'}</td>
      <td class="ia-td-num ia-assign-count ${assignCount > 0 ? 'ia-assign-count--active' : ''}">${assignCount > 0 ? assignCount + '回' : '<span class="ia-none">0</span>'}</td>
      <td class="ia-td-num">${erStr}</td>
      <td class="ia-td-num">${paidStr}</td>
      <td class="ia-td-genre">${reachSavesStr}</td>
    </tr>`;
  }).join('');
}

// ── 期間プリセット計算ヘルパー ──
function _iaPresetRange(preset, fiscalMonth) {
  const fm = (fiscalMonth || 1);
  const today = new Date();
  const y = today.getFullYear();
  const m = today.getMonth() + 1; // 1-indexed
  // 今年度の開始月
  const fyStartM = fm;
  let fyStartY = y;
  if (m < fyStartM) fyStartY = y - 1;
  const pad = v => String(v).padStart(2,'0');
  if (preset === 'thisfy') {
    const fromYM = `${fyStartY}-${pad(fyStartM)}`;
    const toEndM = fyStartM === 1 ? 12 : fyStartM - 1;
    const toEndY = fyStartM === 1 ? fyStartY : fyStartY + 1;
    const toYM   = `${toEndY}-${pad(toEndM)}`;
    return { from: fromYM, to: toYM };
  }
  if (preset === 'lastfy') {
    const prevStartY = fyStartY - 1;
    const fromYM = `${prevStartY}-${pad(fyStartM)}`;
    const toEndM = fyStartM === 1 ? 12 : fyStartM - 1;
    const toEndY = fyStartM === 1 ? prevStartY : fyStartY;
    const toYM   = `${toEndY}-${pad(toEndM)}`;
    return { from: fromYM, to: toYM };
  }
  if (preset === 'this6m') {
    const to = new Date(y, m - 1, 1);
    const from6 = new Date(y, m - 7, 1);
    return { from: `${from6.getFullYear()}-${pad(from6.getMonth()+1)}`, to: `${to.getFullYear()}-${pad(to.getMonth()+1)}` };
  }
  if (preset === 'this3m') {
    const to = new Date(y, m - 1, 1);
    const from3 = new Date(y, m - 4, 1);
    return { from: `${from3.getFullYear()}-${pad(from3.getMonth()+1)}`, to: `${to.getFullYear()}-${pad(to.getMonth()+1)}` };
  }
  return { from: '', to: '' }; // 'all'
}

function _bindInfAnalysisEvents() {
  const searchEl = document.getElementById('inf-analysis-search');
  const sortEl   = document.getElementById('inf-analysis-sort');
  const fromEl   = document.getElementById('ia-period-from');
  const toEl     = document.getElementById('ia-period-to');

  const _rerender = () => {
    const ref = _infAnalysisDataRef || _dashDataCache;
    if (ref) _renderInfAnalysisTable(ref);
  };

  searchEl?.addEventListener('input', () => {
    _infAnalysisSearch = searchEl.value;
    _rerender();
  });
  sortEl?.addEventListener('change', () => {
    _infAnalysisSortKey = sortEl.value;
    _rerender();
  });
  fromEl?.addEventListener('change', () => {
    _infAFromYM = fromEl.value;
    // カスタム入力時はプリセットボタンの active を外す
    document.querySelectorAll('.ia-preset-btn').forEach(b => b.classList.remove('active'));
    _rerender();
  });
  toEl?.addEventListener('change', () => {
    _infAToYM = toEl.value;
    document.querySelectorAll('.ia-preset-btn').forEach(b => b.classList.remove('active'));
    _rerender();
  });

  // プリセットボタン
  document.querySelectorAll('.ia-preset-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.ia-preset-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      const preset = btn.dataset.iaPreset;
      const fiscalMonth = _infAnalysisDataRef?.fiscalMonth
        || _dashDataCache?.fiscalMonth || 1;
      const { from, to } = _iaPresetRange(preset, fiscalMonth);
      _infAFromYM = from;
      _infAToYM   = to;
      if (fromEl) fromEl.value = from;
      if (toEl)   toEl.value   = to;
      const ref = _infAnalysisDataRef || _dashDataCache;
      if (ref) _renderInfAnalysisTable(ref);
    });
  });
}

// ── 月別売上テーブル描画 ──
function _renderAnalysisTable({ projects, products, tickets, fiscalMonth, assigns, infMap }) {
  const tbody = document.getElementById('dash-monthly-tbody');
  if (!tbody) return;

  // 月ごとに集計
  // フィルター範囲取得
  const fromYM = _analysisFilterFrom; // "YYYY-MM"
  const toYM   = _analysisFilterTo;

  // 存在する全月を収集
  const monthSet = new Set();
  const addDate = (dateStr) => {
    if (!dateStr) return;
    const d = new Date(dateStr);
    if (isNaN(d)) return;
    monthSet.add(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`);
  };
  projects.forEach(p => addDate(p.start_date));
  (products||[]).forEach(p => addDate(p.start_date));
  (tickets||[]).forEach(t => addDate(t.start_date));

  // フィルター内の月だけ残す
  let months = [...monthSet].filter(ym => {
    if (fromYM && ym < fromYM) return false;
    if (toYM   && ym > toYM)   return false;
    return true;
  });

  // フィルターが空なら全月
  if (!fromYM && !toYM) months = [...monthSet];

  if (months.length === 0) {
    tbody.innerHTML = `<tr><td colspan="9" class="empty" style="padding:24px;text-align:center;">表示するデータがありません</td></tr>`;
    return;
  }

  // 月ごとの集計
  const _assignCost2 = proj => assigns
    .filter(a => a.project_id === proj.id)
    .reduce((s, a) => {
      const inf = infMap[a.influencer_id];
      let v = a.request_amount;
      if (v === null || v === undefined || v === '') v = inf ? inf.unit_price : null;
      const n = (v === null || v === undefined || v === '') ? 0
        : parseFloat(String(v).replace(/[^0-9.-]/g, ''));
      return s + (isNaN(n) ? 0 : n);
    }, 0);

  const rows = months.map(ym => {
    const [y, m] = ym.split('-').map(Number);
    const mo = m - 1; // 0-indexed

    const infProjs = projects.filter(p => {
      if (!p.start_date) return false;
      const d = new Date(p.start_date);
      return d.getFullYear()===y && d.getMonth()===mo;
    });
    const infAmt  = infProjs.reduce((s, p) => s + (Number(p.budget)||0), 0);
    const costAmt = infProjs.reduce((s, p) => s + _assignCost2(p), 0);

    const ssAmt = (products||[]).filter(p => {
      if (!p.start_date) return false;
      const d = new Date(p.start_date);
      return d.getFullYear()===y && d.getMonth()===mo;
    }).reduce((s, p) => s + (Number(p.total_amount)||0), 0);

    const tkAmt = (tickets||[]).filter(t => {
      if (!t.start_date) return false;
      const d = new Date(t.start_date);
      return d.getFullYear()===y && d.getMonth()===mo;
    }).reduce((s, t) => s + (Number(t.total_amount)||Number(t.budget)||0), 0);

    const total  = infAmt + ssAmt + tkAmt;
    const profit = total - costAmt;
    const margin = total > 0 ? (profit / total * 100) : null;

    return { ym, y, m, total, inf: infAmt, ss: ssAmt, ticket: tkAmt,
             cost: costAmt, profit, margin, projCount: infProjs.length };
  });

  // ソート
  rows.sort((a, b) => {
    let va = a[_analysisSortCol], vb = b[_analysisSortCol];
    if (_analysisSortCol === 'month') { va = a.ym; vb = b.ym; }
    if (typeof va === 'string') return _analysisSortDir==='asc' ? va.localeCompare(vb) : vb.localeCompare(va);
    return _analysisSortDir === 'asc' ? (va||0)-(vb||0) : (vb||0)-(va||0);
  });

  // 合計行
  const sum = rows.reduce((acc, r) => {
    acc.total += r.total; acc.inf += r.inf; acc.ss += r.ss;
    acc.ticket += r.ticket; acc.cost += r.cost; acc.profit += r.profit;
    acc.projCount += r.projCount; return acc;
  }, { total:0, inf:0, ss:0, ticket:0, cost:0, profit:0, projCount:0 });
  const sumMargin = sum.total > 0 ? (sum.profit/sum.total*100) : null;

  const mSign = (v, suffix='') => v > 0 ? `<span style="color:#10b981">▲${Math.abs(v).toFixed(1)}${suffix}</span>` :
    v < 0 ? `<span style="color:#ef4444">▼${Math.abs(v).toFixed(1)}${suffix}</span>` : '—';

  tbody.innerHTML = rows.map((r, i) => {
    // 前月比計算（ソート後の前行）
    const prev = i > 0 ? rows[i-1] : null;
    const momRow = prev && prev.total > 0 ? ((r.total - prev.total)/prev.total*100) : null;
    const mClass = r.margin !== null ? (r.margin >= 30 ? 'margin-good' : r.margin >= 20 ? 'margin-mid' : 'margin-bad') : '';
    return `<tr>
      <td class="dash-mt-month">${r.y}年${r.m}月</td>
      <td class="dash-mt-num"><strong>${formatMoney(r.total)}</strong>
        ${momRow!==null?`<div class="dash-mt-mom">${mSign(momRow,'%')}</div>`:''}
      </td>
      <td class="dash-mt-num">${r.inf>0?formatMoney(r.inf):'<span class="dash-mt-zero">—</span>'}</td>
      <td class="dash-mt-num">${r.ss>0?formatMoney(r.ss):'<span class="dash-mt-zero">—</span>'}</td>
      <td class="dash-mt-num">${r.ticket>0?formatMoney(r.ticket):'<span class="dash-mt-zero">—</span>'}</td>
      <td class="dash-mt-num">${r.cost>0?formatMoney(r.cost):'<span class="dash-mt-zero">—</span>'}</td>
      <td class="dash-mt-num" style="color:${r.profit>=0?'#10b981':'#ef4444'}">${formatMoney(r.profit)}</td>
      <td class="dash-mt-num ${mClass}">${r.margin!==null?r.margin.toFixed(1)+'%':'—'}</td>
      <td class="dash-mt-num">${r.projCount>0?r.projCount+'件':'—'}</td>
    </tr>`;
  }).join('') + `<tr class="dash-mt-sum">
    <td>合 計</td>
    <td class="dash-mt-num"><strong>${formatMoney(sum.total)}</strong></td>
    <td class="dash-mt-num">${formatMoney(sum.inf)}</td>
    <td class="dash-mt-num">${formatMoney(sum.ss)}</td>
    <td class="dash-mt-num">${formatMoney(sum.ticket)}</td>
    <td class="dash-mt-num">${formatMoney(sum.cost)}</td>
    <td class="dash-mt-num" style="color:${sum.profit>=0?'#10b981':'#ef4444'}">${formatMoney(sum.profit)}</td>
    <td class="dash-mt-num">${sumMargin!==null?sumMargin.toFixed(1)+'%':'—'}</td>
    <td class="dash-mt-num">${sum.projCount}件</td>
  </tr>`;

  // ソートヘッダーイベント（1回だけ）
  const table = document.getElementById('dash-monthly-table');
  if (table && !table._sortBound) {
    table._sortBound = true;
    table.querySelectorAll('th.sortable').forEach(th => {
      th.addEventListener('click', () => {
        const col = th.dataset.col;
        if (_analysisSortCol === col) {
          _analysisSortDir = _analysisSortDir === 'asc' ? 'desc' : 'asc';
        } else {
          _analysisSortCol = col;
          _analysisSortDir = col === 'month' ? 'asc' : 'desc';
        }
        if (_analysisDataRef) _renderAnalysisTable(_analysisDataRef);
      });
    });
  }
}

// ── 戦略AI：毎日00:00自動更新 ──
const _STRATEGY_STORAGE_KEY_PREFIX = 'dash_strategy_';
function _autoRefreshDailyStrategy(type, data) {
  const key        = _STRATEGY_STORAGE_KEY_PREFIX + type;
  const todayStr   = new Date().toISOString().slice(0, 10); // YYYY-MM-DD
  const bodyId     = type === 'analysis' ? 'dash-analysis-strategy-body' : 'dash-sales-strategy-body';
  const updatedId  = type === 'analysis' ? 'dash-analysis-strategy-updated' : 'dash-sales-strategy-updated';
  const bodyEl     = document.getElementById(bodyId);
  const updatedEl  = updatedId ? document.getElementById(updatedId) : null;
  if (!bodyEl) return;

  // localStorage から前回の結果を取得
  let cached = null;
  try { cached = JSON.parse(localStorage.getItem(key)); } catch(e) {}

  // 当日のキャッシュがあれば即表示
  if (cached && cached.date === todayStr && cached.html) {
    bodyEl.innerHTML = cached.html;
    if (updatedEl) updatedEl.textContent = `最終更新: ${cached.date}`;
    return;
  }

  // 当日のキャッシュがない → 新規生成
  bodyEl.innerHTML = '<div class="dash-strategy-loading"><i class="fas fa-spinner fa-spin"></i> 分析中...</div>';
  setTimeout(() => {
    _generateStrategyAnalysis(type, data, (html) => {
      bodyEl.innerHTML = html;
      // localStorage に保存
      try {
        localStorage.setItem(key, JSON.stringify({ date: todayStr, html }));
      } catch(e) {}
      if (updatedEl) updatedEl.textContent = `最終更新: ${todayStr}`;
    });
  }, 400);

  // 次の00:00にリセットするタイマー
  _scheduleMidnightStrategyRefresh(type, data);
}

// ── 翌00:00タイマー ──
let _midnightTimers = {};
function _scheduleMidnightStrategyRefresh(type, data) {
  if (_midnightTimers[type]) return; // 既にセット済み
  const now  = new Date();
  const next = new Date(now.getFullYear(), now.getMonth(), now.getDate()+1, 0, 0, 0);
  const ms   = next.getTime() - now.getTime();
  _midnightTimers[type] = setTimeout(() => {
    delete _midnightTimers[type];
    // localStorage の当日キャッシュを削除して再生成
    try { localStorage.removeItem(_STRATEGY_STORAGE_KEY_PREFIX + type); } catch(e) {}
    if (_dashDataCache) {
      if (type === 'analysis') _renderDashAnalysis(_dashDataCache);
      else _renderDashSales(_dashDataCache);
    }
  }, ms);
}

// ─────────────────────────────────────────────
//  PAGE 3: セールス
// ─────────────────────────────────────────────
function _renderDashSales({ projects, clients, influencers, assigns, fiscalMonth,
                             clientMap, infMap }) {
  const today  = new Date();
  const curFY  = _projFiscalYear({ start_date: today.toISOString().slice(0,10) }, fiscalMonth);
  const prevFY = curFY - 1;
  const ytdProjects  = projects.filter(p => _projFiscalYear(p, fiscalMonth) === curFY);
  const prevProjects = projects.filter(p => _projFiscalYear(p, fiscalMonth) === prevFY);
  const ytdSales     = ytdProjects.reduce((s, p) => s + (Number(p.budget)||0), 0);
  const prevSales    = prevProjects.reduce((s, p) => s + (Number(p.budget)||0), 0);

  const activeCount    = projects.filter(p => ['発注済','進行中','投稿完了'].includes(p.status)).length;
  const availableCount = influencers.filter(i => i.available).length;
  const totalFollowers = influencers.reduce((s, i) => s + (Number(i.followers)||0), 0);

  // ── KPIカード ──
  document.getElementById('dash-projects').textContent     = projects.length;
  document.getElementById('dash-projects-sub').innerHTML   =
    `<span class="dash-card-sub-badge blue">${activeCount}件 進行中</span>`;
  document.getElementById('dash-clients').textContent      = clients.length;
  document.getElementById('dash-clients-sub').innerHTML    =
    `<span class="dash-card-sub-badge green">取引中 ${clients.filter(c=>c.status==='取引中'||!c.status).length}社</span>`;
  document.getElementById('dash-influencers').textContent  = influencers.length;
  document.getElementById('dash-influencers-sub').innerHTML =
    `<span class="dash-card-sub-badge purple">稼働可 ${availableCount}名</span>`;
  document.getElementById('dash-followers').textContent    = _fmtFollowersDash(totalFollowers);
  document.getElementById('dash-followers-sub').innerHTML  =
    `<span class="dash-card-sub-badge orange">平均 ${influencers.length>0?_fmtFollowersDash(Math.round(totalFollowers/influencers.length)):'—'}</span>`;

  // ── クライアント別ランキング ──
  const clientSales = {};
  ytdProjects.forEach(p => {
    if (!p.client_id) return;
    if (!clientSales[p.client_id]) clientSales[p.client_id] = { count:0, total:0 };
    clientSales[p.client_id].count++;
    clientSales[p.client_id].total += Number(p.budget)||0;
  });
  const ranking  = Object.entries(clientSales).sort((a,b)=>b[1].total-a[1].total).slice(0,8);
  const totalYtd = ytdSales || 1;
  const rankTbody = document.getElementById('dash-client-ranking');
  if (rankTbody) {
    rankTbody.innerHTML = ranking.length === 0
      ? `<tr><td colspan="5" style="padding:20px;text-align:center;color:var(--gray-400);">当期の案件データがありません</td></tr>`
      : ranking.map(([cid, d], i) => {
          const cl    = clientMap[cid];
          const share = (d.total/totalYtd*100).toFixed(1);
          const medal = i===0?'🥇':i===1?'🥈':i===2?'🥉':`${i+1}`;
          return `<tr>
            <td style="font-size:14px;text-align:center;">${medal}</td>
            <td style="font-weight:600;">${cl?escHtml(cl.company_name):'—'}</td>
            <td style="text-align:right;">${d.count}件</td>
            <td style="text-align:right;font-weight:700;color:var(--primary-dark);">${formatMoney(d.total)}</td>
            <td>
              <div class="dash-rank-share-wrap">
                <div class="dash-rank-share-bar" style="width:${Math.min(100,parseFloat(share))}%"></div>
                <span>${share}%</span>
              </div>
            </td>
          </tr>`;
        }).join('');
  }

  // ── クライアント動向パネル ──
  const trendEl = document.getElementById('dash-client-trend-body');
  if (trendEl) {
    // 新規クライアント（当期に初めて案件が発生したクライアント）
    const prevClientIds = new Set(prevProjects.map(p => p.client_id).filter(Boolean));
    const curClientIds  = new Set(ytdProjects.map(p => p.client_id).filter(Boolean));
    const newClientIds  = [...curClientIds].filter(id => !prevClientIds.has(id));
    const lostClientIds = [...prevClientIds].filter(id => !curClientIds.has(id));

    // 売上伸び率トップ・下落ワーストを計算
    const prevClientSales = {};
    prevProjects.forEach(p => {
      if (!p.client_id) return;
      prevClientSales[p.client_id] = (prevClientSales[p.client_id]||0) + (Number(p.budget)||0);
    });
    const growthRanking = Object.entries(clientSales)
      .filter(([cid]) => prevClientSales[cid])
      .map(([cid, d]) => ({
        cid, name: clientMap[cid]?.company_name||'—',
        cur: d.total, prev: prevClientSales[cid],
        growth: ((d.total - prevClientSales[cid]) / prevClientSales[cid] * 100)
      }))
      .sort((a,b) => b.growth - a.growth);

    const top3Growth = growthRanking.slice(0, 3);
    const top3Drop   = [...growthRanking].sort((a,b) => a.growth - b.growth).slice(0, 3).filter(r => r.growth < 0);

    const badge = (text, color) => `<span class="dash-trend-badge" style="background:${color}20;color:${color};border:1px solid ${color}50;">${text}</span>`;

    trendEl.innerHTML = `
      <div class="dash-trend-grid">
        <div class="dash-trend-item">
          <div class="dash-trend-title">${badge('新規', '#10b981')} 新規獲得 <strong>${newClientIds.length}社</strong></div>
          <ul class="dash-trend-list">
            ${newClientIds.slice(0,5).map(id => `<li><i class="fas fa-plus-circle" style="color:#10b981;"></i> ${escHtml(clientMap[id]?.company_name||'—')}</li>`).join('')||'<li style="color:var(--gray-400);">なし</li>'}
          </ul>
        </div>
        <div class="dash-trend-item">
          <div class="dash-trend-title">${badge('離脱', '#ef4444')} 前期比離脱 <strong>${lostClientIds.length}社</strong></div>
          <ul class="dash-trend-list">
            ${lostClientIds.slice(0,5).map(id => `<li><i class="fas fa-minus-circle" style="color:#ef4444;"></i> ${escHtml(clientMap[id]?.company_name||'—')}</li>`).join('')||'<li style="color:var(--gray-400);">なし</li>'}
          </ul>
        </div>
        <div class="dash-trend-item">
          <div class="dash-trend-title">${badge('伸長', '#6366f1')} 売上伸長TOP</div>
          <ul class="dash-trend-list">
            ${top3Growth.map(r => `<li><i class="fas fa-arrow-up" style="color:#6366f1;"></i> ${escHtml(r.name)} <span style="color:#6366f1;font-weight:700;">▲${r.growth.toFixed(0)}%</span></li>`).join('')||'<li style="color:var(--gray-400);">データ不足</li>'}
          </ul>
        </div>
        <div class="dash-trend-item">
          <div class="dash-trend-title">${badge('下落', '#f59e0b')} 売上下落</div>
          <ul class="dash-trend-list">
            ${top3Drop.map(r => `<li><i class="fas fa-arrow-down" style="color:#f59e0b;"></i> ${escHtml(r.name)} <span style="color:#f59e0b;font-weight:700;">▼${Math.abs(r.growth).toFixed(0)}%</span></li>`).join('')||'<li style="color:var(--gray-400);">なし</li>'}
          </ul>
        </div>
      </div>`;
  }

  // ── クライアント別売上推移グラフ（上位5社）──
  _renderClientTrendChart(projects, fiscalMonth, clientMap);

  // ── 詳しい分析（インフルエンサー・SNS・ステータス） ──
  _renderSalesDetailAnalysis({ projects, influencers, assigns, infMap, ytdProjects, clientMap });

  // ── 最近の案件 ──
  const recent = [...projects].sort((a,b)=>(b.created_at||0)-(a.created_at||0)).slice(0,5);
  const tbody  = document.getElementById('dash-recent-projects');
  if (tbody) {
    tbody.innerHTML = recent.length === 0
      ? '<tr><td colspan="4" class="empty">案件がありません</td></tr>'
      : recent.map(p => {
          const cl = clientMap[p.client_id];
          return `<tr>
            <td><a href="#" class="proj-link" data-id="${escHtml(p.id)}"
              style="color:var(--primary);font-weight:600;">${escHtml(p.project_name)}</a></td>
            <td>${cl?escHtml(cl.company_name):'<span style="color:var(--gray-400)">—</span>'}</td>
            <td>${statusBadge(p.status)}</td>
            <td style="text-align:right;">${formatMoney(p.budget)}</td>
          </tr>`;
        }).join('');
    tbody.querySelectorAll('.proj-link').forEach(a => {
      a.addEventListener('click', e => {
        e.preventDefault();
        navigateTo('projects');
        setTimeout(() => openProjectDetail(a.dataset.id), 100);
      });
    });
  }

  // ── AI セールス戦略（毎日00:00自動更新）──
  {
    const prevClientIds = new Set(prevProjects.map(p=>p.client_id).filter(Boolean));
    const curClientIds  = new Set(ytdProjects.map(p=>p.client_id).filter(Boolean));
    _autoRefreshDailyStrategy('sales', {
      ytdSales, prevSales,
      totalClients: clients.length,
      newClients:   [...curClientIds].filter(id=>!prevClientIds.has(id)).length,
      lostClients:  [...prevClientIds].filter(id=>!curClientIds.has(id)).length,
      activeProjectCount: activeCount,
      topClient: ranking[0] ? (clientMap[ranking[0][0]]?.company_name||'—') : '—',
      topClientSales: ranking[0] ? ranking[0][1].total : 0,
    });
  }
}

// ── クライアント別売上推移グラフ（上位5社）──
let _dashClientTrendChart = null;
function _renderClientTrendChart(projects, fiscalMonth, clientMap) {
  const canvas = document.getElementById('dash-client-trend-chart');
  if (!canvas) return;
  if (_dashClientTrendChart) { _dashClientTrendChart.destroy(); _dashClientTrendChart = null; }

  const today = new Date();
  const curFY = _projFiscalYear({ start_date: today.toISOString().slice(0,10) }, fiscalMonth);
  const fm = (fiscalMonth||1) - 1;
  const monthOrder = Array.from({length:12}, (_,i) => (fm+i) % 12);
  const monthNames = ['1月','2月','3月','4月','5月','6月','7月','8月','9月','10月','11月','12月'];
  const labels = monthOrder.map(m => monthNames[m]);

  // 当期の全プロジェクトからクライアント別合計を集計
  const ytdProjects = projects.filter(p => _projFiscalYear(p, fiscalMonth) === curFY);
  const clientTotals = {};
  ytdProjects.forEach(p => {
    if (!p.client_id) return;
    clientTotals[p.client_id] = (clientTotals[p.client_id]||0) + (Number(p.budget)||0);
  });
  // 上位5社
  const top5 = Object.entries(clientTotals).sort((a,b)=>b[1]-a[1]).slice(0,5);
  if (top5.length === 0) {
    canvas.parentElement.innerHTML = '<div style="padding:40px;text-align:center;color:var(--gray-400);">当期の案件データがありません</div>';
    return;
  }

  const palette = ['#6366f1','#10b981','#f59e0b','#ef4444','#8b5cf6'];
  const datasets = top5.map(([cid], i) => {
    const monthly = Array(12).fill(0);
    ytdProjects.filter(p => p.client_id === cid).forEach(p => {
      if (!p.start_date) return;
      const m = new Date(p.start_date).getMonth();
      const idx = (m - fm + 12) % 12;
      monthly[idx] += Number(p.budget)||0;
    });
    return {
      label: clientMap[cid]?.company_name || '—',
      data: monthly,
      borderColor: palette[i],
      backgroundColor: palette[i] + '18',
      borderWidth: 2,
      pointRadius: 3,
      tension: 0.3,
      fill: false,
    };
  });

  _dashClientTrendChart = new Chart(canvas.getContext('2d'), {
    type: 'line',
    data: { labels, datasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { position:'top', labels:{ font:{size:11}, boxWidth:10, padding:12 } },
        tooltip: { callbacks: { label: ctx => ` ${ctx.dataset.label}: ${formatMoney(ctx.parsed.y)}` } }
      },
      scales: {
        y: {
          beginAtZero: true,
          ticks: { font:{size:10}, callback: v => v>=10000?`${(v/10000).toFixed(0)}万`:v },
          grid: { color:'rgba(0,0,0,0.04)' }
        },
        x: { ticks:{ font:{size:11} }, grid:{ display:false } }
      }
    }
  });
}

// ── 詳しい分析（セールスタブ）──
function _renderSalesDetailAnalysis({ projects, influencers, assigns, infMap, ytdProjects, clientMap }) {
  // ─── 1. インフルエンサー活用分析 ───────────────────────────
  const infEl = document.getElementById('dash-inf-analysis-body');
  if (infEl) {
    // 当期案件にアサインされたインフルエンサーを集計
    const ytdProjIds = new Set(ytdProjects.map(p => p.id));
    const assignsYtd = assigns.filter(a => ytdProjIds.has(a.project_id));
    const usedInfIds = new Set(assignsYtd.map(a => a.influencer_id).filter(Boolean));
    const totalInf   = influencers.length;
    const usedCount  = usedInfIds.size;
    const unusedCount= totalInf - usedCount;
    const usageRate  = totalInf > 0 ? (usedCount / totalInf * 100).toFixed(1) : 0;

    // フォロワー規模別の分布
    const sizeBuckets = { 'マイクロ(〜1万)':0, 'ミドル(1〜10万)':0, 'メガ(10万〜)':0 };
    [...usedInfIds].forEach(id => {
      const inf = infMap[id];
      if (!inf) return;
      const f = Number(inf.followers)||0;
      if      (f < 10000)  sizeBuckets['マイクロ(〜1万)']++;
      else if (f < 100000) sizeBuckets['ミドル(1〜10万)']++;
      else                 sizeBuckets['メガ(10万〜)']++;
    });

    // SNS別アサイン数
    const snsCount = {};
    [...usedInfIds].forEach(id => {
      const inf = infMap[id];
      if (!inf) return;
      const sns = inf.sns_type || 'その他';
      snsCount[sns] = (snsCount[sns]||0) + 1;
    });
    const topSns = Object.entries(snsCount).sort((a,b)=>b[1]-a[1]).slice(0,3);

    // 平均コスト
    const totalAssignCost = assignsYtd.reduce((s, a) => {
      const inf = infMap[a.influencer_id];
      const v = a.request_amount ?? inf?.unit_price ?? 0;
      return s + (parseFloat(String(v).replace(/[^0-9.-]/g,''))||0);
    }, 0);
    const avgAssignCost = assignsYtd.length > 0 ? totalAssignCost / assignsYtd.length : 0;

    infEl.innerHTML = `
      <div class="da-stat-grid">
        <div class="da-stat-item">
          <div class="da-stat-num" style="color:#6366f1;">${usedCount}<span class="da-stat-unit">名</span></div>
          <div class="da-stat-lbl">当期稼働</div>
        </div>
        <div class="da-stat-item">
          <div class="da-stat-num" style="color:#10b981;">${usageRate}<span class="da-stat-unit">%</span></div>
          <div class="da-stat-lbl">稼働率</div>
        </div>
        <div class="da-stat-item">
          <div class="da-stat-num" style="color:#f59e0b;">${formatMoney(Math.round(avgAssignCost))}</div>
          <div class="da-stat-lbl">平均コスト</div>
        </div>
      </div>
      <div class="da-bar-section">
        <div class="da-bar-label">規模別内訳</div>
        ${Object.entries(sizeBuckets).map(([k,v]) => {
          const pct = usedCount > 0 ? (v/usedCount*100).toFixed(0) : 0;
          const colors = { 'マイクロ(〜1万)':'#10b981', 'ミドル(1〜10万)':'#6366f1', 'メガ(10万〜)':'#f59e0b' };
          return `<div class="da-bar-row">
            <span class="da-bar-key">${k}</span>
            <div class="da-bar-track"><div class="da-bar-fill" style="width:${pct}%;background:${colors[k]||'#6366f1'};"></div></div>
            <span class="da-bar-val">${v}名 (${pct}%)</span>
          </div>`;
        }).join('')}
      </div>
      <div class="da-top-list">
        <div class="da-bar-label">主要SNS</div>
        ${topSns.map(([sns, cnt]) => `<div class="da-list-row"><span class="da-list-key">${escHtml(sns)}</span><span class="da-list-val">${cnt}名</span></div>`).join('')||'<div style="color:var(--gray-400);font-size:12px;padding:8px 0;">データなし</div>'}
      </div>`;
  }

  // ─── 2. SNS別分析 ───────────────────────────────────────
  const snsEl = document.getElementById('dash-sns-analysis-body');
  if (snsEl) {
    // 全インフルエンサーのSNS別フォロワー合計・人数
    const snsMap = {};
    influencers.forEach(inf => {
      const sns = inf.sns_type || 'その他';
      if (!snsMap[sns]) snsMap[sns] = { count:0, followers:0, totalCost:0 };
      snsMap[sns].count++;
      snsMap[sns].followers += Number(inf.followers)||0;
    });
    const snsTotal = influencers.length || 1;
    const snsEntries = Object.entries(snsMap).sort((a,b)=>b[1].count-a[1].count);

    const palette = ['#f97316','#e11d48','#0ea5e9','#8b5cf6','#10b981','#6b7280'];
    snsEl.innerHTML = `
      <div class="da-sns-list">
        ${snsEntries.map(([sns, d], i) => {
          const pct   = (d.count / snsTotal * 100).toFixed(1);
          const avgF  = d.count > 0 ? Math.round(d.followers / d.count) : 0;
          const color = palette[i % palette.length];
          const icons = { 'Instagram':'fab fa-instagram','YouTube':'fab fa-youtube',
                          'TikTok':'fab fa-tiktok','X(旧Twitter)':'fab fa-x-twitter',
                          'Facebook':'fab fa-facebook' };
          const icon = icons[sns] || 'fas fa-hashtag';
          return `<div class="da-sns-row">
            <div class="da-sns-icon" style="background:${color}18;color:${color};"><i class="${icon}"></i></div>
            <div class="da-sns-info">
              <div class="da-sns-name">${escHtml(sns)}</div>
              <div class="da-sns-sub">${d.count}名 / 平均${_fmtFollowersDash(avgF)}</div>
            </div>
            <div class="da-sns-bar-wrap">
              <div class="da-sns-bar" style="width:${pct}%;background:${color};"></div>
            </div>
            <div class="da-sns-pct" style="color:${color};">${pct}%</div>
          </div>`;
        }).join('')}
      </div>`;
  }

  // ─── 3. 案件ステータス内訳 ────────────────────────────────
  const stEl = document.getElementById('dash-status-analysis-body');
  if (stEl) {
    const statusList = ['提案中','発注済','進行中','投稿完了','請求中','完了','キャンセル'];
    const statusColors = {
      '提案中':'#f59e0b', '発注済':'#3b82f6', '進行中':'#6366f1',
      '投稿完了':'#8b5cf6', '請求中':'#0ea5e9', '完了':'#10b981', 'キャンセル':'#6b7280'
    };
    const statusIcons = {
      '提案中':'fa-paper-plane', '発注済':'fa-file-signature', '進行中':'fa-bolt',
      '投稿完了':'fa-check-double', '請求中':'fa-file-invoice-dollar', '完了':'fa-check-circle', 'キャンセル':'fa-ban'
    };
    const statusCounts = {};
    const statusBudgets = {};
    projects.forEach(p => {
      const s = p.status || 'その他';
      statusCounts[s]  = (statusCounts[s] ||0) + 1;
      statusBudgets[s] = (statusBudgets[s]||0) + (Number(p.budget)||0);
    });
    const total = projects.length || 1;

    // 完了率・進行中率を先出し
    const doneCount   = (statusCounts['完了']||0);
    const activeCount2= (statusCounts['進行中']||0) + (statusCounts['発注済']||0) + (statusCounts['投稿完了']||0);
    const doneRate    = (doneCount / total * 100).toFixed(1);
    const activeRate2 = (activeCount2 / total * 100).toFixed(1);

    stEl.innerHTML = `
      <div class="da-stat-grid" style="margin-bottom:12px;">
        <div class="da-stat-item">
          <div class="da-stat-num" style="color:#10b981;">${doneRate}<span class="da-stat-unit">%</span></div>
          <div class="da-stat-lbl">完了率</div>
        </div>
        <div class="da-stat-item">
          <div class="da-stat-num" style="color:#6366f1;">${activeRate2}<span class="da-stat-unit">%</span></div>
          <div class="da-stat-lbl">進行中率</div>
        </div>
        <div class="da-stat-item">
          <div class="da-stat-num" style="color:#f59e0b;">${total}</div>
          <div class="da-stat-lbl">総案件数</div>
        </div>
      </div>
      <div class="da-status-list">
        ${statusList.filter(s => statusCounts[s]).map(s => {
          const cnt  = statusCounts[s]||0;
          const pct  = (cnt/total*100).toFixed(1);
          const col  = statusColors[s]||'#6b7280';
          const icon = statusIcons[s]||'fa-circle';
          return `<div class="da-status-row">
            <span class="da-status-dot" style="background:${col};"></span>
            <i class="fas ${icon}" style="color:${col};font-size:11px;width:14px;"></i>
            <span class="da-status-name">${escHtml(s)}</span>
            <div class="da-status-track"><div class="da-status-fill" style="width:${pct}%;background:${col};"></div></div>
            <span class="da-status-cnt">${cnt}件</span>
            <span class="da-status-pct" style="color:${col};">${pct}%</span>
          </div>`;
        }).join('')||'<div style="color:var(--gray-400);font-size:12px;padding:12px 0;">案件データがありません</div>'}
      </div>`;
  }
}

// ── AI 戦略分析（ローカルロジックベース）──
function _generateStrategyAnalysis(type, data, callback) {
  // callback(html) が渡された場合はコールバック形式、なければ直接描画
  const bodyId = type === 'analysis' ? 'dash-analysis-strategy-body' : 'dash-sales-strategy-body';
  const bodyEl = document.getElementById(bodyId);
  if (!bodyEl && !callback) return;
  if (bodyEl && !callback) {
    bodyEl.innerHTML = `<div class="dash-strategy-loading"><i class="fas fa-spinner fa-spin"></i> 分析中...</div>`;
  }

  // ローカルルールベースで戦略提案を生成（外部API不要）
  setTimeout(() => {
    const points = [];

    if (type === 'analysis') {
      const { ytdSales, prevSales, yoy, ytdProfit, avgMargin, mom,
              ytdProjectCount, clientCount } = data;

      // 前期比
      if (yoy === null) {
        points.push({ icon:'fas fa-info-circle', color:'#6366f1', title:'前期データなし',
          text:'前期のデータが存在しないため前期比較ができません。データを蓄積することで来期以降の比較分析が可能になります。' });
      } else if (yoy < 0) {
        points.push({ icon:'fas fa-exclamation-triangle', color:'#ef4444', title:`売上下落 ▼${Math.abs(yoy).toFixed(1)}%`,
          text:`前期比で${Math.abs(yoy).toFixed(1)}%の売上減少が見られます。案件単価の見直し・新規クライアント獲得の強化・既存クライアントへのアップセルを優先して検討してください。` });
      } else if (yoy < 10) {
        points.push({ icon:'fas fa-minus-circle', color:'#f59e0b', title:`微増 ▲${yoy.toFixed(1)}%`,
          text:`前期比+${yoy.toFixed(1)}%と微増ですが、成長率の加速が課題です。高単価案件へのシフトや提案数の増加を検討しましょう。` });
      } else {
        points.push({ icon:'fas fa-arrow-up', color:'#10b981', title:`好調 ▲${yoy.toFixed(1)}%`,
          text:`前期比+${yoy.toFixed(1)}%と好調に推移しています。この勢いを維持するため、人員確保・業務効率化による受注キャパシティの拡大を検討してください。` });
      }

      // 利益率
      if (avgMargin !== null) {
        if (avgMargin < 20) {
          points.push({ icon:'fas fa-coins', color:'#ef4444', title:`利益率が低水準 ${avgMargin.toFixed(1)}%`,
            text:`平均利益率${avgMargin.toFixed(1)}%は業界目安（30%）を大きく下回っています。インフルエンサー単価の見直し、高利益率案件への注力、コスト管理の強化が急務です。` });
        } else if (avgMargin < 30) {
          points.push({ icon:'fas fa-chart-pie', color:'#f59e0b', title:`利益率改善余地あり ${avgMargin.toFixed(1)}%`,
            text:`利益率${avgMargin.toFixed(1)}%は目標30%に近づいています。案件ミックスの最適化（高利益案件の比率アップ）で更なる改善が見込めます。` });
        } else {
          points.push({ icon:'fas fa-check-circle', color:'#10b981', title:`利益率良好 ${avgMargin.toFixed(1)}%`,
            text:`利益率${avgMargin.toFixed(1)}%と良好です。この水準を維持しながら売上規模の拡大を図りましょう。` });
        }
      }

      // 前月比
      if (mom !== null && mom < -15) {
        points.push({ icon:'fas fa-calendar-times', color:'#f59e0b', title:`当月売上鈍化 ▼${Math.abs(mom).toFixed(1)}%`,
          text:`前月比${Math.abs(mom).toFixed(1)}%減少しています。パイプラインの確認と案件化促進の活動を強化してください。` });
      }

      // 案件数
      if (ytdProjectCount < 3) {
        points.push({ icon:'fas fa-briefcase', color:'#8b5cf6', title:'案件数が少ない',
          text:'当期の案件数が少ない状態です。提案活動の増加と見込み客へのアプローチ強化を優先してください。' });
      }

    } else {
      // sales タブ
      const { ytdSales, prevSales, totalClients, newClients, lostClients,
              activeProjectCount, topClient, topClientSales } = data;

      // 新規獲得
      if (newClients === 0) {
        points.push({ icon:'fas fa-user-slash', color:'#ef4444', title:'新規クライアント獲得ゼロ',
          text:'当期は新規クライアントの獲得がありません。既存クライアントへの依存度が高まるリスクがあります。紹介営業・SNS活用・展示会参加など新規接触チャネルを増やしてください。' });
      } else if (newClients >= 3) {
        points.push({ icon:'fas fa-user-plus', color:'#10b981', title:`新規獲得 ${newClients}社`,
          text:`${newClients}社の新規クライアントを獲得できています。新規の定着率を高めるため、オンボーディング・定期レポート送付・次回提案の早期化を意識してください。` });
      } else {
        points.push({ icon:'fas fa-user-plus', color:'#6366f1', title:`新規獲得 ${newClients}社`,
          text:`${newClients}社を新規獲得しています。目標社数に達するよう提案活動を継続してください。` });
      }

      // 離脱クライアント
      if (lostClients > 0) {
        points.push({ icon:'fas fa-door-open', color:'#f59e0b', title:`前期比離脱 ${lostClients}社`,
          text:`${lostClients}社が前期から案件なしとなっています。定期的なコンタクトと潜在ニーズのヒアリングで休眠クライアントの掘り起こしを行ってください。` });
      }

      // 売上集中リスク
      if (ytdSales > 0 && topClientSales / ytdSales > 0.5) {
        points.push({ icon:'fas fa-exclamation-circle', color:'#ef4444', title:`売上集中リスク（${topClient}）`,
          text:`「${topClient}」1社で売上の${(topClientSales/ytdSales*100).toFixed(0)}%を占めています。特定クライアント依存は経営リスクとなるため、他クライアントへの提案強化を優先してください。` });
      }

      // アクティブ案件
      if (activeProjectCount === 0) {
        points.push({ icon:'fas fa-inbox', color:'#ef4444', title:'進行中案件ゼロ',
          text:'現在進行中の案件がありません。パイプラインが空の状態は翌月以降の売上に直結します。すぐに提案活動を開始してください。' });
      } else if (activeProjectCount >= 5) {
        points.push({ icon:'fas fa-fire', color:'#10b981', title:`活発な案件進行中 ${activeProjectCount}件`,
          text:`${activeProjectCount}件が進行中と案件数が多い状態です。品質維持のため担当者のキャパシティ管理と進捗確認を徹底してください。` });
      }

      // 前期比
      if (prevSales > 0) {
        const yoy2 = (ytdSales - prevSales) / prevSales * 100;
        if (yoy2 < 0) {
          points.push({ icon:'fas fa-arrow-down', color:'#ef4444', title:`売上前期比 ▼${Math.abs(yoy2).toFixed(1)}%`,
            text:'前期比で売上が減少しています。高単価サービスへの誘導・クロスセル提案・紹介促進キャンペーンの実施を検討してください。' });
        }
      }
    }

    if (points.length === 0) {
      points.push({ icon:'fas fa-smile', color:'#10b981', title:'特記事項なし',
        text:'現時点で大きな課題は検出されませんでした。引き続きデータを蓄積し、定期的な分析を行ってください。' });
    }

    const html = `<div class="dash-strategy-points">
      ${points.map(p => `
        <div class="dash-strategy-point">
          <div class="dash-sp-icon" style="color:${p.color};"><i class="${p.icon}"></i></div>
          <div class="dash-sp-body">
            <div class="dash-sp-title" style="color:${p.color};">${p.title}</div>
            <div class="dash-sp-text">${p.text}</div>
          </div>
        </div>`).join('')}
      <div class="dash-strategy-footer">
        <i class="fas fa-info-circle"></i> この分析は登録済みデータをもとにルールベースで自動生成されています。
      </div>
    </div>`;

    if (typeof callback === 'function') {
      callback(html);
    } else if (bodyEl) {
      bodyEl.innerHTML = html;
    }
  }, 600);
}

// ── 来店リスト描画 ──
// day: 'today' | 'tomorrow' | null
// specificDate: 'YYYY-MM-DD' | null  ← カレンダー日付選択時に使用
function _renderVisitList(assigns, infMap, projMap, day, specificDate) {
  const now     = new Date();
  const todayMs = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
  const tomMs   = todayMs + 86400000;

  const filtered = assigns.filter(a => {
    if (!a.visit_datetime) return false;
    const ds = a.visit_datetime.slice(0, 10);
    const [y, mo, d] = ds.split('-').map(Number);
    const dMs = new Date(y, mo-1, d).getTime();
    if (specificDate) return ds === specificDate;          // カレンダー選択日
    if (day === 'today')    return dMs === todayMs;
    if (day === 'tomorrow') return dMs === tomMs;
    return false;
  }).sort((a, b) => (a.visit_datetime||'').localeCompare(b.visit_datetime||''));

  const container = document.getElementById('dash-visit-list');
  if (!container) return;

  // ヘッダーラベル
  let headLabel = '';
  if (specificDate) {
    const [sy, sm, sd] = specificDate.split('-').map(Number);
    const WDAY_JP = ['日','月','火','水','木','金','土'];
    const wdayStr = WDAY_JP[new Date(sy, sm-1, sd).getDay()];
    headLabel = `${sm}月${sd}日（${wdayStr}）`;
  } else {
    headLabel = day === 'today' ? '今日' : '明日';
  }

  if (filtered.length === 0) {
    container.innerHTML = `<div class="dash-visit-empty">
      <i class="fas fa-calendar-check"></i>
      <p>${headLabel}の来店予定はありません</p>
    </div>`;
    return;
  }

  // テーブル形式で全表示
  const rows = filtered.map(a => {
    const inf  = infMap[a.influencer_id];
    const proj = projMap[a.project_id];
    if (!inf) return '';
    const dt       = a.visit_datetime || '';
    const datePart = dt.slice(0, 10);
    const timePart = dt.includes('T') ? dt.split('T')[1].slice(0, 5) : '終日';
    const [y, mo, d] = datePart.split('-').map(Number);
    const dMs = new Date(y, mo-1, d).getTime();
    const WDAY_JP2  = ['日','月','火','水','木','金','土'];
    const wdStr     = WDAY_JP2[new Date(y, mo-1, d).getDay()];
    const dayLabel  = dMs === todayMs
      ? '<span class="dash-visit-day today">今日</span>'
      : dMs === tomMs
        ? '<span class="dash-visit-day tomorrow">明日</span>'
        : `<span class="dash-visit-day other">${mo}/${d}（${wdStr}）</span>`;

    const s   = a.request_status || '調整中';
    const cls = s==='確定'?'confirmed':s==='支払OK'?'payok':s==='支払申請済'?'payapplied':'pending';
    // 案件IDがある行はクリック可能にする
    const hasProj  = !!(proj && a.project_id);
    const rowClass = hasProj ? 'vl-row-clickable' : '';
    const rowData  = hasProj ? `data-pid="${a.project_id}"` : '';

    return `<tr class="${rowClass}" ${rowData}>
      <td class="vl-date">${dayLabel}<span class="vl-time">${timePart}</span></td>
      <td class="vl-sns">${snsBadge(inf.sns_type)}</td>
      <td class="vl-name-proj">
        <div class="vl-name-inner"><strong>${escHtml(inf.name)}</strong></div>
        <div class="vl-proj-inner">${proj ? escHtml(proj.project_name) : '<span style="color:var(--gray-300)">—</span>'}</div>
      </td>
      <td class="vl-status"><span class="dash-visit-status ${cls}">${s}</span>${hasProj ? '<span class="vl-link-icon"><i class="fas fa-chevron-right"></i></span>' : ''}</td>
    </tr>`;
  }).join('');

  container.innerHTML = `
    <table class="dash-visit-table">
      <thead>
        <tr>
          <th>日時</th>
          <th>SNS</th>
          <th>アカウント名<br><span style="font-weight:400;color:var(--gray-400)">案件名</span></th>
          <th>ステータス</th>
        </tr>
      </thead>
      <tbody>${rows}</tbody>
    </table>
  `;

  // 行クリック → 案件詳細パネルを開く
  container.querySelectorAll('tr.vl-row-clickable').forEach(tr => {
    tr.addEventListener('click', () => {
      const pid = tr.dataset.pid;
      if (pid) openProjectDetail(pid);
    });
  });
}

// ── 月別売上推移グラフ（当期・前期対比）──
function _renderMonthlyChart(projects, curFY, prevFY, fiscalMonth) {
  const fm = (fiscalMonth||1) - 1; // 0-indexed 開始月

  // 月インデックス（0〜11）を決算期順に並べる
  const monthOrder = Array.from({length:12}, (_,i) => (fm+i) % 12);

  const curMonthly  = Array(12).fill(0);
  const prevMonthly = Array(12).fill(0);
  const curCount    = Array(12).fill(0);

  projects.forEach(p => {
    let date;
    if (p.start_date) date = new Date(p.start_date);
    else if (p.created_at) date = new Date(p.created_at);
    else return;
    const fy = _projFiscalYear(p, fiscalMonth);
    const calMonth = date.getMonth(); // 0-indexed
    // 決算期内の月インデックス（0〜11）
    const idx = (calMonth - fm + 12) % 12;
    if (fy === curFY)  { curMonthly[idx]  += Number(p.budget)||0; curCount[idx]++; }
    if (fy === prevFY) { prevMonthly[idx] += Number(p.budget)||0; }
  });

  // ラベル生成（決算期順）
  const monthNames = ['1月','2月','3月','4月','5月','6月','7月','8月','9月','10月','11月','12月'];
  const labels = monthOrder.map(m => monthNames[m]);

  // 当月の決算期内インデックス
  const nowCalMonth = new Date().getMonth();
  const nowFY = _projFiscalYear({start_date: new Date().toISOString().slice(0,10)}, fiscalMonth);
  const curMonthIdx = (nowCalMonth - fm + 12) % 12;

  const canvas = document.getElementById('dash-monthly-chart');
  if (!canvas) return;
  if (_dashMonthlyChart) { _dashMonthlyChart.destroy(); _dashMonthlyChart = null; }

  _dashMonthlyChart = new Chart(canvas.getContext('2d'), {
    type: 'bar',
    data: {
      labels,
      datasets: [
        {
          label: `当期（${curFY}年度）売上`,
          data: curMonthly,
          backgroundColor: curMonthly.map((_,i) =>
            (nowFY===curFY && i===curMonthIdx)
              ? 'rgba(99,102,241,0.9)' : 'rgba(99,102,241,0.5)'
          ),
          borderColor: 'rgba(99,102,241,1)',
          borderWidth: 1,
          borderRadius: 4,
          yAxisID: 'y',
        },
        {
          label: `前期（${prevFY}年度）売上`,
          data: prevMonthly,
          backgroundColor: 'rgba(156,163,175,0.35)',
          borderColor: 'rgba(156,163,175,0.8)',
          borderWidth: 1,
          borderRadius: 4,
          yAxisID: 'y',
        },
        {
          label: '当期件数',
          data: curCount,
          type: 'line',
          borderColor: '#f97316',
          backgroundColor: 'rgba(249,115,22,0.08)',
          borderWidth: 2,
          pointRadius: 4,
          pointBackgroundColor: '#f97316',
          tension: 0.3,
          yAxisID: 'y2',
          fill: true,
        }
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { position:'top', labels:{ font:{size:11}, boxWidth:12, padding:12 } },
        tooltip: {
          callbacks: {
            label: ctx => ctx.datasetIndex <= 1
              ? ` ${formatMoney(ctx.parsed.y)}` : ` ${ctx.parsed.y}件`
          }
        }
      },
      scales: {
        y: {
          position: 'left',
          beginAtZero: true,
          ticks: {
            font: {size:10},
            callback: v => v>=1000000?`${(v/10000).toFixed(0)}万`:v>=1000?`${(v/1000).toFixed(0)}K`:v
          },
          grid: { color:'rgba(0,0,0,0.04)' }
        },
        y2: {
          position: 'right',
          beginAtZero: true,
          ticks: { font:{size:10}, stepSize:1 },
          grid: { display:false }
        },
        x: { ticks:{ font:{size:11} }, grid:{ display:false } }
      }
    }
  });
}

// ── フォロワー数フォーマット（ダッシュボード用）──
function _fmtFollowersDash(n) {
  n = Number(n)||0;
  if (n >= 100000000) return (n/100000000).toFixed(1)+'億';
  if (n >= 10000)     return (n/10000).toFixed(1)+'万';
  if (n >= 1000)      return (n/1000).toFixed(1)+'K';
  return n.toLocaleString();
}

