/* ── タブバッジ（件数）更新 ─────────────────────── */
function updateProjectTabBadges() {
  // all
  const allBadge = document.getElementById('tab-badge-all');
  if (allBadge) allBadge.textContent = allProjects.length || '';

  // 各タブ
  Object.entries(PROJECT_TAB_MAP).forEach(([tab, statuses]) => {
    if (tab === 'all') return;
    const badge = document.getElementById(`tab-badge-${tab}`);
    if (!badge) return;
    const cnt = statuses ? allProjects.filter(p => statuses.includes(p.status || '')).length : 0;
    badge.textContent = cnt > 0 ? cnt : '';
  });

  // カテゴリタブ：インフルエンサー案件のバッジ
  const catBadgeInf = document.getElementById('cattab-badge-influencer');
  if (catBadgeInf) catBadgeInf.textContent = allProjects.length || '';
}

// ===== 案件カテゴリタブ（インフルエンサー / SS / チケット）=====
let _projCatTabInited = false;
let _currentProjCat   = 'influencer'; // 現在表示中のカテゴリ

function initProjCatTabs() {
  if (_projCatTabInited) return;
  _projCatTabInited = true;

  document.querySelectorAll('.proj-cat-tab').forEach(btn => {
    btn.addEventListener('click', () => {
      _currentProjCat = btn.dataset.cattab;
      document.querySelectorAll('.proj-cat-tab').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      // パネル切り替え
      document.querySelectorAll('.proj-cat-panel').forEach(p => p.style.display = 'none');
      const panel = document.getElementById(`proj-panel-${_currentProjCat}`);
      if (panel) panel.style.display = '';
    });
  });
}

// ===== チケット インライン表示（ステータスタブ付き） =====
let _inlineTickets = [];          // 全チケット（削除済み除く）
let _inlineTicketCatFilter = '';
let _inlineTicketStatusFilter = 'all';  // 'all' | '提案中' | '進行中' | '請求中' | '完了'
let _inlineTicketPage = 1;
const INLINE_TICKET_PAGE_SIZE = 10;

// チケットパネルのステータスタブ初期化
function initTicketStatusTabs() {
  const bar = document.getElementById('ticket-status-tab-bar');
  if (!bar || bar.dataset.inited === '1') return;
  bar.dataset.inited = '1';
  bar.querySelectorAll('.proj-status-tab').forEach(btn => {
    btn.addEventListener('click', () => {
      bar.querySelectorAll('.proj-status-tab').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      _inlineTicketStatusFilter = btn.dataset.tickettab || 'all';
      _inlineTicketPage = 1;
      // cats/prods は _inlineTicketCatsCache / _inlineTicketProdsCache から取得
      renderInlineTickets(_inlineTicketCatsCache, _inlineTicketProdsCache);
    });
  });
}
let _inlineTicketCatsCache = [];
let _inlineTicketProdsCache = [];

async function loadInlineTickets() {
  const tbody = document.getElementById('ticket-inline-tbody');
  if (!tbody) return;
  try {
    const [tkRes, catRes, prodRes] = await Promise.all([
      API.getAll('tickets'),
      API.getAll('ticket_categories'),
      API.getAll('ticket_products'),
    ]);
    // 全チケット（削除済み除く）を保持
    _inlineTickets = (tkRes.data || []).filter(t => !t.is_deleted);
    const cats  = (catRes.data || []).filter(c => !c.is_deleted);
    const prods = prodRes.data || [];
    _inlineTicketCatsCache  = cats;
    _inlineTicketProdsCache = prods;

    // ステータスタブ初期化
    initTicketStatusTabs();

    // カテゴリフィルターを構築
    const catSel = document.getElementById('ticket-inline-cat-filter');
    if (catSel) {
      const existing = [...catSel.options].map(o => o.value);
      cats.forEach(c => {
        if (!existing.includes(c.id)) {
          const opt = document.createElement('option');
          opt.value = c.id; opt.textContent = c.name;
          catSel.appendChild(opt);
        }
      });
      catSel.onchange = () => {
        _inlineTicketCatFilter = catSel.value;
        _inlineTicketPage = 1;
        renderInlineTickets(cats, prods);
      };
    }

    // カテゴリタブバッジ（全件）
    const badge = document.getElementById('cattab-badge-ticket');
    if (badge) badge.textContent = _inlineTickets.length || '';

    renderInlineTickets(cats, prods);
  } catch(e) {
    console.error('loadInlineTickets error', e);
  }
}

function renderInlineTickets(cats, prods) {
  const tbody = document.getElementById('ticket-inline-tbody');
  if (!tbody) return;

  // ステータスタブ初期化（まだなら）
  initTicketStatusTabs();

  // ステータス別バッジ更新
  const TICKET_STATUS_LIST = ['all', '提案中', '進行中', '請求中', '完了'];
  TICKET_STATUS_LIST.forEach(st => {
    const el = document.getElementById(`ticket-stbadge-${st}`);
    if (el) {
      el.textContent = st === 'all'
        ? _inlineTickets.filter(t => !_inlineTicketCatFilter || t.category_id === _inlineTicketCatFilter).length
        : _inlineTickets.filter(t =>
            (!_inlineTicketCatFilter || t.category_id === _inlineTicketCatFilter) && t.status === st
          ).length;
    }
  });

  let filtered = _inlineTickets.filter(t => {
    const catOk    = !_inlineTicketCatFilter || t.category_id === _inlineTicketCatFilter;
    const statusOk = _inlineTicketStatusFilter === 'all' || !_inlineTicketStatusFilter || t.status === _inlineTicketStatusFilter;
    return catOk && statusOk;
  });

  const total = filtered.length;
  const totalPages = Math.max(1, Math.ceil(total / INLINE_TICKET_PAGE_SIZE));
  if (_inlineTicketPage > totalPages) _inlineTicketPage = 1;
  const slice = filtered.slice((_inlineTicketPage-1)*INLINE_TICKET_PAGE_SIZE, _inlineTicketPage*INLINE_TICKET_PAGE_SIZE);

  // 件数バッジ（現在フィルター結果）
  const countBadge = document.getElementById('ticket-inline-count-badge');
  if (countBadge) countBadge.textContent = total;

  if (slice.length === 0) {
    const emptyMsg = _inlineTicketStatusFilter && _inlineTicketStatusFilter !== 'all'
      ? `<span style="font-weight:600;">${escHtml(_inlineTicketStatusFilter)}</span> のチケットはありません`
      : 'チケットはありません';
    tbody.innerHTML = `<tr><td colspan="6" class="empty" style="padding:32px;">${emptyMsg}</td></tr>`;
    document.getElementById('ticket-inline-pagination').innerHTML = '';
    return;
  }

  tbody.innerHTML = slice.map(t => {
    const cat  = cats.find(c => c.id === t.category_id);
    const catColor = cat?.color || '#e2e8f0';
    const catName  = escHtml(cat?.name || t.category_name || '');
    const period   = [t.start_date, t.end_date].filter(Boolean).map(d=>d.slice(0,10)).join(' 〜 ') || '—';

    // 商品名（最初の1件を簡易表示）
    const pids = t.ticket_product_ids || [];
    const firstProd = prods.find(p => pids[0] && p.id === pids[0]);
    const prodText = firstProd
      ? `<span style="font-size:12px;">${escHtml(firstProd.store_name||'')} ${escHtml(firstProd.product_name||'')}</span>${pids.length>1?`<span class="contact-chip-more" style="margin-left:4px;">+${pids.length-1}</span>`:''}`
      : '<span style="color:var(--gray-300);font-size:12px;">—</span>';

    return `<tr>
      <td style="font-size:12px;font-weight:700;color:var(--gray-500);white-space:nowrap;">${escHtml(t.ticket_number||'—')}</td>
      <td style="font-weight:600;">${escHtml(t.title||'—')}</td>
      <td>
        ${catName ? `<span class="ticket-cat-badge" style="background:${catColor}20;color:${catColor};border:1px solid ${catColor}50;border-radius:20px;padding:2px 10px;font-size:11px;font-weight:700;">${catName}</span>` : '—'}
      </td>
      <td style="font-size:12px;white-space:nowrap;">${period}</td>
      <td>${prodText}</td>
      <td>
        <div class="action-btns">
          <button class="btn btn-icon view inline-ticket-detail-btn" data-id="${escHtml(t.id)}" title="チケット管理で開く"><i class="fas fa-external-link-alt"></i></button>
        </div>
      </td>
    </tr>`;
  }).join('');

  // 外部リンクボタン → チケット管理ページへ遷移
  tbody.querySelectorAll('.inline-ticket-detail-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      navigateTo('tickets');
    });
  });

  // ページネーション
  renderPagination('ticket-inline-pagination', _inlineTicketPage, totalPages, p => {
    _inlineTicketPage = p;
    renderInlineTickets(cats, prods);
  });
}

/* ── タブUI初期化（DOMが存在するときに一度だけ呼ぶ） ─── */
let _projectTabsInited = false;
function initProjectTabs() {
  if (_projectTabsInited) return;
  _projectTabsInited = true;

  document.querySelectorAll('.proj-tab').forEach(btn => {
    btn.addEventListener('click', () => {
      currentProjectTab = btn.dataset.tab;
      projectPage = 1;
      document.querySelectorAll('.proj-tab').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      renderProjects();
    });
  });
  // クライアント名テキスト検索
  const clientSearchEl = document.getElementById('projectClientSearch');
  if (clientSearchEl) {
    clientSearchEl.addEventListener('input', () => { projectPage = 1; renderProjects(); });
  }

  // ── 店舗名ドロップダウン ──
  const storeBtn      = document.getElementById('proj-store-filter-btn');
  const storeDropdown = document.getElementById('proj-store-dropdown');
  const storeSearchInput = document.getElementById('proj-store-search-input');

  if (storeBtn && storeDropdown) {
    // ── ポップアップ内のクリックはdocumentへ伝播させない（閉じ防止）
    storeDropdown.addEventListener('click', (e) => {
      e.stopPropagation();
    });

    // ボタンクリックで開閉
    storeBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      const isOpen = storeDropdown.style.display !== 'none';
      if (isOpen) {
        storeDropdown.style.display = 'none';
      } else {
        // 開くとき：確定済み状態を一時状態にコピー
        _psdTempAll    = _projectStoreFilterAll;
        _psdTempFilter = new Set(_projectStoreFilter);
        storeDropdown.style.display = 'block';
        const si = document.getElementById('proj-store-search-input');
        if (si) si.value = '';
        _buildStoreList('');
        si?.focus();
      }
    });

    // ドキュメントクリックでは閉じない（OK/キャンセルのみで閉じる）

    // 店舗名検索インプット（リアルタイム絞り込み）
    storeSearchInput?.addEventListener('input', () => {
      _buildStoreList(storeSearchInput.value);
    });

    // ── フッター：OKボタン（一時状態を確定→反映→閉じる）
    document.getElementById('psd-foot-ok')?.addEventListener('click', () => {
      _projectStoreFilterAll = _psdTempAll;
      _projectStoreFilter    = new Set(_psdTempFilter);
      storeDropdown.style.display = 'none';
      _updateStoreFilterLabel();
      projectPage = 1;
      renderProjects();
    });

    // ── フッター：キャンセルボタン（変更破棄→すべて表示→閉じる）
    document.getElementById('psd-foot-cancel')?.addEventListener('click', () => {
      _projectStoreFilterAll = true;
      _projectStoreFilter    = new Set();
      _psdTempAll            = true;
      _psdTempFilter         = new Set();
      storeDropdown.style.display = 'none';
      _updateStoreFilterLabel();
      projectPage = 1;
      renderProjects();
    });

    // ── フッター：クリアボタン（チェックをすべて外す。閉じない）
    document.getElementById('psd-foot-clear')?.addEventListener('click', () => {
      _psdTempAll    = false;
      _psdTempFilter = new Set();
      _buildStoreList(storeSearchInput?.value || '');
    });

    // ── フッター：すべてボタン（全チェック。閉じない）
    document.getElementById('psd-foot-all')?.addEventListener('click', () => {
      _psdTempAll    = true;
      _psdTempFilter = new Set();
      _buildStoreList(storeSearchInput?.value || '');
    });
  }
  // ソートセレクト
  const sortEl = document.getElementById('projectSortSelect');
  if (sortEl) {
    sortEl.value = currentProjectSort;
    sortEl.addEventListener('change', () => {
      currentProjectSort = sortEl.value;
      projectPage = 1;
      renderProjects();
    });
  }

  // ── 案件一覧 Excel出力ボタン ──
  document.getElementById('btn-proj-excel-export')?.addEventListener('click', () => {
    _exportProjectsExcel();
  });
}

// ── 店舗名フィルター ドロップダウン ヘルパー ──────────────────────────

/** 全案件の product_name から重複なしの店舗名一覧を取得 */
function _getAllStoreNames() {
  const names = new Set();
  allProjects.forEach(p => {
    const n = (p.product_name || '').trim();
    names.add(n || '（未設定）');
  });
  return [...names].sort((a, b) => a.localeCompare(b, 'ja'));
}

/** 初回ロード時にドロップダウンを構築（すべて選択状態） */
function _initStoreFilterDropdown() {
  _projectStoreFilterAll = true;
  _projectStoreFilter    = new Set();
  _psdTempAll            = true;
  _psdTempFilter         = new Set();
  _updateStoreFilterLabel();
}

/** ドロップダウンのリスト部分を構築（q=検索フィルター）
 *  チェック操作は _psdTempFilter/_psdTempAll に保存。OK押下時のみ確定。 */
function _buildStoreList(q) {
  const listEl = document.getElementById('proj-store-list');
  if (!listEl) return;

  const allNames = _getAllStoreNames();
  const lq = (q || '').trim().toLowerCase();
  const filtered = lq ? allNames.filter(function(n){ return n.toLowerCase().indexOf(lq) !== -1; }) : allNames;

  // 一時状態ベースで「すべて選択」ヘッダーの状態を決める
  var allChecked = lq
    ? (filtered.length > 0 && filtered.every(function(n){ return _psdTempAll || _psdTempFilter.has(n); }))
    : _psdTempAll;

  var html = '';

  // ── ヘッダー行（すべて選択トグル）
  html += '<div id="psd-header-row" class="psd-header">'
        +   '<span class="psd-header-check' + (allChecked ? ' checked' : '') + '" id="psd-header-check"></span>'
        +   '<span class="psd-header-label">すべて選択</span>'
        + '</div>';

  if (filtered.length === 0) {
    html += '<div class="psd-empty">店舗が見つかりません</div>';
  } else {
    for (var i = 0; i < filtered.length; i++) {
      var name = filtered[i];
      var sel  = (_psdTempAll || _psdTempFilter.has(name)) ? ' psd-selected' : '';
      var esc  = escHtml(name);
      html += '<div class="psd-item' + sel + '" data-store="' + esc + '">'
            +   '<span class="psd-mark"></span>'
            +   '<span class="psd-name">' + esc + '</span>'
            + '</div>';
    }
  }

  listEl.innerHTML = html;

  // ── ヘッダー行クリック（すべて選択トグル）：閉じない・renderしない
  var headerRow   = document.getElementById('psd-header-row');
  var headerCheck = document.getElementById('psd-header-check');
  if (headerRow && headerCheck) {
    headerRow.addEventListener('click', function() {
      var on = !headerCheck.classList.contains('checked');
      if (!lq) {
        _psdTempAll    = on;
        if (on) _psdTempFilter = new Set();
      } else {
        if (on) filtered.forEach(function(n){ _psdTempFilter.add(n); });
        else    filtered.forEach(function(n){ _psdTempFilter.delete(n); });
        _psdTempAll = (_psdTempFilter.size >= allNames.length);
        if (_psdTempAll) _psdTempFilter = new Set();
      }
      _buildStoreList(q); // リスト再描画のみ（閉じない）
    });
  }

  // ── 個別行クリック：一時状態を更新するだけ（閉じない・renderしない）
  listEl.querySelectorAll('.psd-item').forEach(function(row) {
    row.addEventListener('click', function() {
      var name = row.getAttribute('data-store');
      if (row.classList.contains('psd-selected')) {
        _psdTempFilter.delete(name);
        _psdTempAll = false;
      } else {
        _psdTempFilter.add(name);
        if (!lq && _psdTempFilter.size >= allNames.length) {
          _psdTempAll    = true;
          _psdTempFilter = new Set();
        }
      }
      _buildStoreList(q); // リスト再描画のみ（閉じない）
    });
  });
}

/** 案件一覧を現在の表示フィルターでExcel（CSV）出力 */
function _exportProjectsExcel() {
  const clientMap = {};
  allClients.forEach(c => { clientMap[c.id] = c; });

  const clientSearch = (document.getElementById('projectClientSearch')?.value || '').toLowerCase();
  const tabStatuses  = PROJECT_TAB_MAP[currentProjectTab];

  // renderProjects と同じフィルター条件
  const filtered = allProjects.filter(p => {
    let clNames = '';
    if (p.project_clients) {
      try {
        const _rawF = p.project_clients;
        const pcs = typeof _rawF === 'string' ? JSON.parse(_rawF) : (Array.isArray(_rawF) ? _rawF : []);
        clNames = pcs.map(c => { const cli = clientMap[c.client_id]; return cli ? cli.company_name : ''; }).join(' ');
      } catch(e) {}
    }
    if (!clNames && p.client_id) {
      const cl = clientMap[p.client_id]; clNames = cl ? cl.company_name : '';
    }
    const matchClient = !clientSearch || clNames.toLowerCase().includes(clientSearch);
    const storeName   = (p.product_name || '').trim();
    const matchStore  = _projectStoreFilterAll || _projectStoreFilter.size === 0 ||
      _projectStoreFilter.has(storeName) || (!storeName && _projectStoreFilter.has('（未設定）'));
    const matchTab    = !tabStatuses || tabStatuses.includes(p.status || '');
    return matchClient && matchStore && matchTab;
  });

  // CSV ヘッダー
  const headers = ['案件ID','店舗名','クライアント名','ステータス','開始月','終了月','担当者','予算（税抜）','登録日'];

  const rows = filtered.map(p => {
    // クライアント名を結合
    let clNames = '';
    if (p.project_clients) {
      try {
        const _rawE = p.project_clients;
        const pcs = typeof _rawE === 'string' ? JSON.parse(_rawE) : (Array.isArray(_rawE) ? _rawE : []);
        clNames = pcs.map(c => { const cli = clientMap[c.client_id]; return cli ? cli.company_name : ''; }).filter(Boolean).join('／');
      } catch(e) {}
    }
    if (!clNames && p.client_id) {
      const cl = clientMap[p.client_id]; clNames = cl ? cl.company_name : '';
    }
    return [
      p.id            || '',
      p.product_name  || '',
      clNames,
      p.status        || '',
      p.start_date    || '',
      p.end_date      || '',
      p.manager_name  || '',
      p.budget != null ? p.budget : '',
      p.created_at ? new Date(p.created_at).toLocaleDateString('ja-JP') : ''
    ];
  });

  // BOM付きCSV生成
  const escape = v => {
    const s = String(v);
    return (s.includes(',') || s.includes('"') || s.includes('\n')) ? '"' + s.replace(/"/g, '""') + '"' : s;
  };
  const bom  = '\uFEFF';
  const csv  = bom + [headers, ...rows].map(r => r.map(escape).join(',')).join('\r\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  const now  = new Date();
  const ymd  = now.getFullYear() + ('0'+(now.getMonth()+1)).slice(-2) + ('0'+now.getDate()).slice(-2);
  a.href     = url;
  a.download = '\u6848\u4ef6\u4e00\u89a7_' + ymd + '.csv';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

/** ボタンのラベルを現在の選択状態に応じて更新 */
function _updateStoreFilterLabel() {
  const labelEl = document.getElementById('proj-store-filter-label');
  if (!labelEl) return;
  if (_projectStoreFilterAll || _projectStoreFilter.size === 0) {
    labelEl.textContent = `店舗名（すべて）`;
    document.getElementById('proj-store-filter-btn')?.classList.remove('proj-store-filter-btn--active');
  } else {
    const cnt = _projectStoreFilter.size;
    labelEl.textContent = cnt === 1
      ? [..._projectStoreFilter][0]
      : `店舗名（${cnt}件選択）`;
    document.getElementById('proj-store-filter-btn')?.classList.add('proj-store-filter-btn--active');
  }
}

async function loadProjects() {
  // カテゴリタブUIをバインド（初回 or ページ再表示時）
  initProjCatTabs();
  // ステータスタブUIをバインド
  initProjectTabs();
  // デフォルトタブ（進行中）を常に active にリセット
  currentProjectTab = '進行中';
  projectPage = 1;
  document.querySelectorAll('.proj-tab').forEach(b => {
    b.classList.toggle('active', b.dataset.tab === '進行中');
  });
  // 進行中タブのソートUIはrenderProjects()内で制御するため不要
  // （initProjectTabs内でvalueのみセット済み）
  try {
    const [projRes, clientRes, assignRes, infRes, contactRes] = await Promise.all([
      Cache.get('projects',           () => API.getAll('projects')),
      Cache.get('clients',            () => API.getAll('clients')),
      Cache.get('projectInfluencers', () => API.getAll('project_influencers')),
      Cache.get('influencers',        () => API.getAll('influencers', {}, 20)),
      Cache.get('client_contacts',    () => API.getAll('client_contacts')),
    ]);
    allProjects       = projRes.data    || [];
    allClients        = clientRes.data  || [];
    allAssignments    = assignRes.data  || [];
    allInfluencers    = infRes.data     || [];
    allClientContacts = contactRes.data || [];
    // 店舗名フィルタードロップダウンを更新（初回のみすべて選択）
    _initStoreFilterDropdown();
    renderProjects();
    loadSSSection();          // サブスク/スポットセクション描画
    loadInlineTickets();      // チケット（進行中）描画
  } catch(err) {
    console.error(err);
    showToast('案件の読み込みに失敗しました', 'error');
  }
}

/**
 * キャスティングボタンのみを差分更新（renderProjects()より大幅に軽量）
 * ステータス変更・来店日時更新後のボタン色更新に使用
 */
function updateCastingButtons() {
  const infMap = {};
  allInfluencers.forEach(inf => { infMap[inf.id] = inf; });
  document.querySelectorAll('.casting-detail-btn[data-pid]').forEach(btn => {
    const pid = btn.dataset.pid;
    const assigns = allAssignments.filter(a => a.project_id === pid);
    const newBtn = document.createElement('div');
    newBtn.innerHTML = buildCastingBoard(pid, assigns, infMap);
    const newBtnEl = newBtn.firstElementChild;
    if (newBtnEl) {
      btn.className = newBtnEl.className;
      btn.innerHTML = newBtnEl.innerHTML;
    }
  });
}

// 店舗名フィルター状態（Set: 空=すべて表示）
let _projectStoreFilter    = new Set(); // 確定済み選択（OK押下後に反映）
let _projectStoreFilterAll = true;      // 確定済み「すべて選択」状態
let _psdTempFilter         = new Set(); // ポップアップ操作中の一時選択
let _psdTempAll            = true;      // ポップアップ操作中の一時「すべて選択」状態

function renderProjects() {
  const clientSearch = (document.getElementById('projectClientSearch')?.value || '').toLowerCase();
  const clientMap    = {};
  allClients.forEach(c => { clientMap[c.id] = c; });
  const infMap = {};
  allInfluencers.forEach(i => { infMap[i.id] = i; });
  // 担当者マップ
  const contactMap = {};
  (allClientContacts||[]).filter(c=>!c.is_deleted).forEach(c => { contactMap[c.id] = c; });

  // ── ソートセレクト：進行中タブのみ表示・値を同期 ──
  const sortSelectEl = document.getElementById('projectSortSelect');
  if (sortSelectEl) {
    const isIn = currentProjectTab === '進行中';
    sortSelectEl.style.display = isIn ? '' : 'none';
    if (isIn) sortSelectEl.value = currentProjectSort;
  }

  // 利益率アラート閾値（企業情報から取得）
  const alertRate = (companyInfoRecord && companyInfoRecord.profit_alert_rate !== null &&
    companyInfoRecord.profit_alert_rate !== undefined && companyInfoRecord.profit_alert_rate !== '')
    ? Number(companyInfoRecord.profit_alert_rate) : null;

  // タブ別フィルタ
  const tabStatuses = PROJECT_TAB_MAP[currentProjectTab]; // null=all, array=絞り込み

  let filtered = allProjects.filter(p => {
    // 複数クライアント名を結合して検索
    let clNames = '';
    if (p.project_clients) {
      try {
        const _raw = p.project_clients;
        const pcs = typeof _raw === 'string' ? JSON.parse(_raw) : (Array.isArray(_raw) ? _raw : []);
        clNames = pcs.filter(c => !c.removed).map(c => { const cli = clientMap[c.client_id]; return cli ? cli.company_name : ''; }).join(' ');
      } catch(e) { /* noop */ }
    }
    if (!clNames && p.client_id) {
      const cl = clientMap[p.client_id];
      clNames = cl ? cl.company_name : '';
    }
    // クライアント名テキスト検索（案件名・店舗名も対象）
    const projName  = (p.project_name  || '').toLowerCase();
    const prodName  = (p.product_name  || '').toLowerCase();
    const matchClient = !clientSearch ||
      clNames.toLowerCase().includes(clientSearch) ||
      projName.includes(clientSearch) ||
      prodName.includes(clientSearch);
    // 店舗名チェックボックスフィルター（空Set=すべて表示）
    const storeName = (p.product_name || '').trim();
    const matchStore = _projectStoreFilterAll || _projectStoreFilter.size === 0 ||
      _projectStoreFilter.has(storeName) ||
      (!storeName && _projectStoreFilter.has('（未設定）'));
    const matchTab = !tabStatuses || tabStatuses.includes(p.status || '');
    return matchClient && matchStore && matchTab;
  });

  // タブバッジ（件数）を更新
  updateProjectTabBadges();

  // ── ソート ──
  // 進行中タブ：currentProjectSort に従う / それ以外：start_date 昇順（従来通り）
  // ★ is_urgent=true の案件は常にタブ内先頭に表示
  if (currentProjectTab === '進行中') {
    const sort = currentProjectSort;
    filtered.sort((a, b) => {
      // 至急確認フラグ優先
      const urgA = a.is_urgent ? 1 : 0;
      const urgB = b.is_urgent ? 1 : 0;
      if (urgA !== urgB) return urgB - urgA;
      const da = a.start_date || '';
      const db = b.start_date || '';
      if (sort === 'start_asc') {
        if (da && db)  return da < db ? -1 : da > db ? 1 : (b.created_at||0) - (a.created_at||0);
        if (da && !db) return -1;
        if (!da && db) return 1;
        return (b.created_at||0) - (a.created_at||0);
      } else if (sort === 'start_desc') {
        if (da && db)  return da > db ? -1 : da < db ? 1 : (b.created_at||0) - (a.created_at||0);
        if (da && !db) return -1;
        if (!da && db) return 1;
        return (b.created_at||0) - (a.created_at||0);
      } else { // created_desc
        return (b.created_at||0) - (a.created_at||0);
      }
    });
  } else {
    // 進行中以外：至急確認を先頭に、次いで start_date 昇順
    filtered.sort((a, b) => {
      const urgA = a.is_urgent ? 1 : 0;
      const urgB = b.is_urgent ? 1 : 0;
      if (urgA !== urgB) return urgB - urgA;
      const da = a.start_date || '';
      const db = b.start_date || '';
      if (da && db) return da < db ? -1 : da > db ? 1 : (b.created_at||0) - (a.created_at||0);
      if (da && !db) return -1;
      if (!da && db) return 1;
      return (b.created_at||0) - (a.created_at||0);
    });
  }

  const total = filtered.length;
  // 進行中タブはスクロール型（全件表示）、それ以外はページネーション
  const isScrollMode = currentProjectTab === '進行中';
  const totalPages = isScrollMode ? 1 : Math.max(1, Math.ceil(total/projectPageSize));
  if (projectPage > totalPages) projectPage = 1;
  const paged = isScrollMode
    ? filtered
    : filtered.slice((projectPage-1)*projectPageSize, projectPage*projectPageSize);

  const tbody = document.getElementById('projects-tbody');

  // 「請求中」タブのみ「入金期日」列を表示
  const isInvoiceTab = currentProjectTab === '請求中';
  const deadlineTh = document.querySelector('.payment-deadline-th');
  if (deadlineTh) deadlineTh.style.display = isInvoiceTab ? '' : 'none';

  if (paged.length === 0) {
    tbody.innerHTML = `<tr><td colspan="${isInvoiceTab ? 14 : 13}" class="empty">
      <div class="empty-state"><i class="fas fa-briefcase"></i><p>案件が見つかりません</p></div>
    </td></tr>`;
  } else {
    tbody.innerHTML = paged.map(p => {
      const cl = clientMap[p.client_id];
      const period = (p.start_date||p.end_date)
        ? `${formatDate(p.start_date)} 〜 ${formatDate(p.end_date)}` : '—';
      const assigns = allAssignments.filter(a => a.project_id === p.id);
      const isExpanded = expandedProjectIds.has(p.id);

      // 「全員支払申請済」判定（1名以上いて、全員が支払申請済）
      const allPaidApplied = assigns.length > 0 && assigns.every(a => a.request_status === '支払申請済');
      const invoiceBellMark = allPaidApplied
        ? `<span class="invoice-bell-mark" title="全員支払申請済です"><i class="fas fa-bell"></i></span>`
        : '';

      // 利益率計算（案件詳細と同じロジック: request_amount → unit_price フォールバック）
      const pBudget = Number(p.budget) || 0;
      const pAssignCost = assigns.reduce((sum, a) => {
        const inf = infMap[a.influencer_id];
        let v = a.request_amount;
        if (v === null || v === undefined || v === '') {
          v = inf ? inf.unit_price : null;
        }
        const n = (v === null || v === undefined || v === '')
          ? 0 : parseFloat(String(v).replace(/[^0-9.-]/g, ''));
        return sum + (isNaN(n) ? 0 : n);
      }, 0);
      const pProfit = pBudget - pAssignCost;
      const pProfitRate = pBudget > 0 ? ((pProfit / pBudget) * 100) : null;
      // 利益率バッジ（企業設定閾値で2色化・50%超でベルマーク）
      // alertRate 未設定の場合は 30% をデフォルト閾値とする
      const effectiveAlertRate = alertRate !== null ? alertRate : 30;
      const isGood       = pProfitRate !== null && pProfitRate >= effectiveAlertRate;
      const isBad        = pProfitRate !== null && pProfitRate <  effectiveAlertRate;
      const isHighProfit = pProfitRate !== null && pProfitRate >  50;

      const badgeClass   = isGood ? 'profit-rate-good' : isBad ? 'profit-rate-bad' : '';
      const bellIcon     = isHighProfit
        ? ' <i class="fas fa-bell" style="font-size:9px;" title="利益率50%超"></i>'
        : '';
      const profitRateCellHtml = pProfitRate !== null
        ? `<span class="profit-rate-badge ${badgeClass}">${pProfitRate.toFixed(1)}%${bellIcon}</span>`
        : '<span class="profit-rate-na">—</span>';

      // 利益額セル
      const profitAmtColor = pProfit < 0 ? 'color:#ef4444;font-weight:700;' : pBudget > 0 ? 'color:#10b981;font-weight:600;' : 'color:var(--gray-400);';
      const profitAmtCellHtml = pBudget > 0
        ? `<span style="font-size:12px;${profitAmtColor}">${formatMoney(pProfit)}</span>`
        : '<span class="profit-rate-na">—</span>';

      // アサインなし行スタイル
      const noAssign = assigns.length === 0;
      const rowHtml = `<tr class="project-main-row${noAssign ? ' project-row-no-assign' : ''}${p.is_urgent ? ' project-row-urgent' : ''}" data-project-id="${escHtml(p.id)}">
        <td><a href="#" class="proj-detail-link" data-id="${escHtml(p.id)}"
          style="color:var(--primary);font-weight:600;">${escHtml(p.project_name)}</a></td>
        <td>${(() => {
          // project_clients JSON → 複数社縦並び
          let pcs = [];
          if (p.project_clients) {
            try {
              const _raw = p.project_clients;
              pcs = typeof _raw === 'string' ? JSON.parse(_raw) : (Array.isArray(_raw) ? _raw : []);
            } catch(e) { pcs = []; }
          }
          if (pcs.length === 0 && p.client_id) pcs = [{ client_id: p.client_id }];
          // removed:true を除外して表示
          const activePcs = pcs.filter(c => !c.removed);
          if (activePcs.length === 0) return '<span style="color:var(--gray-400)">—</span>';
          const names = activePcs.map(c => {
            const cli = clientMap[c.client_id];
            return cli ? `<span>${escHtml(cli.company_name)}</span>` : '';
          }).filter(Boolean);
          return names.length > 0
            ? `<div class="multi-client-list">${names.join('')}</div>`
            : '<span style="color:var(--gray-400)">—</span>';
        })()}</td>
        <td class="inline-edit-cell" data-pid="${escHtml(p.id)}" data-field="product_name" title="\u30af\u30ea\u30c3\u30af\u3067\u7de8\u96c6">
          <span class="inline-val">${escHtml(p.product_name)||'<span class="inline-empty">\u672a\u8a2d\u5b9a</span>'}</span>
        </td>
        <td class="inline-edit-cell inline-period-cell" data-pid="${escHtml(p.id)}" data-field="period" title="\u30af\u30ea\u30c3\u30af\u3067\u7de8\u96c6">
          <span class="inline-val">${(p.start_date||p.end_date) ? `${formatDate(p.start_date)}&nbsp;\u301c&nbsp;${formatDate(p.end_date)}` : '<span class="inline-empty">\u672a\u8a2d\u5b9a</span>'}</span>
        </td>
        <td class="inline-edit-cell" data-pid="${escHtml(p.id)}" data-field="budget" title="\u30af\u30ea\u30c3\u30af\u3067\u7de8\u96c6">
          <span class="inline-val">${p.budget ? formatMoney(p.budget) : '<span class="inline-empty">\u672a\u8a2d\u5b9a</span>'}</span>
        </td>
        <td class="casting-board-cell" data-pid="${escHtml(p.id)}">
          ${buildCastingBoard(p.id, assigns, infMap, !!p.is_urgent)}
        </td>
        <td class="inline-edit-cell inline-status-cell" data-pid="${escHtml(p.id)}" data-field="status" title="\u30af\u30ea\u30c3\u30af\u3067\u5909\u66f4">
          <span class="inline-val">${statusBadge(p.status)}</span>
        </td>
        <td class="inline-edit-cell" data-pid="${escHtml(p.id)}" data-field="manager" title="クリックで編集">
          <span class="inline-val">${escHtml(p.manager)||'<span class="inline-empty">未設定</span>'}</span>
        </td>
        <td class="inline-edit-cell contact-inline-cell" data-pid="${escHtml(p.id)}" data-field="contact_id" title="クリックで担当者を変更">
          ${p.contact_id && contactMap[p.contact_id]
            ? `<span class="inline-val"><span class="contact-chip">${escHtml(contactMap[p.contact_id].name)}</span></span>`
            : '<span class="inline-val"><span class="inline-empty">— 未設定 —</span></span>'}
        </td>
        <td class="profit-rate-cell" style="white-space:nowrap;text-align:center;">${profitRateCellHtml}</td>
        <td class="profit-amt-cell" style="white-space:nowrap;text-align:right;padding-right:10px;">${profitAmtCellHtml}</td>
        ${(() => {
          if (!isInvoiceTab) return '';
          // DB保存値を優先、なければ自動計算（翌月末平日）
          let deadline = null;
          let isManual = false;
          if (p.payment_deadline) {
            // DB値は YYYY-MM-DD 形式 → YYYY/MM/DD に変換して表示
            deadline = p.payment_deadline.replace(/-/g, '/');
            isManual = true;
          } else {
            deadline = calcPaymentDeadline(p.end_date);
          }
          if (!deadline) {
            return `<td class="payment-deadline-cell" data-pid="${escHtml(p.id)}">
              <div class="payment-deadline-wrap">
                <span class="payment-deadline-na">—</span>
                <button class="payment-deadline-edit-btn" title="入金期日を設定"><i class="fas fa-pen"></i></button>
              </div>
            </td>`;
          }
          // 今日との比較で期日切れ警告
          const today = new Date(); today.setHours(0,0,0,0);
          const dParts = deadline.split('/').map(Number);
          const dDate  = new Date(dParts[0], dParts[1]-1, dParts[2]);
          const isOver = dDate < today;
          const isSoon = !isOver && (dDate - today) <= 7 * 24 * 60 * 60 * 1000; // 7日以内
          const cls = isOver ? 'payment-deadline-over' : isSoon ? 'payment-deadline-soon' : '';
          // DB保存値（手動上書き）の場合は鉛筆アイコン + リセットボタンを表示
          const manualMark = isManual
            ? `<span class="payment-deadline-manual-mark" title="手動設定済み"><i class="fas fa-user-edit"></i></span>`
            : '';
          return `<td class="payment-deadline-cell" data-pid="${escHtml(p.id)}">
            <div class="payment-deadline-wrap">
              <span class="payment-deadline-badge ${cls}">${deadline}</span>
              ${manualMark}
              <button class="payment-deadline-edit-btn" title="入金期日を変更"><i class="fas fa-pen"></i></button>
              ${isManual ? `<button class="payment-deadline-reset-btn" title="自動計算値にリセット"><i class="fas fa-undo"></i></button>` : ''}
            </div>
          </td>`;
        })()}
        <td>
          <div class="action-btns">
            <button class="btn btn-icon edit"   data-id="${escHtml(p.id)}" title="編集"><i class="fas fa-edit"></i> 編集</button>
            <button class="btn btn-proj-delete" data-id="${escHtml(p.id)}" title="案件削除"><i class="fas fa-trash"></i> 削除</button>
            <button class="btn btn-invoice${allPaidApplied ? ' has-all-paid' : ''}" data-id="${escHtml(p.id)}" title="請求書作成">${invoiceBellMark}<i class="fas fa-file-invoice-dollar"></i> 請求書</button>
          </div>
        </td>
        <td class="proj-comment-cell inline-edit-cell" data-pid="${escHtml(p.id)}" data-field="notes" title="クリックでコメント編集">
          <span class="inline-val proj-comment-text">${p.notes ? escHtml(p.notes.slice(0,10)) + (p.notes.length > 10 ? '…' : '') : '<span class="inline-empty">—</span>'}</span>
        </td>
      </tr>`;

      // 展開時のインフルエンサー一覧
      let expandHtml = '';
      if (isExpanded) {
        expandHtml = buildAssignPanel(p.id, assigns, infMap);
      }
      return rowHtml + expandHtml;
    }).join('');
  }

  // 進行中タブはスクロール型のためページネーション非表示、それ以外は表示
  const paginationEl = document.getElementById('projects-pagination');
  if (paginationEl) {
    if (isScrollMode) {
      paginationEl.innerHTML = '';
      paginationEl.style.display = 'none';
    } else {
      paginationEl.style.display = '';
      renderPagination('projects-pagination', projectPage, totalPages, p => {
        projectPage = p;
        renderProjects();
      });
    }
  }

  // キャスティングボードセル: 詳細確認ボタンのクリックでサイドパネル表示
  tbody.querySelectorAll('.casting-detail-btn').forEach(btn => {
    btn.addEventListener('click', e => {
      e.stopPropagation();
      openProjectDetail(btn.dataset.pid);
    });
  });
  // 展開ボタン（展開パネル内など残存するもの）
  tbody.querySelectorAll('.expand-btn').forEach(btn => {
    btn.addEventListener('click', e => { e.stopPropagation(); toggleProjectExpand(btn.dataset.pid); });
  });
  // 詳細リンク（.proj-detail-link のみ残す。.btn-icon.view は削除済み）
  tbody.querySelectorAll('.proj-detail-link').forEach(el => {
    el.addEventListener('click', e => { e.preventDefault(); openProjectDetail(el.dataset.id); });
  });
  tbody.querySelectorAll('.btn-icon.edit').forEach(el => {
    el.addEventListener('click', () => openProjectModal(el.dataset.id));
  });
  tbody.querySelectorAll('.btn-proj-delete').forEach(el => {
    el.addEventListener('click', async e => {
      e.stopPropagation();
      e.preventDefault();
      const pid = el.dataset.id;
      const proj = allProjects.find(p => p.id === pid);
      const name = proj ? proj.project_name : '案件';
      if (!confirm(`「${name}」を削除しますか？\nこの操作は取り消せません。`)) return;
      el.disabled = true;
      try {
        // 関連アサインも一緒に削除
        const assignsToDelete = allAssignments.filter(a => a.project_id === pid);
        await Promise.all(assignsToDelete.map(a =>
          fetch(`tables/project_influencers/${a.id}`, { method: 'DELETE' })
        ));
        const res = await fetch(`tables/projects/${pid}`, { method: 'DELETE' });
        if (!res.ok) throw new Error('HTTP ' + res.status);
        showToast('案件を削除しました', 'success');
        // 全キャッシュをクリアして再ロード
        Cache.invalidateAll();
        await loadProjects();
      } catch(err) {
        showToast('削除に失敗しました: ' + err.message, 'error');
        el.disabled = false;
      }
    });
  });
  tbody.querySelectorAll('.btn-invoice').forEach(el => {
    el.addEventListener('click', e => { e.stopPropagation(); openInvoice(el.dataset.id); });
  });
  // スケジュールリンク
  tbody.querySelectorAll('.proj-schedule-btn').forEach(el => {
    el.addEventListener('click', e => { e.preventDefault(); e.stopPropagation(); openScheduleModal(el.dataset.id); });
  });

  // ===== 入金期日インライン編集 =====
  tbody.querySelectorAll('.payment-deadline-cell').forEach(cell => {
    const pid = cell.dataset.pid;
    if (!pid) return;

    // 「編集」ボタン → カレンダー入力モードへ
    const editBtn = cell.querySelector('.payment-deadline-edit-btn');
    if (editBtn) {
      editBtn.addEventListener('click', e => {
        e.stopPropagation();
        if (cell.querySelector('input[type="date"]')) return; // 二重起動防止

        const proj = allProjects.find(p => p.id === pid);
        if (!proj) return;

        // 現在の期日（DB値 or 自動計算）を初期値にセット
        let initVal = '';
        if (proj.payment_deadline) {
          initVal = proj.payment_deadline; // YYYY-MM-DD
        } else {
          const auto = calcPaymentDeadline(proj.end_date);
          if (auto) initVal = auto.replace(/\//g, '-'); // YYYY/MM/DD → YYYY-MM-DD
        }

        // セル内を date input に差し替え
        const wrap = document.createElement('div');
        wrap.className = 'payment-deadline-picker-wrap';
        const inp = document.createElement('input');
        inp.type  = 'date';
        inp.className = 'payment-deadline-input';
        inp.value = initVal;
        wrap.appendChild(inp);
        cell.innerHTML = '';
        cell.appendChild(wrap);
        inp.focus();
        inp.showPicker && inp.showPicker(); // ブラウザ対応でピッカーを即オープン

        const save = async () => {
          const val = inp.value; // YYYY-MM-DD or ''
          try {
            await _saveProjectFields(pid, { payment_deadline: val || null });
            proj.payment_deadline = val || null;
            Cache.invalidate('projects');
            renderProjects();
            showToast('入金期日を保存しました');
          } catch(err) {
            showToast('保存に失敗しました', 'error');
            renderProjects();
          }
        };
        inp.addEventListener('change', save);
        inp.addEventListener('blur', () => {
          // blur後にまだ input が残っていたら（change が発火していない）再描画
          setTimeout(() => { if (cell.querySelector('input[type="date"]')) renderProjects(); }, 200);
        });
      });
    }

    // 「リセット」ボタン → DB値を削除して自動計算に戻す
    const resetBtn = cell.querySelector('.payment-deadline-reset-btn');
    if (resetBtn) {
      resetBtn.addEventListener('click', async e => {
        e.stopPropagation();
        if (!confirm('入金期日を自動計算値（翌月末平日）にリセットしますか？')) return;
        const proj = allProjects.find(p => p.id === pid);
        if (!proj) return;
        try {
          await _saveProjectFields(pid, { payment_deadline: null });
          proj.payment_deadline = null;
          Cache.invalidate('projects');
          renderProjects();
          showToast('入金期日をリセットしました');
        } catch(err) { showToast('リセットに失敗しました', 'error'); }
      });
    }
  });

  // 展開パネル内イベント（アサイン追加・編集・削除）
  bindAssignPanelEvents(tbody);

  // ===== インライン編集 =====
  const STATUS_OPTIONS = ['提案中','進行中','請求中','完了','キャンセル'];

  tbody.querySelectorAll('.inline-edit-cell').forEach(cell => {
    cell.addEventListener('click', async e => {
      // すでに編集中なら何もしない
      if (cell.querySelector('input,select')) return;
      const pid   = cell.dataset.pid;
      const field = cell.dataset.field;
      // allProjects から現在値を取得
      const proj  = allProjects.find(p => p.id === pid);
      if (!proj) return;

      // 担当者フィールドはアカウントが未ロードなら先に取得
      if (field === 'manager' && _allAccounts.length === 0) {
        try {
          const ar = await API.get('accounts', { limit: 200, sort: 'created_at' });
          _allAccounts = ar.data || [];
        } catch(e) { /* 取得失敗でも続行 */ }
      }

      // --- ステータス: selectで即時変更 ---
      if (field === 'status') {
        const sel = document.createElement('select');
        sel.className = 'inline-select';
        STATUS_OPTIONS.forEach(s => {
          const opt = document.createElement('option');
          opt.value = s; opt.textContent = s;
          if (s === proj.status) opt.selected = true;
          sel.appendChild(opt);
        });
        cell.innerHTML = '';
        cell.appendChild(sel);
        sel.focus();

        const save = async () => {
          const val = sel.value;
          try {
            await _saveProjectFields(pid, { status: val });
            proj.status = val;
            renderProjects();
            showToast('\u30b9\u30c6\u30fc\u30bf\u30b9\u3092\u5909\u66f4\u3057\u307e\u3057\u305f');
          } catch(err) { showToast('\u4fdd\u5b58\u306b\u5931\u6557\u3057\u307e\u3057\u305f', 'error'); renderProjects(); }
        };
        sel.addEventListener('change', save);
        sel.addEventListener('blur', () => { if (cell.querySelector('select')) renderProjects(); });
        return;
      }

      // --- 期間: 開始日・終了日を2つのdateインプット ---
      if (field === 'period') {
        const wrap = document.createElement('div');
        wrap.className = 'inline-period-wrap';
        const inStart = document.createElement('input');
        inStart.type  = 'date'; inStart.className = 'inline-input';
        inStart.value = proj.start_date || '';
        const sep = document.createElement('span');
        sep.textContent = '\u301c';
        sep.style.cssText = 'margin:0 2px;color:var(--gray-400);font-size:11px;';
        const inEnd = document.createElement('input');
        inEnd.type  = 'date'; inEnd.className = 'inline-input';
        inEnd.value = proj.end_date || '';
        wrap.appendChild(inStart); wrap.appendChild(sep); wrap.appendChild(inEnd);
        cell.innerHTML = '';
        cell.appendChild(wrap);
        inStart.focus();

        let saving = false;
        const save = async () => {
          if (saving) return; saving = true;
          const s = inStart.value || null;
          const en = inEnd.value  || null;
          try {
            await _saveProjectFields(pid, { start_date: s, end_date: en });
            proj.start_date = s; proj.end_date = en;
            renderProjects();
            showToast('\u671f\u9593\u3092\u66f4\u65b0\u3057\u307e\u3057\u305f');
          } catch(err) { showToast('\u4fdd\u5b58\u306b\u5931\u6557\u3057\u307e\u3057\u305f', 'error'); renderProjects(); }
        };
        inStart.addEventListener('blur', () => setTimeout(() => { if (!wrap.contains(document.activeElement)) save(); }, 150));
        inEnd.addEventListener('blur',   () => setTimeout(() => { if (!wrap.contains(document.activeElement)) save(); }, 150));
        inEnd.addEventListener('change', save);
        return;
      }

      // --- テキスト系: product_name / budget ---
      // --- 担当者: selectで選択 ---
      if (field === 'manager') {
        const sel = document.createElement('select');
        sel.className = 'inline-select';
        // 空選択肢
        const emptyOpt = document.createElement('option');
        emptyOpt.value = ''; emptyOpt.textContent = '— 未設定 —';
        if (!proj.manager) emptyOpt.selected = true;
        sel.appendChild(emptyOpt);
        // アクティブアカウントを注入
        _activeAccounts().forEach(a => {
          const opt = document.createElement('option');
          opt.value = a.name; opt.textContent = a.name;
          if (a.name === proj.manager) opt.selected = true;
          sel.appendChild(opt);
        });
        // 削除済みでも現在値があれば追加表示（ホールド対応）
        if (proj.manager && !_activeAccounts().find(a => a.name === proj.manager)) {
          const opt = document.createElement('option');
          opt.value = proj.manager;
          opt.textContent = proj.manager + '（削除済み）';
          opt.selected = true;
          sel.appendChild(opt);
        }
        cell.innerHTML = '';
        cell.appendChild(sel);
        sel.focus();

        const save = async () => {
          const val = sel.value;
          try {
            await _saveProjectFields(pid, { manager: val || null });
            proj.manager = val || null;
            renderProjects();
            showToast('担当者を変更しました');
          } catch(err) { console.error('[save manager]', err); showToast('保存に失敗しました', 'error'); renderProjects(); }
        };
        sel.addEventListener('change', save);
        sel.addEventListener('blur', () => { if (cell.querySelector('select')) renderProjects(); });
        return;
      }

      // --- クライアント担当者: contact_id をセレクトで選択 ---
      if (field === 'contact_id') {
        const proj = allProjects.find(p => p.id === pid);
        if (!proj) return;
        const sel = document.createElement('select');
        sel.className = 'inline-select';
        // 空選択肢
        const emptyOpt = document.createElement('option');
        emptyOpt.value = ''; emptyOpt.textContent = '— 未設定 —';
        if (!proj.contact_id) emptyOpt.selected = true;
        sel.appendChild(emptyOpt);
        // このクライアントの担当者を取得して注入
        const clientId = proj.client_id;
        const contacts = (allClientContacts||[]).filter(c => c.client_id === clientId && !c.is_deleted);
        if (contacts.length === 0) {
          // 担当者未登録の場合はそのまま閉じる
          cell.innerHTML = '<span class="inline-val"><span class="inline-empty" style="font-size:11px;">担当者未登録</span></span>';
          setTimeout(() => renderProjects(), 1500);
          return;
        }
        contacts.forEach(c => {
          const opt = document.createElement('option');
          opt.value = c.id;
          opt.textContent = c.name + (c.email ? ` (${c.email})` : '');
          if (c.id === proj.contact_id) opt.selected = true;
          sel.appendChild(opt);
        });
        cell.innerHTML = '';
        cell.appendChild(sel);
        sel.focus();

        const saveContact = async () => {
          const val = sel.value || null;
          try {
            await _saveProjectFields(pid, { contact_id: val });
            Cache.invalidate('projects');
            proj.contact_id = val;
            renderProjects();
            showToast('クライアント担当者を変更しました');
          } catch(err) { console.error('[save contact_id]', err); showToast('保存に失敗しました', 'error'); renderProjects(); }
        };
        sel.addEventListener('change', saveContact);
        sel.addEventListener('blur', () => { if (cell.querySelector('select')) renderProjects(); });
        return;
      }
      if (field === 'notes') {
        const ta = document.createElement('textarea');
        ta.className = 'inline-textarea';
        ta.value = proj.notes || '';
        ta.placeholder = 'コメントを入力';
        ta.rows = 3;
        cell.innerHTML = '';
        cell.appendChild(ta);
        ta.focus();

        const save = async () => {
          const val = ta.value.trim();
          try {
            await _saveProjectFields(pid, { notes: val || null });
            proj.notes = val || null;
            renderProjects();
            if (val) showToast('コメントを保存しました');
          } catch(err) { console.error('[save notes]', err); showToast('保存に失敗しました', 'error'); renderProjects(); }
        };
        ta.addEventListener('blur', save);
        ta.addEventListener('keydown', e => {
          if (e.key === 'Escape') { renderProjects(); }
          // Ctrl+Enter / Cmd+Enter で保存
          if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) { ta.blur(); }
        });
        return;
      }

      const inp = document.createElement('input');
      inp.className = 'inline-input';
      if (field === 'budget') {
        inp.type = 'number'; inp.min = '0'; inp.placeholder = '下記なし';
        inp.value = proj.budget || '';
      } else {
        inp.type = 'text';
        inp.value = proj.product_name || '';
        inp.placeholder = '未設定';
      }
      cell.innerHTML = '';
      cell.appendChild(inp);
      inp.focus();
      inp.select();

      const save = async () => {
        let val = inp.value.trim();
        const patch = {};
        if (field === 'budget') {
          patch.budget = val === '' ? null : Number(val);
        } else {
          patch[field] = val || null;
        }
        try {
          await _saveProjectFields(pid, patch);
          Object.assign(proj, patch);
          renderProjects();
          showToast('\u66f4\u65b0\u3057\u307e\u3057\u305f');
        } catch(err) { showToast('\u4fdd\u5b58\u306b\u5931\u6557\u3057\u307e\u3057\u305f', 'error'); renderProjects(); }
      };
      inp.addEventListener('blur', save);
      inp.addEventListener('keydown', e => {
        if (e.key === 'Enter')  { inp.blur(); }
        if (e.key === 'Escape') { renderProjects(); }
      });
    });
  });
}

// キャスティングボード: 「詳細確認」ボタンのみ表示
function buildCastingBoard(projectId, assigns, infMap, isUrgent = false) {
  const count = assigns.length;
  const label = count > 0
    ? `<span class="casting-count-badge">${count}名</span>`
    : '';

  // POP未確認の回答あり（赤・最優先）
  // reply_action があり reply_notified が false/null のレコードが1件でもあれば赤表示
  const hasRejectBack = assigns.some(a =>
    a.reply_action &&
    (a.reply_notified === false || a.reply_notified === null || a.reply_notified === undefined)
  );
  // 「受入可否」確認待ち（紫）
  const hasReview = assigns.some(a => a.request_status === '受入可否');
  // 「支払OK」あり（黄）
  const hasPayOk = assigns.some(a => a.request_status === '支払OK');
  // 「調整中」が1名以上いる（グレー）
  const has調整中 = assigns.some(a => (a.request_status || '調整中') === '調整中');

  let bellMark = '';
  let btnClass = '';
  // 至急確認フラグが最優先でクラスを上書き
  if (isUrgent) {
    btnClass = ' is-urgent-detail';
  } else if (hasRejectBack) {
    bellMark = `<span class="casting-bell-mark casting-bell-red" title="受入可否の回答があります"><i class="fas fa-bell"></i></span>`;
    btnClass = ' has-reject-back';
  } else if (hasReview) {
    bellMark = `<span class="casting-bell-mark casting-bell-purple" title="受入可否の確認待ちです"><i class="fas fa-bell"></i></span>`;
    btnClass = ' has-review';
  } else if (hasPayOk) {
    bellMark = `<span class="casting-bell-mark" title="支払OKのインフルエンサーがいます"><i class="fas fa-bell"></i></span>`;
    btnClass = ' has-pay-ok';
  } else if (has調整中) {
    btnClass = ' has-調整中';
  }

  const urgentMark = isUrgent
    ? `<span class="casting-urgent-mark" title="至急確認"><i class="fas fa-flag"></i></span>`
    : '';

  return `<button class="btn btn-sm casting-detail-btn${btnClass}" data-pid="${escHtml(projectId)}">
    ${urgentMark}<i class="fas fa-users"></i> 詳細確認${label}${bellMark}
  </button>`;
}

// アサインパネルHTML生成
