function bindAssignPanelEvents(container) {
  // 追加ボタン
  container.querySelectorAll('.assign-add-btn').forEach(btn => {
    btn.addEventListener('click', async () => {
      const pid = btn.dataset.projectId;
      const currentIds = allAssignments.filter(a => a.project_id === pid).map(a => a.influencer_id);
      await openAddInfluencerModal(pid, currentIds);
    });
  });
  // 編集ボタン
  container.querySelectorAll('.assign-inline-edit').forEach(btn => {
    btn.addEventListener('click', () => openAssignmentModal(btn.dataset.assignId));
  });
  // 削除ボタン
  container.querySelectorAll('.assign-inline-remove').forEach(btn => {
    btn.addEventListener('click', () => {
      confirmDelete(
        `${btn.dataset.infName} を案件から外す`,
        btn.dataset.assignId,
        async () => {
          await API.delete('project_influencers', btn.dataset.assignId);
          Cache.invalidate('projectInfluencers');
          showToast('インフルエンサーを案件から外しました');
          // キャッシュ更新して再描画
          allAssignments = allAssignments.filter(a => a.id !== btn.dataset.assignId);
          renderProjects();
        },
        '案件から外す',
        '案件との紐付けのみ解除されます。インフルエンサーDB本体は削除されません。'
      );
    });
  });
}

function toggleProjectExpand(projectId) {
  if (expandedProjectIds.has(projectId)) {
    expandedProjectIds.delete(projectId);
  } else {
    expandedProjectIds.add(projectId);
  }
  renderProjects();
}

function renderPagination(containerId, current, total, onChange) {
  const container = document.getElementById(containerId);
  if (total <= 1) { container.innerHTML = ''; return; }
  let html = '';
  for (let i = 1; i <= total; i++) {
    html += `<button class="${i===current?'active':''}" data-page="${i}">${i}</button>`;
  }
  container.innerHTML = html;
  container.querySelectorAll('button').forEach(btn => {
    btn.addEventListener('click', () => onChange(parseInt(btn.dataset.page)));
  });
}

// projectSearchはinitProjectTabs()内でバインド済み
// projectStatusFilterはタブUIに置き換えたため不要

// ===== 案件詳細サイドパネル =====

// ── 来店日時ピッカー ヘルパー ──
function buildVisitPicker(datetimeVal, assignId, rejected = false) {
  // datetimeVal: "YYYY-MM-DDTHH:mm" or ""
  let dateVal = '', hourVal = '', minVal = '';
  if (datetimeVal) {
    const [d, t] = datetimeVal.split('T');
    dateVal = d || '';
    if (t) {
      const parts = t.split(':');
      hourVal = parts[0] || '';
      // 5分刻みに丸める
      const rawMin = parseInt(parts[1] || '0', 10);
      minVal = String(Math.round(rawMin / 5) * 5).padStart(2, '0');
      if (minVal === '60') { minVal = '00'; hourVal = String(parseInt(hourVal,10)+1).padStart(2,'0'); }
    }
  }

  // 時間オプション (6:00〜23:00)
  const hourOpts = ['', ...Array.from({length:18}, (_,i)=> String(i+6).padStart(2,'0'))]
    .map(h => `<option value="${h}" ${h===hourVal?'selected':''}>${h===''?'時間':h+'時'}</option>`).join('');

  // 分オプション (5分刻み)
  const minOpts = ['','00','05','10','15','20','25','30','35','40','45','50','55']
    .map(mn => `<option value="${mn}" ${mn===minVal?'selected':''}>${mn===''?'分':mn+'分'}</option>`).join('');

  const clearBtn = datetimeVal
    ? `<button class="visit-clear-btn" data-assign-id="${escHtml(assignId)}" title="クリア"><i class="fas fa-times"></i></button>`
    : '';

  const rejectedCls = rejected ? ' visit-picker--rejected' : '';

  return `<div class="visit-picker${rejectedCls}" data-assign-id="${escHtml(assignId)}">
    <input type="date" class="visit-date-sel" data-assign-id="${escHtml(assignId)}" value="${escHtml(dateVal)}" title="来店日">
    <select class="visit-hour-sel" data-assign-id="${escHtml(assignId)}">${hourOpts}</select>
    <select class="visit-min-sel"  data-assign-id="${escHtml(assignId)}">${minOpts}</select>
    ${clearBtn}
  </div>`;
}

// 来店日時ピッカーのイベントをまとめてバインド
function bindVisitPickers(assignments) {
  const saveVisit = async (assignId) => {
    const dateEl = document.querySelector(`.visit-date-sel[data-assign-id="${assignId}"]`);
    const hourEl = document.querySelector(`.visit-hour-sel[data-assign-id="${assignId}"]`);
    const minEl  = document.querySelector(`.visit-min-sel[data-assign-id="${assignId}"]`);
    if (!dateEl) return;

    const d = dateEl.value;
    const h = hourEl?.value || '';
    const mn = minEl?.value || '';
    let newVal = null;
    if (d && h && mn !== '') {
      newVal = `${d}T${h}:${mn}`;
    } else if (d && !h) {
      newVal = d; // 日付のみ (時刻未設定)
    }

    try {
      await _saveAssignFields(assignId, { visit_datetime: newVal });
      Cache.invalidate('projectInfluencers');
      const a = assignments.find(x => x.id === assignId);
      if (a) a.visit_datetime = newVal;
      showToast('来店日時を更新しました');
      // ピッカーUIを再描画（クリアボタン表示制御）
      const wrap = document.querySelector(`.assign-visit-wrap[data-assign-id="${assignId}"]`);
      if (wrap) wrap.innerHTML = buildVisitPicker(newVal || '', assignId);
      bindVisitPickerOne(assignId, assignments);
    } catch(e) { console.error('[save visit_datetime]', e); showToast('保存に失敗しました', 'error'); }
  };

  document.querySelectorAll('.assign-visit-wrap').forEach(wrap => {
    const assignId = wrap.dataset.assignId;
    bindVisitPickerOne(assignId, assignments);
  });
}

function bindVisitPickerOne(assignId, assignments) {
  let _saveTimer = null;

  const saveVisit = async () => {
    const dateEl = document.querySelector(`.visit-date-sel[data-assign-id="${assignId}"]`);
    const hourEl = document.querySelector(`.visit-hour-sel[data-assign-id="${assignId}"]`);
    const minEl  = document.querySelector(`.visit-min-sel[data-assign-id="${assignId}"]`);
    if (!dateEl) return;
    const d  = dateEl.value;
    const h  = hourEl?.value || '';
    const mn = minEl?.value  || '';

    // 時間か分の片方だけ入っている場合は保存しない（両方揃うまで待つ）
    if ((h && !mn) || (!h && mn)) return;

    let newVal = null;
    if (d && h && mn !== '') newVal = `${d}T${h}:${mn}`;
    else if (d && !h && !mn) newVal = d; // 日付のみ（時刻を明示的に消した場合）
    else if (!d) newVal = null;
    else return; // 不完全な状態なら保存しない

    try {
      await _saveAssignFields(assignId, { visit_datetime: newVal });
      Cache.invalidate('projectInfluencers');
      const a = assignments.find(x => x.id === assignId);
      if (a) a.visit_datetime = newVal;
      showToast('来店日時を更新しました');
      const wrap = document.querySelector(`.assign-visit-wrap[data-assign-id="${assignId}"]`);
      if (wrap) { wrap.innerHTML = buildVisitPicker(newVal || '', assignId); bindVisitPickerOne(assignId, assignments); }
      // 来店日時が設定されたら「確定」へ自動切換え
      if (newVal) {
        await _autoUpdateStatusIfNeeded(assignId, a, assignments, null, '確定');
      }
    } catch(e) { console.error('[save visit_datetime2]', e); showToast('保存に失敗しました', 'error'); }
  };

  // デバウンス付き変更ハンドラ（300ms後に保存）
  const debouncedSave = () => {
    clearTimeout(_saveTimer);
    _saveTimer = setTimeout(saveVisit, 300);
  };

  document.querySelector(`.visit-date-sel[data-assign-id="${assignId}"]`)
    ?.addEventListener('change', debouncedSave);
  document.querySelector(`.visit-hour-sel[data-assign-id="${assignId}"]`)
    ?.addEventListener('change', debouncedSave);
  document.querySelector(`.visit-min-sel[data-assign-id="${assignId}"]`)
    ?.addEventListener('change', debouncedSave);

  // クリアボタン
  document.querySelector(`.visit-clear-btn[data-assign-id="${assignId}"]`)
    ?.addEventListener('click', async () => {
      try {
        await _saveAssignFields(assignId, { visit_datetime: null });
        Cache.invalidate('projectInfluencers');
        const a = assignments.find(x => x.id === assignId);
        if (a) a.visit_datetime = null;
        showToast('来店日時をクリアしました');
        const wrap = document.querySelector(`.assign-visit-wrap[data-assign-id="${assignId}"]`);
        if (wrap) { wrap.innerHTML = buildVisitPicker('', assignId); bindVisitPickerOne(assignId, assignments); }
      } catch(e) { showToast('保存に失敗しました', 'error'); }
    });
}
// ステータス自動切換えヘルパー（来店日時→確定、投稿日+URL→支払OK）
async function _autoUpdateStatusIfNeeded(assignId, assignObj, assignments, projectId, newStatus) {
  try {
    const cur = assignments.find(x => x.id === assignId);
    // すでに同じか、より後続のステータスなら上書きしない
    const ORDER = ['調整中','確定','支払OK','支払申請済'];
    const curIdx = cur ? ORDER.indexOf(cur.request_status || '調整中') : 0;
    const newIdx = ORDER.indexOf(newStatus);
    // 新ステータスが現在より先にある場合のみ更新
    if (newIdx > curIdx) {
      await _saveAssignFields(assignId, { request_status: newStatus });
      Cache.invalidate('projectInfluencers');
      if (cur) cur.request_status = newStatus;
      // allAssignments も更新
      const ga = allAssignments.find(x => x.id === assignId);
      if (ga) ga.request_status = newStatus;
      showToast(`ステータスを「${newStatus}」に更新しました`);
      // ステータスselectのUIを更新
      const sel = document.querySelector(`.assign-status-select[data-assign-id="${assignId}"]`);
      if (sel) sel.value = newStatus;
      updateCastingButtons(); // ボタン色のみ軽量更新
    }
  } catch(e) { /* サイレント失敗 */ }
}

let currentDetailProjectId = null;
let currentDetailPendingGroups = []; // グループ追加ボタンで追加されたローカルグループ名

function openDetailPanel() {
  const panel    = document.getElementById('project-detail-panel');
  const backdrop = document.getElementById('detail-panel-backdrop');
  panel.classList.add('open');
  // デフォルトで全画面（サイドバー付き）表示
  panel.classList.add('expanded');
  backdrop.classList.add('open');
  backdrop.classList.add('expanded');
  document.body.classList.add('panel-open');
  document.body.classList.add('panel-expanded');
}

/** 案件詳細を全画面モードに戻す（キャスティングパネルを閉じた後など） */
function expandDetailPanel() {
  const panel    = document.getElementById('project-detail-panel');
  const backdrop = document.getElementById('detail-panel-backdrop');
  if (!panel || !panel.classList.contains('open')) return;
  panel.classList.add('expanded');
  backdrop.classList.add('expanded');
  document.body.classList.add('panel-expanded');
}

/** 案件詳細を通常サイドパネル幅に縮小（キャスティングパネルと並べるとき） */
function shrinkDetailPanel() {
  const panel    = document.getElementById('project-detail-panel');
  const backdrop = document.getElementById('detail-panel-backdrop');
  if (!panel) return;
  panel.classList.remove('expanded');
  backdrop.classList.remove('expanded');
  document.body.classList.remove('panel-expanded');
}

/** キャスティングパネルを開く際に案件詳細を一時非表示（全画面キャスティング用） */
function hideDetailPanelForCasting() {
  const panel    = document.getElementById('project-detail-panel');
  const backdrop = document.getElementById('detail-panel-backdrop');
  if (!panel) return;
  panel.classList.add('casting-hidden');
  if (backdrop) backdrop.classList.add('casting-hidden');
}

/** キャスティングパネルを閉じた後に案件詳細を全画面で復帰 */
function showDetailPanelAfterCasting() {
  const panel    = document.getElementById('project-detail-panel');
  const backdrop = document.getElementById('detail-panel-backdrop');
  if (!panel) return;
  panel.classList.remove('casting-hidden');
  if (backdrop) backdrop.classList.remove('casting-hidden');
  // 全画面モードで復帰
  expandDetailPanel();
}
function closeDetailPanel() {
  const panel = document.getElementById('project-detail-panel');
  panel.classList.remove('open');
  panel.classList.remove('expanded');
  document.getElementById('detail-panel-backdrop').classList.remove('open');
  document.getElementById('detail-panel-backdrop').classList.remove('expanded');
  document.body.classList.remove('panel-open');
  document.body.classList.remove('panel-expanded');
  // 右パネルを閉じたら左パネルも閉じる
  closeCastingPanel();
}

document.getElementById('btn-close-detail-panel').addEventListener('click', closeDetailPanel);

// ── DMテンプレートモーダル：コピー・閉じるボタン（グローバルバインド） ──
document.getElementById('btn-close-dm-template')?.addEventListener('click', () => {
  document.getElementById('modal-dm-template')?.classList.remove('open');
});
document.getElementById('modal-dm-template')?.addEventListener('click', e => {
  if (e.target === document.getElementById('modal-dm-template')) {
    document.getElementById('modal-dm-template').classList.remove('open');
  }
});
document.getElementById('btn-dm-tmpl-copy')?.addEventListener('click', () => {
  const textEl = document.getElementById('dm-tmpl-text');
  if (!textEl) return;
  const text = textEl.value || '';
  navigator.clipboard.writeText(text).then(() => {
    const doneEl = document.getElementById('dm-tmpl-copy-done');
    if (doneEl) { doneEl.style.display = ''; setTimeout(() => { doneEl.style.display = 'none'; }, 2500); }
  }).catch(() => {
    const ta = document.createElement('textarea');
    ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
    document.body.appendChild(ta); ta.select(); document.execCommand('copy'); document.body.removeChild(ta);
    const doneEl = document.getElementById('dm-tmpl-copy-done');
    if (doneEl) { doneEl.style.display = ''; setTimeout(() => { doneEl.style.display = 'none'; }, 2500); }
  });
});

// ── billed_at 専用保存ヘルパー（GET最新データ → project_clients だけ差し替え → PUT）──
async function _saveBilledAt(pid, pcsStr) {
  // 最新データをGET
  const getRes = await fetch(`tables/projects/${pid}`, { cache: 'no-store' });
  if (!getRes.ok) throw new Error(`GET projects/${pid} failed: ${getRes.status}`);
  const existing = await getRes.json();

  // システムフィールドを除外してマージ
  const { gs_project_id, gs_table_name, created_at, updated_at, deleted, avatar_image, ...rest } = existing;

  // 全フィールドを文字列に正規化（object型があるとD1がエラーになるため）
  const body = { ...rest };
  Object.keys(body).forEach(k => {
    if (body[k] !== null && body[k] !== undefined && typeof body[k] === 'object') {
      body[k] = JSON.stringify(body[k]);
    }
  });
  // project_clients だけ今回の値で上書き
  body.project_clients = pcsStr;

  const putRes = await fetch(`tables/projects/${pid}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body)
  });
  if (!putRes.ok) {
    let msg = `PUT projects/${pid} failed: ${putRes.status}`;
    try { const e = await putRes.json(); msg += ' ' + JSON.stringify(e); } catch(_) {}
    throw new Error(msg);
  }
}

// ── 予算変更履歴をbudget_historyフィールドに追記するヘルパー ──
// pid: project ID, pcs: project_clients配列, clientMap: {id: {company_name}}
// 戻り値: 新しいbudget_history文字列（保存は呼び出し元で行う）
async function _appendBudgetHistory(pid, pcs, clientMap) {
  try {
    const today = new Date();
    const dateStr = `${today.getFullYear()}/${String(today.getMonth()+1).padStart(2,'0')}/${String(today.getDate()).padStart(2,'0')}`;

    // 現在のbudget_historyを取得
    const projRaw = await fetch(`tables/projects/${pid}`, { cache: 'no-store' });
    const proj = await projRaw.json();
    let history = [];
    if (proj.budget_history) {
      try {
        const _rawH = proj.budget_history;
        history = typeof _rawH === 'string' ? JSON.parse(_rawH) : (Array.isArray(_rawH) ? _rawH : []);
      } catch(_) { history = []; }
    }

    // 今日のエントリを作成
    const entry = {
      date: dateStr,
      clients: (pcs || []).filter(c => c.client_id).map(c => ({
        client_id: c.client_id,
        name: (clientMap && clientMap[c.client_id])?.company_name || c.client_id,
        budget: Number(c.budget) || 0
      }))
    };

    // 同日エントリは上書き、それ以外は先頭に追加
    const sameDayIdx = history.findIndex(h => h.date === dateStr);
    if (sameDayIdx !== -1) {
      history[sameDayIdx] = entry;
    } else {
      history.unshift(entry);
    }
    // 最大30件まで保持
    if (history.length > 30) history = history.slice(0, 30);

    return JSON.stringify(history);
  } catch(_) { return null; }
}

// ── 汎用テーブル GET→PUT ヘルパー（PATCH405対策）──
// table: テーブル名, id: レコードID, fields: 更新フィールドオブジェクト
// excludeKeys: PUTボディから除外するシステムフィールド（デフォルト共通セット）
async function _saveTableFields(table, id, fields, excludeKeys = ['gs_project_id','gs_table_name','created_at','updated_at','deleted','avatar_image']) {
  const getRes = await fetch(`tables/${table}/${id}`, { cache: 'no-store' });
  if (!getRes.ok) throw new Error(`GET ${table}/${id} failed: ${getRes.status}`);
  const existing = await getRes.json();
  const body = {};
  Object.keys(existing).forEach(k => {
    if (!excludeKeys.includes(k)) body[k] = existing[k];
  });
  Object.keys(body).forEach(k => {
    if (body[k] !== null && body[k] !== undefined && typeof body[k] === 'object') {
      body[k] = JSON.stringify(body[k]);
    }
  });
  Object.assign(body, fields);
  const putRes = await fetch(`tables/${table}/${id}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  if (!putRes.ok) {
    let msg = `PUT ${table}/${id} failed: ${putRes.status}`;
    try { const e = await putRes.json(); msg += ' ' + JSON.stringify(e); } catch(_) {}
    throw new Error(msg);
  }
  return await putRes.json();
}

