document.getElementById('btn-toggle-master-pw')?.addEventListener('click', () => {
  togglePwVisibility('cv-master-pw', 'icon-master-pw');
});
document.getElementById('btn-toggle-login-pw')?.addEventListener('click', () => {
  togglePwVisibility('cv-login-pw', 'icon-login-pw');
});

// --- 編集モード内の目玉ボタン（動的バインド） ---
document.querySelectorAll('.pw-eye-btn--input').forEach(btn => {
  btn.addEventListener('click', () => {
    const targetId = btn.dataset.target;
    const iconId   = btn.dataset.icon;
    const inp  = document.getElementById(targetId);
    const icon = document.getElementById(iconId);
    if (!inp) return;
    if (inp.type === 'password') {
      inp.type = 'text';
      if (icon) { icon.classList.remove('fa-eye'); icon.classList.add('fa-eye-slash'); }
    } else {
      inp.type = 'password';
      if (icon) { icon.classList.remove('fa-eye-slash'); icon.classList.add('fa-eye'); }
    }
  });
});

