/* ============================================================
   タスク管理
   ============================================================ */

let _allTasks          = [];
let _allSchedules      = [];   // schedules テーブルキャッシュ
let _ensuringDefault   = {};   // スタッフ名 → Promise（並行実行防止）
let _taskCurrentStaff  = 'dashboard';
let _taskProgressFilter = '';
let _taskPriorityFilter = '';
let _taskSearchText    = '';
let _taskStaffInited   = false;

const PROGRESS_CFG = {
  '未着手':  { cls: 'tpg-todo',    label: '未着手'  },
  '進行中':  { cls: 'tpg-doing',   label: '進行中'  },
  '確認待ち':{ cls: 'tpg-waiting', label: '確認待ち'},
  '完了':    { cls: 'tpg-done',    label: '完了'    },
};
const PRIORITY_CFG = {
  '高': { cls: 'tpr-high', label: '高' },
  '中': { cls: 'tpr-mid',  label: '中' },
  '低': { cls: 'tpr-low',  label: '低' },
};

async function loadTasks() {
  try {
    // クイックリンクバー初回ロード（1回のみ）
    if (!_qlBarInited) loadQuickLinks();

    // tasks と accounts は必須 → 失敗時は全体エラー
    // ※ tasks は件数が多いため getAll でページネーション全件取得
    const [taskRes, accRes] = await Promise.all([
      API.getAll('tasks'),
      API.getAll('accounts'),
    ]);
    _allTasks    = (Array.isArray(taskRes.data) ? taskRes.data : []).filter(t => !t.deleted);
    _allAccounts = (Array.isArray(accRes.data)  ? accRes.data  : []).filter(a => !a.is_deleted);

    // schedules 取得（失敗しても tasks/accounts には影響なし）
    try {
      const schedRes = await API.getAll('schedules');
      const schedRows = Array.isArray(schedRes.data) ? schedRes.data : (Array.isArray(schedRes) ? schedRes : []);
      _allSchedules = schedRows.filter(s => s.deleted !== true);
      console.log('[sch] loadTasks schedules:', schedRows.length, '件取得 →', _allSchedules.length, '件有効');
    } catch(se) {
      console.warn('[sch] schedules fetch failed:', se);
      _allSchedules = [];
    }

    // daily_work_logs：ロード → 今日分を全スタッフ upsert
    try {
      await _loadWorkLogs();
      await _upsertAllTodayWorkLogs();
    } catch(se) {
      console.warn('[wlog] init failed:', se);
      _allWorkLogs = []; // エラー時も空配列で初期化
    }

    // ── 完了タスクの自動削除（updated_at から 1 週間経過したもの）──
    const ONE_WEEK_MS = 7 * 24 * 60 * 60 * 1000;
    const now = Date.now();
    const expired = _allTasks.filter(t =>
      t.progress === '完了' &&
      t.updated_at &&
      (now - t.updated_at) >= ONE_WEEK_MS
    );
    if (expired.length > 0) {
      await Promise.allSettled(expired.map(t => API.delete('tasks', t.id)));
      const expiredIds = new Set(expired.map(t => t.id));
      _allTasks = _allTasks.filter(t => !expiredIds.has(t.id));
    }

    try { _buildStaffTabs(); } catch(e) { console.error('[loadTasks] _buildStaffTabs error', e); }
    try { _renderTaskPage(); } catch(e) { console.error('[loadTasks] _renderTaskPage error', e); }
    try { updateTaskNavBadge(); } catch(e) { /* ignore */ }
  } catch(e) {
    console.error('loadTasks error', e);
    showToast('タスクの読み込みに失敗しました', 'error');
  }
}

// 今日の日付文字列（YYYY-MM-DD）
function _todayStr() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}

/**
 * スケジュールレコードが「今日」かどうかを判定。
 * ① s.date === todayStr（文字列一致）
 * ② s.date が空/不正 でも created_at（Unix ms）が今日の範囲内
 * どちらかが true なら今日のレコードとして扱う。
 */
function _schIsToday(s, todayStr) {
  // ① date フィールドが正しく今日
  if (s.date === todayStr) return true;
  // ② date が未設定/不正 → created_at で判定
  if (!s.date && s.created_at) {
    const d = new Date(s.created_at);
    const ds = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
    return ds === todayStr;
  }
  return false;
}

/**
 * スケジュールレコードが「今日より前」かどうかを判定。
 * date フィールドが今日以前 かつ 今日ではないもの。
 * date が空の場合は created_at で代替判定。
 */
function _schIsBeforeToday(s, todayStr) {
  const dateStr = s.date || (s.created_at
    ? (() => { const d = new Date(s.created_at); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; })()
    : null);
  if (!dateStr) return false;
  return dateStr < todayStr;
}

// ── スタッフ並び順管理 ─────────────────────────────────────────
// localStorage に name の配列を保存し、ダッシュボードテーブル行の順序に使う
const STAFF_ORDER_KEY = 'taskStaffOrder_v1';

function _loadStaffOrder() {
  try { return JSON.parse(localStorage.getItem(STAFF_ORDER_KEY) || '[]'); }
  catch { return []; }
}
function _saveStaffOrder(names) {
  localStorage.setItem(STAFF_ORDER_KEY, JSON.stringify(names));
}
// 保存済み順 + 未登録スタッフを末尾追加して返す
function _orderedStaffList() {
  const all     = _activeAccounts();
  const saved   = _loadStaffOrder();
  const ordered = [];
  // 保存順に並べる（削除済みスタッフはスキップ）
  saved.forEach(name => {
    const a = all.find(x => x.name === name);
    if (a) ordered.push(a);
  });
  // 保存にない新スタッフを末尾追加
  all.forEach(a => {
    if (!ordered.find(x => x.name === a.name)) ordered.push(a);
  });
  return ordered;
}

function _buildStaffTabs() {
  const wrap = document.getElementById('task-staff-tabs');
  if (wrap) wrap.innerHTML = _staffTabsHTML();

  // パネルは常に最新の並び順で再生成（既存パネルのinnerHTMLはリセットされないので安全）
  const panels = document.getElementById('task-staff-panels');
  if (panels) {
    const orderedNames = _orderedStaffList().map(a => a.name);
    // 既存パネルを保持しつつ順序を並び替え
    orderedNames.forEach(name => {
      const id = `task-panel-${_staffId(name)}`;
      let el = document.getElementById(id);
      if (!el) {
        el = document.createElement('div');
        el.className = 'task-panel';
        el.id = id;
        el.style.display = 'none';
      }
      panels.appendChild(el); // 末尾に移動（順序を揃える）
    });
  }

  if (_taskStaffInited) return;
  _taskStaffInited = true;
  document.getElementById('task-staff-bar')?.addEventListener('click', e => {
    const btn = e.target.closest('.task-staff-tab');
    if (!btn) return;
    _taskCurrentStaff = btn.dataset.staff;
    document.querySelectorAll('.task-staff-tab').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    _renderTaskPage();
  });
}

function _staffTabsHTML() {
  return _orderedStaffList().map(a => `
    <button class="task-staff-tab${_taskCurrentStaff === a.name ? ' active' : ''}" data-staff="${escHtml(a.name)}">
      <i class="fas fa-user"></i> ${escHtml(a.name)}
    </button>`).join('');
}

function _staffId(name) {
  return 'staff_' + name.replace(/[^a-zA-Z0-9\u3040-\u9FFF]/g, '_');
}

// ── 時間管理設定 ─────────────────────────────────────────────
const DEFAULT_HOUR_LIMIT       = 8;   // daily_hour_limit 未設定時のデフォルト（h）
const TASK_CONCENTRATION_RATIO = 0.4; // 1人にこの割合以上のタスクが集中したら警告

// スタッフ1人の上限時間を返す（accounts の daily_hour_limit 優先、なければ DEFAULT_HOUR_LIMIT）
function _staffHourLimit(staffName) {
  const acc = _allAccounts.find(a => a.name === staffName);
  if (acc && acc.daily_hour_limit != null && parseFloat(acc.daily_hour_limit) > 0) {
    return parseFloat(acc.daily_hour_limit);
  }
  return DEFAULT_HOUR_LIMIT;
}

// ── 指定日付文字列（YYYY-MM-DD）を N 日前にずらす ──────────
function _dateStrOffset(baseStr, offsetDays) {
  const d = new Date(baseStr + 'T00:00:00');
  d.setDate(d.getDate() - offsetDays);
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}

// ══════════════════════════════════════════════════════════════
//  日次稼働ログ（daily_work_logs）
//  ・タスク保存のたびに「今日」の稼働状況を upsert
//  ・過去日アイコンは daily_work_logs から表示
//  ・公休設定も記録
// ══════════════════════════════════════════════════════════════

let _allWorkLogs = [];   // daily_work_logs キャッシュ

/**
 * daily_work_logs を全件ロードしてキャッシュに保持。
 */
async function _loadWorkLogs() {
  try {
    const res = await API.getAll('daily_work_logs');
    const rows = Array.isArray(res.data) ? res.data : [];
    _allWorkLogs = rows.filter(r => !r.deleted);
    console.log('[wlog] loaded:', _allWorkLogs.length, '件');
  } catch(e) {
    console.warn('[wlog] load failed → テーブル未作成またはAPIエラー:', e.message);
    _allWorkLogs = [];
  }
}

/**
 * 指定スタッフの「今日」の稼働ログを upsert する。
 * タスク保存・公休切替のたびに呼び出す。
 *
 * @param {string} staffName  対象スタッフ名
 */
async function _upsertTodayWorkLog(staffName) {
  const today = _todayStr();
  const acct  = _allAccounts.find(a => a.name === staffName);
  const isHoliday = !!(acct?.is_holiday);
  const lim   = _staffHourLimit(staffName);

  // 今日の作業時間を tasks から集計（_calcStaffHours と同ロジック）
  // 完了タスク → today_date or updated_at の日付が今日 / 未完了タスク → is_today=true
  const _msToDateStrLog = ms => { if (!ms) return null; const d = new Date(ms); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
  const _isTodayTaskLog = t => {
    if (t.progress === '完了') return t.today_date ? t.today_date === today : _msToDateStrLog(t.updated_at) === today;
    // 未完了タスク：is_today=true であれば今日タスク（today_dateの日付チェックは不要）
    return !!t.is_today;
  };
  const taskH =
    _allTasks
      .filter(t => t.assignee === staffName && _isTodayTaskLog(t) && (!t.handover || t.handover === staffName))
      .reduce((s, t) => s + (parseFloat(t.today_hours) || 0), 0)
    + _allTasks
      .filter(t => _isTodayTaskLog(t) && t.handover === staffName && t.assignee !== staffName)
      .reduce((s, t) => s + (parseFloat(t.today_hours) || 0), 0);

  const schedH = _allSchedules
    .filter(s => s.assignee === staffName && _schIsToday(s, today))
    .reduce((s, r) => s + (parseFloat(r.duration_hours) || 0), 0);

  const totalH = isHoliday ? 0 : (taskH + schedH);

  // アイコン種別を決定
  let status;
  if (isHoliday) {
    status = 'holiday';
  } else if (totalH <= 0) {
    status = 'none';
  } else {
    const pct = lim > 0 ? (totalH / lim) * 100 : 0;
    if (pct > 110)      status = 'over2';
    else if (pct > 100) status = 'over1';
    else                status = 'ok';
  }

  const now = new Date();
  const updStr = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')} ${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}:${String(now.getSeconds()).padStart(2,'0')}`;

  // 既存レコードを検索
  const existing = _allWorkLogs.find(r => r.date === today && r.staff_name === staffName);

  try {
    if (existing) {
      // GET→PUTでupsert（PATCHは405のため）
      const getRes = await fetch(`tables/daily_work_logs/${existing.id}`, { cache: 'no-store' });
      if (!getRes.ok) throw new Error(`GET daily_work_logs/${existing.id} failed: ${getRes.status}`);
      const exRow = await getRes.json();
      const { gs_project_id, gs_table_name, created_at, updated_at, deleted, ...restRow } = exRow;
      const putBody = { ...restRow,
        total_hours:    totalH,
        limit_hours:    lim,
        is_holiday:     isHoliday,
        status:         status,
        updated_at_str: updStr,
      };
      const putRes = await fetch(`tables/daily_work_logs/${existing.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(putBody),
      });
      if (!putRes.ok) throw new Error(`PUT daily_work_logs/${existing.id} failed: ${putRes.status}`);
      // ローカルキャッシュも更新
      existing.total_hours    = totalH;
      existing.limit_hours    = lim;
      existing.is_holiday     = isHoliday;
      existing.status         = status;
      existing.updated_at_str = updStr;
    } else {
      const created = await API.post('daily_work_logs', {
        date:           today,
        staff_name:     staffName,
        total_hours:    totalH,
        limit_hours:    lim,
        is_holiday:     isHoliday,
        status:         status,
        updated_at_str: updStr,
      });
      if (created && created.id) _allWorkLogs.push(created);
    }
    console.log('[wlog] upsert:', staffName, today, status, totalH + 'h');
  } catch(e) {
    console.warn('[wlog] upsert failed → テーブルが未作成の可能性:', staffName, e.message);
  }
}

/**
 * 全スタッフの今日分を一括 upsert する。
 * loadTasks() 完了後に呼ぶ。
 */
async function _upsertAllTodayWorkLogs() {
  const staffList = _orderedStaffList();
  if (!staffList.length) return;
  await Promise.allSettled(staffList.map(a => _upsertTodayWorkLog(a.name)));
  // 日別稼働時間テーブルを再描画（ダッシュボード表示中のみ）
  if (_taskCurrentStaff === 'dashboard') {
    _renderDailyHoursTable();
  }
}

/**
 * 引継ぎタスク完了時に、引継ぎ者（handoverName）側のコピーレコードを tasks テーブルに POST する。
 * ・重複防止：source_task_id が同じ is_handover_copy=true レコードが既に存在する場合はスキップ。
 * ・コピーは閲覧専用（削除のみ可）。
 * @param {object} originalTask - 元タスクオブジェクト（PATCH 前のキャッシュ）
 * @param {string} handoverName - 完了にした引継ぎ者のスタッフ名
 */
async function _createHandoverCopy(originalTask, handoverName) {
  if (!originalTask?.id || !handoverName) return;
  // 重複チェック（同一 source_task_id のコピーが既にある場合はスキップ）
  const already = _allTasks.find(
    t => t.source_task_id === originalTask.id && t.is_handover_copy === true && !t.deleted
  );
  if (already) {
    console.log('[handover copy] already exists, skip:', originalTask.id);
    return;
  }
  const todayStr = _todayStr();
  const copy = {
    title:             originalTask.title        || '（無題）',
    assignee:          handoverName,
    progress:          '完了',
    is_today:          true,
    today_date:        _todayStr(),
    today_hours:       parseFloat(originalTask.today_hours) || 0,
    store_name:        originalTask.store_name   || null,
    task_category:     originalTask.task_category || null,
    priority:          originalTask.priority     || null,
    due_date:          originalTask.due_date      || null,
    estimated_hours:   parseFloat(originalTask.estimated_hours) || null,
    notes:             originalTask.notes         || null,
    task_url:          originalTask.task_url      || null,
    handover:          null,
    handover_chain:    [],
    source_task_id:    originalTask.id,
    is_handover_copy:  true,
    is_pinned:         false,
    sort_order:        0,
  };
  try {
    const created = await API.post('tasks', copy);
    if (created?.id) {
      _allTasks.push(created);
      console.log('[handover copy] created:', created.id, 'for', handoverName, todayStr);
    }
  } catch(e) {
    console.warn('[handover copy] POST failed:', e.message);
  }
}

/**
 * daily_work_logs からアイコン HTML を返す。
 * ログがない日は schedules フォールバック。
 */
function _overFaceHtmlFromWorkLog(staffName, dateStr, limitH) {
  const log = _allWorkLogs.find(r => r.date === dateStr && r.staff_name === staffName);
  if (log) {
    const pctTitle = log.total_hours > 0 && log.limit_hours > 0
      ? (log.total_hours / log.limit_hours * 100).toFixed(0) + '%' : '';
    switch (log.status) {
      case 'holiday': return `<span class="ovw-face ovw-face--holiday" title="公休">💤</span>`;
      case 'none':    return `<span class="ovw-face ovw-face--none">–</span>`;
      case 'over2':   return `<span class="ovw-face ovw-face--over2" title="${pctTitle}">😣</span>`;
      case 'over1':   return `<span class="ovw-face ovw-face--over1" title="${pctTitle}">😐</span>`;
      case 'ok':      return `<span class="ovw-face ovw-face--ok"    title="${pctTitle}">😊</span>`;
      default:        return `<span class="ovw-face ovw-face--none">–</span>`;
    }
  }
  // フォールバック：ログなし → schedules から計算
  const h = _calcStaffHoursOnDate(staffName, dateStr);
  return _overFaceHtml(h, limitH, false);
}

/**
 * 指定日付のスタッフ稼働時間を返す。
 * - schedules テーブルの duration_hours を s.date で集計
 * - tasks テーブルは today_hours（is_today フラグ）は「今日」専用なので
 *   過去日は schedules のみを参照
 */
function _calcStaffHoursOnDate(staffName, dateStr) {
  const schedH = _allSchedules
    .filter(s => {
      if (s.assignee !== staffName) return false;
      const d = s.date || (s.created_at
        ? (() => { const x = new Date(s.created_at); return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`; })()
        : null);
      return d === dateStr;
    })
    .reduce((sum, r) => sum + (parseFloat(r.duration_hours) || 0), 0);
  // 今日のみ tasks の today_hours も合算（引継ぎ考慮）
  const todayStr = _todayStr();
  let taskH = 0;
  if (dateStr === todayStr) {
    const _msToDateStr = ms => { if (!ms) return null; const d = new Date(ms); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
    // 完了タスク → today_date or updated_at の日付が今日 / 未完了タスク → is_today=true
    const _isTodayTask = t => {
      if (t.progress === '完了') return t.today_date ? t.today_date === todayStr : _msToDateStr(t.updated_at) === todayStr;
      // 未完了タスク：is_today=true であれば今日タスク（today_dateの日付チェックは不要）
      return !!t.is_today;
    };
    // 自分のタスクで引継ぎ出していないもの（完了含む）
    taskH = _allTasks
      .filter(t => t.assignee === staffName && _isTodayTask(t) && (!t.handover || t.handover === staffName))
      .reduce((sum, t) => sum + (parseFloat(t.today_hours) || 0), 0)
    // 引継ぎ受けたタスク（完了含む）
    + _allTasks
      .filter(t => _isTodayTask(t) && t.handover === staffName && t.assignee !== staffName)
      .reduce((sum, t) => sum + (parseFloat(t.today_hours) || 0), 0);
  }
  return schedH + taskH;
}

/**
 * 超過率（0〜）から表情絵文字 HTML を返す。
 * ～100%  : 緑 笑顔
 * 101〜110%: 黄 普通顔
 * 111%〜  : 赤 困り顔
 * 0h（データなし）: グレーの「–」
 */
function _overFaceHtml(totalH, limitH, isHoliday) {
  if (isHoliday) return `<span class="ovw-face ovw-face--holiday" title="公休">💤</span>`;
  if (totalH <= 0) return `<span class="ovw-face ovw-face--none">–</span>`;
  const pct = limitH > 0 ? (totalH / limitH) * 100 : 0;
  if (pct > 110) return `<span class="ovw-face ovw-face--over2" title="${pct.toFixed(0)}%">😣</span>`;
  if (pct > 100) return `<span class="ovw-face ovw-face--over1" title="${pct.toFixed(0)}%">😐</span>`;
  return `<span class="ovw-face ovw-face--ok" title="${pct.toFixed(0)}%">😊</span>`;
}

// ── スタッフ別時間集計ヘルパー ─────────────────────────────
function _calcStaffHours(staffName) {
  // 公休フラグ確認
  const acct = _allAccounts.find(a => a.name === staffName);
  const isHoliday = !!(acct?.is_holiday);

  const mine    = _allTasks.filter(t => t.assignee === staffName);
  const active  = mine.filter(t => t.progress !== '完了');

  const today = _todayStr();

  /**
   * 「今日のタスク」判定ヘルパー
   * ─ 完了タスク：updated_at（完了操作したタイムスタンプ）の日付が今日 → 今日完了した実績
   * ─ 未完了タスク：is_today=true かつ today_date === 今日
   * これにより「昨日完了 → 今日も集計される」バグを根本解消する。
   */
  const _msToDateStr = ms => {
    if (!ms) return null;
    const d = new Date(ms);
    return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  };
  const _isTodayTask = t => {
    if (t.progress === '完了') {
      // 完了タスク：today_date（完了日）が今日であれば今日の実績として計上
      // today_date が未設定の旧データは updated_at でフォールバック
      return t.today_date ? t.today_date === today : _msToDateStr(t.updated_at) === today;
    }
    // 未完了タスク：is_today=true であれば今日タスク（today_dateの日付チェックは不要）
    // today_date は保存日であり、毎日チェックし直さなくても is_today=true が残るケースを正しく集計
    return !!t.is_today;
  };

  // 今日の作業時間（タスク）
  // ・assignee が自分 かつ is_today=true かつ 他者へ引継ぎ中でない（handover が空 or 自分）
  // ・引継ぎを受けた側：handover === 自分 かつ is_today=true のタスクも加算
  const taskTodayH =
    // ① 自分のタスクで引継ぎ出していないもの（完了含む）
    mine.filter(t => _isTodayTask(t) && (!t.handover || t.handover === staffName))
        .reduce((s, t) => s + (parseFloat(t.today_hours) || 0), 0)
    // ② 他者のタスクで自分が引継ぎ先になっているもの（完了含む）
    + _allTasks.filter(t =>
        _isTodayTask(t) &&
        t.handover === staffName &&
        t.assignee !== staffName
      ).reduce((s, t) => s + (parseFloat(t.today_hours) || 0), 0);

  // PR管理タスクの今日時間（内訳表示用）（完了含む）
  const prTaskTodayH =
    mine.filter(t => _isTodayTask(t) && t.task_category === 'PR管理' && (!t.handover || t.handover === staffName))
        .reduce((s, t) => s + (parseFloat(t.today_hours) || 0), 0)
    + _allTasks.filter(t =>
        _isTodayTask(t) && t.task_category === 'PR管理' &&
        t.handover === staffName && t.assignee !== staffName
      ).reduce((s, t) => s + (parseFloat(t.today_hours) || 0), 0);

  const schedTodayH = _allSchedules
    .filter(s => s.assignee === staffName && _schIsToday(s, today))
    .reduce((s, r) => s + (parseFloat(r.duration_hours) || 0), 0);
  // 公休中は今日の作業時間をゼロにする
  const todayH  = isHoliday ? 0 : (taskTodayH + schedTodayH);
  const estH    = active.reduce((s, t) => s + (parseFloat(t.estimated_hours) || 0), 0);
  const limit   = _staffHourLimit(staffName);
  const openCnt = active.length;
  const overdue = active.filter(t => t.due_date && new Date(t.due_date + 'T00:00:00') < (() => { const d = new Date(); d.setHours(0,0,0,0); return d; })()).length;
  return { todayH, taskTodayH, schedTodayH, prTaskTodayH, estH, limit, openCnt, overdue, total: mine.length, isHoliday };
}

function _renderTaskPage() {
  document.querySelectorAll('.task-panel').forEach(p => p.style.display = 'none');
  if (_taskCurrentStaff === 'dashboard') {
    const dash = document.getElementById('task-panel-dashboard');
    if (dash) { dash.style.display = ''; _renderDashboard(); }
  } else {
    const panelId = `task-panel-${_staffId(_taskCurrentStaff)}`;
    const panel   = document.getElementById(panelId);
    if (panel) { panel.style.display = ''; _renderStaffTable(panel, _taskCurrentStaff); }
  }
}

function _renderDashboard() {
  // インフォメーション（初回のみイベントバインド）
  _initAnnouncementsOnce();
  // 新店情報（初回のみイベントバインド）
  _initShopInfoOnce();

  const active    = _allTasks.filter(t => t.progress !== '完了');
  const today     = new Date(); today.setHours(0,0,0,0);
  const staffList = _orderedStaffList(); // ← 保存済み並び順を反映

  // 全スタッフの今日の作業時間合計（タスク today_hours + スケジュール duration_hours）
  const totalTodayH = staffList.reduce((sum, a) => {
    const { todayH } = _calcStaffHours(a.name);
    return sum + todayH;
  }, 0);
  // 全スタッフの今日の想定稼働時間合計
  const totalLimitH = staffList.reduce((sum, a) => sum + _staffHourLimit(a.name), 0);
  const totalEstH   = active.reduce((s, t) => s + (parseFloat(t.estimated_hours) || 0), 0);
  const overworkStaff = staffList.filter(a => {
    const { todayH, limit } = _calcStaffHours(a.name);
    return todayH >= limit;
  }).length;
  const overdue = active.filter(t => t.due_date && new Date(t.due_date + 'T00:00:00') < today).length;

  // サマリーカード
  const summaryEl = document.getElementById('task-summary-cards');
  if (summaryEl) {
    summaryEl.innerHTML = `
      <div class="task-summary-card task-summary-card--hours">
        <div class="task-summary-num">${totalTodayH.toFixed(1)}<span style="font-size:14px;font-weight:500;margin-left:2px;">h</span></div>
        <div class="task-summary-lbl">今日の総作業時間</div>
      </div>
      <div class="task-summary-card task-summary-card--today">
        <div class="task-summary-num">${totalLimitH.toFixed(1)}<span style="font-size:14px;font-weight:500;margin-left:2px;">h</span></div>
        <div class="task-summary-lbl">今日の想定総稼働時間</div>
      </div>
      <div class="task-summary-card task-summary-card--overwork">
        <div class="task-summary-num">${overworkStaff}</div>
        <div class="task-summary-lbl">オーバーワーク中のスタッフ</div>
      </div>
      <div class="task-summary-card task-summary-card--over" id="dash-overdue-card" style="cursor:pointer;" title="クリックして期限超過タスクを表示">
        <div class="task-summary-num">${overdue}</div>
        <div class="task-summary-lbl">期限超過タスク</div>
        ${overdue > 0 ? `<div class="task-summary-action"><i class="fas fa-list"></i> 案件を表示</div>` : ''}
      </div>`;
  }

  // スタッフ別概要テーブル
  const overviewEl = document.getElementById('task-staff-overview');
  if (overviewEl) {
    if (!staffList.length) {
      overviewEl.innerHTML = '<p style="color:var(--gray-400);font-size:13px;">スタッフが登録されていません</p>';
    } else {
      const _ovwToday = _todayStr();
      const _ovwDays  = 7; // 今日を含む過去N日
      const _ovwDateLabels = Array.from({length: _ovwDays}, (_, i) => i === 0 ? '今日' : `${i}日前`);
      const _ovwDates     = Array.from({length: _ovwDays}, (_, i) => _dateStrOffset(_ovwToday, i));
      overviewEl.innerHTML = `
        <table class="task-overview-table" id="task-overview-table">
          <thead><tr>
            <th class="task-overview-drag-col" title="ドラッグして並び替え"></th>
            <th>スタッフ</th>
            <th class="task-overview-position-col">ポジション</th>
            <th class="task-overview-jur-col">管轄</th>
            <th class="r">今日 (h)</th>
            <th class="r" style="color:var(--gray-400);">想定稼働時間</th>
            <th class="r">稼働率</th>
            ${_ovwDateLabels.map((l, i) => `<th class="c ovw-face-th"${i===0?' data-today="1"':''}>${l}</th>`).join('')}
          </tr></thead>
          <tbody id="task-overview-tbody">
          ${staffList.map(a => {
            const { todayH, estH, limit: lim, openCnt, overdue: ov } = _calcStaffHours(a.name);
            const progCnt = _allTasks.filter(t => t.assignee === a.name && t.progress === '進行中').length;
            const isOver  = todayH >= lim;
            const todayDisp = todayH > 0
              ? (isOver ? `<span class="task-time-warn"><i class="fas fa-exclamation-triangle"></i>${todayH.toFixed(1)}h</span>` : `${todayH.toFixed(1)}h`)
              : '—';
            const overPct = lim > 0 && todayH > 0 ? (todayH / lim * 100) : null;
            const overPctDisp = overPct !== null
              ? `<span class="ovw-pct${overPct > 110 ? ' ovw-pct--over2' : overPct > 100 ? ' ovw-pct--over1' : ' ovw-pct--ok'}">${overPct.toFixed(1)}%</span>`
              : '<span style="color:var(--gray-300);">—</span>';
            const faceCells = _ovwDates.map((dateStr, i) => {
              if (i === 0) {
                // 今日：リアルタイム計算
                const h = _calcStaffHoursOnDate(a.name, dateStr);
                const isHolToday = _calcStaffHours(a.name).isHoliday;
                return `<td class="c ovw-face-cell" data-today="1">${_overFaceHtml(h, lim, isHolToday)}</td>`;
              } else {
                // 過去日：daily_work_logs 優先（なければ schedules フォールバック）
                return `<td class="c ovw-face-cell">${_overFaceHtmlFromWorkLog(a.name, dateStr, lim)}</td>`;
              }
            }).join('');
            return `<tr class="task-overview-row${isOver ? ' task-overview-row--overwork' : ''}" draggable="true" data-staff="${escHtml(a.name)}">
              <td class="task-overview-drag-col"><span class="task-drag-handle" title="ドラッグして並び替え"><i class="fas fa-grip-vertical"></i></span></td>
              <td><button class="task-staff-link" data-staff="${escHtml(a.name)}">${escHtml(a.name)}</button></td>
              <td class="task-overview-position-col">${a.position ? `<span class="task-overview-position-badge">${escHtml(a.position)}</span>` : '<span class="task-overview-position-empty">—</span>'}</td>
              <td class="task-overview-jur-col">${(() => {
                const jurs = Array.isArray(a.jurisdiction) ? a.jurisdiction
                           : (a.jurisdiction ? (() => { try { return JSON.parse(a.jurisdiction); } catch { return []; } })() : []);
                return jurs.length
                  ? `<div class="ovw-jur-cell">${jurs.map(j => `<span class="ovw-jur-badge">${escHtml(j)}</span>`).join('')}</div>`
                  : '<span class="task-overview-position-empty">—</span>';
              })()}</td>
              <td class="r">${todayDisp}</td>
              <td class="r" style="color:var(--gray-400);font-size:11px;">${lim}h</td>
              <td class="r">${overPctDisp}</td>
              ${faceCells}
            </tr>`;
          }).join('')}
          </tbody>
        </table>`;
      overviewEl.querySelectorAll('.task-staff-link').forEach(btn => {
        btn.addEventListener('click', () => {
          _taskCurrentStaff = btn.dataset.staff;
          document.querySelectorAll('.task-staff-tab').forEach(b => b.classList.toggle('active', b.dataset.staff === _taskCurrentStaff));
          _renderTaskPage();
        });
      });
      // ── ドラッグ&ドロップ並び替え ─────────────────────────
      _initStaffTableDnD(document.getElementById('task-overview-tbody'));
    }
  }

  // ── 期限超過カード クリック → ポップアップ ──
  const overdueCard = document.getElementById('dash-overdue-card');
  if (overdueCard && overdue > 0) {
    overdueCard.addEventListener('click', () => _showOverduePopup());
  }

  // ── 日別稼働時間テーブル ──
  _renderDailyHoursTable();

}

// ── 日別稼働時間テーブル ──────────────────────────────────────
function _renderDailyHoursTable() {
  const el = document.getElementById('task-daily-hours');
  if (!el) return;

  const staffList = _orderedStaffList();
  if (!staffList.length) { el.innerHTML = ''; return; }

  const todayStr = _todayStr();
  const DAYS     = 7;
  const dates    = Array.from({ length: DAYS }, (_, i) => _dateStrOffset(todayStr, i));

  // 日付ラベル（曜日付き）
  const DOW = ['日','月','火','水','木','金','土'];
  const fmtLabel = d => {
    const dt   = new Date(d + 'T00:00:00');
    const dow  = DOW[dt.getDay()];
    const mmdd = `${dt.getMonth()+1}/${String(dt.getDate()).padStart(2,'0')}`;
    return d === todayStr
      ? `<span class="dh-date-today">${mmdd}<br><small>(${dow})</small></span>`
      : `${mmdd}<br><small>(${dow})</small>`;
  };

  // ── スタッフ×日付 の { h, status, limitH } を返すヘルパー ──
  const getLog = (staffName, dateStr) => {
    const limitH = _staffHourLimit(staffName);

    if (dateStr === todayStr) {
      // 今日：リアルタイム計算（公休チェック込み）
      const acct      = _allAccounts.find(a => a.name === staffName);
      const isHoliday = !!(acct?.is_holiday);
      if (isHoliday) return { h: 0, status: 'holiday', limitH };
      const h = _calcStaffHoursOnDate(staffName, dateStr);
      let status;
      if (h <= 0)                                status = 'none';
      else if (limitH > 0 && h / limitH > 1.10) status = 'over2';
      else if (limitH > 0 && h / limitH > 1.00) status = 'over1';
      else                                       status = 'ok';
      return { h, status, limitH };
    }

    // 過去日：daily_work_logs 優先
    const log = _allWorkLogs.find(r => r.date === dateStr && r.staff_name === staffName);
    if (log) {
      return {
        h:      parseFloat(log.total_hours) || 0,
        status: log.status || 'none',
        limitH: parseFloat(log.limit_hours) || limitH,
      };
    }
    // フォールバック（schedules のみ）
    const h = _calcStaffHoursOnDate(staffName, dateStr);
    return { h, status: h > 0 ? 'ok' : 'none', limitH };
  };

  // ── status → 絵文字アイコン HTML ──
  const faceHtml = status => {
    switch (status) {
      case 'holiday': return `<span class="dh-face dh-face--holiday" title="公休">💤</span>`;
      case 'none':    return `<span class="dh-face dh-face--none">—</span>`;
      case 'over2':   return `<span class="dh-face dh-face--over2" title="大幅超過">😣</span>`;
      case 'over1':   return `<span class="dh-face dh-face--over1" title="超過">😐</span>`;
      case 'ok':      return `<span class="dh-face dh-face--ok"    title="正常">😊</span>`;
      default:        return `<span class="dh-face dh-face--none">—</span>`;
    }
  };

  // ── セル HTML（アイコン＋時間＋棒グラフ＋%） ──
  const cellHtml = (log, isToday) => {
    const { h, status, limitH } = log;
    // 公休・データなし
    if (status === 'holiday') return faceHtml('holiday');
    if (status === 'none' || h <= 0) return faceHtml('none');

    const pct    = limitH > 0 ? h / limitH * 100 : 0;
    const barCls = status === 'over2' ? 'dh-bar--over2' : status === 'over1' ? 'dh-bar--over1' : 'dh-bar--ok';
    const barW   = Math.min(pct, 130);
    const todayCls = isToday ? ' dh-cell--today' : '';
    return `
      <div class="dh-cell-inner${todayCls}">
        ${faceHtml(status)}
        <span class="dh-hours">${h.toFixed(1)}<small>h</small></span>
        <div class="dh-bar-track">
          <div class="dh-bar ${barCls}" style="width:${barW.toFixed(0)}%"></div>
        </div>
        <span class="dh-pct ${status === 'over2' ? 'dh-pct--over2' : status === 'over1' ? 'dh-pct--over' : ''}">${pct.toFixed(0)}%</span>
      </div>`;
  };

  // 日計合計（holidayは加算しない）
  const dateTotals = dates.map(d =>
    staffList.reduce((sum, a) => {
      const { h, status } = getLog(a.name, d);
      return sum + (status === 'holiday' ? 0 : h);
    }, 0)
  );
  const dateLimits = dates.map(_ => staffList.reduce((sum, a) => sum + _staffHourLimit(a.name), 0));

  const theadCols = dates.map((d, i) =>
    `<th class="dh-th dh-th--date${i===0?' dh-th--today':''}">${fmtLabel(d)}</th>`
  ).join('');

  const tbodyRows = staffList.map(a => {
    const cells = dates.map((d, i) => {
      const log = getLog(a.name, d);
      return `<td class="dh-td${i===0?' dh-td--today':''}">${cellHtml(log, i===0)}</td>`;
    }).join('');
    return `<tr class="dh-row" data-staff="${escHtml(a.name)}">
      <td class="dh-td dh-td--staff">
        <button class="task-staff-link dh-staff-btn" data-staff="${escHtml(a.name)}">${escHtml(a.name)}</button>
        <span class="dh-limit-badge">${_staffHourLimit(a.name)}h</span>
      </td>
      ${cells}
    </tr>`;
  }).join('');

  const totalRow = `<tr class="dh-row dh-row--total">
    <td class="dh-td dh-td--staff"><strong>合計</strong></td>
    ${dates.map((_, i) => {
      const h   = dateTotals[i];
      const lim = dateLimits[i];
      if (h <= 0) return `<td class="dh-td${i===0?' dh-td--today':''}"><span class="dh-face dh-face--none">—</span></td>`;
      const pct = lim > 0 ? h / lim * 100 : 0;
      const cls = pct > 110 ? 'dh-pct--over2' : pct > 100 ? 'dh-pct--over' : '';
      return `<td class="dh-td${i===0?' dh-td--today':''}">
        <span class="dh-hours dh-hours--total">${h.toFixed(1)}<small>h</small></span>
        <span class="dh-pct ${cls}" style="margin-left:4px;">${pct.toFixed(0)}%</span>
      </td>`;
    }).join('')}
  </tr>`;

  // 開閉状態を sessionStorage で保持（デフォルト：閉じた状態）
  const DH_STORAGE_KEY = 'dh-open';
  const dhIsOpen = sessionStorage.getItem(DH_STORAGE_KEY) === 'true';

  el.innerHTML = `
  <div class="dh-section">
    <button class="dh-toggle-btn${dhIsOpen ? ' dh-toggle-btn--open' : ''}" id="dh-toggle-btn" aria-expanded="${dhIsOpen}" aria-controls="dh-body">
      <span class="dh-toggle-left">
        <i class="fas fa-chart-bar dh-title-icon"></i>
        <span class="dh-title-text">日別稼働時間</span>
      </span>
      <span class="dh-toggle-right">
        <span class="dh-note">タスク保存時に更新 ・ 棒グラフ＝想定稼働に対する達成率</span>
        <i class="fas ${dhIsOpen ? 'fa-chevron-up' : 'fa-chevron-down'} dh-toggle-icon"></i>
      </span>
    </button>
    <div class="dh-body" id="dh-body"${dhIsOpen ? '' : ' hidden'}>
      <div class="dh-table-wrap">
        <table class="dh-table">
          <thead>
            <tr>
              <th class="dh-th dh-th--staff">スタッフ</th>
              ${theadCols}
            </tr>
          </thead>
          <tbody>
            ${tbodyRows}
            ${totalRow}
          </tbody>
        </table>
      </div>
    </div>
  </div>`;

  // トグルボタン
  const toggleBtn = el.querySelector('#dh-toggle-btn');
  const dhBody    = el.querySelector('#dh-body');
  if (toggleBtn && dhBody) {
    toggleBtn.addEventListener('click', () => {
      const isOpen = !dhBody.hidden;
      dhBody.hidden = isOpen;
      toggleBtn.setAttribute('aria-expanded', String(!isOpen));
      toggleBtn.classList.toggle('dh-toggle-btn--open', !isOpen);
      const icon = toggleBtn.querySelector('.dh-toggle-icon');
      if (icon) icon.className = `fas ${isOpen ? 'fa-chevron-down' : 'fa-chevron-up'} dh-toggle-icon`;
      sessionStorage.setItem(DH_STORAGE_KEY, String(!isOpen));
    });
  }

  el.querySelectorAll('.task-staff-link').forEach(btn => {
    btn.addEventListener('click', () => {
      _taskCurrentStaff = btn.dataset.staff;
      document.querySelectorAll('.task-staff-tab').forEach(b =>
        b.classList.toggle('active', b.dataset.staff === _taskCurrentStaff)
      );
      _renderTaskPage();
    });
  });
}

// ── スタッフテーブルDnD並び替え ────────────────────────────────
function _initStaffTableDnD(tbody) {
  if (!tbody) return;
  let dragSrc = null;

  tbody.querySelectorAll('tr.task-overview-row').forEach(row => {
    row.addEventListener('dragstart', e => {
      dragSrc = row;
      row.classList.add('task-overview-row--dragging');
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', row.dataset.staff);
    });
    row.addEventListener('dragend', () => {
      row.classList.remove('task-overview-row--dragging');
      tbody.querySelectorAll('tr').forEach(r => r.classList.remove('task-overview-row--dragover'));
    });
    row.addEventListener('dragover', e => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      if (row !== dragSrc) {
        tbody.querySelectorAll('tr').forEach(r => r.classList.remove('task-overview-row--dragover'));
        row.classList.add('task-overview-row--dragover');
      }
    });
    row.addEventListener('dragleave', () => {
      row.classList.remove('task-overview-row--dragover');
    });
    row.addEventListener('drop', e => {
      e.preventDefault();
      row.classList.remove('task-overview-row--dragover');
      if (!dragSrc || dragSrc === row) return;

      // DOM 上の位置を比較して前後を決める
      const rows   = [...tbody.querySelectorAll('tr.task-overview-row')];
      const srcIdx = rows.indexOf(dragSrc);
      const dstIdx = rows.indexOf(row);
      if (srcIdx < dstIdx) {
        row.after(dragSrc);
      } else {
        row.before(dragSrc);
      }
      dragSrc = null;

      // 並び順を保存してタブ・テーブルを再描画
      const newOrder = [...tbody.querySelectorAll('tr.task-overview-row')]
        .map(r => r.dataset.staff);
      _saveStaffOrder(newOrder);
      _buildStaffTabs();
      // ダッシュボードのテーブル自体も新順で再描画
      _renderDashboard();
    });
  });
}

// ══════════════════════════════════════════════════════════════
//  クイックリンク機能
// ══════════════════════════════════════════════════════════════

let _qlLinks        = [];   // 取得済みリンク一覧
let _qlInited       = false; // モーダルイベント初期化フラグ
let _qlBarInited    = false; // バーイベント初期化フラグ

/** 起動時にリンクを読み込みバーを描画 */
async function loadQuickLinks() {
  try {
    const res = await API.get('quick_links', { limit: 200, sort: 'sort_order' });
    _qlLinks = (res.data || []).filter(l => !l.is_deleted)
      .sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0));
  } catch(e) {
    console.error('quick_links fetch error', e);
    _qlLinks = [];
  }
  _renderQlBar();
}

/** クイックリンクバーを描画 */
function _renderQlBar() {
  const listEl = document.getElementById('ql-btn-list');
  if (!listEl) return;

  if (!_qlLinks.length) {
    listEl.innerHTML = '<span class="ql-empty-hint">リンクがありません（⚙ボタンで追加）</span>';
  } else {
    listEl.innerHTML = _qlLinks.map(l => {
      const col   = escHtml(l.color || '#6366f1');
      const icon  = escHtml(l.icon  || 'fas fa-link');
      const label = escHtml(l.label || '');
      const url   = escHtml(l.url   || '#');
      return `<button class="ql-link-btn" style="--ql-color:${col};"
                data-url="${url}" title="${label}">
                <i class="${icon} ql-link-icon"></i>
                <span class="ql-link-label">${label}</span>
              </button>`;
    }).join('');

    // クリックで別ウィンドウ
    listEl.querySelectorAll('.ql-link-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        let url = btn.dataset.url || '';
        if (!url || url === '#') return;
        if (!/^https?:\/\//i.test(url)) url = 'https://' + url;
        window.open(url, '_blank', 'noopener,noreferrer');
      });
    });
  }

  // 管理ボタン初期化（1回のみ）
  if (!_qlBarInited) {
    _qlBarInited = true;
    document.getElementById('ql-manage-btn')?.addEventListener('click', () => {
      _openQlModal();
    });
  }
}

/** 管理モーダルを開く */
function _openQlModal() {
  _renderQlList();
  _initQlModalEvents();
  document.getElementById('modal-ql')?.classList.add('open');
}

/** モーダル内イベントバインド（1回のみ） */
function _initQlModalEvents() {
  if (_qlInited) return;
  _qlInited = true;

  // カラープリセット選択
  document.querySelectorAll('#ql-color-presets .ql-color-dot').forEach(dot => {
    dot.addEventListener('click', () => {
      document.querySelectorAll('#ql-color-presets .ql-color-dot').forEach(d => d.classList.remove('selected'));
      dot.classList.add('selected');
      const col = dot.dataset.color;
      const hiddenEl = document.getElementById('ql-inp-color');
      if (hiddenEl) hiddenEl.value = col;
      _updateQlPreview();
    });
  });
  // 最初のプリセットを選択状態に
  document.querySelector('#ql-color-presets .ql-color-dot')?.classList.add('selected');

  // ラベル/アイコン変更時プレビュー更新
  ['ql-inp-label','ql-inp-icon'].forEach(id => {
    document.getElementById(id)?.addEventListener('input', _updateQlPreview);
  });

  // 追加ボタン
  document.getElementById('ql-btn-add')?.addEventListener('click', _addQlLink);

  // Enter でも追加
  ['ql-inp-label','ql-inp-url','ql-inp-icon'].forEach(id => {
    document.getElementById(id)?.addEventListener('keydown', e => {
      if (e.key === 'Enter') { e.preventDefault(); _addQlLink(); }
    });
  });
}

/** プレビューボタン更新 */
function _updateQlPreview() {
  const label = document.getElementById('ql-inp-label')?.value || 'ラベル';
  const icon  = document.getElementById('ql-inp-icon')?.value  || 'fas fa-link';
  const color = document.getElementById('ql-inp-color')?.value || '#6366f1';
  const prev  = document.getElementById('ql-preview-btn');
  if (!prev) return;
  prev.style.setProperty('--ql-color', color);
  prev.querySelector('.ql-link-icon').className = `${icon} ql-link-icon`;
  prev.querySelector('.ql-link-label').textContent = label || 'ラベル';
}

/** リンク追加 */
async function _addQlLink() {
  const label = document.getElementById('ql-inp-label')?.value.trim() || '';
  const url   = document.getElementById('ql-inp-url')?.value.trim()   || '';
  const icon  = document.getElementById('ql-inp-icon')?.value.trim()  || 'fas fa-link';
  const color = document.getElementById('ql-inp-color')?.value        || '#6366f1';

  if (!label) { showToast('ラベルを入力してください', 'error'); return; }
  if (!url)   { showToast('URLを入力してください', 'error'); return; }

  const sort_order = _qlLinks.length
    ? Math.max(..._qlLinks.map(l => l.sort_order || 0)) + 1
    : 0;

  const btn = document.getElementById('ql-btn-add');
  if (btn) btn.disabled = true;
  try {
    await API.post('quick_links', { label, url, icon, color, sort_order, is_deleted: false });
    showToast(`「${label}」を追加しました`, 'success');
    // フォームリセット
    ['ql-inp-label','ql-inp-url'].forEach(id => {
      const el = document.getElementById(id);
      if (el) el.value = '';
    });
    document.getElementById('ql-inp-icon').value = 'fas fa-link';
    document.getElementById('ql-inp-color').value = '#6366f1';
    document.querySelectorAll('#ql-color-presets .ql-color-dot').forEach((d, i) => d.classList.toggle('selected', i === 0));
    _updateQlPreview();
    await loadQuickLinks();
    _renderQlList();
  } catch(e) {
    console.error('ql add error', e);
    showToast('追加に失敗しました', 'error');
  } finally {
    if (btn) btn.disabled = false;
  }
}

/** 管理モーダル内一覧描画 */
function _renderQlList() {
  const listEl = document.getElementById('ql-list-body');
  if (!listEl) return;

  if (!_qlLinks.length) {
    listEl.innerHTML = '<div class="ql-list-empty">まだリンクがありません</div>';
    return;
  }

  listEl.innerHTML = _qlLinks.map((l, idx) => `
    <div class="ql-list-row" data-id="${escHtml(l.id)}">
      <div class="ql-list-preview">
        <span class="ql-link-btn ql-link-btn--sm" style="--ql-color:${escHtml(l.color||'#6366f1')};">
          <i class="${escHtml(l.icon||'fas fa-link')} ql-link-icon"></i>
          <span class="ql-link-label">${escHtml(l.label||'')}</span>
        </span>
      </div>
      <span class="ql-list-url" title="${escHtml(l.url||'')}">${escHtml(l.url||'')}</span>
      <div class="ql-list-actions">
        <button class="ql-list-btn ql-list-btn--up" data-idx="${idx}" title="上へ" ${idx===0?'disabled':''}><i class="fas fa-chevron-up"></i></button>
        <button class="ql-list-btn ql-list-btn--down" data-idx="${idx}" title="下へ" ${idx===_qlLinks.length-1?'disabled':''}><i class="fas fa-chevron-down"></i></button>
        <button class="ql-list-btn ql-list-btn--del" data-id="${escHtml(l.id)}" title="削除"><i class="fas fa-trash"></i></button>
      </div>
    </div>
  `).join('');

  // 上移動
  listEl.querySelectorAll('.ql-list-btn--up').forEach(btn => {
    btn.addEventListener('click', async () => {
      const idx = parseInt(btn.dataset.idx, 10);
      if (idx === 0) return;
      await _swapQlOrder(idx, idx - 1);
    });
  });
  // 下移動
  listEl.querySelectorAll('.ql-list-btn--down').forEach(btn => {
    btn.addEventListener('click', async () => {
      const idx = parseInt(btn.dataset.idx, 10);
      if (idx >= _qlLinks.length - 1) return;
      await _swapQlOrder(idx, idx + 1);
    });
  });
  // 削除
  listEl.querySelectorAll('.ql-list-btn--del').forEach(btn => {
    btn.addEventListener('click', async () => {
      const id = btn.dataset.id;
      const link = _qlLinks.find(l => l.id === id);
      if (!id || !confirm(`「${link?.label || 'このリンク'}」を削除しますか？`)) return;
      try {
        await _saveTableFields('quick_links', id, { is_deleted: true });
        showToast('削除しました', 'success');
        await loadQuickLinks();
        _renderQlList();
      } catch(e) {
        console.error('ql del error', e);
        showToast('削除に失敗しました', 'error');
      }
    });
  });
}

/** 表示順の入れ替え */
async function _swapQlOrder(idxA, idxB) {
  const a = _qlLinks[idxA];
  const b = _qlLinks[idxB];
  const soA = a.sort_order || 0;
  const soB = b.sort_order || 0;
  try {
    await Promise.all([
          _saveTableFields('quick_links', a.id, { sort_order: soB }),
          _saveTableFields('quick_links', b.id, { sort_order: soA }),
    ]);
    await loadQuickLinks();
    _renderQlList();
  } catch(e) {
    console.error('ql swap error', e);
    showToast('並び替えに失敗しました', 'error');
  }
}

// ══════════════════════════════════════════════════════════════
//  インフォメーション機能
// ══════════════════════════════════════════════════════════════

// ══════════════════════════════════════════════════════════════
//  インフォメーション機能（テーブル型 + D&D 並び替え）
// ══════════════════════════════════════════════════════════════

let _annInited   = false;
let _annDragSrc  = null;

function _initAnnouncementsOnce() {
  _renderAnnouncements();
  if (_annInited) return;
  _annInited = true;

  // 「＋追加」ボタン → 末尾に空行を新規 POST して即再描画
  document.getElementById('ann-add-row-btn')?.addEventListener('click', async () => {
    const btn = document.getElementById('ann-add-row-btn');
    if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>'; }
    try {
      // 現在の件数を取得して sort_order を決定
      const res = await API.get('announcements', { limit: 500 });
      const existing = (res.data || []).filter(r => !r.deleted);
      await API.post('announcements', {
        title: '', body: '', level: '通常', author: '', url: '', period: '',
        sort_order: existing.length + 1, deleted: false,
      });
      await _renderAnnouncements();
      // 追加した末尾行のタイトル入力にフォーカス
      const rows = document.querySelectorAll('#ann-tbody tr[data-id]');
      if (rows.length) rows[rows.length - 1].querySelector('.ann-cell-inp')?.focus();
    } catch(e) {
      console.error('ann add error', e);
      showToast('追加に失敗しました', 'error');
    } finally {
      if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-plus"></i> 追加'; }
    }
  });

  // tbody イベント委譲（削除 / セル編集 / D&D）
  const tbody = document.getElementById('ann-tbody');
  if (!tbody) return;

  // 削除ボタン委譲
  tbody.addEventListener('click', async e => {
    const delBtn = e.target.closest('.ann-row-del-btn');
    if (!delBtn) return;
    const id = delBtn.dataset.id;
    if (!id) return;
    try {
      await _saveTableFields('announcements', id, { deleted: true });
      showToast('削除しました', 'success');
      _renderAnnouncements();
    } catch(err) {
      console.error('ann del error', err);
      showToast('削除に失敗しました', 'error');
    }
  });

  // URL「開く」ボタン委譲
  tbody.addEventListener('click', e => {
    const openBtn = e.target.closest('.ann-url-open-btn');
    if (!openBtn) return;
    const row = openBtn.closest('tr[data-id]');
    const inp = row?.querySelector('.ann-url-inp');
    let url = inp?.value.trim() || '';
    if (!url) { showToast('URLを入力してください', 'error'); return; }
    if (!/^https?:\/\//i.test(url)) url = 'https://' + url;
    window.open(url, '_blank', 'noopener,noreferrer');
  });

  // セル入力 blur → PATCH 保存（委譲）
  tbody.addEventListener('blur', async e => {
    const inp = e.target;
    if (!inp.dataset.field) return;
    const row = inp.closest('tr[data-id]');
    if (!row) return;
    const id    = row.dataset.id;
    const field = inp.dataset.field;
    const value = inp.value.trim();
    try {
      await _saveTableFields('announcements', id, { [field]: value });
    } catch(err) {
      console.error('ann patch error', err);
    }
  }, true); // capture=true でフォーカスアウトをキャッチ

  // D&D
  _annInitDnD();
}

// ── テーブル描画 ──────────────────────────────────────────
async function _renderAnnouncements() {
  const tbody = document.getElementById('ann-tbody');
  if (!tbody) return;
  tbody.innerHTML = '<tr><td colspan="5" class="ann-td-loading"><i class="fas fa-spinner fa-spin"></i></td></tr>';
  try {
    const res  = await API.get('announcements', { limit: 200, sort: 'sort_order' });
    const rows = (Array.isArray(res.data) ? res.data : (Array.isArray(res) ? res : []))
      .filter(a => !a.deleted)
      .sort((a, b) => ((a.sort_order ?? 9999) - (b.sort_order ?? 9999)) || ((a.created_at||0) - (b.created_at||0)));

    if (!rows.length) {
      tbody.innerHTML = '<tr><td colspan="5" class="ann-td-empty">データがありません。「追加」ボタンで行を追加できます。</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(r => `
      <tr class="ann-row" data-id="${escHtml(r.id)}" draggable="true">
        <td class="ann-td ann-td--drag">
          <span class="ann-drag-handle" title="ドラッグで並び替え"><i class="fas fa-grip-vertical"></i></span>
        </td>
        <td class="ann-td ann-td--title">
          <input class="ann-cell-inp" data-field="title"
                 value="${escHtml(r.title||'')}" placeholder="タイトル">
        </td>
        <td class="ann-td ann-td--period">
          <input class="ann-cell-inp" data-field="period"
                 value="${escHtml(r.period||'')}" placeholder="例）7/1〜7/31">
        </td>
        <td class="ann-td ann-td--url">
          <div class="ann-url-cell">
            <input class="ann-cell-inp ann-url-inp" data-field="url"
                   value="${escHtml(r.url||'')}" placeholder="https://...">
            <button class="ann-url-open-btn" title="別ウィンドウで開く">
              <i class="fas fa-external-link-alt"></i>
            </button>
          </div>
        </td>
        <td class="ann-td ann-td--act">
          <button class="ann-row-del-btn" data-id="${escHtml(r.id)}" title="削除">
            <i class="fas fa-trash"></i>
          </button>
        </td>
      </tr>`).join('');

    _annBindDnD();
  } catch(e) {
    console.error('ann fetch error', e);
    tbody.innerHTML = '<tr><td colspan="5" class="ann-td-empty">読み込みに失敗しました</td></tr>';
  }
}

// ── D&D ──────────────────────────────────────────────────
function _annInitDnD() {
  const tbody = document.getElementById('ann-tbody');
  if (!tbody) return;
  new MutationObserver(() => _annBindDnD()).observe(tbody, { childList: true });
  _annBindDnD();
}

function _annBindDnD() {
  document.querySelectorAll('#ann-tbody tr[data-id]').forEach(row => {
    row.draggable = true;
    row.addEventListener('dragstart', _annDragStart);
    row.addEventListener('dragover',  _annDragOver);
    row.addEventListener('dragleave', _annDragLeave);
    row.addEventListener('drop',      _annDrop);
    row.addEventListener('dragend',   _annDragEnd);
  });
}

function _annDragStart(e) {
  _annDragSrc = this;
  this.classList.add('ann-drag-source');
  e.dataTransfer.effectAllowed = 'move';
  e.dataTransfer.setData('text/plain', this.dataset.id);
}
function _annDragOver(e) {
  e.preventDefault();
  e.dataTransfer.dropEffect = 'move';
  document.querySelectorAll('#ann-tbody tr.ann-drag-over').forEach(r => r.classList.remove('ann-drag-over'));
  if (this !== _annDragSrc) this.classList.add('ann-drag-over');
}
function _annDragLeave() { this.classList.remove('ann-drag-over'); }
async function _annDrop(e) {
  e.preventDefault(); e.stopPropagation();
  this.classList.remove('ann-drag-over');
  if (!_annDragSrc || _annDragSrc === this) return;
  const tbody = document.getElementById('ann-tbody');
  if (!tbody) return;
  const rows = Array.from(tbody.querySelectorAll('tr[data-id]'));
  const si = rows.indexOf(_annDragSrc), di = rows.indexOf(this);
  if (si < 0 || di < 0) return;
  if (si < di) tbody.insertBefore(_annDragSrc, this.nextSibling);
  else         tbody.insertBefore(_annDragSrc, this);
  try {
    await Promise.all(
      Array.from(tbody.querySelectorAll('tr[data-id]')).map((r, i) =>
          _saveTableFields('announcements', r.dataset.id, { sort_order: i + 1 })
      )
    );
  } catch(err) { console.error('ann sort error', err); }
}
function _annDragEnd() {
  document.querySelectorAll('#ann-tbody tr').forEach(r =>
    r.classList.remove('ann-drag-source', 'ann-drag-over')
  );
  _annDragSrc = null;
}

function _clearAnnForm() {} // 互換性のため残す（旧フォーム削除済み）

// ══════════════════════════════════════════════════════════════
//  新店情報（Shop Information）機能
// ══════════════════════════════════════════════════════════════

let _siInited = false;
let _siEditId  = null;   // 編集中レコードID（null=新規追加モード）
let _siCalTarget = null; // 'start' | 'end'
let _siCalYear   = null;
let _siCalMonth  = null;
let _siCalStartStr = '';  // 選択中開始日 'YYYY-MM-DD'
let _siCalEndStr   = '';  // 選択中終了日 'YYYY-MM-DD'

// ── カレンダーユーティリティ ──────────────────────────────
function _siDateFmt(str) {
  // 'YYYY-MM-DD' → 'YYYY年MM月DD日'
  if (!str) return '';
  const [y, m, d] = str.split('-');
  return `${y}年${String(m).padStart(2,'0')}月${String(d).padStart(2,'0')}日`;
}
function _siDateParse(disp) {
  // 'YYYY年MM月DD日' → 'YYYY-MM-DD'
  if (!disp) return '';
  const m = disp.match(/(\d{4})年(\d{1,2})月(\d{1,2})日/);
  if (!m) return '';
  return `${m[1]}-${String(m[2]).padStart(2,'0')}-${String(m[3]).padStart(2,'0')}`;
}
function _siFormatRange() {
  const s = _siCalStartStr ? _siDateFmt(_siCalStartStr) : '';
  const e = _siCalEndStr   ? _siDateFmt(_siCalEndStr)   : '';
  return s && e ? `${s}〜${e}` : s || e;
}
function _siUpdateDateInputs() {
  const startEl = document.getElementById('si-con-start');
  const endEl   = document.getElementById('si-con-end');
  if (startEl) startEl.value = _siCalStartStr ? _siDateFmt(_siCalStartStr) : '';
  if (endEl)   endEl.value   = _siCalEndStr   ? _siDateFmt(_siCalEndStr)   : '';
}

// ── 汎用カレンダーポップアップ ──────────────────────────
// _siCalMode: 'range'（工事期間） / 'single'（単一日）
let _siCalMode      = 'range';
let _siCalSingleId  = '';    // 単一日モード時の input ID
let _siCalSingleStr = '';    // 単一日モード時の選択値 'YYYY-MM-DD'

function _siGetOrCreatePopup() {
  let popup = document.getElementById('si-cal-popup');
  if (!popup) {
    popup = document.createElement('div');
    popup.id = 'si-cal-popup';
    popup.className = 'si-cal-popup';
    popup.style.display = 'none';
    document.body.appendChild(popup); // body直下に置いてfixedで位置制御
  }
  return popup;
}

// カレンダーを指定 anchor 要素のすぐ下に fixed で表示
function _siPositionPopup(anchor) {
  const popup = _siGetOrCreatePopup();
  const rect  = anchor.getBoundingClientRect();
  popup.style.top  = (rect.bottom + window.scrollY + 4) + 'px';
  popup.style.left = Math.min(rect.left + window.scrollX,
                               window.innerWidth - 310) + 'px';
}

function _siRenderCal() {
  const popup = _siGetOrCreatePopup();
  const y = _siCalYear, m = _siCalMonth;
  const firstDay     = new Date(y, m - 1, 1).getDay();
  const daysInMonth  = new Date(y, m, 0).getDate();
  const weekLabels   = ['日','月','火','水','木','金','土'];
  const isRange      = (_siCalMode === 'range');

  // ── ヘッダー ──
  let html = `<div class="si-cal-header">
    <button class="si-cal-nav" data-nav="-1">&#8249;</button>
    <span class="si-cal-title">${y}年${m}月</span>
    <button class="si-cal-nav" data-nav="1">&#8250;</button>
  </div>`;

  // range モードのみ 開始日/終了日 タブ表示
  if (isRange) {
    html += `<div class="si-cal-mode-row">
      <button class="si-cal-mode-btn${_siCalTarget==='start'?' active':''}" data-mode="start">開始日</button>
      <button class="si-cal-mode-btn${_siCalTarget==='end'?' active':''}" data-mode="end">終了日</button>
      <button class="si-cal-clear">クリア</button>
    </div>`;
  } else {
    html += `<div class="si-cal-mode-row">
      <span class="si-cal-single-label">日付を選択</span>
      <button class="si-cal-clear">クリア</button>
    </div>`;
  }

  // ── カレンダーグリッド ──
  html += `<table class="si-cal-table"><thead><tr>`;
  weekLabels.forEach((w, i) => {
    const cls = i===0?' si-cal-sun':i===6?' si-cal-sat':'';
    html += `<th class="${cls}">${w}</th>`;
  });
  html += '</tr></thead><tbody><tr>';
  let col = firstDay;
  for (let i = 0; i < firstDay; i++) html += '<td></td>';
  for (let d = 1; d <= daysInMonth; d++) {
    const dateStr   = `${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    let cls = 'si-cal-day';
    const dow = (firstDay + d - 1) % 7;
    if (dow === 0) cls += ' si-cal-sun';
    if (dow === 6) cls += ' si-cal-sat';
    if (isRange) {
      if (dateStr === _siCalStartStr) cls += ' si-cal-sel-start';
      if (dateStr === _siCalEndStr)   cls += ' si-cal-sel-end';
      if (_siCalStartStr && _siCalEndStr && dateStr > _siCalStartStr && dateStr < _siCalEndStr)
        cls += ' si-cal-in-range';
    } else {
      if (dateStr === _siCalSingleStr) cls += ' si-cal-sel-start';
    }
    html += `<td class="${cls}" data-date="${dateStr}">${d}</td>`;
    col++;
    if (col % 7 === 0 && d < daysInMonth) html += '</tr><tr>';
  }
  html += '</tr></tbody></table>';

  // ── フッター ──
  const dispText = isRange
    ? (_siFormatRange() || '期間を選択してください')
    : (_siCalSingleStr ? _siDateFmt(_siCalSingleStr) : '日付を選択してください');
  html += `<div class="si-cal-footer">
    <span class="si-cal-range-disp">${dispText}</span>
    <button class="si-cal-ok">OK</button>
  </div>`;

  popup.innerHTML = html;
  popup.style.display = 'block';

  // ── イベント登録 ──
  popup.querySelectorAll('.si-cal-nav').forEach(btn => {
    btn.addEventListener('click', e => {
      e.stopPropagation();
      _siCalMonth += parseInt(btn.dataset.nav);
      if (_siCalMonth > 12) { _siCalMonth = 1;  _siCalYear++; }
      if (_siCalMonth < 1)  { _siCalMonth = 12; _siCalYear--; }
      _siRenderCal();
    });
  });
  if (isRange) {
    popup.querySelectorAll('.si-cal-mode-btn').forEach(btn => {
      btn.addEventListener('click', e => {
        e.stopPropagation();
        _siCalTarget = btn.dataset.mode;
        _siRenderCal();
      });
    });
  }
  popup.querySelector('.si-cal-clear')?.addEventListener('click', e => {
    e.stopPropagation();
    if (isRange) {
      _siCalStartStr = ''; _siCalEndStr = '';
      _siUpdateDateInputs();
    } else {
      _siCalSingleStr = '';
      const el = document.getElementById(_siCalSingleId);
      if (el) el.value = '';
    }
    _siRenderCal();
  });
  popup.querySelectorAll('.si-cal-day[data-date]').forEach(td => {
    td.addEventListener('click', e => {
      e.stopPropagation();
      const dt = td.dataset.date;
      if (isRange) {
        if (_siCalTarget === 'start') {
          _siCalStartStr = dt;
          if (_siCalEndStr && _siCalEndStr < dt) _siCalEndStr = '';
          _siCalTarget = 'end';
        } else {
          if (_siCalStartStr && dt < _siCalStartStr) {
            _siCalEndStr = _siCalStartStr; _siCalStartStr = dt;
          } else {
            _siCalEndStr = dt;
          }
          _siCalTarget = 'start';
        }
        _siUpdateDateInputs();
      } else {
        _siCalSingleStr = dt;
        const el = document.getElementById(_siCalSingleId);
        if (el) el.value = _siDateFmt(dt);
        // 単一日はOKと同じ動作で即閉じ
        popup.style.display = 'none';
        return;
      }
      _siRenderCal();
    });
  });
  popup.querySelector('.si-cal-ok')?.addEventListener('click', e => {
    e.stopPropagation();
    popup.style.display = 'none';
  });
}

// 工事期間（range）用オープン
function _siOpenCal(target, anchorId) {
  _siCalMode   = 'range';
  _siCalTarget = target;
  const now = new Date();
  _siCalYear  = now.getFullYear();
  _siCalMonth = now.getMonth() + 1;
  if (_siCalStartStr) {
    const [y, mo] = _siCalStartStr.split('-');
    _siCalYear = parseInt(y); _siCalMonth = parseInt(mo);
  }
  const anchor = document.getElementById(anchorId || 'si-con-start');
  if (anchor) _siPositionPopup(anchor);
  _siRenderCal();
}

// 単一日（オープン日・レセプション等）用オープン
function _siOpenSingleCal(inputId) {
  _siCalMode      = 'single';
  _siCalSingleId  = inputId;
  const el = document.getElementById(inputId);
  _siCalSingleStr = el ? _siDateParse(el.value) : '';
  const now = new Date();
  _siCalYear  = now.getFullYear();
  _siCalMonth = now.getMonth() + 1;
  if (_siCalSingleStr) {
    const [y, mo] = _siCalSingleStr.split('-');
    _siCalYear = parseInt(y); _siCalMonth = parseInt(mo);
  }
  if (el) _siPositionPopup(el);
  _siRenderCal();
}

// ── メイン初期化 ──────────────────────────────────────────
function _initShopInfoOnce() {
  _renderShopInfo();

  if (_siInited) return;
  _siInited = true;

  const addBtn    = document.getElementById('shop-info-add-btn');
  const cancelBtn = document.getElementById('si-cancel-btn');
  const saveBtn   = document.getElementById('si-save-btn');
  const form      = document.getElementById('shop-info-form');
  if (!addBtn || !form) return;

  // 追加ボタン
  addBtn.addEventListener('click', () => {
    const isOpen = form.style.display !== 'none';
    if (isOpen) {
      form.style.display = 'none';
      _siResetForm();
    } else {
      _siEditId = null;
      _siResetForm();
      form.style.display = 'block';
      document.getElementById('si-store-name').focus();
    }
  });

  // レセ日（single）
  document.getElementById('si-reception-date')?.addEventListener('click', e => {
    e.stopPropagation(); _siOpenSingleCal('si-reception-date');
  });

  // オープン日（single）
  document.getElementById('si-open-date')?.addEventListener('click', e => {
    e.stopPropagation(); _siOpenSingleCal('si-open-date');
  });

  // 外クリックで閉じる
  document.addEventListener('click', e => {
    const popup = document.getElementById('si-cal-popup');
    if (popup && !popup.contains(e.target)) popup.style.display = 'none';
  });

  // キャンセル
  cancelBtn.addEventListener('click', () => {
    form.style.display = 'none';
    _siResetForm();
  });

  // 保存
  saveBtn.addEventListener('click', async () => {
    const storeName = (document.getElementById('si-store-name').value || '').trim();
    if (!storeName) {
      showToast('店舗名は必須です', 'error');
      document.getElementById('si-store-name').focus();
      return;
    }
    const payload = {
      store_name:        storeName,
      reception_date:    (document.getElementById('si-reception-date').value || '').trim(),
      open_date:         (document.getElementById('si-open-date').value || '').trim(),
      media_creation:    document.getElementById('si-media-creation').checked,
      daichou:           document.getElementById('si-daichou').checked,
      reservation_open:  document.getElementById('si-reservation-open').checked,
      gmb:               document.getElementById('si-gmb').checked,
      sns:               document.getElementById('si-sns').checked,
      pr:                document.getElementById('si-pr').checked,
      attraction:        document.getElementById('si-attraction').checked,
      sponsor:           (document.getElementById('si-sponsor').value || '').trim(),
      notes:             (document.getElementById('si-notes').value || '').trim(),
      is_deleted:        false,
    };
    saveBtn.disabled = true;
    saveBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> 保存中…';
    try {
      if (_siEditId) {
        await API.put('shop_info', _siEditId, payload);
        showToast('更新しました', 'success');
      } else {
        const res = await API.get('shop_info', { limit: 500 });
        const existing = (res.data || []).filter(r => !r.is_deleted);
        payload.sort_order = existing.length + 1;
        await API.post('shop_info', payload);
        showToast('追加しました', 'success');
      }
      form.style.display = 'none';
      _siResetForm();
      _renderShopInfo();
    } catch(e) {
      console.error('shop_info save error', e);
      showToast('保存に失敗しました', 'error');
    } finally {
      saveBtn.disabled = false;
      saveBtn.innerHTML = '<i class="fas fa-save"></i> 保存';
    }
  });

  // テーブル行のイベント委譲（編集・削除）
  const tbody = document.getElementById('shop-info-tbody');
  if (tbody) {
    tbody.addEventListener('click', async e => {
      const delBtn = e.target.closest('.si-btn-del');
      if (delBtn) {
        const id = delBtn.dataset.id;
        try {
          // GET→PUTでis_deleted=trueに更新（PATCHは405のため）
          const getRes = await fetch(`tables/shop_info/${id}`, { cache: 'no-store' });
          if (!getRes.ok) throw new Error(`GET shop_info/${id} failed`);
          const exRow = await getRes.json();
          const { gs_project_id, gs_table_name, created_at, updated_at, deleted, ...restRow } = exRow;
          await fetch(`tables/shop_info/${id}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ ...restRow, is_deleted: true }),
          });
          showToast('削除しました', 'success');
          _renderShopInfo();
        } catch(err) {
          console.error('shop_info del error', err);
          showToast('削除に失敗しました', 'error');
        }
        return;
      }
      const editBtn = e.target.closest('.si-btn-edit');
      if (editBtn) {
        const id  = editBtn.dataset.id;
        // DBから直接取得してフォームに反映
        _siEditId = id;
        try {
          const r = await fetch(`tables/shop_info/${id}`, { cache: 'no-store' }).then(res => res.json());
          document.getElementById('si-store-name').value        = r.store_name || '';
          document.getElementById('si-reception-date').value    = r.reception_date || '';
          document.getElementById('si-open-date').value         = r.open_date || '';
          document.getElementById('si-media-creation').checked  = !!r.media_creation;
          document.getElementById('si-daichou').checked         = !!r.daichou;
          document.getElementById('si-reservation-open').checked= !!r.reservation_open;
          document.getElementById('si-gmb').checked             = !!r.gmb;
          document.getElementById('si-sns').checked             = !!r.sns;
          document.getElementById('si-pr').checked              = !!r.pr;
          document.getElementById('si-attraction').checked      = !!r.attraction;
          document.getElementById('si-sponsor').value           = r.sponsor || '';
          document.getElementById('si-notes').value             = r.notes || '';
          document.getElementById('shop-info-form').style.display = 'block';
          document.getElementById('si-store-name').focus();
        } catch(err) {
          console.error('shop_info edit fetch error', err);
          showToast('データ取得に失敗しました', 'error');
        }
        return;
      }
    });
  }

  _siInitDnD();
}

function _siResetForm() {
  _siEditId = null;
  _siCalStartStr = ''; _siCalEndStr = '';
  _siCalSingleStr = ''; _siCalSingleId = '';
  ['si-store-name','si-reception-date','si-open-date','si-sponsor','si-notes']
    .forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
  ['si-media-creation','si-daichou','si-reservation-open','si-gmb','si-sns','si-pr','si-attraction']
    .forEach(id => { const el = document.getElementById(id); if (el) el.checked = false; });
  const popup = document.getElementById('si-cal-popup');
  if (popup) popup.style.display = 'none';
}

// ── D&D 並び替え ──────────────────────────────────────────
let _siDragSrcRow = null;

function _siInitDnD() {
  // tbody内行へのD&D設定（_renderShopInfo後に再設定するためMutationObserver使用）
  const tbody = document.getElementById('shop-info-tbody');
  if (!tbody) return;
  const obs = new MutationObserver(() => _siBindDnD());
  obs.observe(tbody, { childList: true });
  _siBindDnD();
}

function _siBindDnD() {
  const tbody = document.getElementById('shop-info-tbody');
  if (!tbody) return;
  tbody.querySelectorAll('tr[data-id]').forEach(row => {
    row.draggable = true;
    row.addEventListener('dragstart', _siDragStart);
    row.addEventListener('dragover',  _siDragOver);
    row.addEventListener('dragleave', _siDragLeave);
    row.addEventListener('drop',      _siDrop);
    row.addEventListener('dragend',   _siDragEnd);
  });
}

function _siDragStart(e) {
  _siDragSrcRow = this;
  this.classList.add('si-drag-source');
  e.dataTransfer.effectAllowed = 'move';
  e.dataTransfer.setData('text/plain', this.dataset.id);
}
function _siDragOver(e) {
  e.preventDefault();
  e.dataTransfer.dropEffect = 'move';
  document.querySelectorAll('#shop-info-tbody tr.si-drag-over').forEach(r => r.classList.remove('si-drag-over'));
  if (this !== _siDragSrcRow) this.classList.add('si-drag-over');
}
function _siDragLeave() {
  this.classList.remove('si-drag-over');
}
async function _siDrop(e) {
  e.preventDefault();
  e.stopPropagation();
  this.classList.remove('si-drag-over');
  if (!_siDragSrcRow || _siDragSrcRow === this) return;

  const tbody = document.getElementById('shop-info-tbody');
  if (!tbody) return;

  // DOM上で行を入れ替え（即時反映）
  const rows = Array.from(tbody.querySelectorAll('tr[data-id]'));
  const srcIdx  = rows.indexOf(_siDragSrcRow);
  const destIdx = rows.indexOf(this);
  if (srcIdx < 0 || destIdx < 0) return;

  if (srcIdx < destIdx) {
    tbody.insertBefore(_siDragSrcRow, this.nextSibling);
  } else {
    tbody.insertBefore(_siDragSrcRow, this);
  }

  // sort_order を更新してAPIに保存
  const newRows = Array.from(tbody.querySelectorAll('tr[data-id]'));
  try {
    await Promise.all(newRows.map((r, i) =>
          _saveTableFields('shop_info', r.dataset.id, { sort_order: i + 1 })
    ));
  } catch(err) {
    console.error('shop_info sort error', err);
    showToast('並び替えの保存に失敗しました', 'error');
  }
}
function _siDragEnd() {
  document.querySelectorAll('#shop-info-tbody tr').forEach(r => {
    r.classList.remove('si-drag-source', 'si-drag-over');
  });
  _siDragSrcRow = null;
}

async function _renderShopInfo() {
  const tbody = document.getElementById('shop-info-tbody');
  if (!tbody) return;
  tbody.innerHTML = '<tr><td colspan="13" class="si-loading"><i class="fas fa-spinner fa-spin"></i></td></tr>';
  try {
    const res  = await API.get('shop_info', { limit: 500 });
    const rows = (res.data || []).filter(r => !r.is_deleted);
    if (rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="13" class="si-empty">データがありません</td></tr>';
      return;
    }

    // ── オープン日パース ('YYYY年MM月DD日' → Date) ───────────────
    const parseOpenDate = str => {
      if (!str) return null;
      const m = str.match(/(\d{4})年(\d{1,2})月(\d{1,2})日/);
      if (!m) return null;
      return new Date(parseInt(m[1]), parseInt(m[2]) - 1, parseInt(m[3]));
    };

    // ── オープン日順に自動ソート（日付なし→末尾） ───────────────
    rows.sort((a, b) => {
      const da = parseOpenDate(a.open_date);
      const db = parseOpenDate(b.open_date);
      if (!da && !db) return 0;
      if (!da) return 1;
      if (!db) return -1;
      return da - db; // 昇順（早い順）
    });

    // ── 今日基準で色分けクラスを決定 ───────────────────────────
    const now = new Date(); now.setHours(0, 0, 0, 0);
    const MS_1M = 30 * 24 * 60 * 60 * 1000;  // 約1ヶ月
    const MS_2M = 60 * 24 * 60 * 60 * 1000;  // 約2ヶ月

    const rowCls = r => {
      const d = parseOpenDate(r.open_date);
      if (!d) return '';
      const diff = d - now; // 正=未来、負=過去
      if (diff < 0) return '';            // 過去（オープン済み）→ 色なし
      if (diff <= MS_1M)  return 'si-row--open-soon2'; // 1か月以内→濃い赤
      if (diff <= MS_2M)  return 'si-row--open-soon1'; // 2か月以内→薄い赤
      return '';
    };

    // インラインチェックボックスHTML生成
    const _inlineChk = (id, field, val) =>
      `<input type="checkbox" class="si-inline-chk" data-id="${escHtml(id)}" data-field="${field}" ${val ? 'checked' : ''} title="クリックで切替・自動保存">`;
    // インラインテキストHTML生成
    const _inlineTxt = (id, field, val, cls='') =>
      `<span class="si-inline-text${cls ? ' '+cls : ''}" data-id="${escHtml(id)}" data-field="${field}" title="クリックで編集">${escHtml(val || '')}<span class="si-inline-placeholder">${val ? '' : '—'}</span></span>`;

    tbody.innerHTML = rows.map(r => `
      <tr data-id="${escHtml(r.id)}" class="si-row ${rowCls(r)}">
        <td class="si-cell si-cell--name">
          <span class="si-drag-handle" title="ドラッグで並び替え"><i class="fas fa-grip-vertical"></i></span>
          ${escHtml(r.store_name || '—')}
        </td>
        <td class="si-cell">${escHtml(r.reception_date || '—')}</td>
        <td class="si-cell">${escHtml(r.open_date || '—')}</td>
        <td class="si-cell si-cell--chk">${_inlineChk(r.id,'media_creation',r.media_creation)}</td>
        <td class="si-cell si-cell--chk">${_inlineChk(r.id,'daichou',r.daichou)}</td>
        <td class="si-cell si-cell--chk">${_inlineChk(r.id,'reservation_open',r.reservation_open)}</td>
        <td class="si-cell si-cell--chk">${_inlineChk(r.id,'gmb',r.gmb)}</td>
        <td class="si-cell si-cell--chk">${_inlineChk(r.id,'sns',r.sns)}</td>
        <td class="si-cell si-cell--chk">${_inlineChk(r.id,'pr',r.pr)}</td>
        <td class="si-cell si-cell--chk">${_inlineChk(r.id,'attraction',r.attraction)}</td>
        <td class="si-cell si-cell--sponsor">${_inlineTxt(r.id,'sponsor',r.sponsor)}</td>
        <td class="si-cell si-cell--notes">${_inlineTxt(r.id,'notes',r.notes)}</td>
        <td class="si-cell si-act-cell">
          <button class="si-btn-edit" data-id="${escHtml(r.id)}" title="編集"><i class="fas fa-pen"></i></button>
          <button class="si-btn-del"  data-id="${escHtml(r.id)}" title="削除"><i class="fas fa-trash"></i></button>
        </td>
      </tr>`).join('');

    // ── インライン編集イベント ──────────────────────────────
    // チェックボックス：changeで即時保存
    tbody.querySelectorAll('.si-inline-chk').forEach(chk => {
      chk.addEventListener('change', async function() {
        const id    = this.dataset.id;
        const field = this.dataset.field;
        const val   = this.checked;
        this.disabled = true;
        try {
          await _saveTableFields('shop_info', id, { [field]: val });
        } catch(err) {
          console.error('inline chk save error', err);
          showToast('保存に失敗しました', 'error');
          this.checked = !val; // ロールバック
        } finally {
          this.disabled = false;
        }
      });
    });

    // テキストセル：クリックでinput化 → blur/Enterで保存
    tbody.querySelectorAll('.si-inline-text').forEach(span => {
      span.addEventListener('click', function() {
        if (this.querySelector('input')) return; // 既にinput化済み
        const id     = this.dataset.id;
        const field  = this.dataset.field;
        const curVal = this.textContent.replace('—','').trim();
        const input  = document.createElement('input');
        input.type  = 'text';
        input.value = curVal;
        input.className = 'si-inline-input';
        input.maxLength = 300;
        this.textContent = '';
        this.appendChild(input);
        input.focus();
        input.select();

        const doSave = async () => {
          const newVal = input.value.trim();
          input.disabled = true;
          try {
            await _saveTableFields('shop_info', id, { [field]: newVal });
            // DOM更新（再レンダリングせずに更新）
            span.textContent = '';
            const ph = document.createElement('span');
            ph.className = 'si-inline-placeholder';
            ph.textContent = newVal ? '' : '—';
            if (newVal) span.textContent = newVal;
            span.appendChild(ph);
          } catch(err) {
            console.error('inline txt save error', err);
            showToast('保存に失敗しました', 'error');
            span.textContent = curVal || '';
            const ph = document.createElement('span');
            ph.className = 'si-inline-placeholder';
            ph.textContent = curVal ? '' : '—';
            span.appendChild(ph);
          }
        };

        input.addEventListener('blur', doSave);
        input.addEventListener('keydown', e => {
          if (e.key === 'Enter') { e.preventDefault(); input.blur(); }
          if (e.key === 'Escape') { input.removeEventListener('blur', doSave); span.textContent = curVal || ''; const ph = document.createElement('span'); ph.className='si-inline-placeholder'; ph.textContent=curVal?'':'—'; span.appendChild(ph); }
        });
      });
    });

  } catch(e) {
    console.error('shop_info fetch error', e);
    tbody.innerHTML = '<tr><td colspan="13" class="si-empty">読み込みに失敗しました</td></tr>';
  }
}

// ── 期限超過タスク ポップアップ ────────────────────────────────
function _showOverduePopup() {
  const today = new Date(); today.setHours(0,0,0,0);
  const fmtDate = d => {
    if (!d) return '—';
    const dt = new Date(d + 'T00:00:00');
    return `${dt.getFullYear()}/${String(dt.getMonth()+1).padStart(2,'0')}/${String(dt.getDate()).padStart(2,'0')}`;
  };
  const diffDays = d => {
    const dt = new Date(d + 'T00:00:00');
    return Math.floor((today - dt) / (1000 * 60 * 60 * 24));
  };

  // 期限超過タスクを取得（完了除外・due_date あり・期日 < 今日）
  const overdueTasks = _allTasks
    .filter(t => t.progress !== '完了' && t.due_date && new Date(t.due_date + 'T00:00:00') < today)
    .sort((a, b) => (a.due_date || '') < (b.due_date || '') ? -1 : 1); // 古い期日順

  // スタッフごとにグループ化
  const byStaff = new Map();
  overdueTasks.forEach(t => {
    const name = t.assignee || '未割当';
    if (!byStaff.has(name)) byStaff.set(name, []);
    byStaff.get(name).push(t);
  });

  const PRIORITY_COLORS = { '高': '#ef4444', '中': '#f59e0b', '低': '#6b7280' };
  const PROGRESS_COLORS = {
    '未着手': { bg: '#f3f4f6', color: '#4b5563' },
    '進行中': { bg: '#fee2e2', color: '#b91c1c' },
    '確認待ち': { bg: '#fef9c3', color: '#854d0e' },
  };

  const staffSections = [...byStaff.entries()].map(([name, tasks]) => {
    const rows = tasks.map(t => {
      const days = diffDays(t.due_date);
      const prioColor = PRIORITY_COLORS[t.priority] || '#6b7280';
      const progStyle = PROGRESS_COLORS[t.progress] || { bg: '#f3f4f6', color: '#4b5563' };
      const catBadge = t.task_category && t.task_category !== 'タスク管理'
        ? `<span class="odp-cat-badge">${escHtml(t.task_category)}</span>` : '';
      return `<tr class="odp-row">
        <td class="odp-cell odp-cell--store">${escHtml(t.store_name || '—')}</td>
        <td class="odp-cell odp-cell--title">
          ${catBadge}
          ${t.task_url
            ? `<a class="odp-title-link" href="${escHtml(t.task_url)}" target="_blank" rel="noopener noreferrer">${escHtml(t.title || '（無題）')}</a>`
            : `<span>${escHtml(t.title || '（無題）')}</span>`}
        </td>
        <td class="odp-cell odp-cell--priority">
          <span class="odp-prio-dot" style="background:${prioColor};" title="${escHtml(t.priority||'—')}"></span>
        </td>
        <td class="odp-cell odp-cell--due">
          <span class="odp-due-date">${fmtDate(t.due_date)}</span>
          <span class="odp-overdue-days">+${days}日超過</span>
        </td>
        <td class="odp-cell odp-cell--progress">
          <span class="odp-prog-badge" style="background:${progStyle.bg};color:${progStyle.color};">${escHtml(t.progress || '未着手')}</span>
        </td>
      </tr>`;
    }).join('');

    return `<div class="odp-staff-section">
      <div class="odp-staff-header">
        <span class="odp-staff-name"><i class="fas fa-user"></i> ${escHtml(name)}</span>
        <span class="odp-staff-count">${tasks.length}件</span>
      </div>
      <table class="odp-table">
        <thead><tr>
          <th class="odp-th odp-th--store">店舗名</th>
          <th class="odp-th odp-th--title">タスク名</th>
          <th class="odp-th odp-th--priority">優先度</th>
          <th class="odp-th odp-th--due">完了予定日</th>
          <th class="odp-th odp-th--progress">進捗</th>
        </tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>`;
  }).join('');

  // 既存モーダルを除去
  const existing = document.getElementById('odp-modal');
  if (existing) existing.remove();

  const modal = document.createElement('div');
  modal.id = 'odp-modal';
  modal.className = 'odp-modal-overlay';
  modal.innerHTML = `
    <div class="odp-modal" role="dialog" aria-modal="true">
      <div class="odp-modal-header">
        <h2 class="odp-modal-title"><i class="fas fa-exclamation-triangle" style="color:#ef4444;margin-right:8px;"></i>期限超過タスク <span class="odp-total-badge">${overdueTasks.length}件</span></h2>
        <button class="odp-modal-close" id="odp-close-btn" title="閉じる"><i class="fas fa-times"></i></button>
      </div>
      <div class="odp-modal-body">
        ${staffSections || '<p style="color:#9ca3af;text-align:center;padding:32px;">超過タスクはありません</p>'}
      </div>
    </div>`;

  document.body.appendChild(modal);

  // 閉じる：ボタン・オーバーレイクリック・Escape
  const close = () => modal.remove();
  document.getElementById('odp-close-btn').addEventListener('click', close);
  modal.addEventListener('click', e => { if (e.target === modal) close(); });
  const escHandler = e => { if (e.key === 'Escape') { close(); document.removeEventListener('keydown', escHandler); } };
  document.addEventListener('keydown', escHandler);
}


function _renderStaffTable(panel, staffName) {
  const q  = _taskSearchText.toLowerCase();
  const matchSearch = t =>
    !q || [t.title, t.store_name, t.handover, t.notes].some(v => v && v.toLowerCase().includes(q));
  const po = { '高': 0, '中': 1, '低': 2 };
  const byPriority = (a, b) => {
    const pd = (po[a.priority] ?? 1) - (po[b.priority] ?? 1);
    return pd || ((a.start_date || '') < (b.start_date || '') ? -1 : 1);
  };

  // ① 引継ぎタスク：自分が【依頼元】のタスクのみ（assignee===自分 && handover が他人に設定）
  //   ※ 依頼先（handover===自分）は引継ぎタスクではなくタスク管理に表示する
  let handoverTasks = _allTasks.filter(t =>
    matchSearch(t) &&
    t.assignee === staffName &&
    t.handover && t.handover !== staffName
  );
  handoverTasks.sort(byPriority);

  // ② タスク管理：以下のいずれかで未完了のタスク（PR管理・定期タスクを除く）
  //   (a) 自分が assignee で handover なし（または自分自身）
  //   (b) 他人が assignee で handover===自分（引継ぎを受けたタスク）
  let myTasks = _allTasks.filter(t =>
    t.progress !== '完了' &&
    (t.task_category || 'タスク管理') !== 'PR管理' &&
    (t.task_category || 'タスク管理') !== '定期タスク' &&
    matchSearch(t) && (
      // (a) 自分のタスク（引継ぎなし）
      (t.assignee === staffName && (!t.handover || t.handover === staffName)) ||
      // (b) 引継ぎを受けたタスク（他人が assignee, 自分が handover）
      (t.handover === staffName && t.assignee !== staffName)
    )
  );

  // ② 定期タスク管理：task_category === '定期タスク' のタスク（未完了）
  let recurTasks = _allTasks.filter(t =>
    t.progress !== '完了' &&
    t.task_category === '定期タスク' &&
    matchSearch(t) && (
      (t.assignee === staffName && (!t.handover || t.handover === staffName)) ||
      (t.handover === staffName && t.assignee !== staffName)
    )
  );

  // 定期タスク 完了タスク
  // 定期タスク 完了タスク（引継ぎ中のものは除外：高尾の引継ぎタスクテーブルで管理）
  let recurDoneTasks = _allTasks.filter(t =>
    t.assignee === staffName &&
    t.progress === '完了' &&
    t.task_category === '定期タスク' &&
    (!t.handover || t.handover === staffName) &&
    matchSearch(t)
  );
  recurDoneTasks.sort((a, b) => (b.updated_at || 0) - (a.updated_at || 0));

  // ② PR管理：task_category === 'PR管理' のタスク（未完了）
  let prTasks = _allTasks.filter(t =>
    t.progress !== '完了' &&
    t.task_category === 'PR管理' &&
    matchSearch(t) && (
      (t.assignee === staffName && (!t.handover || t.handover === staffName)) ||
      (t.handover === staffName && t.assignee !== staffName)
    )
  );

  // PR管理 完了タスク
  // PR管理 完了タスク（引継ぎ中のものは除外：引継ぎタスクテーブルで「確認・完了/差し戻し」待ち）
  let prDoneTasks = _allTasks.filter(t =>
    t.assignee === staffName &&
    t.progress === '完了' &&
    t.task_category === 'PR管理' &&
    (!t.handover || t.handover === staffName) &&
    matchSearch(t)
  );
  prDoneTasks.sort((a, b) => (b.updated_at || 0) - (a.updated_at || 0));
  if (_taskProgressFilter) myTasks = myTasks.filter(t => t.progress === _taskProgressFilter);
  if (_taskPriorityFilter)  myTasks = myTasks.filter(t => t.priority === _taskPriorityFilter);
  // ソート順：① 今日チェック最優先 → ② 優先度「高」（グループ内に高があればグループ全体を高扱い）→ ③ D&D手動順(sort_order) → ④ 完了予定日が今日 → ⑤ 優先度（中→低）→ ⑥ 店舗名昇順
  const PRIOR = { '高': 0, '中': 1, '低': 2 };
  const today0 = _todayStr(); // YYYY-MM-DD

  // グループ内に「高」が1つでもあれば、そのグループ全体の実効優先度を「高」とするマップを事前構築
  const _groupEffPriority = new Map(); // group_id → 実効優先度ランク（数値）
  myTasks.forEach(t => {
    if (!t.group_id) return;
    const cur = _groupEffPriority.get(t.group_id) ?? 99;
    const rank = PRIOR[t.priority] ?? 1;
    if (rank < cur) _groupEffPriority.set(t.group_id, rank);
  });
  // タスクの実効優先度ランクを返す（グループ行はグループ全体の最高優先度を使用）
  const _effPriorRank = t => {
    if (t.group_id && _groupEffPriority.has(t.group_id)) {
      return _groupEffPriority.get(t.group_id);
    }
    return PRIOR[t.priority] ?? 1;
  };

  myTasks.sort((a, b) => {
    // ★ ピン止め最優先
    const pinDiff = (b.is_pinned ? 1 : 0) - (a.is_pinned ? 1 : 0);
    if (pinDiff !== 0) return pinDiff;
    // ① 今日チェック：is_today=true を最優先
    const todayDiff = (b.is_today ? 1 : 0) - (a.is_today ? 1 : 0);
    if (todayDiff !== 0) return todayDiff;
    // ② 優先度「高」を最優先（グループ内に「高」があればグループ全体を「高」扱い）
    const priorA = _effPriorRank(a);
    const priorB = _effPriorRank(b);
    const isHighA = priorA === 0; // 「高」= rank 0
    const isHighB = priorB === 0;
    if (isHighA !== isHighB) return isHighA ? -1 : 1; // 「高」を上へ
    // ③ 完了予定日が今日のものを優先
    const aDueToday = (a.due_date === today0) ? 1 : 0;
    const bDueToday = (b.due_date === today0) ? 1 : 0;
    const dueTodayDiff = bDueToday - aDueToday;
    if (dueTodayDiff !== 0) return dueTodayDiff;
    // ④ 優先度（中 → 低）
    const priorDiff = priorA - priorB;
    if (priorDiff !== 0) return priorDiff;
    // ⑤ 店舗名昇順（null/undefined は末尾）
    const sA = a.store_name || '\uffff';
    const sB = b.store_name || '\uffff';
    const storeDiff = sA.localeCompare(sB, 'ja');
    if (storeDiff !== 0) return storeDiff;
    // ⑥ sort_order（D&D手動順）
    const hasA = a.sort_order != null, hasB = b.sort_order != null;
    if (hasA && hasB) return a.sort_order - b.sort_order;
    if (hasA) return -1;
    if (hasB) return  1;
    return 0;
  });

  // ── グループ化：同じ group_id を持つ行を代表行の直後にまとめる ──
  // 代表行（親）= group_id === t.id の行。代表行の位置を基準に子を直後へ集める。
  (() => {
    // group_id ごとに行をグループ化（出現順を保持）
    const groupMap = new Map(); // group_id → [tasks in order]
    const ungrouped = [];
    myTasks.forEach(t => {
      if (t.group_id) {
        if (!groupMap.has(t.group_id)) groupMap.set(t.group_id, []);
        groupMap.get(t.group_id).push(t);
      } else {
        ungrouped.push(t);
      }
    });
    if (groupMap.size === 0) return; // グループなし → 並び替え不要

    // ソート済み myTasks を走査し、各グループの代表行（最初に出現した行）位置に全メンバーをまとめる
    const result = [];
    const insertedGroups = new Set();
    myTasks.forEach(t => {
      if (!t.group_id) {
        result.push(t);
        return;
      }
      const gid = t.group_id;
      if (insertedGroups.has(gid)) return; // 既に挿入済みのグループはスキップ
      insertedGroups.add(gid);
      // 親（group_id === id）を先頭に、残りを後ろに並べてまとめて挿入
      const members = groupMap.get(gid) || [];
      const parent  = members.find(m => m.id === gid);
      const children = members.filter(m => m.id !== gid);
      if (parent) {
        result.push(parent, ...children);
      } else {
        result.push(...members); // 親が見当たらない場合はそのまま
      }
    });
    // myTasks を in-place 更新
    myTasks.length = 0;
    result.forEach(t => myTasks.push(t));
  })();

  // ③ 完了タスク：自分が assignee で完了（handover 問わず）、PR管理・定期タスクを除く
  let doneTasks = _allTasks.filter(t =>
    t.assignee === staffName &&
    t.progress === '完了' &&
    (t.task_category || 'タスク管理') !== 'PR管理' &&
    (t.task_category || 'タスク管理') !== '定期タスク' &&
    (!t.handover || t.handover === staffName) &&  // 引継ぎ中のものは除外
    matchSearch(t)
  );
  doneTasks.sort((a, b) => (b.updated_at || 0) - (a.updated_at || 0));

  // PR管理タスクのソート（myTasks と完全に同一のロジック）
  // ── PR グループ内に「高」があればグループ全体を「高」扱いするマップ ──
  const _prGroupEffPriority = new Map();
  prTasks.forEach(t => {
    if (!t.group_id) return;
    const cur  = _prGroupEffPriority.get(t.group_id) ?? 99;
    const rank = PRIOR[t.priority] ?? 1;
    if (rank < cur) _prGroupEffPriority.set(t.group_id, rank);
  });
  const _prEffPriorRank = t => {
    if (t.group_id && _prGroupEffPriority.has(t.group_id)) {
      return _prGroupEffPriority.get(t.group_id);
    }
    return PRIOR[t.priority] ?? 1;
  };

  prTasks.sort((a, b) => {
    // ★ ピン止め最優先
    const pinDiff = (b.is_pinned ? 1 : 0) - (a.is_pinned ? 1 : 0);
    if (pinDiff !== 0) return pinDiff;
    // ① 今日チェック最優先
    const todayDiff = (b.is_today ? 1 : 0) - (a.is_today ? 1 : 0);
    if (todayDiff !== 0) return todayDiff;
    // ② 優先度「高」を最優先（グループ全体の最高優先度を使用）
    const priorA = _prEffPriorRank(a);
    const priorB = _prEffPriorRank(b);
    const isHighA = priorA === 0;
    const isHighB = priorB === 0;
    if (isHighA !== isHighB) return isHighA ? -1 : 1;
    // ③ 完了予定日が今日のものを優先
    const aDueToday = (a.due_date === today0) ? 1 : 0;
    const bDueToday = (b.due_date === today0) ? 1 : 0;
    const dueTodayDiff = bDueToday - aDueToday;
    if (dueTodayDiff !== 0) return dueTodayDiff;
    // ④ 優先度（中 → 低）
    const priorDiff = priorA - priorB;
    if (priorDiff !== 0) return priorDiff;
    // ⑤ 店舗名昇順（null/undefined は末尾）
    const sA = a.store_name || '\uffff';
    const sB = b.store_name || '\uffff';
    const storeDiff = sA.localeCompare(sB, 'ja');
    if (storeDiff !== 0) return storeDiff;
    // ⑥ sort_order（D&D手動順）
    const hasA = a.sort_order != null, hasB = b.sort_order != null;
    if (hasA && hasB) return a.sort_order - b.sort_order;
    if (hasA) return -1;
    if (hasB) return  1;
    return 0;
  });

  // ── PR管理グループ化：同じ group_id を持つ行を代表行の直後にまとめる ──
  (() => {
    const groupMap = new Map();
    const ungrouped = [];
    prTasks.forEach(t => {
      if (t.group_id) {
        if (!groupMap.has(t.group_id)) groupMap.set(t.group_id, []);
        groupMap.get(t.group_id).push(t);
      } else {
        ungrouped.push(t);
      }
    });
    if (groupMap.size === 0) return;
    const result = [];
    const insertedGroups = new Set();
    prTasks.forEach(t => {
      if (!t.group_id) { result.push(t); return; }
      const gid = t.group_id;
      if (insertedGroups.has(gid)) return;
      insertedGroups.add(gid);
      const members = groupMap.get(gid) || [];
      const parent  = members.find(m => m.id === gid);
      const children = members.filter(m => m.id !== gid);
      if (parent) result.push(parent, ...children);
      else result.push(...members);
    });
    prTasks.length = 0;
    result.forEach(t => prTasks.push(t));
  })();

  // ── 定期タスクのソート・グループ化（myTasks / prTasks と完全同一ロジック）──
  const _recurGroupEffPriority = new Map();
  recurTasks.forEach(t => {
    if (!t.group_id) return;
    const cur  = _recurGroupEffPriority.get(t.group_id) ?? 99;
    const rank = PRIOR[t.priority] ?? 1;
    if (rank < cur) _recurGroupEffPriority.set(t.group_id, rank);
  });
  const _recurEffPriorRank = t => {
    if (t.group_id && _recurGroupEffPriority.has(t.group_id)) return _recurGroupEffPriority.get(t.group_id);
    return PRIOR[t.priority] ?? 1;
  };
  recurTasks.sort((a, b) => {
    // ★ ピン止め最優先
    const pinDiff = (b.is_pinned ? 1 : 0) - (a.is_pinned ? 1 : 0);
    if (pinDiff !== 0) return pinDiff;
    const todayDiff = (b.is_today ? 1 : 0) - (a.is_today ? 1 : 0);
    if (todayDiff !== 0) return todayDiff;
    const priorA = _recurEffPriorRank(a), priorB = _recurEffPriorRank(b);
    const isHighA = priorA === 0, isHighB = priorB === 0;
    if (isHighA !== isHighB) return isHighA ? -1 : 1;
    const aDueToday = (a.due_date === today0) ? 1 : 0;
    const bDueToday = (b.due_date === today0) ? 1 : 0;
    const dueTodayDiff = bDueToday - aDueToday;
    if (dueTodayDiff !== 0) return dueTodayDiff;
    const priorDiff = priorA - priorB;
    if (priorDiff !== 0) return priorDiff;
    const sA = a.store_name || '\uffff', sB = b.store_name || '\uffff';
    const storeDiff = sA.localeCompare(sB, 'ja');
    if (storeDiff !== 0) return storeDiff;
    const hasA = a.sort_order != null, hasB = b.sort_order != null;
    if (hasA && hasB) return a.sort_order - b.sort_order;
    if (hasA) return -1; if (hasB) return 1;
    return 0;
  });
  (() => {
    const groupMap = new Map();
    recurTasks.forEach(t => {
      if (t.group_id) {
        if (!groupMap.has(t.group_id)) groupMap.set(t.group_id, []);
        groupMap.get(t.group_id).push(t);
      }
    });
    if (groupMap.size === 0) return;
    const result = [];
    const insertedGroups = new Set();
    recurTasks.forEach(t => {
      if (!t.group_id) { result.push(t); return; }
      const gid = t.group_id;
      if (insertedGroups.has(gid)) return;
      insertedGroups.add(gid);
      const members = groupMap.get(gid) || [];
      const parent  = members.find(m => m.id === gid);
      const children = members.filter(m => m.id !== gid);
      if (parent) result.push(parent, ...children);
      else result.push(...members);
    });
    recurTasks.length = 0;
    result.forEach(t => recurTasks.push(t));
  })();

  const { todayH, taskTodayH, schedTodayH, prTaskTodayH, estH, limit: staffLimit } = _calcStaffHours(staffName);
  const remainH       = Math.max(0, estH - todayH);

  // ── 月間稼働計算 ──────────────────────────────────────────
  // 今月の土日を除く営業日数を計算
  const _countWorkdays = () => {
    const now = new Date();
    const y = now.getFullYear(), m = now.getMonth();
    const lastDay = new Date(y, m + 1, 0).getDate();
    let cnt = 0;
    for (let d = 1; d <= lastDay; d++) {
      const dow = new Date(y, m, d).getDay();
      if (dow !== 0 && dow !== 6) cnt++;
    }
    return cnt;
  };
  const workdays        = _countWorkdays();
  const monthlyCapacity = staffLimit * workdays;          // 月間想定稼働時間
  const monthlyEstH     = _allTasks
    .filter(t => t.assignee === staffName && t.progress !== '完了')
    .reduce((s, t) => s + (parseFloat(t.estimated_hours) || 0), 0);
  const monthlyPct      = monthlyCapacity > 0 ? Math.round(monthlyEstH / monthlyCapacity * 100) : 0;

  const nearThreshold = staffLimit * 0.75;
  const isOverwork    = todayH > staffLimit;          // ぴったりはオーバーではない
  const isNearOver    = todayH >= nearThreshold && todayH <= staffLimit;
  const todayPct      = staffLimit > 0 ? Math.round(todayH / staffLimit * 100) : 0;

  const active = _allTasks.filter(t => t.progress !== '完了');
  const myOpen = active.filter(t => t.assignee === staffName).length;

  const sid = _staffId(staffName);

  const timeSummaryHTML = `
    <div class="task-time-summary-bar">
      <div class="task-time-summary-chip task-time-summary-chip--today">
        <div class="task-time-chip-num">${todayH.toFixed(1)}<span style="font-size:13px;font-weight:500;">h</span></div>
        <div class="task-time-chip-lbl">今日の作業時間</div>
        <div class="task-time-chip-sub">タスク ${(taskTodayH - prTaskTodayH).toFixed(1)}h + PR ${prTaskTodayH.toFixed(1)}h + スケジュール ${schedTodayH.toFixed(1)}h</div>
      </div>
      <div class="task-time-summary-chip task-time-summary-chip--est">
        <div class="task-time-chip-num">${estH.toFixed(1)}<span style="font-size:13px;font-weight:500;">h</span></div>
        <div class="task-time-chip-lbl">未完了タスク 予測合計</div>
      </div>
      <div class="task-time-summary-chip task-time-summary-chip--remain">
        <div class="task-time-chip-num">${remainH.toFixed(1)}<span style="font-size:13px;font-weight:500;">h</span></div>
        <div class="task-time-chip-lbl">残予測時間</div>
      </div>
      <div class="task-time-summary-chip ${isOverwork ? 'task-time-summary-chip--overwork' : ''}" style="${isOverwork ? '' : 'border-color:var(--gray-200);background:#fff;'}">
        <div class="task-time-chip-num" style="${isOverwork ? '' : 'color:var(--gray-700);'}">${staffLimit}<span style="font-size:13px;font-weight:500;">h</span></div>
        <div class="task-time-chip-lbl">想定稼働時間</div>
      </div>
    </div>`;

  // ── 今日アラートバナー ───────────────────────────────────
  let warnBannerHTML = '';
  if (isOverwork) {
    const overPct = todayPct - 100;
    const isCritical = todayPct >= 150;
    warnBannerHTML = `
      <div class="task-alert-banner task-alert-banner--today task-alert-banner--${isCritical ? 'critical' : 'over'}">
        <div class="task-alert-icon"><i class="fas fa-exclamation-triangle"></i></div>
        <div class="task-alert-body">
          <div class="task-alert-title">⚠️ 今日の稼働時間 オーバー</div>
          <div class="task-alert-detail">
            今日の作業時間 <strong>${todayH.toFixed(1)}h</strong>（タスク ${taskTodayH.toFixed(1)}h + スケジュール ${schedTodayH.toFixed(1)}h）が
            想定稼働時間 <strong>${staffLimit}h</strong> を <strong>${(todayH - staffLimit).toFixed(1)}h 超過</strong> しています。
            ${isCritical ? '<br>深刻なオーバーワーク状態です。タスクの再分配を検討してください。' : '<br>タスクの分散や優先度の見直しを推奨します。'}
          </div>
        </div>
      </div>`;
  } else if (isNearOver) {
    warnBannerHTML = `
      <div class="task-alert-banner task-alert-banner--today task-alert-banner--warn">
        <div class="task-alert-icon"><i class="fas fa-clock"></i></div>
        <div class="task-alert-body">
          <div class="task-alert-title">今日の稼働時間 注意</div>
          <div class="task-alert-detail">
            今日の作業時間 <strong>${todayH.toFixed(1)}h</strong>（タスク ${taskTodayH.toFixed(1)}h + スケジュール ${schedTodayH.toFixed(1)}h）が
            想定稼働時間（${staffLimit}h）の 75% に達しています。
          </div>
        </div>
      </div>`;
  }

  // ── 月間アラートバナー ───────────────────────────────────
  let monthlyBannerHTML = '';
  if (monthlyPct > 100) {
    // 他スタッフの月間負荷を計算して余裕のあるスタッフを列挙
    const staffList = _activeAccounts().filter(a => a.name !== staffName);
    const lightStaff = staffList.map(a => {
      const aEstH    = _allTasks.filter(t => t.assignee === a.name && t.progress !== '完了')
                                .reduce((s, t) => s + (parseFloat(t.estimated_hours) || 0), 0);
      const aCap     = _staffHourLimit(a.name) * workdays;
      const aPct     = aCap > 0 ? Math.round(aEstH / aCap * 100) : 0;
      return { name: a.name, pct: aPct };
    }).filter(a => a.pct < 80).sort((a, b) => a.pct - b.pct);

    const lightNames = lightStaff.slice(0, 3).map(a =>
      `<strong>${escHtml(a.name)}</strong>（${a.pct}%）`).join('、');
    const isCritical = monthlyPct >= 150;

    monthlyBannerHTML = `
      <div class="task-alert-banner task-alert-banner--monthly task-alert-banner--${isCritical ? 'critical' : 'over'}">
        <div class="task-alert-icon"><i class="fas fa-calendar-alt"></i></div>
        <div class="task-alert-body">
          <div class="task-alert-title">📅 月間稼働 オーバー（${monthlyPct}%）</div>
          <div class="task-alert-detail">
            未完了タスク予測時間の合計 <strong>${monthlyEstH.toFixed(1)}h</strong> が
            月間想定稼働時間 <strong>${monthlyCapacity}h</strong>（${staffLimit}h × ${workdays}日）を超過しています。
            ${lightNames ? `<br>タスクを ${lightNames} へ振り分けることを推奨します。` : '<br>他のスタッフへのタスク振り分けを検討してください。'}
          </div>
        </div>
        <div class="task-alert-pct task-alert-pct--over">${monthlyPct}%</div>
      </div>`;
  }

  // 集中警告バナーは非表示（削除）
  let concBannerHTML = '';

  panel.innerHTML = `
    ${timeSummaryHTML}
    ${warnBannerHTML}
    ${monthlyBannerHTML}
    ${concBannerHTML}

    <!-- スケジュール + カレンダー 2カラム -->
    <div class="staff-sch-cal-row">
      <section class="task-section task-section--schedule staff-sch-col" id="sch-section-${sid}">
        <div class="task-section-header">
          <h3 class="task-section-title">
            <i class="fas fa-calendar-day"></i> 今日のスケジュール
            <span class="sch-today-date">${(() => { const d = new Date(); return `${d.getFullYear()}/${String(d.getMonth()+1).padStart(2,'0')}/${String(d.getDate()).padStart(2,'0')}`; })()}</span>
          </h3>
          <p class="task-section-desc">開始・終了時間を入力すると作業時間を自動計算します。</p>
        </div>
        <div id="sch-container-${sid}">
          ${_buildScheduleSection(staffName, sid)}
        </div>
      </section>
      <div class="staff-cal-col">
        ${_buildStaffCalendarSection(staffName, sid)}
      </div>
    </div>

    <section class="task-section task-section--handover">
      <div class="task-section-header">
        <h3 class="task-section-title task-section-title--handover">
          <i class="fas fa-share"></i> 引継ぎタスク
          ${handoverTasks.length > 0 ? `<span class="task-section-badge">${handoverTasks.length}</span>` : ''}
        </h3>
        <p class="task-section-desc">引継者が設定されているタスクです。引継者を指定するとここに移動します。</p>
      </div>
      <div class="task-inline-wrap">
        ${handoverTasks.length > 0
          ? _buildHandoverTable(handoverTasks, staffName, sid)
          : `<div class="task-section-empty"><i class="fas fa-inbox"></i> 引継者が設定されたタスクはここに表示されます</div>`
        }
      </div>
    </section>

    <!-- ═══════════════════════════════════════════════════════
         定期タスク管理テーブル（タスク管理の上）
    ════════════════════════════════════════════════════════ -->
    <section class="task-section task-section--recur" id="recur-section-${sid}">
      <div class="task-section-header">
        <h3 class="task-section-title task-section-title--recur">
          <i class="fas fa-sync-alt"></i> 定期タスク管理
          <span class="task-section-badge task-section-badge--recur">${recurTasks.length}</span>
        </h3>
        <p class="task-section-desc">管理区分を「定期タスク」に設定したタスクがここに表示されます。</p>
      </div>
      <div class="task-inline-wrap" id="recur-inline-wrap-${sid}">
        ${_buildInlineTaskTable(recurTasks, staffName, '定期タスク')}
      </div>
    </section>

    <section class="task-section task-section--main">
      <div class="task-section-header">
        <h3 class="task-section-title task-section-title--main">
          <i class="fas fa-tasks"></i> タスク管理
          <span class="task-section-badge">${myTasks.length}</span>
        </h3>
        <div class="task-table-filters" style="margin-top:8px;">
          <select id="task-progress-filter-${sid}" class="task-filter-select">
            <option value="">進捗：すべて</option>
            <option value="未着手">未着手</option>
            <option value="進行中">進行中</option>
            <option value="確認待ち">確認待ち</option>
          </select>
          <select id="task-priority-filter-${sid}" class="task-filter-select">
            <option value="">優先度：すべて</option>
            <option value="高">高</option>
            <option value="中">中</option>
            <option value="低">低</option>
          </select>
          <input type="text" id="task-search-${sid}" class="task-search-input"
            placeholder="🔍 タスク名・店舗名で検索" value="${escHtml(_taskSearchText)}">
          <button id="task-cross-search-btn-${sid}" class="task-cross-search-btn${_taskSearchText ? ' has-query' : ''}" title="全スタッフから検索">
            <i class="fas fa-users"></i> 全スタッフ
          </button>
        </div>
      </div>
      <!-- 全スタッフ検索結果エリア（検索テキストがある場合のみ表示） -->
      <div id="task-cross-result-${sid}" class="task-cross-result" style="display:none;"></div>
      <div class="task-inline-wrap" id="task-inline-wrap-${sid}">
        ${_buildInlineTaskTable(myTasks, staffName)}
      </div>
    </section>

    <!-- ═══════════════════════════════════════════════════════
         PR管理テーブル
    ════════════════════════════════════════════════════════ -->
    <section class="task-section task-section--pr" id="pr-section-${sid}">
      <div class="task-section-header">
        <h3 class="task-section-title task-section-title--pr">
          <i class="fas fa-bullhorn"></i> PR管理
          <span class="task-section-badge task-section-badge--pr">${prTasks.length}</span>
        </h3>
        <p class="task-section-desc">管理区分を「PR管理」に設定したタスクがここに移動します。</p>
      </div>
      <div class="task-inline-wrap" id="pr-inline-wrap-${sid}">
        ${_buildInlineTaskTable(prTasks, staffName, 'PR管理')}
      </div>
    </section>

    <!-- PR管理 完了タスク保管庫 -->
    <section class="task-section task-section--pr-done" id="pr-done-section-${sid}">
      <div class="task-section-header task-section-header--done">
        <button class="arc-toggle-btn" id="pr-arc-toggle-${sid}" aria-expanded="false" aria-controls="pr-arc-body-${sid}">
          <span class="arc-toggle-icon"><i class="fas fa-chevron-right"></i></span>
          <span class="arc-toggle-label">
            <i class="fas fa-archive"></i>
            PR管理 完了保管庫
          </span>
          <span class="task-section-badge task-section-badge--done">${prDoneTasks.length}</span>
          <span class="arc-toggle-hint">${prDoneTasks.length === 0 ? '完了したPRタスクはまだありません' : `${prDoneTasks.length}件が保管されています`}</span>
        </button>
      </div>
      <div class="arc-body" id="pr-arc-body-${sid}" hidden>
        ${prDoneTasks.length > 0
          ? _buildDoneTable(prDoneTasks, sid + '-pr')
          : '<p class="task-section-empty"><i class="fas fa-inbox"></i> 完了したPRタスクはまだありません</p>'}
      </div>
    </section>

    <section class="task-section task-section--done" id="done-section-${sid}">
      <div class="task-section-header task-section-header--done">
        <button class="arc-toggle-btn" id="arc-toggle-${sid}" aria-expanded="false" aria-controls="arc-body-${sid}">
          <span class="arc-toggle-icon"><i class="fas fa-chevron-right"></i></span>
          <span class="arc-toggle-label">
            <i class="fas fa-archive"></i>
            完了タスク保管庫
          </span>
          <span class="task-section-badge task-section-badge--done">${doneTasks.length}</span>
          <span class="arc-toggle-hint">${doneTasks.length === 0 ? '完了タスクはまだありません' : `${doneTasks.length}件のタスクが保管されています`}</span>
        </button>
      </div>
      <div class="arc-body" id="arc-body-${sid}" hidden>
        ${doneTasks.length > 0
          ? _buildDoneTable(doneTasks, sid)
          : '<p class="task-section-empty"><i class="fas fa-inbox"></i> 完了したタスクはまだありません</p>'}
      </div>
    </section>

    <!-- 定期タスク 完了保管庫（一番下） -->
    <section class="task-section task-section--recur-done" id="recur-done-section-${sid}">
      <div class="task-section-header task-section-header--done">
        <button class="arc-toggle-btn" id="recur-arc-toggle-${sid}" aria-expanded="false" aria-controls="recur-arc-body-${sid}">
          <span class="arc-toggle-icon"><i class="fas fa-chevron-right"></i></span>
          <span class="arc-toggle-label">
            <i class="fas fa-archive"></i>
            定期タスク 完了保管庫
          </span>
          <span class="task-section-badge task-section-badge--done">${recurDoneTasks.length}</span>
          <span class="arc-toggle-hint">${recurDoneTasks.length === 0 ? '完了した定期タスクはまだありません' : `${recurDoneTasks.length}件が保管されています`}</span>
        </button>
      </div>
      <div class="arc-body" id="recur-arc-body-${sid}" hidden>
        ${recurDoneTasks.length > 0
          ? _buildDoneTable(recurDoneTasks, sid + '-recur')
          : '<p class="task-section-empty"><i class="fas fa-inbox"></i> 完了した定期タスクはまだありません</p>'}
      </div>
    </section>
`;

  // フィルターイベント
  const pfEl = panel.querySelector(`#task-progress-filter-${sid}`);
  const prEl = panel.querySelector(`#task-priority-filter-${sid}`);
  const srEl = panel.querySelector(`#task-search-${sid}`);
  const crossBtn  = panel.querySelector(`#task-cross-search-btn-${sid}`);
  const crossResult = panel.querySelector(`#task-cross-result-${sid}`);

  // ── 全スタッフ検索結果を描画するヘルパー ──
  const _renderCrossResult = q => {
    if (!crossResult) return;
    if (!q) { crossResult.style.display = 'none'; return; }
    const lq = q.toLowerCase();
    const matched = _allTasks.filter(t =>
      t.progress !== '完了' &&
      [t.title, t.store_name, t.handover, t.notes].some(v => v && v.toLowerCase().includes(lq))
    );
    if (matched.length === 0) {
      crossResult.style.display = 'none';
      return;
    }
    // スタッフ別グループ化
    const byStaff = new Map();
    matched.forEach(t => {
      const s = t.assignee || '（未割当）';
      if (!byStaff.has(s)) byStaff.set(s, []);
      byStaff.get(s).push(t);
    });
    const PRIOR_LABEL = { '高': '<span class="tpr-high">高</span>', '中': '<span class="tpr-mid">中</span>', '低': '<span class="tpr-low">低</span>' };
    let html = `<div class="cross-result-header"><i class="fas fa-users"></i> 全スタッフ検索結果 <span class="cross-result-count">${matched.length}件</span>
      <button class="cross-result-close" id="cross-close-${sid}" title="閉じる"><i class="fas fa-times"></i></button></div>
      <div class="cross-result-body">`;
    byStaff.forEach((tasks, staff) => {
      const isMine = staff === staffName;
      html += `<div class="cross-staff-group">
        <div class="cross-staff-label${isMine ? ' cross-staff-label--me' : ''}">
          <i class="fas fa-user"></i> ${escHtml(staff)}${isMine ? ' <span class="cross-me-badge">自分</span>' : ''}
          <span class="cross-staff-count">${tasks.length}件</span>
        </div>
        <table class="cross-result-table">
          <tbody>`;
      tasks.forEach(t => {
        const prHtml = PRIOR_LABEL[t.priority] || '—';
        const store  = t.store_name ? `<span class="cross-store">${escHtml(t.store_name)}</span>` : '';
        const due    = t.due_date   ? `<span class="cross-due">${escHtml(t.due_date)}</span>` : '';
        const prog   = t.progress   ? `<span class="cross-prog">${escHtml(t.progress)}</span>` : '';
        html += `<tr>
          <td class="cross-td-prior">${prHtml}</td>
          <td class="cross-td-title">${escHtml(t.title || '')}${store}</td>
          <td class="cross-td-meta">${prog}${due}</td>
        </tr>`;
      });
      html += `</tbody></table></div>`;
    });
    html += `</div>`;
    crossResult.innerHTML = html;
    crossResult.style.display = '';
    // 閉じるボタン
    crossResult.querySelector(`#cross-close-${sid}`)?.addEventListener('click', () => {
      crossResult.style.display = 'none';
    });
  };

  if (pfEl) { pfEl.value = _taskProgressFilter; pfEl.addEventListener('change', e => { _taskProgressFilter = e.target.value; _renderStaffTable(panel, staffName); }); }
  if (prEl) { prEl.value = _taskPriorityFilter;  prEl.addEventListener('change', e => { _taskPriorityFilter = e.target.value;  _renderStaffTable(panel, staffName); }); }
  if (srEl) {
    // input イベントではパネル全体を再描画せず、タスクテーブル部分だけを差し替える
    srEl.addEventListener('input', e => {
      _taskSearchText = e.target.value;
      // 全スタッフ検索ボタンの活性/非活性
      if (crossBtn) crossBtn.classList.toggle('has-query', !!_taskSearchText);
      // 全スタッフ検索結果が表示中なら即時更新
      if (crossResult && crossResult.style.display !== 'none') {
        _renderCrossResult(_taskSearchText);
      }
      const wrap = panel.querySelector(`#task-inline-wrap-${sid}`);
      if (wrap) {
        const _q = _taskSearchText.toLowerCase();
        const _matchSearch = t =>
          !_q || [t.title, t.store_name, t.handover, t.notes].some(v => v && v.toLowerCase().includes(_q));
        let _filtered = _allTasks.filter(t =>
          t.progress !== '完了' && _matchSearch(t) && (
            (t.assignee === staffName && (!t.handover || t.handover === staffName)) ||
            (t.handover === staffName && t.assignee !== staffName)
          )
        );
        if (_taskProgressFilter) _filtered = _filtered.filter(t => t.progress === _taskProgressFilter);
        if (_taskPriorityFilter)  _filtered = _filtered.filter(t => t.priority === _taskPriorityFilter);
        wrap.innerHTML = _buildInlineTaskTable(_filtered, staffName);
        _bindInlineTableEvents(panel, staffName);
        const badge = panel.querySelector('.task-section--main .task-section-badge');
        if (badge) badge.textContent = _filtered.length;
      }
    });
  }

  // 「全スタッフ」ボタン：クリックで全スタッフ検索結果をトグル表示
  if (crossBtn) {
    crossBtn.addEventListener('click', () => {
      if (crossResult && crossResult.style.display !== 'none') {
        crossResult.style.display = 'none';
      } else {
        _renderCrossResult(_taskSearchText);
      }
    });
  }

  _bindInlineTableEvents(panel, staffName);
  _bindHandoverTableEvents(panel, staffName);
  _bindDoneTableEvents(panel, staffName);
  _bindScheduleEvents(panel, staffName, sid);

  // ── 初回表示時：デフォルトスケジュールを自動登録 ──────────────
  (async () => {
    const today = _todayStr();
    const added = await _ensureDefaultSchedule(staffName, today);
    if (added) {
      // 登録できたのでキャッシュ更新＋テーブル再描画
      try {
        const res = await API.getAll('schedules');
        _allSchedules = (Array.isArray(res.data) ? res.data : (Array.isArray(res) ? res : []))
          .filter(s => s.deleted !== true);
      } catch(e) { console.warn('[sch] initial default reload failed', e); }
      const tbody = document.getElementById(`sch-tbody-${sid}`);
      if (tbody) {
        const rows = _allSchedules
          .filter(s => s.assignee === staffName && _schIsToday(s, today))
          .sort((a, b) => (a.start_time || '').localeCompare(b.start_time || ''));
        tbody.innerHTML = rows.slice(0, 5).map(_schRowHtml).join('');
        _schRefreshTotal(sid, staffName);
      }
    }
  })();

  // ── 定期タスクテーブル イベントバインド ──
  const recurWrap = panel.querySelector(`#recur-inline-wrap-${sid}`);
  if (recurWrap) {
    _bindInlineTableEvents(panel, staffName, 'recur');
  }

  // ── PR管理テーブル イベントバインド ──
  const prWrap = panel.querySelector(`#pr-inline-wrap-${sid}`);
  if (prWrap) {
    _bindInlineTableEvents(panel, staffName, 'pr');
  }

}

// ══════════════════════════════════════════════════════════════
//  今日のスケジュール
// ══════════════════════════════════════════════════════════════

/** 時刻文字列（HH:MM）→ 分 */
function _schTimeToMin(t) {
  if (!t) return null;
  const [h, m] = t.split(':').map(Number);
  if (isNaN(h) || isNaN(m)) return null;
  return h * 60 + m;
}

/** "1100" / "11:0" / 全角 → "HH:MM" に正規化。不正なら '' */
function _schNormalizeTime(val) {
  if (!val) return '';
  let s = val
    .replace(/[０-９]/g, c => String.fromCharCode(c.charCodeAt(0) - 0xFEE0))
    .replace(/[：]/g, ':')
    .trim();
  if (/^\d{3,4}$/.test(s)) {
    s = s.length === 3 ? '0' + s : s;
    s = s.slice(0, 2) + ':' + s.slice(2);
  }
  const m = s.match(/^(\d{1,2}):(\d{1,2})$/);
  if (m) s = m[1].padStart(2, '0') + ':' + m[2].padStart(2, '0');
  const [hh, mm] = s.split(':').map(Number);
  if (isNaN(hh) || isNaN(mm) || hh > 23 || mm > 59) return '';
  return s;
}

/** HH:MM × 2 → 所要時間(h)。0.1h単位。無効なら 0 */
function _schCalcDuration(st, et) {
  const s = _schTimeToMin(st), e = _schTimeToMin(et);
  if (s == null || e == null || e <= s) return 0;
  return Math.round((e - s) / 60 * 10) / 10;
}

/** スケジュールテーブルの <tbody> 行 HTML */
function _schRowHtml(r) {
  const dur = r.duration_hours != null ? parseFloat(r.duration_hours) : 0;
  const durTxt = dur > 0 ? dur.toFixed(1) : '—';
  return `<tr class="sch-row" data-id="${escHtml(r.id)}">
    <td class="sch-cell sch-cell--title">
      <input class="sch-inp" data-field="title" type="text" value="${escHtml(r.title||'')}" placeholder="予定名">
    </td>
    <td class="sch-cell sch-cell--time">
      <input class="sch-inp sch-inp--time" data-field="start_time" type="text" value="${escHtml(r.start_time||'')}" placeholder="11:00" maxlength="5">
    </td>
    <td class="sch-cell sch-cell--time">
      <input class="sch-inp sch-inp--time" data-field="end_time" type="text" value="${escHtml(r.end_time||'')}" placeholder="12:00" maxlength="5">
    </td>
    <td class="sch-cell sch-cell--dur">
      <span class="sch-dur${dur > 0 ? '' : ' sch-dur--zero'}">${durTxt}</span>
    </td>
    <td class="sch-cell sch-cell--notes">
      <input class="sch-inp" data-field="notes" type="text" value="${escHtml(r.notes||'')}" placeholder="メモ">
    </td>
    <td class="sch-cell sch-cell--created">${(() => {
      if (!r.created_at) return '—';
      const d = new Date(r.created_at);
      return (d.getMonth()+1) + '/' + String(d.getDate()).padStart(2,'0') + ' ' + String(d.getHours()).padStart(2,'0') + ':' + String(d.getMinutes()).padStart(2,'0');
    })()}</td>
    <td class="sch-cell sch-cell--save">
      <button class="sch-btn sch-btn--save" data-id="${escHtml(r.id)}"><i class="fas fa-check"></i> 保存</button>
    </td>
    <td class="sch-cell sch-cell--del">
      <button class="sch-btn sch-btn--del" data-id="${escHtml(r.id)}"><i class="fas fa-trash"></i> 削除</button>
    </td>
  </tr>`;
}

/** 合計時間・サマリーバー・アラートバナーを再描画 */
function _schRefreshTotal(sid, staffName) {
  const today = _todayStr();
  // ── スケジュール合計欄 ──
  const total = _allSchedules
    .filter(s => s.assignee === staffName && _schIsToday(s, today))
    .reduce((acc, s) => acc + (parseFloat(s.duration_hours) || 0), 0);
  const elTotal = document.getElementById(`sch-total-${sid}`);
  if (elTotal) elTotal.innerHTML = `合計 <strong>${total.toFixed(1)}h</strong>`;

  // ── 最新の時間集計を取得 ──
  const { todayH, taskTodayH, schedTodayH, prTaskTodayH, estH, limit: staffLimit } = _calcStaffHours(staffName);
  const remainH      = Math.max(0, estH - todayH);
  const nearThreshold = staffLimit * 0.75;
  const isOverwork    = todayH > staffLimit;          // ぴったりはオーバーではない
  const isNearOver    = todayH >= nearThreshold && todayH <= staffLimit;
  const todayPct      = staffLimit > 0 ? Math.round(todayH / staffLimit * 100) : 0;

  const panel = document.getElementById(`task-panel-${sid}`);
  if (!panel) return;

  // ── 時間サマリーバーを差し替え ──
  const bar = panel.querySelector('.task-time-summary-bar');
  if (bar) {
    bar.querySelector('.task-time-summary-chip--today .task-time-chip-num').innerHTML =
      `${todayH.toFixed(1)}<span style="font-size:13px;font-weight:500;">h</span>`;
    bar.querySelector('.task-time-summary-chip--today .task-time-chip-sub').textContent =
      `タスク ${taskTodayH.toFixed(1)}h + スケジュール ${schedTodayH.toFixed(1)}h`;
    bar.querySelector('.task-time-summary-chip--remain .task-time-chip-num').innerHTML =
      `${remainH.toFixed(1)}<span style="font-size:13px;font-weight:500;">h</span>`;
    // 想定稼働チップの overwork クラスも更新
    const limitChip = bar.querySelectorAll('.task-time-summary-chip')[3];
    if (limitChip) {
      limitChip.className = `task-time-summary-chip${isOverwork ? ' task-time-summary-chip--overwork' : ''}`;
      limitChip.style.cssText = isOverwork ? '' : 'border-color:var(--gray-200);background:#fff;';
      const limitNum = limitChip.querySelector('.task-time-chip-num');
      if (limitNum) limitNum.style.cssText = isOverwork ? '' : 'color:var(--gray-700);';
    }
  }

  // ── アラートバナーを再生成 ──
  let warnHTML = '';
  if (isOverwork) {
    const overPct  = todayPct - 100;
    const isCrit   = todayPct >= 150;
    warnHTML = `
      <div class="task-alert-banner task-alert-banner--today task-alert-banner--${isCrit ? 'critical' : 'over'}">
        <div class="task-alert-icon"><i class="fas fa-exclamation-triangle"></i></div>
        <div class="task-alert-body">
          <div class="task-alert-title">⚠️ 今日の稼働時間 オーバー</div>
          <div class="task-alert-detail">
            今日の作業時間 <strong>${todayH.toFixed(1)}h</strong>（タスク ${taskTodayH.toFixed(1)}h + スケジュール ${schedTodayH.toFixed(1)}h）が
            想定稼働時間 <strong>${staffLimit}h</strong> を <strong>${(todayH - staffLimit).toFixed(1)}h 超過</strong> しています。
            ${isCrit ? '<br>深刻なオーバーワーク状態です。タスクの再分配を検討してください。' : '<br>タスクの分散や優先度の見直しを推奨します。'}
          </div>
        </div>
      </div>`;
  } else if (isNearOver) {
    warnHTML = `
      <div class="task-alert-banner task-alert-banner--today task-alert-banner--warn">
        <div class="task-alert-icon"><i class="fas fa-clock"></i></div>
        <div class="task-alert-body">
          <div class="task-alert-title">今日の稼働時間 注意</div>
          <div class="task-alert-detail">
            今日の作業時間 <strong>${todayH.toFixed(1)}h</strong>（タスク ${taskTodayH.toFixed(1)}h + スケジュール ${schedTodayH.toFixed(1)}h）が
            想定稼働時間（${staffLimit}h）の 75% に達しています。
          </div>
        </div>
      </div>`;
  }
  // 既存のアラートバナーを差し替え（なければ挿入、あれば更新、0件なら削除）
  let existBanner = panel.querySelector('.task-alert-banner--today');
  if (warnHTML) {
    const tmp = document.createElement('div');
    tmp.innerHTML = warnHTML.trim();
    const newBanner = tmp.firstElementChild;
    if (existBanner) {
      existBanner.replaceWith(newBanner);
    } else {
      // サマリーバーの直後に挿入
      const bar2 = panel.querySelector('.task-time-summary-bar');
      if (bar2) bar2.after(newBanner);
    }
  } else {
    if (existBanner) existBanner.remove();
  }
}

/** API再取得 → tbody再描画 */
async function _schReload(sid, staffName) {
  try {
    const res = await API.get('schedules', { limit: 500 });
    const rows = Array.isArray(res.data) ? res.data : (Array.isArray(res) ? res : []);
    _allSchedules = rows.filter(s => s.deleted !== true);
    console.log('[sch] reload: 取得', rows.length, '件 → 有効', _allSchedules.length, '件');
  } catch(e) { console.warn('[sch] reload failed', e); }

  const today = _todayStr();
  // ※ ここでは _ensureDefaultSchedule を呼ばない
  //    → 手動削除後は復活しない（クリアボタン経由のみ復活）

  const tbody = document.getElementById(`sch-tbody-${sid}`);
  if (tbody) {
    const rows = _allSchedules
      .filter(s => s.assignee === staffName && _schIsToday(s, today))
      .sort((a, b) => (a.start_time || '').localeCompare(b.start_time || ''));
    const SCH_VISIBLE = 5;
    const visibleRows = rows.slice(0, SCH_VISIBLE);
    const hiddenRows  = rows.slice(SCH_VISIBLE);
    tbody.innerHTML = visibleRows.map(_schRowHtml).join('');

    // 「もっと見る」tbody 更新
    let tbodyMore = document.getElementById(`sch-tbody-more-${sid}`);
    const moreWrap = document.getElementById(`sch-more-wrap-${sid}`);
    const moreBtn  = document.getElementById(`sch-btn-more-${sid}`);

    if (hiddenRows.length > 0) {
      if (!tbodyMore) {
        // 存在しなければ tbody の直後に追加
        tbodyMore = document.createElement('tbody');
        tbodyMore.className = 'sch-tbody--hidden';
        tbodyMore.id = `sch-tbody-more-${sid}`;
        tbody.after(tbodyMore);
      }
      // expanded 状態を維持する
      const isExpanded = moreBtn?.dataset.expanded === 'true';
      tbodyMore.innerHTML = hiddenRows.map(_schRowHtml).join('');
      tbodyMore.style.display = isExpanded ? '' : 'none';

      if (moreWrap) {
        moreWrap.style.display = '';
        if (moreBtn && !isExpanded) {
          moreBtn.innerHTML = `<i class="fas fa-chevron-down"></i> もっと見る（残り ${hiddenRows.length} 件）`;
        }
      } else {
        // moreWrap が無ければ挿入
        const table = tbody.closest('table');
        if (table) {
          const wrap = document.createElement('div');
          wrap.className = 'sch-more-wrap';
          wrap.id = `sch-more-wrap-${sid}`;
          wrap.innerHTML = `<button class="sch-btn-more" id="sch-btn-more-${sid}" data-expanded="false">
            <i class="fas fa-chevron-down"></i> もっと見る（残り ${hiddenRows.length} 件）
          </button>`;
          table.after(wrap);
          // 新しく追加したボタンにイベントバインド
          _bindSchMoreBtn(wrap.querySelector(`#sch-btn-more-${sid}`), sid);
        }
      }
    } else {
      // 隠し行なし → もっと見る非表示・tbody削除
      if (tbodyMore) tbodyMore.innerHTML = '';
      if (moreWrap) moreWrap.style.display = 'none';
    }
  }
  _schRefreshTotal(sid, staffName);
}

/** スケジュールセクション HTML生成（初期描画・再描画共用） */
// ── デフォルトスケジュール設定 ────────────────────────────────
const DEFAULT_SCHEDULE = {
  title:          'タスク確認・朝礼',
  start_time:     '09:00',
  end_time:       '10:00',
  duration_hours: 1,
  notes:          null,
  is_default:     true,
  is_recurring:   false,
  recur_days:     [],
  deleted:        false,
};

/**
 * 指定スタッフの今日のスケジュールにデフォルトレコードがなければ登録する。
 * - is_default===true のレコードが今日分に1件以上あれば何もしない
 * - 手動削除（deleted===true）されているものはカウントしない
 * @param {string} staffName
 * @param {string} today  YYYY-MM-DD
 * @returns {Promise<boolean>} 新規登録した場合 true
 */
async function _ensureDefaultSchedule(staffName, today) {
  // 並行実行防止：同一スタッフで既に実行中なら結果を待つ
  const key = `${staffName}__${today}`;
  if (_ensuringDefault[key]) {
    return await _ensuringDefault[key];
  }

  // 今日のデフォルトレコードが既にあるか確認（削除済み除外）
  const exists = _allSchedules.some(
    s => s.assignee === staffName
      && _schIsToday(s, today)
      && s.is_default === true
  );
  if (exists) return false;

  // なければ登録（DB側にも今日分がないか先確認してから POST）
  const promise = (async () => {
    try {
      // DB を直接確認（_allSchedules が不完全な場合の二重POST防止）
      const checkRes = await API.get('schedules', {
        search: staffName,
        limit: 10,
      });
      const dbRows = Array.isArray(checkRes.data) ? checkRes.data : (Array.isArray(checkRes) ? checkRes : []);
      const dbExists = dbRows.some(
        s => s.assignee === staffName
          && _schIsToday(s, today)
          && s.is_default === true
          && s.deleted !== true
      );
      if (dbExists) {
        // DBには既に存在 → キャッシュを更新して終了
        const refreshRes = await API.getAll('schedules');
        _allSchedules = (Array.isArray(refreshRes.data) ? refreshRes.data : (Array.isArray(refreshRes) ? refreshRes : []))
          .filter(s => s.deleted !== true);
        return false;
      }
      await API.post('schedules', {
        assignee: staffName,
        date:     today,
        ...DEFAULT_SCHEDULE,
      });
      return true;
    } catch(e) {
      console.warn('[sch] default schedule POST failed', e);
      return false;
    } finally {
      delete _ensuringDefault[key];
    }
  })();

  _ensuringDefault[key] = promise;
  return await promise;
}

function _buildScheduleSection(staffName, sid) {
  const today = _todayStr();
  const rows = _allSchedules
    .filter(s => s.assignee === staffName && _schIsToday(s, today))
    .sort((a, b) => (a.start_time || '').localeCompare(b.start_time || ''));
  const totalH = rows.reduce((acc, r) => acc + (parseFloat(r.duration_hours) || 0), 0);

  const SCH_VISIBLE = 5; // 折りたたみ前の表示件数
  const visibleRows = rows.slice(0, SCH_VISIBLE);
  const hiddenRows  = rows.slice(SCH_VISIBLE);
  const hasMore = hiddenRows.length > 0;

  // メモの初期値を _allAccounts から取得
  const acct = _allAccounts.find(a => a.name === staffName);
  const memoVal = escHtml(acct?.schedule_memo || '');

  return `
  <div class="sch-wrap" id="sch-wrap-${sid}">
    <table class="sch-table">
      <thead>
        <tr>
          <th class="sch-th sch-th--title">予定名</th>
          <th class="sch-th sch-th--time">開始</th>
          <th class="sch-th sch-th--time">終了</th>
          <th class="sch-th sch-th--dur">時間</th>
          <th class="sch-th sch-th--notes">メモ</th>
          <th class="sch-th sch-th--created">作成日時</th>
          <th class="sch-th" colspan="2"></th>
        </tr>
      </thead>
      <tbody id="sch-tbody-${sid}">
        ${visibleRows.map(_schRowHtml).join('')}
      </tbody>
      ${hasMore ? `
      <tbody class="sch-tbody--hidden" id="sch-tbody-more-${sid}" style="display:none">
        ${hiddenRows.map(_schRowHtml).join('')}
      </tbody>` : ''}
    </table>
    ${hasMore ? `
    <div class="sch-more-wrap" id="sch-more-wrap-${sid}">
      <button class="sch-btn-more" id="sch-btn-more-${sid}" data-expanded="false">
        <i class="fas fa-chevron-down"></i> もっと見る（残り ${hiddenRows.length} 件）
      </button>
    </div>` : ''}
    <div class="sch-footer">
      <button class="sch-btn sch-btn--add" id="sch-btn-add-${sid}">
        <i class="fas fa-plus"></i> 予定を追加
      </button>
      <span class="sch-total" id="sch-total-${sid}">合計 <strong>${totalH.toFixed(1)}h</strong></span>
      <button class="sch-btn sch-btn--holiday" id="sch-btn-holiday-${sid}" data-holiday="${_allAccounts.find(a=>a.name===staffName)?.is_holiday ? '1' : '0'}">
        ${_allAccounts.find(a=>a.name===staffName)?.is_holiday
          ? '<i class="fas fa-moon"></i> 公休中'
          : '<i class="fas fa-umbrella-beach"></i> 公休'}
      </button>
      <button class="sch-btn sch-btn--clear" id="sch-btn-clear-${sid}">
        <i class="fas fa-trash-alt"></i> スケジュールクリア
      </button>
    </div>
    <div class="sch-memo-wrap" id="sch-memo-wrap-${sid}">
      <div class="sch-memo-label"><i class="fas fa-sticky-note"></i> MEMO</div>
      <textarea class="sch-memo-area" id="sch-memo-area-${sid}" placeholder="メモを入力...">${memoVal}</textarea>
      <div class="sch-memo-status" id="sch-memo-status-${sid}"></div>
    </div>
  </div>`;
}

/** 「もっと見る」ボタンの開閉バインド */
function _bindSchMoreBtn(btn, sid) {
  if (!btn) return;
  btn.addEventListener('click', () => {
    const expanded = btn.dataset.expanded === 'true';
    const tbodyMore = document.getElementById(`sch-tbody-more-${sid}`);
    if (!tbodyMore) return;
    if (expanded) {
      tbodyMore.style.display = 'none';
      btn.dataset.expanded = 'false';
      btn.innerHTML = `<i class="fas fa-chevron-down"></i> もっと見る（${tbodyMore.querySelectorAll('tr').length} 件）`;
    } else {
      tbodyMore.style.display = '';
      btn.dataset.expanded = 'true';
      btn.innerHTML = `<i class="fas fa-chevron-up"></i> 閉じる`;
    }
  });
}

/** スケジュールのイベント登録（panel 委任）*/
function _bindScheduleEvents(panel, staffName, sid) {
  const container = panel.querySelector(`#sch-container-${sid}`);
  if (!container) return;

  container.addEventListener('click', async e => {
    // ── 予定を追加ボタン ──────────────────────────────
    if (e.target.closest(`#sch-btn-add-${sid}`)) {
      const tbody = document.getElementById(`sch-tbody-${sid}`);
      if (!tbody || tbody.querySelector('.sch-row--new')) return;
      const tr = document.createElement('tr');
      tr.className = 'sch-row sch-row--new';
      tr.innerHTML = `
        <td class="sch-cell sch-cell--title">
          <input class="sch-inp sch-inp--new" data-field="title" type="text" placeholder="予定名（必須）">
        </td>
        <td class="sch-cell sch-cell--time">
          <input class="sch-inp sch-inp--time sch-inp--new" data-field="start_time" type="text" placeholder="11:00" maxlength="5">
        </td>
        <td class="sch-cell sch-cell--time">
          <input class="sch-inp sch-inp--time sch-inp--new" data-field="end_time" type="text" placeholder="12:00" maxlength="5">
        </td>
        <td class="sch-cell sch-cell--dur">
          <span class="sch-dur sch-dur--zero" id="sch-new-dur-${sid}">—</span>
        </td>
        <td class="sch-cell sch-cell--notes">
          <input class="sch-inp sch-inp--new" data-field="notes" type="text" placeholder="メモ">
        </td>
        <td class="sch-cell sch-cell--created">—</td>
        <td class="sch-cell sch-cell--save" colspan="2">
          <button class="sch-btn sch-btn--commit" id="sch-btn-commit-${sid}">
            <i class="fas fa-plus"></i> 追加
          </button>
          <button class="sch-btn sch-btn--cancel" id="sch-btn-cancel-${sid}" style="margin-left:4px;">
            <i class="fas fa-times"></i>
          </button>
        </td>`;
      tbody.appendChild(tr);
      tr.querySelector('[data-field="title"]').focus();
      return;
    }

    // ── キャンセルボタン ──────────────────────────────
    if (e.target.closest(`#sch-btn-cancel-${sid}`)) {
      const tbody = document.getElementById(`sch-tbody-${sid}`);
      const newRow = tbody ? tbody.querySelector('.sch-row--new') : null;
      if (newRow) newRow.remove();
      return;
    }

    // ── 追加確定ボタン（POST）────────────────────────
    if (e.target.closest(`#sch-btn-commit-${sid}`)) {
      const btn = e.target.closest(`#sch-btn-commit-${sid}`);
      if (btn.disabled) return;
      const tbody = document.getElementById(`sch-tbody-${sid}`);
      const newRow = tbody ? tbody.querySelector('.sch-row--new') : null;
      if (!newRow) return;

      const title = newRow.querySelector('[data-field="title"]')?.value.trim() || '';
      if (!title) { showToast('予定名を入力してください', 'error'); return; }
      const st  = _schNormalizeTime(newRow.querySelector('[data-field="start_time"]')?.value || '');
      const et  = _schNormalizeTime(newRow.querySelector('[data-field="end_time"]')?.value   || '');
      const dur = _schCalcDuration(st, et);
      const notes = newRow.querySelector('[data-field="notes"]')?.value.trim() || null;
      const today = _todayStr();

      btn.disabled = true;
      btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';
      try {
        await API.post('schedules', {
          assignee: staffName, date: today, title,
          start_time: st || null, end_time: et || null,
          duration_hours: dur, is_recurring: false, recur_days: [], notes,
          deleted: false,
        });
        newRow.remove();
        await _schReload(sid, staffName);
        showToast('予定を追加しました', 'success');
      } catch(err) {
        console.error('[sch] POST error', err);
        showToast('追加に失敗しました', 'error');
        btn.disabled = false;
        btn.innerHTML = '<i class="fas fa-plus"></i> 追加';
      }
      return;
    }

    // ── 保存ボタン（PATCH）───────────────────────────
    if (e.target.closest('.sch-btn--save')) {
      const btn = e.target.closest('.sch-btn--save');
      if (btn.disabled) return;
      const row = btn.closest('tr.sch-row[data-id]');
      if (!row) return;
      const id  = row.dataset.id;
      const st  = _schNormalizeTime(row.querySelector('[data-field="start_time"]')?.value || '');
      const et  = _schNormalizeTime(row.querySelector('[data-field="end_time"]')?.value   || '');
      const dur = _schCalcDuration(st, et);
      const title = row.querySelector('[data-field="title"]')?.value.trim() || '';
      if (!title) { showToast('予定名を入力してください', 'error'); return; }

      btn.disabled = true;
      btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';
      try {
        await _saveTableFields('schedules', id, {
          assignee: staffName, date: _todayStr(), title,
          start_time: st || null, end_time: et || null, duration_hours: dur,
          notes: row.querySelector('[data-field="notes"]')?.value.trim() || null,
          deleted: false,
        });
        btn.innerHTML = '<i class="fas fa-check"></i> 保存';
        showToast('保存しました', 'success');
        await _schReload(sid, staffName);
      } catch(err) {
        console.error('[sch] PATCH error', err);
        showToast('保存に失敗しました', 'error');
        btn.innerHTML = '<i class="fas fa-check"></i> 保存';
      } finally { btn.disabled = false; }
      return;
    }

    // ── 削除ボタン ──────────────────────────────────
    if (e.target.closest('.sch-btn--del')) {
      const btn = e.target.closest('.sch-btn--del');
      const id  = btn.dataset.id;
      if (!id || !confirm('この予定を削除しますか？')) return;
      btn.disabled = true;
      try {
        await API.delete('schedules', id);
        showToast('予定を削除しました', 'success');
        await _schReload(sid, staffName);
      } catch(err) { showToast('削除に失敗しました', 'error'); btn.disabled = false; }
      return;
    }

    // ── スケジュールクリアボタン ─────────────────────
    if (e.target.closest(`#sch-btn-holiday-${sid}`)) {
      const btn  = e.target.closest(`#sch-btn-holiday-${sid}`);
      const acct = _allAccounts.find(a => a.name === staffName);
      if (!acct?.id) return;
      const nowHoliday = !!(acct.is_holiday);
      const nextHoliday = !nowHoliday;
      btn.disabled = true;
      btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';
      try {
        await _saveTableFields('accounts', acct.id, { is_holiday: nextHoliday });
        // ローカルキャッシュ更新
        acct.is_holiday = nextHoliday;
        if (nextHoliday) {
          showToast(`${staffName} を公休中に設定しました`, 'success');
          btn.innerHTML = '<i class="fas fa-moon"></i> 公休中';
          btn.dataset.holiday = '1';
        } else {
          showToast(`${staffName} を出勤日に戻しました`, 'success');
          btn.innerHTML = '<i class="fas fa-umbrella-beach"></i> 公休';
          btn.dataset.holiday = '0';
        }
        btn.classList.toggle('sch-btn--holiday-on', nextHoliday);
        // ダッシュボードを再描画して顔アイコンも更新
        if (_taskCurrentStaff === 'dashboard') {
          _renderDashboard();
        }
        // 公休状態の変化を当日ログに反映
        try { await _upsertTodayWorkLog(staffName); } catch(e) { console.warn('[wlog]', e); }
      } catch(err) {
        console.error('[sch] holiday error', err);
        showToast('公休設定に失敗しました', 'error');
        btn.innerHTML = nowHoliday ? '<i class="fas fa-moon"></i> 公休中' : '<i class="fas fa-umbrella-beach"></i> 公休';
      } finally {
        btn.disabled = false;
      }
      return;
    }

    // ── スケジュールクリアボタン ─────────────────────
    if (e.target.closest(`#sch-btn-clear-${sid}`)) {
      const btn = e.target.closest(`#sch-btn-clear-${sid}`);
      const today = _todayStr();
      const allToday = _allSchedules.filter(s => s.assignee === staffName && _schIsToday(s, today));
      // デフォルト以外が削除対象
      const targets = allToday.filter(s => !s.is_default);
      btn.disabled = true;
      btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> 処理中…';
      try {
        // デフォルト以外を全削除
        if (targets.length) {
          await Promise.all(targets.map(s => API.delete('schedules', s.id)));
        }
        // キャッシュ更新
        const res = await API.getAll('schedules');
        _allSchedules = (Array.isArray(res.data) ? res.data : (Array.isArray(res) ? res : []))
          .filter(s => s.deleted !== true);
        // デフォルトが今日なければ再登録（手動削除後のクリアで復活）
        const added = await _ensureDefaultSchedule(staffName, today);
        if (added) {
          const res2 = await API.getAll('schedules');
          _allSchedules = (Array.isArray(res2.data) ? res2.data : (Array.isArray(res2) ? res2 : []))
            .filter(s => s.deleted !== true);
        }
        showToast('今日のスケジュールをクリアしました', 'success');
        // _schReload は _ensureDefaultSchedule を呼ばないので描画のみ
        await _schReload(sid, staffName);
      } catch(err) {
        console.error('[sch] clear error', err);
        showToast('クリアに失敗しました', 'error');
      }
      finally { btn.disabled = false; btn.innerHTML = '<i class="fas fa-trash-alt"></i> スケジュールクリア'; }
      return;
    }
  });

  // ── 「もっと見る」ボタンのバインド ──────────────────────────
  _bindSchMoreBtn(container.querySelector(`#sch-btn-more-${sid}`), sid);

  // ── スケジュールメモの自動保存（debounce 800ms）──────────────
  const memoArea   = container.querySelector(`#sch-memo-area-${sid}`);
  const memoStatus = container.querySelector(`#sch-memo-status-${sid}`);
  if (memoArea) {
    let _memoTimer = null;
    memoArea.addEventListener('input', () => {
      if (memoStatus) { memoStatus.textContent = '編集中…'; memoStatus.className = 'sch-memo-status sch-memo-status--editing'; }
      clearTimeout(_memoTimer);
      _memoTimer = setTimeout(async () => {
        const val = memoArea.value;
        // _allAccounts から対象アカウントの ID を特定
        const acct = _allAccounts.find(a => a.name === staffName);
        if (!acct?.id) { if (memoStatus) { memoStatus.textContent = '保存失敗'; memoStatus.className = 'sch-memo-status sch-memo-status--error'; } return; }
        if (memoStatus) { memoStatus.textContent = '保存中…'; memoStatus.className = 'sch-memo-status sch-memo-status--saving'; }
        try {
          await _saveTableFields('accounts', acct.id, { schedule_memo: val });
          // ローカルキャッシュを更新
          acct.schedule_memo = val;
          if (memoStatus) { memoStatus.textContent = '保存済み ✓'; memoStatus.className = 'sch-memo-status sch-memo-status--saved'; }
          setTimeout(() => { if (memoStatus) memoStatus.textContent = ''; }, 2000);
        } catch(err) {
          console.error('[sch memo] save error', err);
          if (memoStatus) { memoStatus.textContent = '保存失敗'; memoStatus.className = 'sch-memo-status sch-memo-status--error'; }
        }
      }, 800);
    });
  }

  // ── 時間入力 → 所要時間リアルタイムプレビュー ──────────────
  container.addEventListener('input', e => {
    const inp = e.target;
    if (!inp.classList.contains('sch-inp--time')) return;
    const row = inp.closest('tr.sch-row');
    if (!row) return;
    const st  = _schNormalizeTime(row.querySelector('[data-field="start_time"]')?.value || '');
    const et  = _schNormalizeTime(row.querySelector('[data-field="end_time"]')?.value   || '');
    const dur = _schCalcDuration(st, et);
    const durEl = row.querySelector('.sch-dur');
    if (durEl) {
      durEl.textContent = dur > 0 ? dur.toFixed(1) : '—';
      durEl.className = 'sch-dur' + (dur > 0 ? '' : ' sch-dur--zero');
    }
  });
}

// ══════════════════════════════════════════════════════════════
//  過去スケジュール（完了タスク保管庫の下）
// ══════════════════════════════════════════════════════════════

/** 日付ごとにグループ化して過去スケジュールテーブルHTMLを生成 */


// ── Googleカレンダー埋め込みセクション HTML 生成 ──────────────
/**
 * アカウントの embed_code から iframe src を抽出し
 * 安全に iframe を生成して返す。
 * embed_code 未設定の場合は設定を促すメッセージを返す。
 */
function _buildStaffCalendarSection(staffName, sid) {
  const acc = _allAccounts.find(a => a.name === staffName && !a.is_deleted);

  // embed_code から src 属性値を抽出
  let calSrc = '';
  if (acc && acc.embed_code) {
    const m = acc.embed_code.match(/src=["']([^"']+)["']/i);
    if (m) calSrc = m[1];
  }

  // embed_code がなく calendar_id だけある場合は公開カレンダーURLを生成
  if (!calSrc && acc && acc.calendar_id) {
    const cid = encodeURIComponent(acc.calendar_id);
    calSrc = `https://calendar.google.com/calendar/embed?src=${cid}&ctz=Asia%2FTokyo&mode=WEEK&showTitle=0&showNav=1&showPrint=0&showTabs=1&showCalendars=0`;
  }

  const noCalHTML = `
    <div class="staff-cal-empty">
      <i class="fas fa-calendar-times"></i>
      <p>Googleカレンダーが設定されていません</p>
      <small>企業情報 → アカウント管理 でこのスタッフの「カレンダーID」または「埋め込みコード」を設定してください。</small>
    </div>`;

  const iframeHTML = calSrc
    ? `<div class="staff-cal-iframe-wrap">
         <iframe
           src="${escHtml(calSrc)}"
           class="staff-cal-iframe"
           frameborder="0"
           scrolling="no"
           title="${escHtml(staffName)} のGoogleカレンダー"
           loading="lazy"
         ></iframe>
       </div>`
    : noCalHTML;

  // 2カラム右側に直接レンダリングするシンプル版（折りたたみなし）
  return `
    <section class="task-section task-section--gcal" id="gcal-section-${sid}">
      <div class="task-section-header task-section-header--gcal">
        <h3 class="task-section-title" style="display:flex;align-items:center;gap:6px;">
          <i class="fab fa-google" style="color:#4285F4;"></i>
          Googleカレンダー
          ${calSrc
            ? `<span class="gcal-status-badge gcal-status-badge--set"><i class="fas fa-check-circle"></i> 連携済み</span>`
            : `<span class="gcal-status-badge gcal-status-badge--unset"><i class="fas fa-exclamation-circle"></i> 未設定</span>`
          }
        </h3>
      </div>
      <div class="gcal-body" id="gcal-body-${sid}">
        ${iframeHTML}
      </div>
    </section>`;
}

// ── インライン編集テーブルHTML生成 ────────────────────────────
function _buildInlineTaskTable(tasks, staffName, sectionCategory) {
  // sectionCategory: 'PR管理' の場合は新規行の管理区分を PR管理 に初期化
  const _secCat = sectionCategory || 'タスク管理';
  const today = new Date(); today.setHours(0,0,0,0);
  const sid   = _staffId(staffName);
  const handoverOpts = ['<option value="">— なし —</option>',
    ..._activeAccounts().map(a => `<option value="${escHtml(a.name)}">${escHtml(a.name)}</option>`)
  ].join('');

  // ── グループIDごとに色インデックスを割り当て（最大8色循環）──
  const _groupColorMap = new Map();
  let _groupColorIdx = 0;
  tasks.forEach(t => {
    if (t.group_id && !_groupColorMap.has(t.group_id)) {
      _groupColorMap.set(t.group_id, _groupColorIdx % 8);
      _groupColorIdx++;
    }
  });

  const mkSelSimple = (name, options, val) => {
    const blankOpt = name === 'priority'
      ? `<option value=""${val === '' || val == null ? ' selected' : ''}>—</option>`
      : '';
    const optsHTML = options.map(o =>
      `<option value="${o}"${o === val ? ' selected' : ''}>${o}</option>`).join('');
    const extraCls = name === 'priority' ? ' til-sel--priority' : '';
    return `<select class="til-sel${extraCls}" data-field="${name}" data-value="${val || ''}">${blankOpt}${optsHTML}</select>`;
  };

  const rowHTML = (t, isNew = false) => {
    const tmpId  = t ? escHtml(t.id) : '';
    const isDue  = t && t.due_date && t.progress !== '完了' && new Date(t.due_date + 'T00:00:00') < today;

    // 期限色分け
    let dueCls = '';
    if (!isNew && t && t.due_date && t.progress !== '完了') {
      const dueDate = new Date(t.due_date + 'T00:00:00');
      const diffMs  = dueDate - today;
      const diffDay = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
      if (diffDay === 0)      dueCls = ' task-inline-row--due-today';   // 今日
      else if (diffDay <= 3)  dueCls = ' task-inline-row--due-soon';    // 3日以内
    }

    // 引継ぎを受けたタスク：自分が assignee でなく handover に指定されたタスク
    const isReceived = !isNew && t && t.assignee !== staffName;
    const rowCls = isNew
      ? 'task-inline-row task-inline-row--new'
      : `task-inline-row${t.is_pinned ? ' task-inline-row--pinned' : ''}${t.is_today ? ' task-inline-row--today' : ''}${isDue ? ' task-inline-row--overdue' : ''}${dueCls}${isReceived ? ' task-inline-row--received' : ''}`;
    const hoverSel = hOpts => {
      const v = t ? (t.handover || '') : '';
      return hOpts.replace(`value="${escHtml(v)}"`, `value="${escHtml(v)}" selected`);
    };
    // 引継ぎ履歴チップ（高尾 → 西脇 → 濱野 のように連鎖表示）
    const buildChainBadge = task => {
      const chain = Array.isArray(task.handover_chain) ? task.handover_chain : [];
      if (!chain.length) return '';
      const chips = chain.map((n, i) =>
        `<span class="til-chain-item">${i > 0 ? '<i class="fas fa-arrow-right til-chain-arrow"></i>' : ''}${escHtml(n)}</span>`
      ).join('');
      return `<div class="til-chain-badges">${chips}</div>`;
    };
    // 引継ぎ受け行でも再引継ぎ可能なセレクト＋履歴チップを表示
    const handoverCell = isReceived
      ? `<div class="til-handover-wrap">
           <span class="til-received-chip"><i class="fas fa-share"></i> ${escHtml(t.assignee)}</span>
           <select class="til-sel til-sel--handover til-sel--rehandover" data-field="handover" title="さらに引継ぐ">${hoverSel(handoverOpts)}</select>
           ${buildChainBadge(t)}
         </div>`
      : `<div class="til-handover-wrap">
           <select class="til-sel til-sel--handover" data-field="handover">${hoverSel(handoverOpts)}</select>
           ${t ? buildChainBadge(t) : ''}
         </div>`;
    const groupCls = (!isNew && t && t.group_id) ? ' til-row--grouped' : '';
    const isGroupParent = !isNew && t && t.group_id && t.id === t.group_id;
    const groupIcon = isGroupParent ? '<i class="fas fa-layer-group til-group-icon" title="グループ親"></i>' : (t && t.group_id && !isGroupParent ? '<i class="fas fa-link til-group-child-icon" title="グループ内"></i>' : '');
    // グループ色インデックス（グループに属する行のみ data-group-color 付与）
    const groupColorIdx = (!isNew && t && t.group_id) ? _groupColorMap.get(t.group_id) : undefined;
    const groupColorAttr = groupColorIdx !== undefined ? ` data-group-color="${groupColorIdx}"` : '';
    return `<tr class="${rowCls}${groupCls}" data-id="${tmpId}" data-new="${isNew}" data-received="${isReceived}" data-group-id="${t ? escHtml(t.group_id||'') : ''}"${groupColorAttr} draggable="${!isNew}">
      <td class="til-cell til-cell--chk">
        ${isNew ? '' : `<input type="checkbox" class="til-row-chk" data-id="${tmpId}">`}
        ${isNew ? '' : `<button class="til-btn-pin${t && t.is_pinned ? ' til-btn-pin--active' : ''}" data-id="${tmpId}" title="${t && t.is_pinned ? 'ピン止め解除' : 'ピン止め'}"><i class="fas fa-thumbtack"></i></button>`}
      </td>
      <td class="til-cell til-cell--drag">
        ${isNew ? '' : `<span class="til-drag-handle" title="ドラッグで並び替え"><i class="fas fa-grip-vertical"></i></span>${groupIcon}`}
      </td>
      <td class="til-cell til-cell--handover">${handoverCell}</td>
      <td class="til-cell til-cell--store" data-tooltip="${escHtml(t ? (t.store_name || '') : '')}">
        <input class="til-inp" data-field="store_name" type="text"
          value="${escHtml(t ? (t.store_name || '') : '')}" placeholder="店舗名">
      </td>
      <td class="til-cell til-cell--title" data-tooltip="${escHtml(t ? (t.title || '') : '')}">
        <input class="til-inp til-inp--title" data-field="title" type="text"
          value="${escHtml(t ? (t.title || '') : '')}" placeholder="タスク名（必須）">
      </td>
      <td class="til-cell til-cell--url">
        ${(() => {
          const urlVal = t ? (t.task_url || '') : '';
          const linkBtn = urlVal
            ? `<a class="til-url-link" href="${escHtml(urlVal)}" target="_blank" rel="noopener noreferrer" title="${escHtml(urlVal)}"><i class="fas fa-external-link-alt"></i></a>`
            : '';
          return `<div class="til-url-wrap">${linkBtn}<input class="til-inp til-inp--url" data-field="task_url" type="text" value="${escHtml(urlVal)}" placeholder="https://..."></div>`;
        })()}
      </td>
      <td class="til-cell til-cell--today">
        <label class="til-chk-wrap" title="今日のタスク">
          <input type="checkbox" class="til-chk" data-field="is_today"${t && t.is_today ? ' checked' : ''}>
          <span class="til-chk-ui"></span>
        </label>
      </td>
      <td class="til-cell til-cell--today-hours">
        <input class="til-inp til-inp--num" data-field="today_hours" type="number" min="0" step="0.5"
          value="${t && t.today_hours != null ? t.today_hours : ''}" placeholder="0.0">
      </td>
      <td class="til-cell til-cell--priority">
        ${mkSelSimple('priority', ['高','中','低'], t ? (t.priority || '') : '')}
      </td>
      <td class="til-cell til-cell--start">
        <input class="til-inp til-inp--date" data-field="start_date" type="date"
          value="${escHtml(t ? (t.start_date || '') : '')}">
      </td>
      <td class="til-cell til-cell--due">
        <input class="til-inp til-inp--date" data-field="due_date" type="date"
          value="${escHtml(t ? (t.due_date || '') : '')}">
      </td>
      <td class="til-cell til-cell--est">
        <input class="til-inp til-inp--num" data-field="estimated_hours" type="number" min="0" step="0.5"
          value="${t && t.estimated_hours != null ? t.estimated_hours : ''}" placeholder="0.0">
      </td>
      <td class="til-cell til-cell--progress">
        ${mkSelSimple('progress', ['未着手','進行中','確認待ち','完了'], t ? (t.progress || '未着手') : '未着手')}
      </td>
      <td class="til-cell til-cell--notes">
        <input class="til-inp til-inp--notes" data-field="notes" type="text"
          value="${escHtml(t ? (t.notes || '') : '')}" placeholder="メモ">
      </td>
      <td class="til-cell til-cell--category">
        <select class="til-sel til-sel--category" data-field="task_category">
          <option value="タスク管理"${(!t ? (_secCat === 'タスク管理' || (!_secCat || _secCat === '')) : (!t.task_category || t.task_category === 'タスク管理')) ? ' selected' : ''}>タスク管理</option>
          <option value="定期タスク"${(!t ? (_secCat === '定期タスク') : (t && t.task_category === '定期タスク')) ? ' selected' : ''}>定期タスク</option>
          <option value="PR管理"${(!t ? (_secCat === 'PR管理') : (t && t.task_category === 'PR管理')) ? ' selected' : ''}>PR管理</option>
        </select>
      </td>
      <td class="til-cell til-cell--del">
        ${isNew
          ? `<button class="til-btn-cancel" title="キャンセル"><i class="fas fa-times"></i></button>`
          : `<div class="til-action-wrap">
               <button class="til-btn-save" title="保存"><i class="fas fa-save"></i> 保存</button>
               <button class="til-btn-del" title="削除"><i class="fas fa-trash"></i></button>
             </div>`}
      </td>
    </tr>`;
  };

  const existingRows = tasks.map(t => rowHTML(t, false)).join('');
  const newRow = rowHTML(null, true);

  return `
  <div class="til-group-toolbar" id="til-group-toolbar-${sid}" style="display:none">
    <span class="til-sel-count" id="til-sel-count-${sid}">0件選択中</span>
    <button class="til-group-btn" id="til-group-btn-${sid}"><i class="fas fa-layer-group"></i> グループ化</button>
    <button class="til-ungroup-btn" id="til-ungroup-btn-${sid}"><i class="fas fa-unlink"></i> 解除</button>
    <button class="til-desel-btn" id="til-desel-btn-${sid}"><i class="fas fa-times"></i> 選択解除</button>
  </div>
  <table class="task-inline-table" id="task-inline-table-${sid}">
    <thead>
      <tr class="task-inline-thead">
        <th class="til-th til-th--chk"><input type="checkbox" class="til-chk-all" id="til-chk-all-${sid}" title="全選択"></th>
        <th class="til-th til-th--drag"></th>
        <th class="til-th til-th--handover">引継者</th>
        <th class="til-th til-th--store">店舗名</th>
        <th class="til-th til-th--title">タスク名</th>
        <th class="til-th til-th--url">URL</th>
        <th class="til-th til-th--today">今日</th>
        <th class="til-th til-th--today-hours">今日時間</th>
        <th class="til-th til-th--priority">優先度</th>
        <th class="til-th til-th--start">開始日</th>
        <th class="til-th til-th--due">完了予定日</th>
        <th class="til-th til-th--est">予測時間</th>
        <th class="til-th til-th--progress">進捗</th>
        <th class="til-th til-th--notes">メモ</th>
        <th class="til-th til-th--category">管理区分</th>
        <th class="til-th til-th--del"></th>
      </tr>
    </thead>
    <tbody id="task-inline-tbody-${sid}${_secCat === 'PR管理' ? '-pr' : _secCat === '定期タスク' ? '-recur' : ''}">
      ${existingRows}
      ${newRow}
    </tbody>
  </table>
  <div class="task-inline-add-wrap">
    <button class="task-inline-add-btn" id="task-inline-add-btn-${sid}${_secCat === 'PR管理' ? '-pr' : _secCat === '定期タスク' ? '-recur' : ''}">
      <i class="fas fa-plus"></i> 行を追加
    </button>
  </div>`;
}

// ── インラインテーブル イベントバインド ────────────────────────
function _bindInlineTableEvents(panel, staffName, _suffix) {
  const sid   = _staffId(staffName);
  // suffix: undefined=通常タスク管理, 'pr'=PR管理, 'recur'=定期タスク管理
  const sfx = _suffix || '';
  const tbodyId  = sfx ? `task-inline-tbody-${sid}-${sfx}` : `task-inline-tbody-${sid}`;
  const addBtnId = sfx ? `task-inline-add-btn-${sid}-${sfx}` : `task-inline-add-btn-${sid}`;
  const tbody = panel.querySelector(`#${tbodyId}`);
  if (!tbody) return;

  // debounce（テキスト入力の連打防止 400ms）
  const _debounceTimers = new Map();
  const debounced = (key, fn, ms = 400) => {
    if (_debounceTimers.has(key)) clearTimeout(_debounceTimers.get(key));
    _debounceTimers.set(key, setTimeout(() => { _debounceTimers.delete(key); fn(); }, ms));
  };

  const collectRow = row => {
    const get = f => row.querySelector(`[data-field="${f}"]`);
    const val = f => (get(f)?.value ?? '').trim();
    const num = f => { const v = get(f)?.value; return (v !== '' && v != null) ? parseFloat(v) : null; };
    const chk = f => !!get(f)?.checked;
    const isTodayChecked = chk('is_today');
    return {
      // assignee / handover は保存ボタンで絶対に上書きしない
      store_name:      val('store_name') || null,
      title:           val('title'),
      is_today:        isTodayChecked,
      today_date:      isTodayChecked ? _todayStr() : null,
      today_hours:     num('today_hours'),
      priority:        val('priority') || null,
      start_date:      val('start_date') || null,
      due_date:        val('due_date')   || null,
      estimated_hours: num('estimated_hours'),
      progress:        val('progress')  || '未着手',
      notes:           val('notes')     || null,
      task_url:        val('task_url')  || null,
      task_category:   val('task_category') || 'タスク管理',
    };
  };

  // ── 行を「未保存」状態にマークするヘルパー ──
  const markDirty = row => {
    if (!row || row.dataset.new === 'true') return;
    row.dataset.dirty = 'true';
    const saveBtn = row.querySelector('.til-btn-save');
    if (saveBtn) saveBtn.classList.add('til-btn-save--dirty');
  };

  // ── click 委譲（保存・削除・キャンセル・ピン止め）──
  tbody.addEventListener('click', async e => {
    const saveBtn   = e.target.closest('.til-btn-save');
    const delBtn    = e.target.closest('.til-btn-del');
    const cancelBtn = e.target.closest('.til-btn-cancel');
    const pinBtn    = e.target.closest('.til-btn-pin');

    // 保存ボタン
    if (saveBtn) {
      const row = saveBtn.closest('tr');
      const id  = row?.dataset.id;
      if (!id) return;
      const payload = collectRow(row);
      saveBtn.disabled = true;
      try {
        const originalTask  = _allTasks.find(x => x.id === id);
        const handoverName  = originalTask?.handover || null;
        const becomingDone  = payload.progress === '完了';
        // 引継ぎを受けたタスク（自分が handover）が完了になる場合 → コピー作成 & 元タスクを is_today:false に
        const isHandoverWorker = !!(handoverName && handoverName !== (originalTask?.assignee) && handoverName === staffName);
        const taskSnapshot  = Object.assign({}, originalTask, payload);
        const finalPayload  = (isHandoverWorker && becomingDone)
          ? Object.assign({}, payload, { is_today: false, today_date: _todayStr() })
          : (becomingDone ? Object.assign({}, payload, { today_date: _todayStr() }) : payload);

        await _saveTableFields('tasks', id, finalPayload);
        row.dataset.dirty = '';
        saveBtn.classList.remove('til-btn-save--dirty');

        // コピー作成（引継ぎ受けた側が完了にした時のみ）
        if (isHandoverWorker && becomingDone) {
          await _createHandoverCopy(taskSnapshot, handoverName);
        }

        showToast('保存しました', 'success');
        await loadTasks();
      } catch(err) {
        console.error('saveTask error', err);
        showToast('保存に失敗しました', 'error');
        saveBtn.disabled = false;
      }
      return;
    }

    if (delBtn) {
      const row = delBtn.closest('tr');
      const id  = row.dataset.id;
      if (!id || !confirm('このタスクを削除しますか？')) return;
      try {
        await API.delete('tasks', id);
        showToast('タスクを削除しました', 'success');
        await loadTasks();
      } catch(err) {
        console.error('deleteTaskInline error', err);
        showToast('削除に失敗しました', 'error');
      }
      return;
    }

    if (cancelBtn) {
      const row = cancelBtn.closest('tr');
      if (row.dataset.new === 'true') {
        row.remove();
      } else {
        row.querySelectorAll('input').forEach(i => {
          if (i.type === 'checkbox') i.checked = false;
          else i.value = '';
        });
        row.querySelectorAll('select').forEach(s => { s.selectedIndex = 0; });
      }
      return;
    }

    // ピン止めボタン
    if (pinBtn) {
      const id = pinBtn.dataset.id;
      if (!id) return;
      const task = _allTasks.find(x => x.id === id);
      if (!task) return;
      const newPinned = !task.is_pinned;
      pinBtn.disabled = true;
      try {
        await _saveTableFields('tasks', id, { is_pinned: newPinned });
        showToast(newPinned ? '📌 ピン止めしました（最上位固定）' : 'ピン止めを解除しました', 'success');
        await loadTasks();
      } catch(err) {
        console.error('pin error', err);
        showToast('ピン止めに失敗しました', 'error');
        pinBtn.disabled = false;
      }
      return;
    }
  });

  // ── 既存行：select.change → handover は即時PATCH+再描画、task_category は一括PATCH+再描画、それ以外はdirtyマーク ──
  tbody.addEventListener('change', async e => {
    const sel = e.target.closest('select[data-field]');
    if (!sel) return;
    const row = sel.closest('tr');
    if (!row || row.dataset.new === 'true') return;
    const id = row.dataset.id;
    if (!id) return;

    const field = sel.dataset.field;
    const value = sel.value || null;
    // data-value を更新して CSS 色付けを反映
    sel.dataset.value = sel.value;

    if (field === 'handover') {
      // handover は即時保存（引継ぎ操作は意図的なアクション）
      const task = _allTasks.find(x => x.id === id);
      let chain = Array.isArray(task?.handover_chain) ? [...task.handover_chain] : [];
      if (value) {
        if (chain[chain.length - 1] !== value) chain.push(value);
      } else {
        chain = [];
      }
      sel.disabled = true;
      try {
        await _saveTableFields('tasks', id, { handover: value, handover_chain: chain });
        showToast(value ? `「${value}」へ引継ぎ依頼しました` : '引継者を解除しました', 'success');
        await loadTasks();
      } catch(err) {
        console.error('autoSave(handover) error', err);
        showToast('自動保存に失敗しました', 'error');
        sel.disabled = false;
      }
    } else if (field === 'task_category') {
      // task_category は即時保存（テーブル間移動）＋行内の他変更も一括保存してから再描画
      sel.disabled = true;
      try {
        const rowPayload = collectRow(row);
        await _saveTableFields('tasks', id, rowPayload);
        const toastMsg = value === 'PR管理' ? 'PR管理テーブルへ移動しました'
          : value === '定期タスク' ? '定期タスク管理テーブルへ移動しました'
          : 'タスク管理テーブルへ移動しました';
        showToast(toastMsg, 'success');
        await loadTasks();
      } catch(err) {
        console.error('autoSave(task_category) error', err);
        showToast('保存に失敗しました', 'error');
        sel.disabled = false;
      }
    } else {
      // progress / priority その他すべて dirtyマーク（保存ボタンで一括保存）
      markDirty(row);
    }
  });

  // ── 既存行：checkbox.change → dirtyマーク（保存ボタンで一括保存） ──
  tbody.addEventListener('change', e => {
    const chk = e.target.closest('input[type="checkbox"][data-field]');
    if (!chk) return;
    const row = chk.closest('tr');
    if (!row || row.dataset.new === 'true') return;
    if (!row.dataset.id) return;
    // is_today を OFF にしたとき today_hours の入力欄もUIリセット
    if (chk.dataset.field === 'is_today' && !chk.checked) {
      const todayHoursInp = row.querySelector('input[data-field="today_hours"]');
      if (todayHoursInp) todayHoursInp.value = '';
    }
    markDirty(row);
  });

  // ── 既存行：input 変更 → すべて dirtyマーク（保存ボタンで一括保存） ──
  tbody.addEventListener('input', e => {
    const inp = e.target.closest('input[data-field]:not([type="checkbox"])');
    if (!inp) return;
    const row = inp.closest('tr');
    if (!row || row.dataset.new === 'true') return;
    if (!row.dataset.id) return;
    markDirty(row);
  });

  // ── タスク名・店舗名セルのツールチップ（data-tooltip）をリアルタイム更新 ──
  tbody.addEventListener('input', e => {
    const inp = e.target.closest('.til-inp--title, [data-field="store_name"]');
    if (!inp) return;
    const td = inp.closest('.til-cell--title, .til-cell--store');
    if (td) td.dataset.tooltip = inp.value;
  });

  // ── URL入力：リアルタイムでリンクアイコンを更新 ──
  tbody.addEventListener('input', e => {
    const urlInp = e.target.closest('.til-inp--url');
    if (!urlInp) return;
    const cell = urlInp.closest('.til-cell--url');
    if (!cell) return;
    const wrap = cell.querySelector('.til-url-wrap');
    if (!wrap) return;
    const urlVal = urlInp.value.trim();
    let linkBtn = wrap.querySelector('.til-url-link');
    if (urlVal) {
      if (linkBtn) {
        linkBtn.href = urlVal;
        linkBtn.title = urlVal;
      } else {
        linkBtn = document.createElement('a');
        linkBtn.className = 'til-url-link';
        linkBtn.href = urlVal;
        linkBtn.target = '_blank';
        linkBtn.rel = 'noopener noreferrer';
        linkBtn.title = urlVal;
        linkBtn.innerHTML = '<i class="fas fa-external-link-alt"></i>';
        wrap.insertBefore(linkBtn, urlInp);
      }
    } else {
      if (linkBtn) linkBtn.remove();
    }
  });

  // ── 新規行：タスク名 blur または Enter → API.post ──
  const bindNewRowEvents = tr => {
    const titleInp = tr.querySelector('.til-inp--title');
    if (!titleInp) return;

    // 類似タスクサジェスト要素（行の直下にインサート）
    let _suggestEl = null;
    const _removeSuggest = () => { if (_suggestEl) { _suggestEl.remove(); _suggestEl = null; } };

    const _showSuggest = q => {
      _removeSuggest();
      if (!q || q.length < 2) return;

      // ── 検索テキスト正規化ヘルパー ──
      // スペース（全角・半角）・記号（・、/／。、など）を除去して小文字化
      const _normalize = s => (s || '').toLowerCase()
        .replace(/[\s\u3000・\/／。、，,.\-_―‐]+/g, '');

      const normQ = _normalize(q);

      // 新規行の店舗名欄が埋まっていれば、店舗名での絞り込みにも使う
      const storeInp = tr.querySelector('[data-field="store_name"]');
      const storeQ   = _normalize(storeInp ? storeInp.value.trim() : '');

      // ── マッチ判定 ──
      // 入力値を正規化し、タスク名 OR 店舗名のどちらかに部分一致すればヒット
      // 店舗名欄が埋まっている場合は「店舗名にstoreQ一致 AND タスク名にnormQ一致」で絞る
      const hits = _allTasks.filter(t => {
        if (t.progress === '完了') return false;
        const normTitle = _normalize(t.title);
        const normStore = _normalize(t.store_name);

        if (storeQ.length >= 2) {
          // 店舗名欄が入力済み → 店舗名マッチ必須、タスク名もマッチ必須
          const storeMatch = normStore.includes(storeQ) || storeQ.includes(normStore.slice(0,2));
          const titleMatch = normTitle.includes(normQ);
          return storeMatch && titleMatch;
        } else {
          // 店舗名未入力 → タスク名 OR 店舗名のどちらかに一致
          return normTitle.includes(normQ) || normStore.includes(normQ);
        }
      }).slice(0, 5);
      if (hits.length === 0) return;
      _suggestEl = document.createElement('div');
      _suggestEl.className = 'til-suggest-box';
      _suggestEl.innerHTML = `<div class="til-suggest-header"><i class="fas fa-lightbulb"></i> もしかしてこのタスクですか？</div>` +
        hits.map(t => {
          const isMine = t.assignee === staffName;
          const prCls  = t.priority === '高' ? 'tpr-high' : t.priority === '低' ? 'tpr-low' : 'tpr-mid';
          return `<div class="til-suggest-item" data-tid="${escHtml(t.id)}">
            <span class="${prCls}" style="font-size:10px;font-weight:700;">${escHtml(t.priority||'—')}</span>
            <span class="til-suggest-title">${escHtml(t.title)}</span>
            ${t.store_name ? `<span class="til-suggest-store">${escHtml(t.store_name)}</span>` : ''}
            <span class="til-suggest-assignee${isMine ? ' is-mine' : ''}"><i class="fas fa-user"></i> ${escHtml(t.assignee||'—')}${isMine ? ' (自分)' : ''}</span>
            <span class="til-suggest-prog">${escHtml(t.progress||'')}</span>
          </div>`;
        }).join('') +
        `<div class="til-suggest-footer">このまま新しいタスクとして登録する場合は Enter</div>`;
      tr.after(_suggestEl);
      // サジェスト項目クリック → 入力欄をその内容に置換
      _suggestEl.querySelectorAll('.til-suggest-item').forEach(item => {
        item.addEventListener('mousedown', e => {
          e.preventDefault(); // blur を防ぐ
          const tid = item.dataset.tid;
          const task = _allTasks.find(t => t.id === tid);
          if (task) {
            titleInp.value = task.title;
            const storeFld = tr.querySelector('[data-field="store_name"]');
            if (storeFld && task.store_name) storeFld.value = task.store_name;
          }
          _removeSuggest();
          titleInp.focus();
        });
      });
    };

    // 入力中にリアルタイムサジェスト（debounce 250ms）
    let _suggestTimer = null;
    titleInp.addEventListener('input', () => {
      clearTimeout(_suggestTimer);
      _suggestTimer = setTimeout(() => _showSuggest(titleInp.value.trim()), 250);
    });
    titleInp.addEventListener('blur', () => {
      // サジェストのmousedownが先に発火するのでわずかに遅延してから削除
      setTimeout(_removeSuggest, 200);
    });

    // 店舗名欄が変わったときもサジェストを再発火
    const storeInpEl = tr.querySelector('[data-field="store_name"]');
    if (storeInpEl) {
      storeInpEl.addEventListener('input', () => {
        if (!titleInp.value.trim()) return; // タスク名が空なら発火しない
        clearTimeout(_suggestTimer);
        _suggestTimer = setTimeout(() => _showSuggest(titleInp.value.trim()), 250);
      });
    }

    const doCreate = async () => {
      _removeSuggest();
      const title = titleInp.value.trim();
      if (!title) {
        tr.remove();
        return;
      }
      const payload = collectRow(tr);
      // 新規作成時は担当者を必ずセット（collectRow は PATCH 用で assignee を除外しているため）
      payload.assignee = staffName;
      titleInp.disabled = true;
      try {
        await API.post('tasks', payload);
        showToast('タスクを追加しました', 'success');
        await loadTasks();
      } catch(err) {
        console.error('createTaskInline error', err);
        showToast('タスクの作成に失敗しました', 'error');
        titleInp.disabled = false;
      }
    };

    titleInp.addEventListener('blur', doCreate);
    titleInp.addEventListener('keydown', e => {
      if (e.key === 'Enter') { e.preventDefault(); titleInp.blur(); }
    });
  };

  // 初期描画時の新規行にイベントをバインド
  tbody.querySelectorAll('tr.task-inline-row--new').forEach(bindNewRowEvents);

  // 「行を追加」ボタン
  const addBtn = panel.querySelector(`#${addBtnId}`);
  if (addBtn) {
    addBtn.addEventListener('click', () => {
      const existingNew = tbody.querySelector('tr.task-inline-row--new');
      if (existingNew) {
        existingNew.querySelector('.til-inp--title')?.focus();
        existingNew.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        return;
      }
      const tr = document.createElement('tr');
      tr.className = 'task-inline-row task-inline-row--new';
      tr.dataset.new = 'true';
      tr.dataset.id  = '';
      tr.innerHTML = _newInlineRowInnerHTML(staffName, sfx === 'pr' ? 'PR管理' : sfx === 'recur' ? '定期タスク' : 'タスク管理');
      tbody.appendChild(tr);
      bindNewRowEvents(tr);
      tr.querySelector('.til-inp--title')?.focus();
      tr.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    });
  }

  // ══════════════════════════════════════════════════════════════
  // ① 行選択チェックボックス + グループ化ツールバー
  // ══════════════════════════════════════════════════════════════
  const toolbar   = panel.querySelector(`#til-group-toolbar-${sid}`);
  const selCount  = panel.querySelector(`#til-sel-count-${sid}`);
  const groupBtn  = panel.querySelector(`#til-group-btn-${sid}`);
  const ungroupBtn= panel.querySelector(`#til-ungroup-btn-${sid}`);
  const deselBtn  = panel.querySelector(`#til-desel-btn-${sid}`);
  const allChk    = panel.querySelector(`#til-chk-all-${sid}`);

  const getCheckedRows = () => [...tbody.querySelectorAll('.til-row-chk:checked')].map(c => c.closest('tr'));
  const updateToolbar  = () => {
    const rows = getCheckedRows();
    const n    = rows.length;
    if (toolbar) toolbar.style.display = n > 0 ? 'flex' : 'none';
    if (selCount) selCount.textContent = `${n}件選択中`;
    // グループ化ボタン：2件以上選択時のみ有効
    if (groupBtn)   groupBtn.disabled   = n < 2;
    // 解除ボタン：1件以上かつ選択中行にgroup_idがある場合有効
    if (ungroupBtn) ungroupBtn.disabled = !rows.some(r => r.dataset.groupId);
  };

  tbody.addEventListener('change', e => {
    if (e.target.classList.contains('til-row-chk')) {
      updateToolbar();
      // allChk の状態同期
      if (allChk) {
        const all  = [...tbody.querySelectorAll('.til-row-chk')];
        const chked= all.filter(c => c.checked);
        allChk.indeterminate = chked.length > 0 && chked.length < all.length;
        allChk.checked       = chked.length === all.length && all.length > 0;
      }
    }
  });
  if (allChk) {
    allChk.addEventListener('change', () => {
      tbody.querySelectorAll('.til-row-chk').forEach(c => c.checked = allChk.checked);
      updateToolbar();
    });
  }
  if (deselBtn) {
    deselBtn.addEventListener('click', () => {
      tbody.querySelectorAll('.til-row-chk').forEach(c => c.checked = false);
      if (allChk) { allChk.checked = false; allChk.indeterminate = false; }
      updateToolbar();
    });
  }

  // ── グループ化 ──
  const PRIORITY_RANK = { '高': 0, '中': 1, '低': 2 };
  if (groupBtn) {
    groupBtn.addEventListener('click', async () => {
      const rows = getCheckedRows();
      if (rows.length < 2) return;
      const ids = rows.map(r => r.dataset.id).filter(Boolean);
      // 既にグループ化されているものは除外（再グループ化禁止）
      // 最高優先度を算出
      const tasks = ids.map(id => _allTasks.find(t => t.id === id)).filter(Boolean);
      const bestPriority = tasks.reduce((best, t) => {
        return (PRIORITY_RANK[t.priority] ?? 1) < (PRIORITY_RANK[best] ?? 1) ? t.priority : best;
      }, tasks[0]?.priority || '中');
      // 最も近い due_date（null でない最小値）
      const dueDates = tasks.map(t => t.due_date).filter(Boolean).sort();
      const bestDue  = dueDates[0] || null;
      // 最初の行を親（group_id = 自身の id）とする
      const parentId = ids[0];
      try {
        await Promise.all(ids.map((id, i) =>
          _saveTableFields('tasks', id, {
            group_id:  parentId,
            priority:  bestPriority,
            due_date:  bestDue || undefined,
            sort_order: i,
          })
        ));
        showToast('グループ化しました', 'success');
        await loadTasks();
      } catch(err) {
        console.error('group error', err);
        showToast('グループ化に失敗しました', 'error');
      }
    });
  }

  // ── グループ解除 ──
  if (ungroupBtn) {
    ungroupBtn.addEventListener('click', async () => {
      const rows  = getCheckedRows();
      const ids   = rows.map(r => r.dataset.id).filter(Boolean);
      try {
        await Promise.all(ids.map(id => _saveTableFields('tasks', id, { group_id: null })));
        showToast('グループを解除しました', 'success');
        await loadTasks();
      } catch(err) {
        console.error('ungroup error', err);
        showToast('グループ解除に失敗しました', 'error');
      }
    });
  }

  // ══════════════════════════════════════════════════════════════
  // ② ドラッグ＆ドロップ 行並び替え（HTML5 Drag and Drop API）
  // ══════════════════════════════════════════════════════════════
  let _dragSrcRow  = null;

  tbody.addEventListener('dragstart', e => {
    const row = e.target.closest('tr[draggable="true"]');
    if (!row) return;
    _dragSrcRow = row;
    const groupId = row.dataset.groupId || '';
    if (groupId) {
      [...tbody.querySelectorAll('tr[draggable="true"]')]
        .filter(r => r.dataset.groupId === groupId)
        .forEach(r => r.classList.add('til-dragging'));
    } else {
      row.classList.add('til-dragging');
    }
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', row.dataset.id || '');
  });

  tbody.addEventListener('dragend', e => {
    tbody.querySelectorAll('.til-dragging').forEach(r => r.classList.remove('til-dragging'));
    tbody.querySelectorAll('.til-drag-over').forEach(r => r.classList.remove('til-drag-over'));
    _dragSrcRow = null;
  });

  tbody.addEventListener('dragover', e => {
    e.preventDefault();
    const row = e.target.closest('tr[draggable="true"]');
    if (!row || row === _dragSrcRow) return;
    const srcGroupId = _dragSrcRow ? (_dragSrcRow.dataset.groupId || '') : '';
    // ドラッグ元グループ内の行はハイライト不要
    if (srcGroupId && row.dataset.groupId === srcGroupId) return;
    tbody.querySelectorAll('.til-drag-over').forEach(r => r.classList.remove('til-drag-over'));
    const tgtGroupId = row.dataset.groupId || '';
    if (tgtGroupId) {
      [...tbody.querySelectorAll('tr[draggable="true"]')]
        .filter(r => r.dataset.groupId === tgtGroupId)
        .forEach(r => r.classList.add('til-drag-over'));
    } else {
      row.classList.add('til-drag-over');
    }
    e.dataTransfer.dropEffect = 'move';
  });

  tbody.addEventListener('dragleave', e => {
    const row = e.target.closest('tr');
    if (row) row.classList.remove('til-drag-over');
  });

  tbody.addEventListener('drop', async e => {
    e.preventDefault();
    const targetRow = e.target.closest('tr[draggable="true"]');
    tbody.querySelectorAll('.til-drag-over').forEach(r => r.classList.remove('til-drag-over'));
    if (!_dragSrcRow || !targetRow || _dragSrcRow === targetRow) return;

    // ── ドラッグ元のグループ行を DOM順で取得 ──
    const srcGroupId = _dragSrcRow.dataset.groupId || '';
    // ※ groupId が空の場合は単独行のみ（data-group-id="" の他行を巻き込まない）
    const srcRows = srcGroupId
      ? [...tbody.querySelectorAll('tr[draggable="true"]')]
          .filter(r => r.dataset.groupId === srcGroupId)
      : [_dragSrcRow];

    // ドロップ先がドラッグ元グループ内の行なら何もしない
    if (srcRows.includes(targetRow)) return;

    // ── ドロップ先のグループ行を DOM順で取得 ──
    const tgtGroupId = targetRow.dataset.groupId || '';
    const tgtRows = tgtGroupId
      ? [...tbody.querySelectorAll('tr[draggable="true"]')]
          .filter(r => r.dataset.groupId === tgtGroupId)
      : [targetRow];

    // 全行のリスト（DOM順）
    const allRows = [...tbody.querySelectorAll('tr[draggable="true"]')];
    const srcFirstIdx = allRows.indexOf(srcRows[0]);
    const tgtFirstIdx = allRows.indexOf(tgtRows[0]);

    if (srcFirstIdx === tgtFirstIdx) return; // 同じ位置なら何もしない

    // ── DOM を移動（グループごと） ──
    if (srcFirstIdx < tgtFirstIdx) {
      // 下に移動：ドロップ先グループ最終行の後ろに src を正順で挿入
      // after() は挿入のたびに参照行が変わらないため逆順で挿入して順序を維持
      const tgtLastRow = tgtRows[tgtRows.length - 1];
      for (let i = srcRows.length - 1; i >= 0; i--) {
        tgtLastRow.after(srcRows[i]);
      }
    } else {
      // 上に移動：ドロップ先グループ先頭行の前に src を正順で挿入
      const tgtFirstRow = tgtRows[0];
      for (let i = 0; i < srcRows.length; i++) {
        // insertBefore の参照ノードは常に tgtFirstRow なので
        // 毎回 tgtFirstRow の前に挿入すると逆順になる → 逆順ループで正順を維持
        tgtFirstRow.before(srcRows[srcRows.length - 1 - i]);
      }
    }

    // sort_order を再計算して API に保存
    const newOrder = [...tbody.querySelectorAll('tr[data-id]')]
      .filter(r => r.dataset.id && !r.dataset.new)
      .map((r, i) => ({ id: r.dataset.id, sort_order: i }));
    try {
      await Promise.all(newOrder.map(({ id, sort_order }) =>
          _saveTableFields('tasks', id, { sort_order })
      ));
      newOrder.forEach(({ id, sort_order }) => {
        const t = _allTasks.find(x => x.id === id);
        if (t) t.sort_order = sort_order;
      });
    } catch(err) {
      console.error('sort_order save error', err);
    }
  });
}

function _newInlineRowInnerHTML(staffName, sectionCategory) {
  const _secCatNew = sectionCategory || 'タスク管理';
  const isRecurNew = _secCatNew === '定期タスク';
  const isPRNew    = _secCatNew === 'PR管理';
  const handoverOpts = ['<option value="">— なし —</option>',
    ..._activeAccounts().map(a => `<option value="${escHtml(a.name)}">${escHtml(a.name)}</option>`)
  ].join('');
  return `
    <td class="til-cell til-cell--chk"></td>
    <td class="til-cell til-cell--drag"></td>
    <td class="til-cell til-cell--handover">
      <select class="til-sel til-sel--handover" data-field="handover">${handoverOpts}</select>
    </td>
    <td class="til-cell til-cell--store">
      <input class="til-inp" data-field="store_name" type="text" value="" placeholder="店舗名">
    </td>
    <td class="til-cell til-cell--title">
      <input class="til-inp til-inp--title" data-field="title" type="text" value="" placeholder="タスク名（必須）">
    </td>
    <td class="til-cell til-cell--url">
      <div class="til-url-wrap"><input class="til-inp til-inp--url" data-field="task_url" type="text" value="" placeholder="https://..."></div>
    </td>
    <td class="til-cell til-cell--today">
      <label class="til-chk-wrap" title="今日のタスク">
        <input type="checkbox" class="til-chk" data-field="is_today">
        <span class="til-chk-ui"></span>
      </label>
    </td>
    <td class="til-cell til-cell--today-hours">
      <input class="til-inp til-inp--num" data-field="today_hours" type="number" min="0" step="0.5" value="" placeholder="0.0">
    </td>
    <td class="til-cell til-cell--priority">
      <select class="til-sel" data-field="priority" data-value="中">
        <option value="高">高</option><option value="中" selected>中</option><option value="低">低</option>
      </select>
    </td>
    <td class="til-cell til-cell--start">
      <input class="til-inp til-inp--date" data-field="start_date" type="date" value="">
    </td>
    <td class="til-cell til-cell--due">
      <input class="til-inp til-inp--date" data-field="due_date" type="date" value="">
    </td>
    <td class="til-cell til-cell--est">
      <input class="til-inp til-inp--num" data-field="estimated_hours" type="number" min="0" step="0.5" value="" placeholder="0.0">
    </td>
    <td class="til-cell til-cell--progress">
      <select class="til-sel" data-field="progress" data-value="未着手">
        <option value="未着手" selected>未着手</option>
        <option value="進行中">進行中</option>
        <option value="確認待ち">確認待ち</option>
        <option value="完了">完了</option>
      </select>
    </td>
    <td class="til-cell til-cell--notes">
      <input class="til-inp til-inp--notes" data-field="notes" type="text" value="" placeholder="メモ">
    </td>
    <td class="til-cell til-cell--category">
      <select class="til-sel til-sel--category" data-field="task_category">
        <option value="タスク管理"${(!isRecurNew && !isPRNew) ? ' selected' : ''}>タスク管理</option>
        <option value="定期タスク"${isRecurNew ? ' selected' : ''}>定期タスク</option>
        <option value="PR管理"${isPRNew ? ' selected' : ''}>PR管理</option>
      </select>
    </td>
    <td class="til-cell til-cell--del">
      <button class="til-btn-cancel" title="キャンセル"><i class="fas fa-times"></i></button>
    </td>`;
}

// ── 引継ぎタスクテーブル HTML ─────────────────────────────────
// 依頼元・依頼先ともに優先度・完了予定日・今日・今日時間・進捗・メモを編集可能。
// 編集後は行末の「保存」ボタンを押して確定する。
function _buildHandoverTable(tasks, staffName, sid) {
  const today = new Date(); today.setHours(0,0,0,0);

  // スタッフ選択肢（引継者セレクト用）
  const handoverOpts = ['<option value="">— なし —</option>',
    ..._activeAccounts().map(a => `<option value="${escHtml(a.name)}">${escHtml(a.name)}</option>`)
  ].join('');

  const mkSelSimple = (name, options, val, cls='') => {
    const optsHTML = options.map(o =>
      `<option value="${o}"${o === val ? ' selected' : ''}>${o}</option>`).join('');
    return `<select class="til-sel${cls?' '+cls:''}" data-field="${name}" data-value="${val || ''}">${optsHTML}</select>`;
  };

  const rows = tasks.map(t => {
    const isDone = t.progress === '完了';
    const isDue  = !isDone && t.due_date && new Date(t.due_date + 'T00:00:00') < today;
    const rowCls = `hov-row${isDone?' hov-row--done':''}${isDue?' hov-row--overdue':''}`;

    // 自分が依頼元か依頼先か
    const isOwner  = t.assignee === staffName;
    const roleChip = isOwner
      ? `<span class="hov-role-chip hov-role-chip--owner"><i class="fas fa-paper-plane"></i> 依頼中</span>`
      : `<span class="hov-role-chip hov-role-chip--worker"><i class="fas fa-share"></i> 依頼あり</span>`;

    // 引継ぎ履歴チップ
    const buildHovChain = task => {
      const chain = Array.isArray(task.handover_chain) ? task.handover_chain : [];
      if (!chain.length) return '';
      const chips = chain.map((n, i) =>
        `<span class="til-chain-item">${i > 0 ? '<i class="fas fa-arrow-right til-chain-arrow"></i>' : ''}${escHtml(n)}</span>`
      ).join('');
      return `<div class="til-chain-badges">${chips}</div>`;
    };

    // 引継者セル（依頼元：変更可 / 依頼先：再引継ぎ可）
    const handoverCell = `<div class="til-handover-wrap">
      <select class="til-sel til-sel--handover${isOwner?'':' til-sel--rehandover'}" data-field="handover" title="${isOwner?'引継者を変更':'さらに引継ぐ'}">
        ${handoverOpts.replace(
          `value="${escHtml(t.handover||'')}"`,
          `value="${escHtml(t.handover||'')}" selected`
        )}
      </select>
      ${buildHovChain(t)}
    </div>`;

    // 担当者セル
    const assigneeCell = isOwner
      ? `<span class="hov-text-muted">${escHtml(t.assignee||'—')}</span>`
      : `<span class="hov-assignee-chip">${escHtml(t.assignee||'—')}</span>`;

    // ── 以下は依頼元・依頼先どちらも編集可能（保存ボタンで確定） ──

    // 優先度セル
    const priorityCell = mkSelSimple('priority', ['高','中','低'], t.priority||'中', 'til-sel--priority');

    // 完了予定日セル
    const dueDateCell = `<input class="til-inp til-inp--date" data-field="due_date" type="date"
      value="${escHtml(t.due_date||'')}" title="完了予定日">`;

    // 今日チェックセル
    const todayCell = `<label class="til-chk-wrap">
      <input type="checkbox" class="til-chk" data-field="is_today"${t.is_today?' checked':''}>
      <span class="til-chk-ui"></span>
    </label>`;

    // 今日時間セル
    const todayHoursCell = `<input class="til-inp til-inp--num" data-field="today_hours" type="number"
      min="0" step="0.5" value="${t.today_hours!=null?t.today_hours:''}" placeholder="0.0">`;

    // 進捗セル
    const progressCell = mkSelSimple('progress', ['未着手','進行中','確認待ち','完了'], t.progress||'未着手');

    // メモセル
    const notesCell = `<input class="til-inp til-inp--notes" data-field="notes" type="text"
      value="${escHtml(t.notes||'')}" placeholder="メモ">`;

    // アクションセル：依頼元で引継先が完了した場合は確認・完了/差し戻し + 保存ボタン
    // 差し戻し先 = handover_chain の末尾（完了にした引継ぎ者）
    const chain = Array.isArray(t.handover_chain) ? t.handover_chain : [];
    const lastHandover = chain.length >= 1 ? chain[chain.length - 1] : null;
    const chainJson = escHtml(JSON.stringify(chain));
    const confirmBtns = (isOwner && isDone)
      ? `<button class="dlg-btn-confirm" data-id="${escHtml(t.id)}" title="引継ぎ完了を確認・承認">
           <i class="fas fa-check-circle"></i> 確認・完了
         </button>
         <button class="dlg-btn-return"
           data-id="${escHtml(t.id)}"
           data-last-handover="${escHtml(lastHandover||'')}"
           data-chain="${chainJson}"
           title="完了にした引継ぎ者へ差し戻す">
           <i class="fas fa-undo"></i> 差し戻し${lastHandover ? `（→${escHtml(lastHandover)}）` : '（自分に戻す）'}
         </button>
         <button class="dlg-btn-mytask"
           data-id="${escHtml(t.id)}"
           title="引継ぎを解除して自分のタスクに戻す">
           <i class="fas fa-user-check"></i> Myタスクへ戻す
         </button>`
      : '';

    const actionCell = `<div class="hov-action-wrap">
      ${confirmBtns}
      <button class="hov-btn-save" data-id="${escHtml(t.id)}" title="変更を保存">
        <i class="fas fa-save"></i> 保存
      </button>
    </div>`;

    return `<tr class="${rowCls}" data-id="${escHtml(t.id)}" data-role="${isOwner?'owner':'worker'}">
      <td class="hov-cell hov-cell--role">${roleChip}</td>
      <td class="hov-cell hov-cell--assignee">${assigneeCell}</td>
      <td class="hov-cell hov-cell--handover">${handoverCell}</td>
      <td class="hov-cell hov-cell--store">${escHtml(t.store_name||'—')}</td>
      <td class="hov-cell hov-cell--title">${escHtml(t.title||'（無題）')}</td>
      <td class="hov-cell hov-cell--priority">${priorityCell}</td>
      <td class="hov-cell hov-cell--due">${dueDateCell}</td>
      <td class="hov-cell hov-cell--today">${todayCell}</td>
      <td class="hov-cell hov-cell--today-hours">${todayHoursCell}</td>
      <td class="hov-cell hov-cell--progress">${progressCell}</td>
      <td class="hov-cell hov-cell--notes">${notesCell}</td>
      <td class="hov-cell hov-cell--action">${actionCell}</td>
    </tr>`;
  }).join('');

  return `
  <table class="hov-table" id="hov-table-${sid}">
    <thead>
      <tr class="hov-thead">
        <th class="hov-th hov-th--role"></th>
        <th class="hov-th hov-th--assignee">担当者</th>
        <th class="hov-th hov-th--handover">引継者</th>
        <th class="hov-th hov-th--store">店舗名</th>
        <th class="hov-th hov-th--title">タスク名</th>
        <th class="hov-th hov-th--priority">優先度</th>
        <th class="hov-th hov-th--due">完了予定日</th>
        <th class="hov-th hov-th--today">今日</th>
        <th class="hov-th hov-th--today-hours">今日時間</th>
        <th class="hov-th hov-th--progress">進捗</th>
        <th class="hov-th hov-th--notes">メモ</th>
        <th class="hov-th hov-th--action"></th>
      </tr>
    </thead>
    <tbody id="hov-tbody-${sid}">${rows}</tbody>
  </table>`;
}

// ── 引継ぎ中タスクテーブル HTML（自分が依頼した側・閲覧＋承認） ─────────────
function _buildDelegatedTable(tasks, staffName, sid) {
  const today = new Date(); today.setHours(0,0,0,0);
  const fmtDate = d => {
    if (!d) return '—';
    const dt = new Date(d + 'T00:00:00');
    return `${dt.getFullYear()}/${String(dt.getMonth()+1).padStart(2,'0')}/${String(dt.getDate()).padStart(2,'0')}`;
  };

  const rows = tasks.map(t => {
    const isDone  = t.progress === '完了';
    const isDue   = !isDone && t.due_date && new Date(t.due_date + 'T00:00:00') < today;
    const pcfg    = PROGRESS_CFG[t.progress]  || PROGRESS_CFG['未着手'];
    const prcfg   = PRIORITY_CFG[t.priority] || PRIORITY_CFG['中'];
    const rowCls  = `dlg-row${isDone?' dlg-row--done':''}${isDue?' dlg-row--overdue':''}`;

    return `<tr class="${rowCls}" data-id="${escHtml(t.id)}">
      <td class="dlg-cell dlg-cell--handover">
        <span class="dlg-handover-chip">${escHtml(t.handover||'—')}</span>
      </td>
      <td class="dlg-cell dlg-cell--store">${escHtml(t.store_name||'—')}</td>
      <td class="dlg-cell dlg-cell--title">${escHtml(t.title||'（無題）')}</td>
      <td class="dlg-cell dlg-cell--priority">
        <span class="task-prior-badge ${prcfg.cls}">${prcfg.label}</span>
      </td>
      <td class="dlg-cell dlg-cell--due">${fmtDate(t.due_date)}</td>
      <td class="dlg-cell dlg-cell--est">${t.estimated_hours!=null?t.estimated_hours+'h':'—'}</td>
      <td class="dlg-cell dlg-cell--progress">
        <span class="task-progress-badge ${pcfg.cls}">${pcfg.label}</span>
      </td>
      <td class="dlg-cell dlg-cell--notes">${escHtml(t.notes||'')}</td>
      <td class="dlg-cell dlg-cell--action">
        ${isDone
          ? `<div class="dlg-action-btns">
               <button class="dlg-btn-confirm" data-id="${escHtml(t.id)}">
                 <i class="fas fa-check-circle"></i> 確認・完了
               </button>
               <button class="dlg-btn-return" data-id="${escHtml(t.id)}" data-handover="${escHtml(t.handover||'')}" title="引継ぎ者に差し戻す">
                 <i class="fas fa-undo"></i> 差し戻し
               </button>
             </div>`
          : `<span class="dlg-status-working"><i class="fas fa-spinner fa-spin"></i> 対応中</span>`
        }
      </td>
    </tr>`;
  }).join('');

  return `
  <table class="dlg-table" id="dlg-table-${sid}">
    <thead>
      <tr class="dlg-thead">
        <th class="dlg-th dlg-th--handover">引継先</th>
        <th class="dlg-th dlg-th--store">店舗名</th>
        <th class="dlg-th dlg-th--title">タスク名</th>
        <th class="dlg-th dlg-th--priority">優先度</th>
        <th class="dlg-th dlg-th--due">完了予定日</th>
        <th class="dlg-th dlg-th--est">予測時間</th>
        <th class="dlg-th dlg-th--progress">進捗</th>
        <th class="dlg-th dlg-th--notes">メモ</th>
        <th class="dlg-th dlg-th--action"></th>
      </tr>
    </thead>
    <tbody>${rows}</tbody>
  </table>`;
}

// ── 完了タスクテーブル HTML ────────────────────────────────────
function _buildDoneTable(tasks, sid) {
  const now = Date.now();
  const ONE_WEEK_MS = 7 * 24 * 60 * 60 * 1000;
  const fmtDate = d => {
    if (!d) return '—';
    const dt = new Date(d+'T00:00:00');
    return `${dt.getFullYear()}/${String(dt.getMonth()+1).padStart(2,'0')}/${String(dt.getDate()).padStart(2,'0')}`;
  };
  const fmtDatetime = ms => {
    if (!ms) return '—';
    const dt = new Date(ms);
    return `${dt.getFullYear()}/${String(dt.getMonth()+1).padStart(2,'0')}/${String(dt.getDate()).padStart(2,'0')}`;
  };
  // 自動削除までの残り日数を計算（updated_at 基準）
  const calcRemaining = ms => {
    if (!ms) return null;
    const diff = ms + ONE_WEEK_MS - now;
    return Math.ceil(diff / (24 * 60 * 60 * 1000));
  };

  const rows = tasks.map(t => {
    const prcfg    = PRIORITY_CFG[t.priority] || PRIORITY_CFG['中'];
    const remaining = calcRemaining(t.updated_at);
    // 残り日数バッジ
    let expBadge = '';
    if (remaining !== null) {
      if (remaining <= 0) {
        expBadge = `<span class="done-exp-badge done-exp-badge--expired">削除予定</span>`;
      } else if (remaining <= 2) {
        expBadge = `<span class="done-exp-badge done-exp-badge--soon">あと${remaining}日</span>`;
      } else {
        expBadge = `<span class="done-exp-badge">あと${remaining}日</span>`;
      }
    }
    // 引継完了コピーフラグ
    const isCopy = !!(t.is_handover_copy);
    // 進捗変更セレクト（is_handover_copy=true の行は非表示）
    const progressSel = isCopy
      ? `<span class="done-copy-readonly">完了</span>`
      : `
      <select class="done-prog-sel" data-field="progress" data-id="${escHtml(t.id)}" data-value="完了">
        <option value="未着手">未着手</option>
        <option value="進行中">進行中</option>
        <option value="確認待ち">確認待ち</option>
        <option value="完了" selected>完了</option>
      </select>`;
    // URL リンク
    const urlCell = t.task_url
      ? `<a class="done-url-link" href="${escHtml(t.task_url)}" target="_blank" rel="noopener noreferrer" title="${escHtml(t.task_url)}"><i class="fas fa-external-link-alt"></i></a>`
      : '—';
    // 引継者
    const handoverCell = t.handover && t.handover !== t.assignee
      ? `<span class="done-handover-chip">${escHtml(t.handover)}</span>`
      : '<span style="color:var(--gray-300);">—</span>';

    return `<tr class="done-row${remaining !== null && remaining <= 2 ? ' done-row--expiring' : ''}${isCopy ? ' done-row--copy' : ''}" data-id="${escHtml(t.id)}" data-copy="${isCopy?'1':'0'}">
      <td class="done-cell done-cell--assignee">
        <span class="done-assignee-chip">${escHtml(t.assignee||'—')}</span>
        ${isCopy ? `<span class="done-copy-badge" title="引継ぎタスクの完了コピー"><i class="fas fa-share-square"></i> 引継完了</span>` : ''}
      </td>
      <td class="done-cell done-cell--handover">${handoverCell}</td>
      <td class="done-cell done-cell--store">${escHtml(t.store_name||'—')}</td>
      <td class="done-cell done-cell--title">
        <span class="done-title-text" title="${escHtml(t.title||'')}">${escHtml(t.title||'（無題）')}</span>
      </td>
      <td class="done-cell done-cell--url">${urlCell}</td>
      <td class="done-cell done-cell--today-hours">${t.today_hours!=null ? t.today_hours+'h' : '—'}</td>
      <td class="done-cell done-cell--priority">
        <span class="task-prior-badge ${prcfg.cls}">${prcfg.label}</span>
      </td>
      <td class="done-cell done-cell--start">${fmtDate(t.start_date)}</td>
      <td class="done-cell done-cell--due">${fmtDate(t.due_date)}</td>
      <td class="done-cell done-cell--completed">
        ${fmtDatetime(t.updated_at)}${expBadge ? '<br>' + expBadge : ''}
      </td>
      <td class="done-cell done-cell--hours">${t.estimated_hours!=null ? t.estimated_hours+'h' : '—'}</td>
      <td class="done-cell done-cell--progress">${progressSel}</td>
      <td class="done-cell done-cell--notes">${escHtml(t.notes||'')}</td>
      <td class="done-cell done-cell--category">
        <span class="done-cat-badge">${escHtml(t.task_category||'タスク管理')}</span>
      </td>
      <td class="done-cell done-cell--del">
        <button class="done-btn-del" data-id="${escHtml(t.id)}" title="削除"><i class="fas fa-trash"></i></button>
      </td>
    </tr>`;
  }).join('');
  return `
  <div class="arc-table-wrap">
    <table class="done-table" id="done-table-${sid}">
      <thead><tr class="done-thead">
        <th class="done-th done-th--assignee">担当者</th>
        <th class="done-th done-th--handover">引継者</th>
        <th class="done-th done-th--store">店舗名</th>
        <th class="done-th done-th--title">タスク名</th>
        <th class="done-th done-th--url">URL</th>
        <th class="done-th done-th--today-hours">今日時間</th>
        <th class="done-th done-th--priority">優先度</th>
        <th class="done-th done-th--start">開始日</th>
        <th class="done-th done-th--due">完了予定日</th>
        <th class="done-th done-th--completed">完了日</th>
        <th class="done-th done-th--hours">予測時間</th>
        <th class="done-th done-th--progress">進捗</th>
        <th class="done-th done-th--notes">メモ</th>
        <th class="done-th done-th--category">管理区分</th>
        <th class="done-th"></th>
      </tr></thead>
      <tbody>${rows}</tbody>
    </table>
  </div>`;
}

// ── 引継ぎタスクテーブル イベント（依頼元・依頼先ともに保存ボタンで一括保存） ──
function _bindHandoverTableEvents(panel, staffName) {
  const sid   = _staffId(staffName);
  const tbody = panel.querySelector(`#hov-tbody-${sid}`);
  if (!tbody) return;

  // ── 行データを収集するヘルパー ──
  const collectHovRow = row => {
    const get = f => row.querySelector(`[data-field="${f}"]`);
    const val = f => (get(f)?.value ?? '').trim();
    const num = f => { const v = get(f)?.value; return (v !== '' && v != null) ? parseFloat(v) : null; };
    const chk = f => !!get(f)?.checked;
    const isTodayChecked = chk('is_today');
    return {
      // handover は change イベントで即時PATCH済みのため保存ボタンのペイロードから除外
      priority    : val('priority') || null,
      due_date    : val('due_date') || null,
      is_today    : isTodayChecked,
      today_date  : isTodayChecked ? _todayStr() : null,
      today_hours : num('today_hours'),
      progress    : val('progress') || '未着手',
      notes       : val('notes')    || null,
    };
  };

  // ── 行を「未保存」状態にマークするヘルパー ──
  const markDirtyHov = row => {
    if (!row) return;
    row.dataset.dirty = 'true';
    const saveBtn = row.querySelector('.hov-btn-save');
    if (saveBtn) saveBtn.classList.add('hov-btn-save--dirty');
  };

  // ── 変更検知（input / change / checkbox）→ markDirty のみ ──
  tbody.addEventListener('input', e => {
    const el = e.target.closest('[data-field]');
    if (!el) return;
    const field = el.dataset.field;
    // is_today OFF 時は today_hours を即クリア（視覚的に）
    if (el.type === 'checkbox' && field === 'is_today' && !el.checked) {
      const row = el.closest('tr');
      const thInp = row?.querySelector('input[data-field="today_hours"]');
      if (thInp) thInp.value = '';
    }
    markDirtyHov(el.closest('tr'));
  });

  tbody.addEventListener('change', e => {
    const el = e.target.closest('select[data-field], input[type="checkbox"][data-field]');
    if (!el) return;
    const field = el.dataset.field;
    const row   = el.closest('tr');

    // handover（引継者）のみ：変更の都度即時 PATCH（引継者変更は handover_chain も更新が必要なため）
    if (field === 'handover') {
      const id = row?.dataset.id;
      if (!id) return;
      el.disabled = true;
      const value = el.value || null;
      const task  = _allTasks.find(x => x.id === id);
      let chain   = Array.isArray(task?.handover_chain) ? [...task.handover_chain] : [];
      if (value) {
        if (chain[chain.length - 1] !== value) chain.push(value);
      } else {
        chain = [];
      }
                _saveTableFields('tasks', id, { handover: value, handover_chain: chain })
        .then(() => {
          if (value) showToast(`「${value}」へ引継ぎ依頼しました`, 'success');
          else       showToast('引継者を解除しました', 'info');
          loadTasks();
        })
        .catch(err => {
          console.error('hov handover change error', err);
          showToast('引継者の変更に失敗しました', 'error');
          el.disabled = false;
        });
      return; // handover は即時保存 → markDirty 不要
    }

    // その他フィールドはmarkDirtyのみ（is_today 用 data-value 更新）
    if (el.dataset.value !== undefined) el.dataset.value = el.value;
    markDirtyHov(row);
  });

  // ── click 委譲（保存ボタン / 確認・完了 / 差し戻し） ──
  tbody.addEventListener('click', async e => {
    // 保存ボタン
    const saveBtn = e.target.closest('.hov-btn-save');
    if (saveBtn) {
      const row = saveBtn.closest('tr');
      const id  = row?.dataset.id;
      if (!id) return;
      const payload = collectHovRow(row);
      saveBtn.disabled = true;
      try {
        // 引継ぎ者（worker）が「完了」にした場合 → コピーレコード作成
        const isWorker     = row.dataset.role === 'worker';
        const becomingDone = payload.progress === '完了';
        const originalTask = _allTasks.find(x => x.id === id);
        const handoverName = originalTask?.handover || null;

        // 元タスクに payload をマージしたスナップショットを作成（today_hours 等の最新値を取得）
        const taskSnapshot = Object.assign({}, originalTask, payload);

        // worker が完了にする場合は元タスクも is_today:false にして高尾側への混入を防ぐ
        const finalPayload = (isWorker && becomingDone)
          ? Object.assign({}, payload, { is_today: false, today_date: _todayStr() })
          : (becomingDone ? Object.assign({}, payload, { today_date: _todayStr() }) : payload);

        await _saveTableFields('tasks', id, finalPayload);
        row.dataset.dirty = '';
        saveBtn.classList.remove('hov-btn-save--dirty');
        saveBtn.disabled = false;

        // コピー作成（worker が完了にした時のみ・payload の最新値を使用）
        if (isWorker && becomingDone && handoverName) {
          await _createHandoverCopy(taskSnapshot, handoverName);
        }

        showToast('保存しました', 'success');
        await loadTasks();
      } catch(err) {
        console.error('hov save error', err);
        showToast('保存に失敗しました', 'error');
        saveBtn.disabled = false;
      }
      return;
    }

    // 確認・完了ボタン
    const confirmBtn = e.target.closest('.dlg-btn-confirm');
    if (confirmBtn) {
      const id = confirmBtn.dataset.id;
      if (!id) return;
      const t = _allTasks.find(x => x.id === id);
      if (!t) return;
      if (!confirm(`「${t.title}」の引継ぎ完了を確認しますか？\n完了タスクとして記録されます。`)) return;
      try {
        // is_today=false も同時に送ることで、高尾の today_hours 集計に混入しないようにする
        // （小池のコピーレコードに is_today=true が残るため、小池の時間は維持される）
                await _saveTableFields('tasks', id, { progress: '完了', handover: null, is_today: false, today_date: _todayStr() });
        showToast('引継ぎ完了を承認しました', 'success');
        await loadTasks();
      } catch(err) {
        console.error('confirmHandover error', err);
        showToast('処理に失敗しました', 'error');
      }
      return;
    }

    // Myタスクへ戻すボタン
    const myTaskBtn = e.target.closest('.dlg-btn-mytask');
    if (myTaskBtn) {
      const id = myTaskBtn.dataset.id;
      if (!id) return;
      const t = _allTasks.find(x => x.id === id);
      if (!t) return;
      if (!confirm(`「${t.title}」の引継ぎを解除して自分のタスクに戻しますか？\n進捗が「進行中」に戻ります。`)) return;
      try {
        await _saveTableFields('tasks', id, {
          progress: '進行中',
          handover: null,
        });
        showToast(`「${t.title}」をMyタスクへ戻しました`, 'success');
        await loadTasks();
      } catch(err) {
        console.error('myTaskReturn error', err);
        showToast('処理に失敗しました', 'error');
      }
      return;
    }

    // 差し戻しボタン
    const returnBtn = e.target.closest('.dlg-btn-return');
    if (returnBtn) {
      const id           = returnBtn.dataset.id;
      const lastHandover = returnBtn.dataset.lastHandover || null; // 完了にした引継ぎ者
      let   chain;
      try { chain = JSON.parse(returnBtn.dataset.chain || '[]'); } catch { chain = []; }
      if (!id) return;
      const t = _allTasks.find(x => x.id === id);
      if (!t) return;
      const dest = lastHandover || '依頼元（自分）';
      if (!confirm(`「${t.title}」を「${dest}」へ差し戻しますか？\n進捗が「進行中」に戻ります。`)) return;
      try {
        // handover を完了にした引継ぎ者に戻す（chain・assignee は変更しない）
        await _saveTableFields('tasks', id, {
          progress: '進行中',
          handover: lastHandover || null,
        });
        showToast(`「${t.title}」を「${dest}」へ差し戻しました`, 'info');
        await loadTasks();
      } catch(err) {
        console.error('returnHandover error', err);
        showToast('差し戻しに失敗しました', 'error');
      }
      return;
    }
  });
}

// ── 引継ぎ中タスクテーブル イベント（依頼元が確認・完了 / 差し戻し） ────────
function _bindDelegatedTableEvents(panel, staffName) {
  panel.querySelectorAll('.dlg-btn-confirm').forEach(btn => {
    btn.addEventListener('click', async () => {
      const id = btn.dataset.id;
      if (!id) return;
      const t = _allTasks.find(x => x.id === id);
      if (!t) return;
      const msg = `「${t.title}」の引継ぎ完了を確認しますか？\n完了タスクとして記録されます。`;
      if (!confirm(msg)) return;
      try {
        // is_today=false も同時に送ることで、assignee 側の today_hours 集計に混入しないようにする
                await _saveTableFields('tasks', id, { progress: '完了', handover: null, is_today: false, today_date: _todayStr() });
        showToast('引継ぎ完了を承認しました', 'success');
        await loadTasks();
      } catch(err) {
        console.error('confirmDelegated error', err);
        showToast('処理に失敗しました', 'error');
      }
    });
  });

  // 差し戻し：引継ぎ者のタスクに戻し、進捗を「進行中」にする
  panel.querySelectorAll('.dlg-btn-return').forEach(btn => {
    btn.addEventListener('click', async () => {
      const id       = btn.dataset.id;
      const handover = btn.dataset.handover;
      if (!id) return;
      const t = _allTasks.find(x => x.id === id);
      if (!t) return;
      const msg = `「${t.title}」を${handover ? `「${handover}」` : '引継ぎ者'}へ差し戻しますか？\n進捗が「進行中」に戻ります。`;
      if (!confirm(msg)) return;
      try {
        await _saveTableFields('tasks', id, { progress: '進行中' });
        showToast(`「${t.title}」を差し戻しました`, 'info');
        await loadTasks();
      } catch(err) {
        console.error('returnDelegated error', err);
        showToast('差し戻しに失敗しました', 'error');
      }
    });
  });
}

// ── 完了タスクテーブル イベント ───────────────────────────────
function _bindDoneTableEvents(panel, staffName) {
  const sid = _staffId(staffName);

  // ── 通常完了保管庫 アコーディオントグル ──
  const toggleBtn = panel.querySelector(`#arc-toggle-${sid}`);
  const arcBody   = panel.querySelector(`#arc-body-${sid}`);
  if (toggleBtn && arcBody) {
    const storageKey = `arc-open-${sid}`;
    const savedOpen  = sessionStorage.getItem(storageKey) === 'true';
    if (savedOpen) {
      arcBody.hidden = false;
      toggleBtn.setAttribute('aria-expanded', 'true');
      toggleBtn.classList.add('arc-toggle-btn--open');
    }
    toggleBtn.addEventListener('click', () => {
      const isOpen = !arcBody.hidden;
      arcBody.hidden = isOpen;
      toggleBtn.setAttribute('aria-expanded', String(!isOpen));
      toggleBtn.classList.toggle('arc-toggle-btn--open', !isOpen);
      sessionStorage.setItem(storageKey, String(!isOpen));
    });
  }

  // ── PR管理 完了保管庫 アコーディオントグル ──
  const prToggleBtn = panel.querySelector(`#pr-arc-toggle-${sid}`);
  const prArcBody   = panel.querySelector(`#pr-arc-body-${sid}`);
  if (prToggleBtn && prArcBody) {
    const prStorageKey = `pr-arc-open-${sid}`;
    const prSavedOpen  = sessionStorage.getItem(prStorageKey) === 'true';
    if (prSavedOpen) {
      prArcBody.hidden = false;
      prToggleBtn.setAttribute('aria-expanded', 'true');
      prToggleBtn.classList.add('arc-toggle-btn--open');
    }
    prToggleBtn.addEventListener('click', () => {
      const isOpen = !prArcBody.hidden;
      prArcBody.hidden = isOpen;
      prToggleBtn.setAttribute('aria-expanded', String(!isOpen));
      prToggleBtn.classList.toggle('arc-toggle-btn--open', !isOpen);
      sessionStorage.setItem(prStorageKey, String(!isOpen));
    });
  }

  // ── 定期タスク 完了保管庫 アコーディオントグル ──
  const recurToggleBtn = panel.querySelector(`#recur-arc-toggle-${sid}`);
  const recurArcBody   = panel.querySelector(`#recur-arc-body-${sid}`);
  if (recurToggleBtn && recurArcBody) {
    const recurStorageKey = `recur-arc-open-${sid}`;
    const recurSavedOpen  = sessionStorage.getItem(recurStorageKey) === 'true';
    if (recurSavedOpen) {
      recurArcBody.hidden = false;
      recurToggleBtn.setAttribute('aria-expanded', 'true');
      recurToggleBtn.classList.add('arc-toggle-btn--open');
    }
    recurToggleBtn.addEventListener('click', () => {
      const isOpen = !recurArcBody.hidden;
      recurArcBody.hidden = isOpen;
      recurToggleBtn.setAttribute('aria-expanded', String(!isOpen));
      recurToggleBtn.classList.toggle('arc-toggle-btn--open', !isOpen);
      sessionStorage.setItem(recurStorageKey, String(!isOpen));
    });
  }

  // 進捗セレクト変更 → 即時 PATCH（完了以外に変更でタスク管理へ移動）
  panel.querySelectorAll('.done-prog-sel').forEach(sel => {
    sel.addEventListener('change', async () => {
      const id  = sel.dataset.id;
      const val = sel.value;
      if (!id) return;
      // data-value を更新して CSS 色付けを反映
      sel.dataset.value = val;
      sel.disabled = true;
      try {
        await _saveTableFields('tasks', id, { progress: val });
        if (val !== '完了') {
          showToast(`進捗を「${val}」に変更し、タスク管理へ移動しました`, 'success');
        }
        await loadTasks();
      } catch(err) {
        console.error('done progress change error', err);
        showToast('保存に失敗しました', 'error');
        sel.disabled = false;
      }
    });
  });

  // 削除ボタン
  panel.querySelectorAll('.done-btn-del').forEach(btn => {
    btn.addEventListener('click', async () => {
      const id = btn.dataset.id;
      const t  = _allTasks.find(x => x.id === id);
      if (!t || !confirm(`「${t.title}」を保管庫から削除しますか？\nこの操作は元に戻せません。`)) return;
      try {
        await API.delete('tasks', id);
        showToast('タスクを削除しました', 'success');
        await loadTasks();
      } catch(err) {
        showToast('削除に失敗しました', 'error');
      }
    });
  });
}

// ── テーブル行クリックでモーダル（ダッシュボード用・互換維持） ─
// ══════════════════════════════════════════════════════════════
//  スケジュール管理
