const DOW_LABELS = ['日', '月', '火', '水', '木', '金', '土'];

// ── 全角コロン・全角数字を半角に正規化して "HH:mm" 形式に変換（カレンダー表示等で使用）──
function _normalizeTimeInput(val) {
  if (!val) return '';
  // 全角→半角
  let s = val
    .replace(/[０-９]/g, c => String.fromCharCode(c.charCodeAt(0) - 0xFEE0))
    .replace(/[：]/g, ':')
    .trim();
  // "1100" → "11:00"
  if (/^\d{3,4}$/.test(s)) {
    s = s.length === 3 ? '0' + s : s;
    s = s.slice(0, 2) + ':' + s.slice(2);
  }
  // "11:0" → "11:00"
  const m = s.match(/^(\d{1,2}):(\d{1,2})$/);
  if (m) {
    s = m[1].padStart(2, '0') + ':' + m[2].padStart(2, '0');
  }
  // 範囲チェック
  const [hh, mm] = s.split(':').map(Number);
  if (isNaN(hh) || isNaN(mm) || hh > 23 || mm > 59) return '';
  return s;
}

function _bindTableRowEvents(container) {
  container.querySelectorAll('.task-row').forEach(row => {
    row.addEventListener('click', () => openTaskModal(row.dataset.id));
  });
}

function updateTaskNavBadge() {
  const badge = document.getElementById('nav-badge-tasks');
  if (!badge) return;
  const openCnt = _allTasks.filter(t => t.progress !== '完了').length;
  badge.textContent = openCnt > 0 ? openCnt : '';
  badge.style.display = openCnt > 0 ? '' : 'none';
}

function openTaskModal(id = null, defaultAssignee = '') {
  const isNew = !id;
  document.getElementById('task-modal-title').textContent = isNew ? 'タスクを追加' : 'タスクを編集';
  document.getElementById('task-id').value = id || '';
  document.getElementById('task-delete-btn').style.display = isNew ? 'none' : '';
  const staffOptions = ['<option value="">— 未設定 —</option>',
    ..._activeAccounts().map(a=>`<option value="${escHtml(a.name)}">${escHtml(a.name)}</option>`)].join('');
  document.getElementById('task-assignee').innerHTML = staffOptions;
  document.getElementById('task-handover').innerHTML = '<option value="">— なし —</option>'+
    _activeAccounts().map(a=>`<option value="${escHtml(a.name)}">${escHtml(a.name)}</option>`).join('');

  if (isNew) {
    document.getElementById('task-title').value          = '';
    document.getElementById('task-assignee').value       = defaultAssignee||(_taskCurrentStaff!=='dashboard'?_taskCurrentStaff:'');
    document.getElementById('task-handover').value       = '';
    document.getElementById('task-store-name').value     = '';
    document.getElementById('task-priority').value       = '';
    document.getElementById('task-start-date').value     = '';
    document.getElementById('task-due-date').value       = '';
    document.getElementById('task-estimated-hours').value= '';
    document.getElementById('task-progress').value       = '未着手';
    document.getElementById('task-is-today').checked     = false;
    document.getElementById('task-today-hours').value    = '';
    document.getElementById('task-notes').value          = '';
  } else {
    const t = _allTasks.find(x => x.id === id);
    if (!t) return;
    document.getElementById('task-title').value          = t.title||'';
    document.getElementById('task-assignee').value       = t.assignee||'';
    document.getElementById('task-handover').value       = t.handover||'';
    document.getElementById('task-store-name').value     = t.store_name||'';
    document.getElementById('task-priority').value       = t.priority||'';
    document.getElementById('task-start-date').value     = t.start_date||'';
    document.getElementById('task-due-date').value       = t.due_date||'';
    document.getElementById('task-estimated-hours').value= t.estimated_hours!=null?t.estimated_hours:'';
    document.getElementById('task-progress').value       = t.progress||'未着手';
    document.getElementById('task-is-today').checked     = !!t.is_today;
    document.getElementById('task-today-hours').value    = t.today_hours!=null?t.today_hours:'';
    document.getElementById('task-notes').value          = t.notes||'';
  }
  document.getElementById('modal-task').style.display = 'flex';
  document.getElementById('task-title').focus();
}

async function saveTask() {
  const title = document.getElementById('task-title').value.trim();
  if (!title) { showToast('タスク名を入力してください','error'); return; }
  const id     = document.getElementById('task-id').value;
  const estH   = document.getElementById('task-estimated-hours').value;
  const todayH = document.getElementById('task-today-hours').value;
  const isTodayModalChecked = document.getElementById('task-is-today').checked;
  const payload = {
    title:           title,
    assignee:        document.getElementById('task-assignee').value,
    handover:        document.getElementById('task-handover').value,
    store_name:      document.getElementById('task-store-name').value.trim(),
    priority:        document.getElementById('task-priority').value,
    start_date:      document.getElementById('task-start-date').value,
    due_date:        document.getElementById('task-due-date').value,
    estimated_hours: estH!==''?parseFloat(estH):null,
    progress:        document.getElementById('task-progress').value,
    is_today:        isTodayModalChecked,
    today_date:      isTodayModalChecked ? _todayStr() : null,
    today_hours:     todayH!==''?parseFloat(todayH):null,
    notes:           document.getElementById('task-notes').value.trim(),
  };
  try {
    id ? await _saveTableFields('tasks', id, payload) : await API.post('tasks', payload);
    document.getElementById('modal-task').style.display = 'none';
    showToast(id?'タスクを更新しました':'タスクを追加しました','success');
    await loadTasks();
  } catch(e) { console.error('saveTask error',e); showToast('保存に失敗しました','error'); }
}

async function deleteTask() {
  const id = document.getElementById('task-id').value;
  if (!id||!confirm('このタスクを削除しますか？')) return;
  try {
    await API.delete('tasks',id);
    document.getElementById('modal-task').style.display = 'none';
    showToast('タスクを削除しました','success');
    await loadTasks();
  } catch(e) { console.error('deleteTask error',e); showToast('削除に失敗しました','error'); }
}

document.getElementById('headerAddBtn')?.addEventListener('click', () => {
  if (currentPage === 'tasks') openTaskModal();
});
document.getElementById('task-save-btn')?.addEventListener('click', saveTask);
document.getElementById('task-delete-btn')?.addEventListener('click', deleteTask);

// ── かんばん描画 ──────────────────────────────────────────────
function renderTaskKanban() {
  const statuses = ['未着手', '進行中', '完了'];
  const q        = _taskSearchText.toLowerCase();

  const filtered = _allTasks.filter(t => {
    const statusMatch = _taskStatusFilter === 'all' || t.status === _taskStatusFilter;
    const priorMatch  = !_taskPriorityFilter || t.priority === _taskPriorityFilter;
    const textMatch   = !q || [t.title, t.assignee, t.related_project, t.notes]
      .some(v => v && v.toLowerCase().includes(q));
    return statusMatch && priorMatch && textMatch;
  });

  statuses.forEach(status => {
    const col   = document.getElementById(`task-cards-${status}`);
    const badge = document.getElementById(`task-badge-${status}`);
    if (!col) return;

    const cards = filtered.filter(t => t.status === status);
    if (badge) badge.textContent = cards.length;

    if (cards.length === 0) {
      col.innerHTML = `<div class="task-empty-col">タスクがありません</div>`;
      return;
    }

    col.innerHTML = cards
      .sort((a, b) => {
        const po = { '高': 0, '中': 1, '低': 2 };
        return (po[a.priority] ?? 1) - (po[b.priority] ?? 1);
      })
      .map(t => buildTaskCard(t))
      .join('');

    // カードクリック → モーダル編集
    col.querySelectorAll('.task-card').forEach(el => {
      el.addEventListener('click', () => openTaskModal(el.dataset.id));
    });
  });
}

// ── タスクカードHTML ──────────────────────────────────────────
function buildTaskCard(t) {
  const priorCls = { '高': 'task-prior-high', '中': 'task-prior-mid', '低': 'task-prior-low' };
  const priorLbl = t.priority || '中';
  const due      = t.due_date ? (() => {
    const d   = new Date(t.due_date + 'T00:00:00');
    const now = new Date();
    now.setHours(0,0,0,0);
    const diff = Math.ceil((d - now) / 86400000);
    const lbl  = `${d.getMonth()+1}/${d.getDate()}`;
    if (diff < 0)  return `<span class="task-due task-due--over">${lbl} 期限切れ</span>`;
    if (diff <= 3) return `<span class="task-due task-due--near">${lbl} あと${diff}日</span>`;
    return `<span class="task-due">${lbl}</span>`;
  })() : '';

  const assignee = t.assignee ? `<span class="task-assignee"><i class="fas fa-user"></i> ${escHtml(t.assignee)}</span>` : '';
  const related  = t.related_project ? `<span class="task-related"><i class="fas fa-briefcase"></i> ${escHtml(t.related_project)}</span>` : '';
  const notes    = t.notes ? `<p class="task-card-notes">${escHtml(t.notes.slice(0, 60))}${t.notes.length > 60 ? '…' : ''}</p>` : '';

  return `
  <div class="task-card" data-id="${escHtml(t.id)}">
    <div class="task-card-top">
      <span class="task-prior-badge ${priorCls[priorLbl] || 'task-prior-mid'}">${priorLbl}</span>
    </div>
    <div class="task-card-title">${escHtml(t.title || '（無題）')}</div>
    ${notes}
    <div class="task-card-meta">
      ${assignee}${related}${due}
    </div>
  </div>`;
}

