// ─── 商品保存 ────────────────────────────────────────────────
document.getElementById('btn-tprod-save')?.addEventListener('click', async () => {
  const storeName = document.getElementById('tprod-store-name').value.trim();
  const prodName  = document.getElementById('tprod-name').value.trim();
  if (!storeName) { showToast('店舗名を入力してください', 'error'); return; }
  if (!prodName)  { showToast('商品名を入力してください', 'error'); return; }

  const id         = document.getElementById('tprod-id').value;
  const price      = parseFloat(document.getElementById('tprod-sale-price').value)      || 0;
  const collection = parseFloat(document.getElementById('tprod-comm-collection').value) || 0;
  const totalRate  = _calcTotalCommRate();
  const totalAmt   = Math.round(price * totalRate / 100);

  const data = {
    store_name:             storeName,
    store_address:          document.getElementById('tprod-store-address').value.trim(),
    store_phone:            document.getElementById('tprod-store-phone').value.trim(),
    store_hours:            _buildStoreHours(),
    product_name:           prodName,
    product_detail:         document.getElementById('tprod-detail').value,
    image_url:              document.getElementById('tprod-image-url').value.trim(),
    sale_price:             price,
    commission_collection:  collection,
    commissions:            _tprodBrokers.map(b => ({ label: b.label, rate: parseFloat(b.rate)||0 })),
    commission_total:       parseFloat(totalRate.toFixed(2)),
    commission_amount:      totalAmt,
    status:                 document.querySelector('input[name="tprod-status"]:checked').value,
    notes:                  document.getElementById('tprod-notes').value.trim()
  };

  try {
    if (id) {
      await API.put('ticket_products', id, data);
      const idx = _allTicketProducts.findIndex(x => x.id === id);
      if (idx >= 0) {
        _allTicketProducts[idx] = { ..._allTicketProducts[idx], ...data };
        // _status_original をリセット → 次回 computeTprodOnSaleStatus で再評価
        delete _allTicketProducts[idx]._status_original;
      }
      showToast('商品を更新しました');
    } else {
      data.sort_order = _allTicketProducts.length + 1;
      const created = await API.post('ticket_products', data);
      _allTicketProducts.push(created);
      showToast('商品を登録しました');
    }
    computeTprodOnSaleStatus();
    renderTprodGrid();
    closeModal('modal-ticket-product');
  } catch(e) {
    console.error(e);
    showToast('保存に失敗しました', 'error');
  }
});

// ─── 商品削除 ────────────────────────────────────────────────
document.getElementById('btn-tprod-delete')?.addEventListener('click', async () => {
  const id = document.getElementById('tprod-id').value;
  if (!id) return;
  const p = _allTicketProducts.find(x => x.id === id);
  if (!confirm(`「${p?.product_name||'この商品'}」を削除してもよいですか？`)) return;
  try {
    await API.delete('ticket_products', id);
    _allTicketProducts = _allTicketProducts.filter(x => x.id !== id);
    renderTprodGrid();
    closeModal('modal-ticket-product');
    showToast('商品を削除しました');
  } catch(e) { showToast('削除に失敗しました', 'error'); }
});

