let _tcatEditSelectedColor = '#e2e8f0';

// ─── カテゴリ一覧描画 ────────────────────────────────────────
function renderTicketCatList() {
  const el = document.getElementById('ticket-cat-list');
  if (!el) return;
  if (_allTicketCatsAll.length === 0) {
    el.innerHTML = '<p style="color:var(--gray-400);font-size:13px;text-align:center;padding:12px 0;">カテゴリがまだありません</p>';
    return;
  }
  el.innerHTML = _allTicketCatsAll.map(c => {
    const isDeleted = !!c.is_deleted;
    return `<div class="svc-mgr-item ${isDeleted ? 'svc-mgr-item-deleted' : ''}">
      <span class="svc-mgr-dot" style="background:${escHtml(c.color||'#e2e8f0')};"></span>
      <span class="svc-mgr-name ${isDeleted?'svc-mgr-name-deleted':''}">${escHtml(c.name)}</span>
      ${isDeleted
        ? `<button class="btn btn-ghost btn-xs svc-restore-btn" onclick="restoreTcat('${c.id}')" title="復元"><i class="fas fa-undo"></i></button>`
        : `<button class="btn btn-ghost btn-xs" onclick="openTcatEditForm('${c.id}')" title="編集"><i class="fas fa-edit"></i></button>
           <button class="btn btn-ghost btn-xs svc-del-btn" onclick="deleteTcat('${c.id}')" title="削除"><i class="fas fa-trash"></i></button>`
      }
    </div>`;
  }).join('');
}

// ─── カテゴリ追加/編集フォームを開く ────────────────────────
function openTcatEditForm(id = null) {
  const form = document.getElementById('ticket-cat-edit-form');
  if (!form) return;

  _tcatEditSelectedColor = '#e2e8f0';
  document.getElementById('tcat-edit-id').value    = '';
  document.getElementById('tcat-edit-name').value  = '';
  document.getElementById('tcat-edit-color').value = '#e2e8f0';

  if (id) {
    const c = _allTicketCatsAll.find(x => x.id === id);
    if (c) {
      document.getElementById('tcat-edit-id').value    = c.id;
      document.getElementById('tcat-edit-name').value  = c.name;
      _tcatEditSelectedColor = c.color || '#e2e8f0';
      document.getElementById('tcat-edit-color').value = _tcatEditSelectedColor;
    }
  }

  // カラーピッカーのアクティブ表示更新
  document.querySelectorAll('#tcat-color-picker .tcat-color-btn').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.color === _tcatEditSelectedColor);
  });

  form.style.display = '';
  document.getElementById('tcat-edit-name').focus();
}

