// ─── カテゴリ保存 ────────────────────────────────────────────
document.getElementById('btn-tcat-edit-save')?.addEventListener('click', async () => {
  const name  = document.getElementById('tcat-edit-name').value.trim();
  const color = document.getElementById('tcat-edit-color').value || '#e2e8f0';
  if (!name) { showToast('カテゴリ名を入力してください', 'error'); return; }
  const id = document.getElementById('tcat-edit-id').value;
  try {
    if (id) {
      await API.put('ticket_categories', id, { name, color });
      const idx = _allTicketCatsAll.findIndex(c => c.id === id);
      if (idx >= 0) _allTicketCatsAll[idx] = { ..._allTicketCatsAll[idx], name, color };
      showToast('カテゴリを更新しました');
    } else {
      const sortOrder = _allTicketCatsAll.length + 1;
      const created = await API.post('ticket_categories', { name, color, sort_order: sortOrder });
      _allTicketCatsAll.push(created);
      showToast('カテゴリを追加しました');
    }
    _allTicketCats = _allTicketCatsAll.filter(c => !c.is_deleted);
    populateTicketCategorySelects();
    renderTicketCatList();
    document.getElementById('ticket-cat-edit-form').style.display = 'none';
  } catch(e) {
    console.error(e);
    showToast('保存に失敗しました', 'error');
  }
});

// ─── カテゴリ削除（ソフトデリート） ─────────────────────────
async function deleteTcat(id) {
  const c = _allTicketCatsAll.find(x => x.id === id);
  if (!c) return;
  if (!confirm(`「${c.name}」を削除してもよいですか？\n既存データはそのまま保持されます。`)) return;
  try {
      await _saveTableFields('ticket_categories', id, { is_deleted: true });
    const idx = _allTicketCatsAll.findIndex(x => x.id === id);
    if (idx >= 0) _allTicketCatsAll[idx].is_deleted = true;
    _allTicketCats = _allTicketCatsAll.filter(c => !c.is_deleted);
    populateTicketCategorySelects();
    renderTicketCatList();
    showToast('カテゴリを削除しました');
  } catch(e) { showToast('削除に失敗しました', 'error'); }
}

// ─── カテゴリ復元 ────────────────────────────────────────────
async function restoreTcat(id) {
  try {
      await _saveTableFields('ticket_categories', id, { is_deleted: false });
    const idx = _allTicketCatsAll.findIndex(x => x.id === id);
    if (idx >= 0) _allTicketCatsAll[idx].is_deleted = false;
    _allTicketCats = _allTicketCatsAll.filter(c => !c.is_deleted);
    populateTicketCategorySelects();
    renderTicketCatList();
    showToast('カテゴリを復元しました');
  } catch(e) { showToast('復元に失敗しました', 'error'); }
}

// ─── カテゴリ管理ツールバーボタン（チケット一覧ページ）───────
document.getElementById('btn-open-ticket-cat-mgr')?.addEventListener('click', async () => {
  try {
    const res = await API.getAll('ticket_categories');
    _allTicketCatsAll = res.data || [];
    _allTicketCats    = _allTicketCatsAll.filter(c => !c.is_deleted);
  } catch(e) { _allTicketCatsAll = [..._allTicketCats]; }
  renderTicketCatList();
  document.getElementById('ticket-cat-edit-form').style.display = 'none';
  document.getElementById('modal-ticket-cat-mgr').classList.add('open');
});


// ─── 提案書ステートを構築 ─────────────────────────────────────
function _buildProposalState(t, prods) {
  const p1 = prods[0] || null;
  const p2 = prods[1] || null;

  // 有効期間文字列
  const bi = Array.isArray(t.billing_items) ? t.billing_items : [];
  const dates   = bi.map(r => r.date_from).filter(Boolean).sort();
  const datesTo = bi.map(r => r.date_to || r.date_from).filter(Boolean).sort();
  const fmtD = s => {
    if (!s) return '';
    const d = new Date(s);
    return isNaN(d) ? s : `${d.getFullYear()}年${d.getMonth()+1}月${d.getDate()}日`;
  };
  const periodFrom = dates[0]   || t.start_date || '';
  const periodTo   = datesTo[datesTo.length-1] || t.end_date   || '';
  const periodStr  = periodFrom
    ? (periodTo && periodTo !== periodFrom ? `${fmtD(periodFrom)}〜${fmtD(periodTo)}` : fmtD(periodFrom))
    : '—';

  return {
    title:        t.title || '',
    period:       periodStr,
    unavailable:  '',
    store_name:   p1?.store_name    || '',
    store_addr:   p1?.store_address || '',
    store_hours:  p1?.store_hours   || '',
    store_desc:   '',
    sub_img1:     '',
    sub_img2:     '',
    notes:        '',
    issuer:       '一般社団法人 Collection',
    phone:        p1?.store_phone   || '',
    prod1_img:    p1?.image_url     || '',
    prod1_name:   p1?.product_name  || '',
    prod1_price:  p1?.sale_price    || '',
    prod1_detail: p1?.product_detail || '',
    prod1_order:  '',
    prod2_img:    p2?.image_url     || '',
    prod2_name:   p2?.product_name  || '',
    prod2_price:  p2?.sale_price    || '',
    prod2_detail: p2?.product_detail || '',
    prod2_order:  '',
    is_two_products: prods.length >= 2,
  };
}

// ─── 提案書ウィンドウ用完全HTMLドキュメント生成 ────────────────
// product_count=1 → A4縦・1商品デザイン
// product_count=2 → A4横・2商品デザイン（従来）
function _buildProposalWindowHtml(s, logoHtml, mapHtml, t) {
  return s.is_two_products
    ? _buildProposalHtml2(s, logoHtml, mapHtml, t)
    : _buildProposalHtml1(s, logoHtml, mapHtml, t);
}

