// ─── 印刷用 商品HTML生成 ─────────────────────────────────────
function _printProdHtml(s, imgData) {
  const card = (n) => {
    const imgSrc  = imgData[`prod${n}_img`] || '';
    const name    = escHtml(s[`prod${n}_name`]  || '');
    const detail  = escHtml(s[`prod${n}_detail`] || '');
    const order   = escHtml(s[`prod${n}_order`]  || '');
    const price   = parseFloat(s[`prod${n}_price`]) || 0;
    return `<div class="prop-prod-card">
      <div class="prop-prod-top">
        <div class="prop-prod-img prop-img-wrap">
          ${imgSrc ? `<img src="${imgSrc}" alt="">` : `<div class="prop-img-placeholder"><i class="fas fa-image"></i></div>`}
        </div>
        <div class="prop-prod-body">
          <div class="prop-prod-name">${name}</div>
          <div class="prop-prod-detail">${detail}</div>
        </div>
      </div>
      <table class="prop-price-table">
        <thead><tr><th class="prop-th-kind">種別</th><th class="prop-th-order">注文番号</th><th class="prop-th-price">販売価格</th></tr></thead>
        <tbody><tr><td>${name}</td><td class="prop-order-td">${order}</td><td class="prop-price-td">${price ? '¥' + price.toLocaleString() : ''}</td></tr></tbody>
      </table>
    </div>`;
  };
  const grid = s.is_two_products
    ? `<div class="prop-prod-grid prop-two">${card(1)}${card(2)}</div>`
    : `<div class="prop-prod-grid prop-one">${card(1)}</div>`;
  return grid;
}

// ─── ここから本物のチケット入金通知書実装 ───────────────────

/* ============================================================
   チケット入金通知書
   ============================================================ */

// ─── 月選択モーダルを開く ────────────────────────────────────
function openTicketMonthSelect(ticketId) {
  const t = _allTickets.find(x => x.id === ticketId);
  if (!t) return;

  // start_date / end_date から月ごとのリストを生成
  const months = _buildMonthRange(t.start_date, t.end_date);

  const grid  = document.getElementById('tmonth-grid');
  const title = document.getElementById('tmonth-modal-title');
  const desc  = document.getElementById('tmonth-desc');
  if (!grid) return;

  if (title) title.textContent = `対象月を選択 — ${escHtml(t.title||'')} `;
  if (desc)  desc.textContent  = '発行したい利用月を選択してください';

  if (months.length === 0) {
    // 期間未設定の場合は当月で直接開く
    const now = new Date();
    const ym  = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
    grid.innerHTML = `<p class="tmonth-noresult">開始日・終了日が設定されていないため、当月（${now.getFullYear()}年${now.getMonth()+1}月）で発行します。</p>`;
    document.getElementById('modal-ticket-month-select').classList.add('open');
    // フォールバック：月指定なしで直接表示
    setTimeout(() => {
      document.getElementById('modal-ticket-month-select').classList.remove('open');
      openTicketPaymentNotice(ticketId, ym);
    }, 800);
    return;
  }

  grid.innerHTML = months.map(({ year, month, label }) => {
    return `<button class="tmonth-btn"
      onclick="_onTicketMonthClick('${ticketId}','${year}-${String(month).padStart(2,'0')}')"
    >
      <span class="tmonth-btn-year">${year}年</span>
      <span class="tmonth-btn-month">${month}月</span>
      <span class="tmonth-btn-label">${label}利用分</span>
    </button>`;
  }).join('');

  document.getElementById('modal-ticket-month-select').classList.add('open');
}

function _onTicketMonthClick(ticketId, ym) {
  document.getElementById('modal-ticket-month-select').classList.remove('open');
  // 少し遅延してから通知書を開く（モーダルのトランジション後）
  setTimeout(() => openTicketPaymentNotice(ticketId, ym), 180);
}

// start_date〜end_date の範囲内の年月を配列で返す
// 例: '2025-04-24' 〜 '2025-08-31' → [{year:2025,month:4,...}, ..., {year:2025,month:8,...}]
function _buildMonthRange(startDate, endDate) {
  if (!startDate || !endDate) return [];
  const s = new Date(startDate);
  const e = new Date(endDate);
  if (isNaN(s) || isNaN(e) || s > e) return [];

  const results = [];
  const cur = new Date(s.getFullYear(), s.getMonth(), 1); // 月初に揃える
  const end = new Date(e.getFullYear(), e.getMonth(), 1);

  while (cur <= end) {
    const y = cur.getFullYear();
    const m = cur.getMonth() + 1;
    const MONTHS = ['1月','2月','3月','4月','5月','6月','7月','8月','9月','10月','11月','12月'];
    results.push({
      year:  y,
      month: m,
      label: `${y}年${m}月`,
      ym:    `${y}-${String(m).padStart(2,'0')}`
    });
    cur.setMonth(cur.getMonth() + 1);
  }
  return results;
}

// ─── 入金通知書を生成・表示 ───────────────────────────────────
async function openTicketPaymentNotice(ticketId, targetYM = null) {
  const t = _allTickets.find(x => x.id === ticketId);
  if (!t) return;

  // クライアント情報
  const client = _allTicketClients.find(c => c.id === t.client_id) || null;
  if (!client) {
    showToast('クライアントが設定されていません', 'error'); return;
  }

  // 自社情報
  const ci = await getCompanyInfo();

  // ── 対象月の表示文字列 ───────────────────────────────────────
  let targetYear  = null;
  let targetMonth = null;
  let periodLabel = '—';

  if (targetYM) {
    const [yy, mm] = targetYM.split('-').map(Number);
    targetYear  = yy;
    targetMonth = mm;
    periodLabel = `${yy}年${mm}月`;
  } else {
    // フォールバック：start_date〜end_date の文字列
    periodLabel = [t.start_date, t.end_date].filter(Boolean).map(d => {
      const dt = new Date(d);
      return `${dt.getFullYear()}年${dt.getMonth()+1}月${dt.getDate()}日`;
    }).join(' 〜 ') || '—';
  }

  // ── billing_items から対象月の行をフィルタ ────────────────────
  // date_from〜date_to が targetYM の月と重なる行を抽出
  const allBillingItems = Array.isArray(t.billing_items) ? t.billing_items : [];

  const billingItems = targetYM
    ? allBillingItems.filter(row => {
        // date_from か date_to のいずれかが入力されていれば判定
        const fromStr = row.date_from || row.date || '';
        const toStr   = row.date_to   || row.date_from || row.date || '';
        if (!fromStr) return false;

        const rowFrom = new Date(fromStr);
        const rowTo   = new Date(toStr);
        // 対象月の最初の日と最後の日
        const mStart = new Date(targetYear, targetMonth - 1, 1);
        const mEnd   = new Date(targetYear, targetMonth, 0); // 月末日

        // 期間の重複判定：rowFrom <= mEnd && rowTo >= mStart
        return rowFrom <= mEnd && rowTo >= mStart;
      })
    : allBillingItems;

  // ── 商品マスタ（手数料計算用）───────────────────────────────
  const pids  = t.ticket_product_ids || [];
  const prods = pids.map(pid => _allTicketProducts.find(x => x.id === pid)).filter(Boolean);

  // ── エラー判定 ────────────────────────────────────────────────
  // billing_items が1件以上登録されているのに当月該当なし → エラーPOP（商品マスタにフォールバックしない）
  if (allBillingItems.length > 0 && billingItems.length === 0) {
    showToast(`${periodLabel}の請求項目がありません。\nチケット編集で該当月の期間を入力してください。`, 'error');
    return;
  }
  // billing_items も商品マスタも両方空の場合はエラー
  if (billingItems.length === 0 && prods.length === 0) {
    showToast('チケット商品と請求項目のどちらも設定されていません', 'error');
    return;
  }

  // ── 明細行 HTML + 集計 ────────────────────────────────────────
  const TAX_RATE = 0.10;
  let grandTotal    = 0;
  let grandCommAmt  = 0;
  let grandCommBase = 0;
  let detailRows    = '';
  // 手数料率別集計マップ: { '15': { commAmt, commBase }, '20': { ... } }
  const commByRate  = {};

  if (billingItems.length > 0) {
    // ── パターンA: billing_items を使用（手動入力）──────────────

    detailRows = billingItems.map(row => {
      // 行ごとに対応商品マスタを取得して手数料率を計算
      const refProd    = _allTicketProducts.find(x => x.id === row.product_id) || prods[0] || null;
      // date_from / date_to → 「YYYY/M/D〜YYYY/M/D」形式で表示
      const fmtDate = s => {
        if (!s) return '';
        const d = new Date(s);
        return isNaN(d) ? s : `${d.getFullYear()}/${d.getMonth()+1}/${d.getDate()}`;
      };
      const fromStr  = row.date_from || row.date || '';
      const toStr    = row.date_to   || '';
      const dateStr  = fromStr
        ? (toStr && toStr !== fromStr
            ? `${fmtDate(fromStr)}〜${fmtDate(toStr)}`
            : fmtDate(fromStr))
        : '—';
      // 手数料率（商品ごと）: Collection含む全手数料合計
      const collRate   = parseFloat(refProd?.commission_collection) || 0;
      const brokers    = Array.isArray(refProd?.commissions) ? refProd.commissions : [];
      const brokerRate = brokers.reduce((s, b) => s + (parseFloat(b.rate) || 0), 0);
      const totalRate  = collRate + brokerRate;  // 行ごとに計算

      const qty      = Number(row.qty)        || 0;
      const price    = Number(row.unit_price) || 0;  // 販売価格
      // 精算額 = 販売価格 − 手数料（支払項目と同じ全手数料ベース）
      const clearPrice = price > 0 && totalRate > 0
        ? Math.round(price * (1 - totalRate / 100))
        : price;
      const subtotal = clearPrice * qty;  // 精算額 × 数量
      const commAmt  = price * qty - subtotal;  // 手数料総額（集計用）
      const commBase = Math.round(commAmt / (1 + TAX_RATE));
      const netAmt   = subtotal;  // 精算後の受取額 = subtotal そのもの

      grandTotal    += price * qty;   // 販売総額（集計の税率10%合計に使用）
      grandCommAmt  += commAmt;
      grandCommBase += commBase;
      // 率別集計
      if (totalRate > 0) {
        const rKey = String(totalRate);
        if (!commByRate[rKey]) commByRate[rKey] = { commAmt: 0, commBase: 0 };
        commByRate[rKey].commAmt  += commAmt;
        commByRate[rKey].commBase += commBase;
      }

      return `
        <tr class="tnotice-detail-row">
          <td class="tnotice-td-date">${escHtml(dateStr)}</td>
          <td class="tnotice-td-store">${escHtml(refProd?.store_name||'')}</td>
          <td class="tnotice-td-prod">${escHtml(row.product_name||'')}<div class="tnotice-prod-price-sub">販売価格 ${price.toLocaleString()}</div></td>
          <td class="tnotice-td-qty" style="text-align:center;">${qty}</td>
          <td class="tnotice-td-price" style="text-align:right;">${clearPrice.toLocaleString()}</td>
          <td class="tnotice-td-sub" style="text-align:right;">${subtotal.toLocaleString()}</td>
        </tr>
        <tr class="tnotice-comm-row">
          <td class="tnotice-td-date"></td>
          <td class="tnotice-td-store"></td>
          <td class="tnotice-td-prod"><span class="tnotice-comm-tag">販売手数料</span></td>
          <td class="tnotice-td-qty"></td>
          <td class="tnotice-td-price" style="text-align:right;">${totalRate ? `<span class="tnotice-comm-rate-total">合計 ${totalRate}%</span>` : ''}</td>
          <td class="tnotice-td-sub" style="text-align:right;font-size:12px;color:var(--gray-600);">${commAmt.toLocaleString()}</td>
        </tr>`;
    }).join('');

  } else {
    // ── パターンB: 商品マスタのみ（billing_items 未入力）────────
    detailRows = prods.map(p => {
      const price    = p.sale_price      || 0;
      const qty      = 1;
      const totalRate= p.commission_total || 0;
      // 精算額 = 販売価格 − 手数料
      const clearPrice = price > 0 && totalRate > 0
        ? Math.round(price * (1 - totalRate / 100))
        : price;
      const subtotal = clearPrice * qty;
      const commAmt  = price - clearPrice;  // 1枚の手数料
      const commBase = Math.round(commAmt / (1 + TAX_RATE));
      const netAmt   = subtotal;

      grandTotal    += price * qty;
      grandCommAmt  += commAmt * qty;
      grandCommBase += commBase * qty;
      // 率別集計（パターンB）
      if (totalRate > 0) {
        const rKey = String(totalRate);
        if (!commByRate[rKey]) commByRate[rKey] = { commAmt: 0, commBase: 0 };
        commByRate[rKey].commAmt  += commAmt * qty;
        commByRate[rKey].commBase += commBase * qty;
      }

      return `
        <tr class="tnotice-detail-row">
          <td class="tnotice-td-date">${periodLabel}</td>
          <td class="tnotice-td-store">${escHtml(p.store_name||'')}</td>
          <td class="tnotice-td-prod">${escHtml(p.product_name||'')}<div class="tnotice-prod-price-sub">販売価格 ${price.toLocaleString()}</div></td>
          <td class="tnotice-td-qty" style="text-align:center;">${qty}</td>
          <td class="tnotice-td-price" style="text-align:right;">${clearPrice.toLocaleString()}</td>
          <td class="tnotice-td-sub" style="text-align:right;">${subtotal.toLocaleString()}</td>
        </tr>
        <tr class="tnotice-comm-row">
          <td class="tnotice-td-date"></td>
          <td class="tnotice-td-store"></td>
          <td class="tnotice-td-prod"><span class="tnotice-comm-tag">販売手数料</span></td>
          <td class="tnotice-td-qty"></td>
          <td class="tnotice-td-price" style="text-align:right;"><span class="tnotice-comm-rate-total">合計 ${totalRate}%</span></td>
          <td class="tnotice-td-sub" style="text-align:right;font-size:12px;color:var(--gray-600);">${(commAmt * qty).toLocaleString()}</td>
        </tr>`;
    }).join('');
  }

  // 消費税内訳
  const commTax     = grandCommAmt - grandCommBase;
  const netTotal    = grandTotal - grandCommAmt;

  // 手数料率別の集計行HTML（複数率に対応）
  const rateKeys = Object.keys(commByRate).sort((a, b) => parseFloat(a) - parseFloat(b));
  const commRateRows = rateKeys.length > 0
    ? rateKeys.map(rKey => {
        const g       = commByRate[rKey];
        const taxAmt  = g.commAmt - g.commBase;
        return `
          <tr><td>販売手数料（${rKey}%）</td><td class="tnotice-sum-val">${g.commAmt.toLocaleString()}</td></tr>
          <tr><td class="tnotice-sum-indent">うち消費税（10%対象）</td><td class="tnotice-sum-val tnotice-sum-tax">${taxAmt.toLocaleString()}</td></tr>`;
      }).join('')
    : `<tr><td>販売手数料</td><td class="tnotice-sum-val">${grandCommAmt.toLocaleString()}</td></tr>
       <tr><td class="tnotice-sum-indent">うち消費税（10%対象）</td><td class="tnotice-sum-val tnotice-sum-tax">${commTax.toLocaleString()}</td></tr>`;

  // 発行日
  const today = new Date();
  const issueDate = `${today.getFullYear()}年${today.getMonth()+1}月${today.getDate()}日`;

  // 自社ロゴ
  const logoHtml = ci?.logo_data
    ? `<img src="${ci.logo_data}" alt="ロゴ" style="max-height:52px;max-width:160px;object-fit:contain;display:block;margin-bottom:6px;">`
    : '';

  // 自社情報
  const issuerName    = ci?.company_name || '';
  const issuerAddr    = ci?.address     || '';
  const issuerTel     = ci?.phone       || '';
  const issuerQnum    = ci?.qualified_number || '';

  // ── 振込先：クライアントの口座情報を使用 ──────────────────
  const bankLine = client?.bank_name
    ? [
        client.bank_name,
        client.bank_branch || '',
        client.bank_type   || '',
        client.bank_number || ''
      ].filter(Boolean).join('　')
    : '—';
  const bankHolder = client?.bank_holder
    || client?.company_name
    || client?.client_name
    || issuerName;

  // クライアント情報
  const clientQnum   = client.qualified_number || '—';
  const clientCompany= client.company_name || client.client_name || '';

  // ── 緑テーマ請求書スタイルのHTML生成（iframeに書き込む）─────
  const noticeHtml = `<!DOCTYPE html>
<html lang="ja"><head>
<meta charset="utf-8">
<title>入金通知書 - ${escHtml(t.title||'')} ${targetYM ? `(${periodLabel})` : ''}</title>
<link href="https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
*{box-sizing:border-box;margin:0;padding:0;}
body{font-family:'Noto Sans JP',sans-serif;background:#e8edf3;color:#1f2937;font-size:12px;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.inv-wrap{max-width:820px;margin:32px auto;background:#fff;border-radius:10px;box-shadow:0 4px 32px rgba(0,0,0,0.12);padding:40px 48px;}
.inv-title-row{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:24px;padding-bottom:16px;border-bottom:2px solid #e5e7eb;}
.inv-title{font-size:32px;font-weight:800;letter-spacing:.12em;color:#1f2937;}
.inv-title-sub{font-size:11px;color:#6b7280;margin-top:4px;}
.inv-meta{font-size:11px;color:#374151;text-align:left;line-height:1.8;}
.inv-meta-lbl{color:#6b7280;margin-right:8px;}
.inv-issuer{text-align:right;}
.inv-issuer-name{font-size:14px;font-weight:700;color:#1f2937;margin-bottom:4px;}
.inv-issuer-info{font-size:11px;color:#6b7280;line-height:1.7;}
.inv-to-row{margin-bottom:18px;padding-bottom:14px;border-bottom:1px solid #e5e7eb;}
.inv-to-name{font-size:20px;font-weight:700;margin-bottom:4px;}
.inv-to-sub{font-size:11px;color:#6b7280;display:flex;gap:20px;}
.inv-message{font-size:12px;color:#374151;margin-bottom:16px;}
.inv-subject-rows{display:flex;gap:24px;margin-bottom:6px;}
.inv-subject-row{display:flex;align-items:center;gap:8px;font-size:12px;}
.inv-subject-lbl{color:#6b7280;font-weight:600;white-space:nowrap;}
.inv-grand-box{background:#f0fdf4;border:2px solid #6ee7b7;border-radius:8px;padding:14px 20px;display:flex;align-items:center;gap:16px;margin-bottom:20px;}
.inv-grand-label{font-size:12px;color:#374151;flex:1;}
.inv-grand-amount{font-size:28px;font-weight:800;color:#059669;}
.inv-grand-tax{font-size:12px;color:#6b7280;}
.inv-section-title{display:flex;align-items:center;gap:6px;font-size:13px;font-weight:700;color:#374151;margin-bottom:6px;padding-left:4px;border-left:3px solid #059669;}
.inv-table{width:100%;border-collapse:collapse;margin-bottom:4px;}
.inv-table th{background:#059669;color:#fff;padding:7px 10px;text-align:left;font-size:11px;font-weight:700;}
.inv-table th:last-child,.inv-table th:nth-last-child(2){text-align:right;}
.inv-detail-row td{padding:7px 10px;border-bottom:1px solid #e5e7eb;vertical-align:top;font-size:12px;}
.inv-comm-row td{padding:3px 10px 7px;background:#f9fafb;border-bottom:1px solid #e5e7eb;font-size:11px;}
.inv-comm-tag{background:#d1fae5;color:#059669;padding:1px 7px;border-radius:3px;font-weight:700;font-size:10px;}
.inv-prod-sub{font-size:10px;color:#9ca3af;margin-top:2px;}
.inv-rate-tag{background:#fef3c7;color:#92400e;padding:1px 6px;border-radius:3px;font-weight:700;font-size:10px;}
.inv-td-date{width:110px;} .inv-td-store{width:130px;} .inv-td-qty{width:40px;text-align:center;} .inv-td-price{width:90px;text-align:right;} .inv-td-sub{width:90px;text-align:right;}
.inv-summary-wrap{display:flex;justify-content:flex-end;margin:8px 0 20px;}
.inv-summary{border-collapse:collapse;font-size:11px;min-width:300px;}
.inv-summary td{padding:5px 12px;border:1px solid #e5e7eb;}
.inv-sum-val{text-align:right;font-variant-numeric:tabular-nums;}
.inv-sum-indent{padding-left:22px!important;color:#6b7280;}
.inv-sum-tax{color:#9ca3af;}
.inv-sum-sep td{border-top:2px solid #d1d5db;}
.inv-sum-total td{background:#f0fdf4;font-weight:700;font-size:13px;border-top:2px solid #059669;}
.inv-sum-total .inv-sum-val{color:#059669;}
.inv-bank-box{border:1px solid #6ee7b7;border-radius:8px;padding:14px 18px;margin-bottom:16px;background:#f0fdf4;}
.inv-bank-title{font-size:12px;font-weight:700;color:#059669;margin-bottom:8px;display:flex;align-items:center;gap:6px;}
.inv-bank-table{border-collapse:collapse;width:100%;font-size:11px;}
.inv-bank-table th{background:#d1fae5;padding:5px 10px;border:1px solid #a7f3d0;width:90px;font-weight:600;color:#047857;text-align:left;}
.inv-bank-table td{padding:5px 10px;border:1px solid #a7f3d0;color:#1f2937;}
.inv-footer{display:flex;justify-content:space-between;align-items:flex-end;padding-top:14px;border-top:1px solid #e5e7eb;font-size:10px;color:#9ca3af;margin-top:8px;}
@page{size:A4 portrait;margin:16px;}
@media print{body{background:#fff;}.inv-wrap{margin:0;border-radius:0;box-shadow:none;padding:28px 36px;}.inv-grand-amount{font-size:22px;}}
</style>
</head>
<body>
<div class="inv-wrap">
  <div class="inv-title-row">
    <div>
      <div class="inv-title">入 金 通 知 書</div>
      <div class="inv-title-sub">媒介者交付特例を適用します</div>
      <div class="inv-meta" style="margin-top:10px;">
        <div><span class="inv-meta-lbl">発行日</span>${issueDate}</div>
        <div><span class="inv-meta-lbl">適格事業者番号</span>${escHtml(issuerQnum)}</div>
      </div>
    </div>
    <div class="inv-issuer">
      ${logoHtml}
      <div class="inv-issuer-name">${escHtml(issuerName)}</div>
      <div class="inv-issuer-info">
        ${issuerAddr ? `<div>${escHtml(issuerAddr)}</div>` : ''}
        ${issuerTel  ? `<div>TEL: ${escHtml(issuerTel)}</div>` : ''}
        ${issuerQnum ? `<div>適格事業者番号: ${escHtml(issuerQnum)}</div>` : ''}
      </div>
    </div>
  </div>
  <div class="inv-to-row">
    <div class="inv-to-name">${escHtml(clientCompany)} 御中</div>
    <div class="inv-to-sub"><span>適格事業者番号：${escHtml(clientQnum)}</span></div>
  </div>
  <div class="inv-subject-rows">
    <div class="inv-subject-row"><span class="inv-subject-lbl">利用店舗</span><span>${prods.map(p=>escHtml(p.store_name||'')).filter(Boolean).join(' / ') || '—'}</span></div>
    <div class="inv-subject-row"><span class="inv-subject-lbl">件名</span><span>${escHtml(t.title||'')}</span></div>
    <div class="inv-subject-row"><span class="inv-subject-lbl">対象月</span><span style="font-weight:700;color:#059669;">${escHtml(periodLabel)}</span></div>
  </div>
  <div class="inv-message" style="margin-top:10px;margin-bottom:16px;">下記の通り、お振込致します。</div>
  <div class="inv-grand-box">
    <span class="inv-grand-label">今期ご請求申請（税込）<br><span style="font-size:10px;color:#6b7280;">支払金額：${netTotal.toLocaleString()}円（税込）</span></span>
    <span class="inv-grand-amount">¥${netTotal.toLocaleString()}</span>
    <span class="inv-grand-tax">（税込）</span>
  </div>
  <div class="inv-section-title"><i>明　細</i></div>
  <table class="inv-table">
    <thead>
      <tr>
        <th class="inv-td-date">日付</th>
        <th class="inv-td-store">対象店舗</th>
        <th class="inv-td-prod" style="min-width:120px;">内容</th>
        <th class="inv-td-qty">数量</th>
        <th class="inv-td-price">単価（税込）</th>
        <th class="inv-td-sub">小計</th>
      </tr>
    </thead>
    <tbody>
      ${detailRows.replace(/tnotice-detail-row/g,'inv-detail-row').replace(/tnotice-comm-row/g,'inv-comm-row').replace(/tnotice-td-date/g,'inv-td-date').replace(/tnotice-td-store/g,'inv-td-store').replace(/tnotice-td-prod/g,'inv-td-prod').replace(/tnotice-td-qty/g,'inv-td-qty').replace(/tnotice-td-price/g,'inv-td-price').replace(/tnotice-td-sub/g,'inv-td-sub').replace(/tnotice-prod-price-sub/g,'inv-prod-sub').replace(/tnotice-comm-tag/g,'inv-comm-tag').replace(/tnotice-comm-rate-total/g,'inv-rate-tag')}
    </tbody>
  </table>
  <div class="inv-summary-wrap">
    <table class="inv-summary">
      <tr><td>税率10%項目合計</td><td class="inv-sum-val">${grandTotal.toLocaleString()}</td></tr>
      <tr class="inv-sum-sep"><td>税込小計 / 対象金額合計</td><td class="inv-sum-val">${grandTotal.toLocaleString()}</td></tr>
      ${commRateRows.replace(/tnotice-sum-val/g,'inv-sum-val').replace(/tnotice-sum-indent/g,'inv-sum-indent').replace(/tnotice-sum-tax/g,'inv-sum-tax')}
      <tr class="inv-sum-total"><td><strong>振込金額（税込）</strong></td><td class="inv-sum-val"><strong>¥${netTotal.toLocaleString()}</strong></td></tr>
    </table>
  </div>
  <div class="inv-bank-box">
    <div class="inv-bank-title">&#127968; 振込先</div>
    <table class="inv-bank-table">
      <tr><th>銀行名</th><td>${escHtml(bankLine)}</td></tr>
      <tr><th>口座名義</th><td>${escHtml(bankHolder)}</td></tr>
    </table>
  </div>
  <div class="inv-footer">
    <span>${escHtml(issuerName)} &nbsp; ${issuerAddr ? escHtml(issuerAddr) : ''}</span>
    <span>適格事業者番号：${escHtml(issuerQnum)}</span>
  </div>
</div>
</body></html>`;

  // ── iframeプレビューモーダルで表示 ──
  const overlay = document.getElementById('modal-ticket-notice');
  const frame   = document.getElementById('ticket-notice-frame');
  if (!overlay || !frame) {
    showToast('プレビューモーダルが見つかりません', 'error'); return;
  }

  const loadingEl = document.getElementById('ticket-notice-loading');
  if (loadingEl) { loadingEl.style.display = 'flex'; }

  frame.srcdoc = noticeHtml;
  frame.onload = () => {
    if (loadingEl) loadingEl.style.display = 'none';
  };

  const printBtn = document.getElementById('btn-ticket-notice-print');
  if (printBtn) {
    const newBtn = printBtn.cloneNode(true);
    printBtn.parentNode.replaceChild(newBtn, printBtn);
    newBtn.addEventListener('click', () => {
      frame.contentWindow && frame.contentWindow.print();
    });
  }

  overlay.classList.add('open');
  showToast('入金通知書を生成しました');
}

/* ─ 末尾 ─ */

/* ============================================================
   アカウント管理
   ============================================================ */

// (グローバル宣言は先頭に移動済み)
// ─── ロール設定マップ ─────────────────────────────────────────
const ROLE_CONFIG = {
  '管理者': { cls: 'account-role-badge--admin',  icon: 'fa-user-shield' },
  '登録者': { cls: 'account-role-badge--editor', icon: 'fa-user-edit'   },
  '閲覧者': { cls: 'account-role-badge--viewer', icon: 'fa-user'        },
};

// ─── アクティブ（未削除）アカウントのみ返すヘルパー ─────────
function _activeAccounts() {
  return _allAccounts.filter(a => !a.is_deleted);
}

// ─── アカウント一覧を読み込み・描画 ──────────────────────────
async function loadAccounts() {
  try {
    const res = await API.get('accounts', { limit: 200, sort: 'created_at' });
    _allAccounts = res.data || [];
    renderAccountTable();
  } catch(e) {
    console.error('loadAccounts error:', e);
  }
}

// ─── テーブル描画 ─────────────────────────────────────────────
function renderAccountTable() {
  const tbody = document.getElementById('account-table-body');
  if (!tbody) return;

  const visible = _activeAccounts();

  if (visible.length === 0) {
    tbody.innerHTML = `
      <tr id="account-empty-row">
        <td colspan="7">
          <div class="account-empty">
            <i class="fas fa-user-slash"></i>
            <span>アカウントが登録されていません</span>
          </div>
        </td>
      </tr>`;
    return;
  }

  tbody.innerHTML = visible.map(acc => {
    const initials   = (acc.name || '?').trim().charAt(0).toUpperCase();
    const posLabel   = acc.position ? `<span class="account-position-badge">${escHtml(acc.position)}</span>` : '';
    const limitLabel = acc.daily_hour_limit != null
      ? `<span class="account-limit-badge"><i class="fas fa-clock"></i> ${acc.daily_hour_limit}h</span>`
      : '';

    // ── 管轄バッジ列 ──────────────────────────────────────────
    const jurTags = Array.isArray(acc.jurisdiction) ? acc.jurisdiction
                  : (acc.jurisdiction ? (() => { try { return JSON.parse(acc.jurisdiction); } catch { return []; } })() : []);
    const jurCell = jurTags.length
      ? jurTags.map(j => `<span class="account-jur-badge">${escHtml(j)}</span>`).join('')
      : '<span class="acct-unset-label">—</span>';

    // ── カレンダーID 列 ──────────────────────────────────────
    const calIdCell = acc.calendar_id
      ? `<div class="acct-cal-id-cell">
           <i class="fas fa-calendar-alt acct-cal-icon"></i>
           <span class="acct-cal-id-text" title="${escHtml(acc.calendar_id)}">${escHtml(acc.calendar_id)}</span>
         </div>`
      : `<span class="acct-unset-label">未設定</span>`;

    // ── 埋め込みコード 列 ─────────────────────────────────────
    // embed_code があれば先頭50文字をプレビュー + セット済みバッジ
    const embedCell = acc.embed_code
      ? `<div class="acct-embed-cell">
           <span class="acct-embed-badge acct-embed-badge--set">
             <i class="fas fa-check-circle"></i> 設定済み
           </span>
           <span class="acct-embed-preview" title="${escHtml(acc.embed_code)}">${escHtml(acc.embed_code.slice(0, 48))}${acc.embed_code.length > 48 ? '…' : ''}</span>
         </div>`
      : `<span class="acct-unset-label">未設定</span>`;

    return `<tr>
      <td>
        <div class="account-name-cell">
          <div class="account-avatar">${escHtml(initials)}</div>
          <div>
            <span class="account-name-text">${escHtml(acc.name || '—')}</span>
            ${posLabel}
          </div>
        </div>
      </td>
      <td class="account-info-cell">${limitLabel}</td>
      <td class="acct-td-jur">${jurCell}</td>
      <td class="acct-td-calid">${calIdCell}</td>
      <td class="acct-td-embed">${embedCell}</td>
      <td class="account-action-cell">
        <button class="btn-account-edit" onclick="openAccountModal('${acc.id}')">
          <i class="fas fa-edit"></i> 編集
        </button>
      </td>
      <td class="account-action-cell">
        <button class="btn-account-row-delete" onclick="deleteAccountRow('${acc.id}','${escHtml(acc.name || '')}')" title="削除">
          <i class="fas fa-trash"></i>
        </button>
      </td>
    </tr>`;
  }).join('');
}

// ─── 管轄タグ入力UI ヘルパー ─────────────────────────────────
/**
 * タグリストを描画する
 * @param {string[]} tags
 */
function _renderJurTags(tags) {
  const listEl = document.getElementById('jur-tag-list');
  if (!listEl) return;
  listEl.innerHTML = tags.map((t, i) =>
    `<span class="jur-tag">
      ${escHtml(t)}
      <button type="button" class="jur-tag-del" data-idx="${i}" title="削除">×</button>
    </span>`
  ).join('');
  listEl.querySelectorAll('.jur-tag-del').forEach(btn => {
    btn.addEventListener('click', () => {
      const idx = parseInt(btn.dataset.idx, 10);
      const hidden = document.getElementById('account-jurisdiction');
      const cur = _jurTagsFromHidden();
      cur.splice(idx, 1);
      hidden.value = JSON.stringify(cur);
      _renderJurTags(cur);
    });
  });
}

/** hidden から現在のタグ配列を取得 */
function _jurTagsFromHidden() {
  try {
    const v = document.getElementById('account-jurisdiction')?.value || '[]';
    const parsed = JSON.parse(v);
    return Array.isArray(parsed) ? parsed : [];
  } catch { return []; }
}

/** タグ入力欄の初期化（モーダルを開くたびに呼ぶ） */
function _initJurTagInput() {
  const inp    = document.getElementById('jur-tag-input');
  const hidden = document.getElementById('account-jurisdiction');
  if (!inp || !hidden) return;

  // 以前のリスナーを外すためクローン置換
  const newInp = inp.cloneNode(true);
  inp.parentNode.replaceChild(newInp, inp);

  newInp.addEventListener('keydown', e => {
    if (e.key === 'Enter' || e.key === ',') {
      e.preventDefault();
      const val = newInp.value.trim().replace(/,/g, '');
      if (!val) return;
      const cur = _jurTagsFromHidden();
      if (!cur.includes(val)) {
        cur.push(val);
        hidden.value = JSON.stringify(cur);
        _renderJurTags(cur);
      }
      newInp.value = '';
    }
    // Backspaceで最後のタグを削除
    if (e.key === 'Backspace' && newInp.value === '') {
      const cur = _jurTagsFromHidden();
      if (cur.length) {
        cur.pop();
        hidden.value = JSON.stringify(cur);
        _renderJurTags(cur);
      }
    }
  });
}

// ─── モーダルを開く（新規 or 編集） ─────────────────────────
function openAccountModal(id = null) {
  const modal    = document.getElementById('modal-account');
  const title    = document.getElementById('modal-account-title');
  const editId   = document.getElementById('account-edit-id');
  const nameEl     = document.getElementById('account-name');
  const posEl     = document.getElementById('account-position');
  const limitEl   = document.getElementById('account-hour-limit');
  const calIdEl   = document.getElementById('account-calendar-id');
  const embedEl   = document.getElementById('account-embed-code');
  const delBtn    = document.getElementById('btn-account-delete');

  if (id) {
    const acc = _allAccounts.find(a => a.id === id);
    if (!acc) return;
    title.innerHTML    = '<i class="fas fa-user-edit" style="color:var(--primary);"></i> アカウントを編集';
    editId.value       = acc.id;
    nameEl.value       = acc.name || '';
    if (posEl)   posEl.value   = acc.position  || '';
    if (limitEl) limitEl.value = acc.daily_hour_limit != null ? acc.daily_hour_limit : '';
    if (calIdEl) calIdEl.value = acc.calendar_id || '';
    if (embedEl) embedEl.value = acc.embed_code  || '';
    // 管轄タグ
    const jurHidden = document.getElementById('account-jurisdiction');
    const jurTags   = Array.isArray(acc.jurisdiction) ? acc.jurisdiction
                    : (acc.jurisdiction ? JSON.parse(acc.jurisdiction) : []);
    if (jurHidden) jurHidden.value = JSON.stringify(jurTags);
    _renderJurTags(jurTags);
    delBtn.style.display = 'inline-flex';
  } else {
    title.innerHTML    = '<i class="fas fa-user-plus" style="color:var(--primary);"></i> アカウントを追加';
    editId.value       = '';
    nameEl.value       = '';
    if (posEl)   posEl.value   = '';
    if (limitEl) limitEl.value = '';
    if (calIdEl) calIdEl.value = '';
    if (embedEl) embedEl.value = '';
    // 管轄タグリセット
    const jurHidden = document.getElementById('account-jurisdiction');
    if (jurHidden) jurHidden.value = '[]';
    _renderJurTags([]);
    delBtn.style.display = 'none';
  }

  _initJurTagInput();
  modal.classList.add('open');
  nameEl.focus();
}

// ─── 保存ボタン ───────────────────────────────────────────────
document.getElementById('btn-account-save')?.addEventListener('click', async () => {
  const id       = document.getElementById('account-edit-id').value.trim();
  const name        = document.getElementById('account-name').value.trim();
  const position    = document.getElementById('account-position')?.value.trim() || null;
  const limitRaw    = document.getElementById('account-hour-limit')?.value.trim();
  const daily_hour_limit = limitRaw !== '' ? parseFloat(limitRaw) : null;
  const calendar_id = document.getElementById('account-calendar-id')?.value.trim() || null;
  const embed_code  = document.getElementById('account-embed-code')?.value.trim()  || null;
  const jurisdiction = _jurTagsFromHidden();

  if (!name) { showToast('氏名を入力してください', 'error'); return; }
  if (daily_hour_limit !== null && (isNaN(daily_hour_limit) || daily_hour_limit <= 0)) {
    showToast('想定実動時間は正の数値で入力してください', 'error'); return;
  }

  const payload = { name, position, daily_hour_limit, calendar_id, embed_code, jurisdiction };

  try {
    if (id) {
      await _saveTableFields('accounts', id, payload);
      showToast('アカウントを更新しました', 'success');
    } else {
      await API.post('accounts', payload);
      showToast('アカウントを登録しました', 'success');
    }
    document.getElementById('modal-account').classList.remove('open');
    await loadAccounts();
  } catch(e) {
    showToast('保存に失敗しました', 'error');
  }
});

// ─── モーダル内削除ボタン（編集モード時） ────────────────────
document.getElementById('btn-account-delete')?.addEventListener('click', async () => {
  const id   = document.getElementById('account-edit-id').value.trim();
  const name = document.getElementById('account-name').value.trim();
  if (!id) return;
  if (!confirm(`「${name}」を削除してよろしいですか？\n\n削除後、担当者の選択肢から外れます。過去の案件データはそのまま保持されます。`)) return;
  try {
      await _saveTableFields('accounts', id, { is_deleted: true });
    showToast(`「${name}」を削除しました`, 'success');
    document.getElementById('modal-account').classList.remove('open');
    await loadAccounts();
  } catch(e) {
    showToast('削除に失敗しました', 'error');
  }
});

// ─── 行の削除ボタン（一覧から直接削除） ──────────────────────
async function deleteAccountRow(id, name) {
  if (!confirm(`「${name}」を削除してよろしいですか？\n\n削除後、担当者の選択肢から外れます。過去の案件データはそのまま保持されます。`)) return;
  try {
      await _saveTableFields('accounts', id, { is_deleted: true });
    showToast(`「${name}」を削除しました`, 'success');
    await loadAccounts();
  } catch(e) {
    showToast('削除に失敗しました', 'error');
  }
}

// ─── 追加ボタン ───────────────────────────────────────────────
document.getElementById('btn-account-add')?.addEventListener('click', () => openAccountModal());

// ─── 権限カードのクリック選択 ─────────────────────────────────
document.querySelectorAll('.account-role-card').forEach(card => {
  card.addEventListener('click', () => {
    document.querySelectorAll('.account-role-card').forEach(c =>
      c.classList.remove('account-role-card--active')
    );
    card.classList.add('account-role-card--active');
    card.querySelector('input[type="radio"]').checked = true;
  });
});

/* ============================================================
   スケジュール回答 通知POP（GAS同期は削除済み）
   ============================================================ */

// ダミー（後続コードのエラー防止）
function getGasUrl() { return ''; }
function saveGasUrl() {}



/* ============================================================
   スケジュール回答 通知POP
   ============================================================ */

const ReplyPop = (() => {
  let _pollTimer = null;
  let _infMap    = {};
  let _projMap   = {};

  function _timeAgo(ms) {
    const diff = Date.now() - ms;
    const m = Math.floor(diff / 60000);
    if (m < 1)  return 'たった今';
    if (m < 60) return `${m}分前`;
    const h = Math.floor(m / 60);
    if (h < 24) return `${h}時間前`;
    return `${Math.floor(h / 24)}日前`;
  }

  function _cardHtml(a) {
    const inf      = _infMap[a.influencer_id] || {};
    const proj     = _projMap[a.project_id]   || {};
    const isAccept = a.reply_action === 'accept';
    const badgeCls = isAccept ? 'reply-pop-badge--accept' : 'reply-pop-badge--reject';
    const itemCls  = isAccept ? 'reply-pop-item--accept'  : 'reply-pop-item--reject';
    const icon     = isAccept ? 'fa-check-circle'         : 'fa-times-circle';
    const label    = isAccept ? '受入可'                  : '受入不可';
    const timeStr  = _timeAgo(a.updated_at || a.created_at || Date.now());
    return `
      <div class="reply-pop-item ${itemCls}" data-assign-id="${a.id}" data-project-id="${a.project_id || ''}">
        <div class="reply-pop-top">
          <span class="reply-pop-badge ${badgeCls}">
            <i class="fas ${icon}"></i>${label}
          </span>
          <span class="reply-pop-time">${timeStr}</span>
        </div>
        <div class="reply-pop-body">
          <div class="reply-pop-project">${escHtml(proj.project_name || '（案件名不明）')}</div>
          <div class="reply-pop-name">${escHtml(inf.name || '（名前不明）')}</div>
        </div>
        <div class="reply-pop-footer">
          <button class="btn-reply-pop-done" data-assign-id="${a.id}">
            <i class="fas fa-check"></i> 対応済
          </button>
        </div>
      </div>`;
  }

  function _render(items) {
    const outer     = document.getElementById('reply-pop-outer');
    const container = document.getElementById('reply-pop-container');
    const countEl   = document.getElementById('reply-pop-count');
    if (!container || !outer) return;

    // 件数バッジ更新
    if (countEl) countEl.textContent = items.length;

    // 0件ならパネル全体を非表示
    if (items.length === 0) {
      container.innerHTML = '';
      outer.style.display = 'none';
      return;
    }

    // パネル表示
    outer.style.display = '';

    container.innerHTML = items.map(_cardHtml).join('');
    // 最新が見えるよう末尾へスクロール
    requestAnimationFrame(() => { container.scrollTop = container.scrollHeight; });

    // ── 折りたたみボタン（初回のみ登録）──
    const toggleBtn = document.getElementById('reply-pop-toggle');
    if (toggleBtn && !toggleBtn._bound) {
      toggleBtn._bound = true;
      toggleBtn.addEventListener('click', () => {
        outer.classList.toggle('is-collapsed');
        const expanded = !outer.classList.contains('is-collapsed');
        toggleBtn.setAttribute('aria-expanded', expanded);
      });
    }

    // 「対応済」ボタン
    container.querySelectorAll('.btn-reply-pop-done').forEach(btn => {
      btn.addEventListener('click', async (e) => {
        e.stopPropagation();
        const assignId = btn.dataset.assignId;
        btn.disabled = true;
        try {
          await _saveAssignFields(assignId, { reply_notified: true });
          Cache.invalidate('projectInfluencers');
          // 案件一覧のベルマーク表示を即時更新
          if (typeof loadProjects === 'function') loadProjects();
          const card = container.querySelector(`.reply-pop-item[data-assign-id="${assignId}"]`);
          if (card) {
            card.style.transition = 'opacity .25s, transform .25s';
            card.style.opacity    = '0';
            card.style.transform  = 'translateX(20px)';
            setTimeout(() => {
              card.remove();
              // 残件数更新
              const remaining = container.querySelectorAll('.reply-pop-item').length;
              if (countEl) countEl.textContent = remaining;
              if (remaining === 0) outer.style.display = 'none';
            }, 260);
          }
        } catch(err) {
          btn.disabled = false;
          showToast('更新に失敗しました', 'error');
        }
      });
    });

    // カード本体クリック → 案件に遷移
    container.querySelectorAll('.reply-pop-item').forEach(card => {
      card.addEventListener('click', (e) => {
        if (e.target.closest('.btn-reply-pop-done')) return;
        const projectId = card.dataset.projectId;
        if (!projectId) return;
        // まず案件一覧ページに切り替えてから詳細を開く
        navigateTo('projects');
        setTimeout(() => openProjectDetail(projectId), 150);
      });
    });
  }

  async function _poll() {
    try {
      const [assignRes, infRes, projRes] = await Promise.all([
        API.getAll('project_influencers'),
        Cache.get('influencers', () => API.getAll('influencers', {}, 20)),
        Cache.get('projects',    () => API.getAll('projects')),
      ]);
      (infRes.data  || []).forEach(i => { _infMap[i.id]  = i; });
      (projRes.data || []).forEach(p => { _projMap[p.id] = p; });

      const pending = (assignRes.data || []).filter(a =>
        a.reply_action &&
        (a.reply_notified === false || a.reply_notified === null || a.reply_notified === undefined)
      ).sort((a, b) => (b.updated_at || 0) - (a.updated_at || 0));

      _render(pending);
    } catch(e) { /* サイレント */ }
  }

  return {
    start()   { _poll(); _pollTimer = setInterval(_poll, 30000); },
    stop()    { if (_pollTimer) clearInterval(_pollTimer); },
    refresh() { _poll(); },
  };
})();

document.addEventListener('DOMContentLoaded', () => { ReplyPop.start(); });
